def capture_scenario_internal_setups(label: str) -> tuple[str, ...]:
    """Return fixture-owned setup checkpoints for one singleton scenario."""

    if label in CAPTURE_SCENARIO_FRESH_LABELS:
        return ("fresh-first-run",)
    if label == "purchase-confirmation-fertilizer-queue":
        return ("nurtured-active", "transaction-snapshot")
    if label.startswith("purchase-"):
        return ("development-stress", "transaction-snapshot")
    if label.startswith("growth-charge-"):
        return ("development-stress", "growth-charge-snapshot")
    if label.startswith("reviewer-find-"):
        return ("development-stress", "reviewer-ready")
    if label.startswith("collection-"):
        return ("development-stress", "collection-snapshot")
    if label.startswith("nursery-"):
        return ("development-stress", "nursery-snapshot")
    if (
        label.startswith("settings-")
        or label.startswith("diagnostics-")
        or label in {
            "production-build-controls-absent",
            "reduced-motion-enabled",
        }
    ):
        return ("nurtured-active", "settings-snapshot")
    if label in CAPTURE_SCENARIO_DEVELOPMENT_STRESS_LABELS:
        return ("development-stress",)
    if label.startswith("home-preview-"):
        return ("nurtured-active", "home-preview-state")
    if label in {
        "starter-placement",
        "starter-completion",
        "onboarding-persistence-error",
    }:
        return ("planted-not-nurtured", "state-snapshot")
    if label in CAPTURE_SCENARIO_NURTURED_ACTIVE_LABELS:
        return ("nurtured-active",)
    return ("planted-not-nurtured",)


def capture_scenario_prerequisites(label: str) -> tuple[str, ...]:
    """Return setup-only capture steps needed to reach one exact scenario."""

    return (
        (CAPTURE_SCENARIO_SETUP_BOUNDARY,)
        if "nurtured-active" in capture_scenario_internal_setups(label)
        and label != CAPTURE_SCENARIO_SETUP_BOUNDARY
        else ()
    )


def capture_scenario_checkpoint(label: str) -> str:
    """Return the stable fixture checkpoint which owns one capture face."""

    setups = capture_scenario_internal_setups(label)
    if label == CAPTURE_SCENARIO_SETUP_BOUNDARY:
        return "nurture-transition"
    return setups[0] if setups else "unknown"


def capture_contract_digest(profile: str) -> str:
    """Return the exact compiled v26 contract digest used by the runtime."""

    normalized = str(profile).strip().lower()
    profiles = _COMPILED_CAPTURE_CONTRACT.get("profiles", {})
    if normalized not in profiles:
        return ""
    return str(_COMPILED_CAPTURE_CONTRACT.get("contract_digest", ""))

