def dialog_scroll_geometry_issue_codes(
    *,
    registered_count: int,
    active_count: int,
    footer_visible: bool,
    footer_height: int,
    footer_top: int,
    viewport_top: int,
    viewport_height: int,
    declared_clearance: int,
    layout_clearance: int,
    content_height: int,
    content_size_hint_height: int,
    content_minimum_size_hint_height: int,
    scroll_minimum: int,
    scroll_maximum: int,
    last_body_child_bottom: int,
    last_body_child_bottom_at_scroll_end: int,
    require_no_scroll: bool,
    expected_active_count: int = 1,
) -> tuple[str, ...]:
    """Return fail-closed issue codes for one dialog's vertical scroll owner."""

    registered = int(registered_count)
    active = int(active_count)
    expected_active = int(expected_active_count)
    issues: list[str] = []
    if expected_active not in {0, 1}:
        issues.append("invalid-expected-active-scroll-count")
        return tuple(issues)
    if registered and active != expected_active:
        issues.append("active-scroll-count")
    if active != expected_active:
        return tuple(issues)

    metrics = {
        "footer_height": int(footer_height),
        "footer_top": int(footer_top),
        "viewport_top": int(viewport_top),
        "declared_clearance": int(declared_clearance),
        "layout_clearance": int(layout_clearance),
        "content_height": int(content_height),
        "content_size_hint_height": int(content_size_hint_height),
        "content_minimum_size_hint_height": int(
            content_minimum_size_hint_height
        ),
        "scroll_minimum": int(scroll_minimum),
        "scroll_maximum": int(scroll_maximum),
        "last_body_child_bottom": int(last_body_child_bottom),
        "last_body_child_bottom_at_scroll_end": int(
            last_body_child_bottom_at_scroll_end
        ),
    }
    if registered < 1:
        issues.append("registered-scroll-count")
    for field, value in metrics.items():
        if value < 0:
            issues.append(f"negative-scroll-metric:{field}")
    if int(viewport_height) <= 0:
        issues.append("invalid-scroll-metric:viewport_height")
    if int(content_height) <= 0:
        issues.append("invalid-scroll-metric:content_height")
    if int(scroll_maximum) < int(scroll_minimum):
        issues.append("invalid-scroll-range")
    scroll_span = max(0, int(scroll_maximum) - int(scroll_minimum))
    expected_body_end = int(viewport_top) + max(
        0,
        int(last_body_child_bottom) - scroll_span,
    )
    if int(last_body_child_bottom_at_scroll_end) != expected_body_end:
        issues.append("last-body-child-position-mismatch")
    body_limit = (
        int(footer_top)
        if bool(footer_visible)
        else int(viewport_top) + int(viewport_height)
    )
    if int(last_body_child_bottom_at_scroll_end) > body_limit:
        issues.append("last-body-child-under-footer")
    if bool(require_no_scroll) and scroll_span != 0:
        issues.append("compact-transaction-scroll-range")

    if bool(footer_visible) and int(footer_height) <= 0:
        issues.append("visible-footer-height")
    if not bool(footer_visible) and int(footer_height) != 0:
        issues.append("hidden-footer-height")
    # DialogShell pins the footer as a normal sibling below the scroll owner.
    # Its content margin therefore stays at the layout's original value
    # (normally zero); adding the footer height would manufacture a blank tail.
    if int(declared_clearance) != int(layout_clearance):
        issues.append("footer-clearance-mismatch")
    viewport_bottom = int(viewport_top) + int(viewport_height)
    if bool(footer_visible) and viewport_bottom > int(footer_top):
        issues.append("footer-viewport-overlap")

    # ``sizeHint`` is a preferred height and may legitimately exceed the
    # widgetResizable QScrollArea's laid-out height. Reachability is governed
    # by the actual content/descendant geometry and its minimum size hint.
    # Treating the preferred hint as mandatory rejects fully reachable Qt
    # layouts by their ordinary style spacing delta.
    required_content_height = max(
        0,
        int(content_height),
        int(content_minimum_size_hint_height),
    )
    reachable_content_height = int(viewport_height) + scroll_span
    if reachable_content_height < required_content_height:
        issues.append("unreachable-scroll-content")
    return tuple(issues)


def dialog_scroll_state_observation_issue_codes(
    observation: Any,
) -> tuple[str, ...]:
    """Validate one painted member of the release scroll-state matrix."""

    if not isinstance(observation, dict):
        return ("invalid-scroll-state-observation",)
    issues: list[str] = []
    state = str(observation.get("state", ""))
    if state not in DIALOG_SCROLL_FOUR_STATE_NAMES:
        issues.append("unknown-scroll-state")
    if observation.get("painted") is not True:
        issues.append("scroll-state-not-painted")
    digest = observation.get("paint_digest")
    if not isinstance(digest, str) or len(digest) != 64:
        issues.append("invalid-scroll-state-paint-digest")
    paint_size = observation.get("paint_size")
    if not (
        isinstance(paint_size, list)
        and len(paint_size) == 2
        and all(type(value) is int and value > 0 for value in paint_size)
    ):
        issues.append("invalid-scroll-state-paint-size")

    integer_fields = (
        "row_count",
        "scroll_minimum",
        "scroll_maximum",
        "scroll_value",
        "horizontal_scroll_minimum",
        "horizontal_scroll_maximum",
        "content_width",
        "viewport_width",
        "viewport_height",
    )
    invalid = [
        field
        for field in integer_fields
        if type(observation.get(field)) is not int
    ]
    issues.extend(f"invalid-scroll-state-metric:{field}" for field in invalid)
    for field in (
        "vertical_scrollbar_visible",
        "horizontal_scrollbar_visible",
    ):
        if type(observation.get(field)) is not bool:
            issues.append(f"invalid-scroll-state-metric:{field}")
    intrusions = observation.get("fixed_region_intrusions")
    if not isinstance(intrusions, list):
        issues.append("invalid-fixed-region-intrusions")
    elif intrusions:
        issues.append("scrollbar-fixed-region-intrusion")
    if invalid or any(
        issue.startswith("invalid-scroll-state-metric:")
        for issue in issues
    ):
        return tuple(dict.fromkeys(issues))

    row_count = int(observation["row_count"])
    scroll_minimum = int(observation["scroll_minimum"])
    scroll_maximum = int(observation["scroll_maximum"])
    scroll_value = int(observation["scroll_value"])
    horizontal_minimum = int(observation["horizontal_scroll_minimum"])
    horizontal_maximum = int(observation["horizontal_scroll_maximum"])
    content_width = int(observation["content_width"])
    viewport_width = int(observation["viewport_width"])
    viewport_height = int(observation["viewport_height"])
    scroll_span = scroll_maximum - scroll_minimum
    if (
        row_count < 0
        or scroll_minimum < 0
        or scroll_maximum < scroll_minimum
        or not scroll_minimum <= scroll_value <= scroll_maximum
        or viewport_width <= 0
        or viewport_height <= 0
        or content_width <= 0
    ):
        issues.append("invalid-scroll-state-geometry")
    if (
        horizontal_maximum != horizontal_minimum
        or observation.get("horizontal_scrollbar_visible") is True
        or content_width > viewport_width
    ):
        issues.append("horizontal-scroll-overflow")

    if state == "no-overflow-list":
        if scroll_span != 0:
            issues.append("no-overflow-state-has-scroll-range")
        if observation.get("vertical_scrollbar_visible") is True:
            issues.append("scrollbar-shown-when-content-fits")
    elif state == "one-row-list":
        if row_count != 1:
            issues.append("one-row-state-row-count")
        if scroll_span != 0:
            issues.append("one-row-state-has-scroll-range")
        if observation.get("vertical_scrollbar_visible") is True:
            issues.append("scrollbar-shown-when-content-fits")
    elif state == "enough-rows-to-scroll":
        if row_count < 2:
            issues.append("scrolling-state-row-count")
        if scroll_span <= 0:
            issues.append("scrolling-state-missing-range")
        if scroll_value != scroll_minimum:
            issues.append("scrolling-state-not-at-start")
    elif state == "final-item-at-maximum-scroll":
        if row_count < 2:
            issues.append("maximum-scroll-state-row-count")
        if scroll_span <= 0:
            issues.append("maximum-scroll-state-missing-range")
        if scroll_value != scroll_maximum:
            issues.append("maximum-scroll-value")
        final_bounds = observation.get("final_item_bounds")
        if not (
            isinstance(final_bounds, list)
            and len(final_bounds) == 4
            and all(type(value) is int for value in final_bounds)
            and int(final_bounds[2]) > 0
            and int(final_bounds[3]) > 0
        ):
            issues.append("invalid-final-item-bounds")
        else:
            _left, top, _width, height = final_bounds
            if top < 0 or top + height > viewport_height:
                issues.append("clipped-final-row")
        if observation.get("final_item_visible") is not True:
            issues.append("final-item-not-visible")
    return tuple(dict.fromkeys(issues))


def dialog_scroll_state_matrix_issue_codes(
    matrix: Any,
    *,
    require_complete: bool,
) -> tuple[str, ...]:
    """Validate local scroll observations or the aggregate four-state gate."""

    if not isinstance(matrix, dict):
        return ("missing-scroll-state-matrix",)
    observations = matrix.get("observations")
    if not isinstance(observations, list):
        return ("invalid-scroll-state-observations",)
    issues: list[str] = []
    seen: set[str] = set()
    for index, observation in enumerate(observations):
        if not isinstance(observation, dict):
            issues.append(f"invalid-scroll-state-observation:{index}")
            continue
        state = str(observation.get("state", ""))
        if state in seen:
            issues.append(f"duplicate-scroll-state:{state}")
        seen.add(state)
        issues.extend(
            f"{state or index}:{issue}"
            for issue in dialog_scroll_state_observation_issue_codes(
                observation
            )
        )
        if observation.get("issues") != []:
            issues.append(f"{state or index}:reported-issues")
        if observation.get("passed") is not True:
            issues.append(f"{state or index}:did-not-pass")
    if matrix.get("canonical_scroll_restored") is not True:
        issues.append("canonical-scroll-not-restored")
    before = matrix.get("canonical_scroll_value_before")
    after = matrix.get("canonical_scroll_value_after")
    if type(before) is not int or type(after) is not int or before != after:
        issues.append("canonical-scroll-value-mismatch")
    if require_complete:
        for state in DIALOG_SCROLL_FOUR_STATE_NAMES:
            if state not in seen:
                issues.append(f"missing-scroll-state:{state}")
    return tuple(dict.fromkeys(issues))


def session_summary_capture_issue_codes(
    evidence: dict[str, Any],
    *,
    require_expanded: bool = False,
    require_little_scroll: bool = False,
    require_scroll: bool = False,
    require_retina: bool = False,
) -> tuple[str, ...]:
    """Return fail-closed issue codes for the Session Summary capture audit.

    The live capture code owns measurement; this pure reducer makes the
    release contract independently unit-testable without importing Anki or
    Qt.  It intentionally validates the dense, cards-remaining fixture used by
    the single permanent Session Summary surface.
    """

    issues: list[str] = []

    for key in (
        "visible",
        "contained",
        "viewport_size_passed",
        "parent_is_main_webview",
        "focus_safe",
        "shell_siblings",
        "footer_viewport_clear",
        "last_body_reachable",
        "final_boost_reachable",
        "copy_passed",
        "zero_sections_passed",
        "accounting_passed",
        "progress_passed",
        "authoritative_cards_total_passed",
        "actions_passed",
        "highlights_passed",
        "art_passed",
        "boost_art_passed",
        "boost_layout_passed",
        "garden_item_taxonomy_passed",
        "standard_find_identity_passed",
        "hero_spacing_passed",
        "static_card_semantics_passed",
        "open_garden_capitalization_passed",
    ):
        if evidence.get(key) is not True:
            issues.append(key.replace("_", "-"))

    bounds = list(evidence.get("bounds", ()) or ())
    expected_bounds = list(evidence.get("expected_bounds", ()) or ())
    if len(bounds) != 4 or bounds != expected_bounds:
        issues.append("panel-geometry")
    if len(bounds) == 4 and int(bounds[2]) != 416:
        issues.append("panel-width")
    if int(evidence.get("right_margin", -1)) < 20:
        issues.append("right-margin")
    if int(evidence.get("top_margin", -1)) < 16:
        issues.append("top-margin")
    if int(evidence.get("bottom_margin", -1)) < 16:
        issues.append("bottom-margin")
    header_height = int(evidence.get("header_height", -1))
    if evidence.get("compact_density") is True:
        if header_height != 44:
            issues.append("header-height")
    elif not 52 <= header_height <= 56:
        issues.append("header-height")
    if int(evidence.get("scroll_count", -1)) != 1:
        issues.append("scroll-owner-count")
    if int(evidence.get("horizontal_scroll_maximum", -1)) != 0:
        issues.append("horizontal-scroll")

    expected_order = (
        "hero",
        "today",
        "highlights",
        "rewards",
        "active_boosts",
    )
    if tuple(evidence.get("information_order", ()) or ()) != expected_order:
        issues.append("information-order")
    clearance_bottom = evidence.get("summary_home_clearance_bottom")
    clearance_telemetry = evidence.get("summary_home_clearance_telemetry")
    clearance_rect = (
        clearance_telemetry.get("rect")
        if isinstance(clearance_telemetry, dict) else
        None
    )
    clearance_viewport = (
        clearance_telemetry.get("viewport")
        if isinstance(clearance_telemetry, dict) else
        None
    )
    summary_bounds = list(evidence.get("bounds", ()) or ())
    container_size = list(evidence.get("container_size", ()) or ())
    measurement_fresh = bool(
        isinstance(clearance_telemetry, dict)
        and clearance_telemetry.get("schema_version") == 1
        and clearance_telemetry.get("source") == "home-garden-dom"
        and clearance_telemetry.get("measured") is True
        and evidence.get("summary_home_clearance_measured") is True
        and isinstance(clearance_rect, dict)
        and isinstance(clearance_viewport, dict)
        and len(container_size) == 2
        and abs(
            int(clearance_viewport.get("width", -1))
            - int(container_size[0])
        ) <= 2
        and abs(
            int(clearance_viewport.get("height", -1))
            - int(container_size[1])
        ) <= 2
    )
    geometric_overlap = bool(
        measurement_fresh
        and len(summary_bounds) == 4
        and min(
            int(clearance_rect.get("right", -1)),
            int(summary_bounds[0]) + int(summary_bounds[2]),
        ) > max(
            int(clearance_rect.get("left", -1)),
            int(summary_bounds[0]),
        )
    )
    overlap_contract = bool(
        evidence.get("summary_home_clearance_horizontal_overlap")
        is geometric_overlap
        and (
            type(clearance_bottom) is int
            and clearance_bottom > 0
            and evidence.get("summary_home_clearance_source")
            == "home-garden-dom"
            and evidence.get("summary_home_clearance_applied") is True
            and int(clearance_rect.get("bottom", -1)) == clearance_bottom
            and int(evidence.get("top_margin", -1)) >= clearance_bottom + 16
            if geometric_overlap else
            clearance_bottom is None
            and evidence.get("summary_home_clearance_source") == "none"
            and evidence.get("summary_home_clearance_applied") is False
            and int(evidence.get("top_margin", -1)) >= 16
        )
    )
    if not (measurement_fresh and overlap_contract):
        issues.append("home-garden-exclusion")
    if list(evidence.get("reward_metric_order", ()) or ()) != [
        "total_growth",
        "garden_coins",
        "standard_finds",
    ]:
        issues.append("reward-metric-order")
    if evidence.get("project_progress_placement") != "breakdown":
        issues.append("project-progress-placement")
    if int(evidence.get("landmark_growth_units", -1) or 0) != 0:
        issues.append("unexpected-landmark-growth")
    if int(evidence.get("project_growth_units", -1) or 0) != 12_500:
        issues.append("project-growth-units")
    if int(evidence.get("project_allocation_count", -1) or 0) != 1:
        issues.append("project-allocation-count")
    if require_expanded:
        if evidence.get("growth_breakdown_expanded") is not True:
            issues.append("growth-breakdown-not-expanded")
        if evidence.get("expanded_accounting_copy_passed") is not True:
            issues.append("expanded-accounting-copy")
    elif evidence.get("growth_breakdown_expanded") is not False:
        issues.append("growth-breakdown-not-collapsed")

    scroll_maximum = int(evidence.get("vertical_scroll_maximum", -1))
    if require_little_scroll and scroll_maximum != 0:
        issues.append("unexpected-default-scroll")
    if require_scroll and scroll_maximum <= 0:
        issues.append("missing-required-scroll")

    if require_retina:
        try:
            dpr = float(evidence.get("device_pixel_ratio", 0.0))
        except (TypeError, ValueError):
            dpr = 0.0
        if not 1.9 <= dpr <= 2.1:
            issues.append("retina-device-pixel-ratio")

    return tuple(dict.fromkeys(issues))


def reviewer_hud_growth_destination_issue_codes(
    evidence: Any,
) -> tuple[str, ...]:
    """Require the Full Bloom HUD to expose one typed Mastery destination."""

    if not isinstance(evidence, dict):
        return ("reviewer-hud-project-destination-missing",)
    expected = {
        "visible": True,
        "kind": "active_project",
        "target_type": "mastery",
        "target_id": "bonsai",
        "artwork_id": "mastery_bronze",
        "heading": "Bonsai Cultivation Mastery",
        "status": "In progress",
        "next_action": "growth_destination",
        "stored_growth_units": 1_250,
        "frame_kind": "active_project",
        "frame_target_type": "mastery",
        "frame_target_id": "bonsai",
        "frame_artwork_id": "mastery_bronze",
    }
    issues = [
        f"reviewer-hud-project-destination:{key}"
        for key, value in expected.items()
        if evidence.get(key) != value
    ]
    if "Open Collection" not in str(evidence.get("accessible_name", "")):
        issues.append("reviewer-hud-project-destination:collection-route")
    return tuple(issues)


def session_summary_project_effect_issue_codes(
    evidence: Any,
    *,
    require_rendered_project: bool,
) -> tuple[str, ...]:
    """Require one typed Landmark allocation and card-counted Fertilizer."""

    if not isinstance(evidence, dict):
        return ("session-project-effect-evidence-missing",)
    issues: list[str] = []
    if evidence.get("typed_project_allocations") != [[
        "landmark",
        "garden_landmark",
        12_500,
    ]]:
        issues.append("session-project-allocation-source")
    if evidence.get("fertilizer_effect_rows") != [{
        "effect_id": "capture-fertilizer",
        "remaining_cards": 38,
        "remaining_seconds": 0,
        "expires_at_epoch_seconds": 0,
        "value": "38 cards remaining",
    }]:
        issues.append("session-fertilizer-source")
    if evidence.get("rendered_fertilizer_rows") != [{
        "kind": "fertilizer",
        "value": "38 cards remaining",
        "artwork_id": "fertilizer_quality",
    }]:
        issues.append("session-fertilizer-rendering")
    if require_rendered_project:
        rendered = evidence.get("rendered_project_allocations")
        if not (
            isinstance(rendered, list)
            and len(rendered) == 1
            and rendered[0].get("target_type") == "landmark"
            and rendered[0].get("target_id") == "garden_landmark"
            and rendered[0].get("row_key")
            == "project:landmark:garden_landmark"
            and rendered[0].get("artwork_id")
            == "landmark_glasshouse_conservatory"
            and "Garden Landmark" in str(rendered[0].get("copy", ""))
            and "+125" in str(rendered[0].get("copy", ""))
        ):
            issues.append("session-project-allocation-rendering")
    return tuple(issues)


def sync_reward_project_allocation_issue_codes(
    evidence: Any,
) -> tuple[str, ...]:
    """Require canonical Sync allocation order without scalar double-counting."""

    if not isinstance(evidence, dict):
        return ("sync-project-allocation-evidence-missing",)
    issues: list[str] = []
    content = evidence.get("content")
    raw_allocations = (
        content.get("project_allocations", ())
        if isinstance(content, dict) else ()
    )
    try:
        allocations = [list(row) for row in raw_allocations]
    except TypeError:
        allocations = []
    if not isinstance(content, dict) or (
        content.get("shared_growth_delta_units") != 8_000
        or content.get("landmark_growth_delta_units") != 2_000
        or allocations != [[
            "landmark",
            "garden_landmark",
            2_000,
        ]]
    ):
        issues.append("sync-project-allocation-source")
    if evidence.get("allocation_records") != [
        {
            "target_type": "",
            "target_id": "",
            "units": 8_000,
            "amount": "+80",
            "label": "Shared Growth",
            "status": "",
            "artwork_id": "shared_growth",
        },
        {
            "target_type": "landmark",
            "target_id": "garden_landmark",
            "units": 2_000,
            "amount": "+20",
            "label": "Stored Growth added to Garden Landmark",
            "status": "In progress",
            "artwork_id": "landmark_glasshouse_conservatory",
        },
    ]:
        issues.append("sync-project-allocation-rendering")
    return tuple(issues)


