def expected_capture_window_family(label: str) -> str:
    """Return the exact renderer family required for one manifest fixture."""

    try:
        surface = REGISTRY[str(label)]
    except KeyError:
        return ""
    return surface.renderer_family if surface.active else ""


def expected_capture_state_profile(label: str) -> dict[str, Any]:
    """Return the state-specific fixture profile required by one capture label.

    Renderer identity alone cannot distinguish two states rendered by the same
    dialog.  Every manifest label therefore receives an exact profile which is
    checked against live widget and storage state immediately before pixels are
    saved.
    """

    family = expected_capture_window_family(label)
    if not family:
        return {}
    profile: dict[str, Any] = {
        "profile_id": label,
        "window_family": family,
    }
    if label in _HOME_CAPTURE_LABELS:
        if label in {
            "session-summary-after-review",
            "sync-rewards-summary",
        }:
            surface = "deckBrowser"
        elif label == "home-preview-error":
            surface = "overview"
        elif label.startswith("home-preview-"):
            surface = "deckBrowser"
        else:
            surface = "deckBrowser" if "deck-browser" in label else "overview"
        if label == "home-preview-loading":
            fixture_state = "preview-loading"
        elif label == "home-preview-error":
            fixture_state = "preview-error"
        elif label == "home-preview-stale":
            fixture_state = "preview-stale"
        elif label.startswith("starter-"):
            fixture_state = "starter-not-selected"
        elif label in {"deck-browser-home", "overview-home"}:
            fixture_state = "starter-planted-not-nurtured"
        else:
            fixture_state = "nurtured-active"
        profile.update({
            "kind": "home",
            "surface": surface,
            "fixture_state": fixture_state,
        })
        match = re.search(r"-plot-(\d+)$", label)
        if match:
            profile["active_slot"] = int(match.group(1)) - 1
        return profile
    if label == "collection-known-not-collected-overview":
        profile.update({
            "kind": "dialog",
            "state": "known-not-collected-rare-mystery",
        })
        return profile
    if label in _REVIEWER_CAPTURE_LABELS:
        if label in {
            "reviewer-hud-expanded",
            "reviewer-reward-dock-bundle",
        }:
            profile.update({
                "kind": "reviewer_hud",
                "state": label,
                "expanded": True,
                "dock": "right",
            })
            if label == "reviewer-reward-dock-bundle":
                profile["reward_event_count"] = 7
            return profile
        profile.update({
            "kind": "reviewer",
            "state": label,
            "toast_tier": (
                "Common" if label in {
                    "reviewer-find-common-reduced-motion",
                } else
                "Rare" if label == "reviewer-find-environment" else
                ""
            ),
            "stacked_sync": False,
            "reduced_motion": label == "reviewer-find-common-reduced-motion",
        })
        return profile
    if label in _DASHBOARD_CAPTURE_LABELS:
        profile.update({"kind": "dashboard", "state": label})
        return profile
    if label in _PROGRESS_CAPTURE_LABELS:
        page = (
            "today" if label == "progress-today-cards" else
            "growth" if label.startswith("growth-") else
            "streak" if label.startswith("streak-") else
            "currency" if label.startswith("coins-") else
            "growth" if label == "progress-overview-redirect-growth" else
            "collection" if label in {
                "progress-collection",
                "collection-several-discovered",
            "collection-no-filter-matches",
            "collection-known-not-collected-overview",
            "collection-environment-mechanics",
            } else
            "achievements"
        )
        profile.update({"kind": "progress", "page": page, "state": label})
        return profile
    growth_charge_status_by_label = {
        "growth-charge-use-ready": "ready",
        "growth-charge-empty-inventory": "empty_inventory",
        "growth-charge-loading-disabled": "loading",
        "growth-charge-stale-inventory": "stale_inventory",
        "growth-charge-invalid-target": "target_invalid",
        "growth-charge-persistence-failure": "persistence_failure",
        "growth-charge-success-stage-reward": "success",
    }
    if label in growth_charge_status_by_label:
        profile.update({
            "kind": "dialog",
            "state": label,
            "growth_charge_status": growth_charge_status_by_label[label],
        })
        if label == "growth-charge-stale-inventory":
            profile["growth_charge_fixture_semantics"] = (
                "ready_with_stale_inventory_warning"
            )
        return profile
    if label in _NURSERY_CAPTURE_LABELS:
        tab_by_label = {
            "starter-nursery-plants": 0,
            "starter-action-above-footer": 0,
            "nursery-plants": 0,
            "nursery-fertilizer-booster": 1,
            "nursery-garden-spaces": 2,
            "nursery-garden-decorations-scenery": 3,
            "nursery-item-owned": 0,
            "nursery-item-locked": 1,
            "nursery-purchase-success": 3,
            "nursery-final-row-above-footer": 0,
            "missing-artwork-graphical-fallback": 3,
            "purchase-success-inventory-collection": 0,
            "purchase-success-fertilizer-applied": 1,
            "purchase-success-garden-bed-unlocked": 2,
            "nursery-empty-state": 0,
        }
        profile.update({
            "kind": "nursery",
            "tab": tab_by_label[label],
            "state": label,
            "starter_mode": label.startswith("starter-"),
        })
        return profile
    if label in _SETTINGS_CAPTURE_LABELS:
        diagnostics_labels = {
            "diagnostics-clean",
            "diagnostics-warning",
            "diagnostics-expanded",
            "production-build-controls-absent",
        }
        profile.update({
            "kind": "settings",
            "tab": 1 if label in diagnostics_labels else 0,
            "state": label,
        })
        return profile
    if label in {
        "collection-loadout-detail",
        "collection-preview-active",
        "collection-preview-restored",
        "collection-loadout-persistence-error",
    }:
        profile.update({"kind": "collectible-detail", "state": label})
        return profile
    purchase_status_by_label = {
        "purchase-confirmation-species": "ready",
        "purchase-confirmation-growth-charge": "ready",
        "purchase-confirmation-environment": "ready",
        "purchase-confirmation-fertilizer-application": "ready",
        "purchase-confirmation-fertilizer-extension": "ready",
        "purchase-confirmation-fertilizer-queue": "ready",
        "purchase-confirmation-garden-bed": "ready",
        "purchase-confirmation-loading-disabled": "loading",
        "purchase-error-insufficient-coins": "insufficient_coins",
        "purchase-error-persistence-failure": "persistence_failure",
        "purchase-error-item-unavailable": "item_unavailable",
        "purchase-error-already-owned": "already_owned",
        "purchase-error-invalid-target": "target_invalid",
        "purchase-error-stale-price": "stale_price",
        "purchase-error-stale-balance": "stale_balance",
    }
    if label in purchase_status_by_label:
        profile.update({
            "kind": "dialog",
            "state": label,
            "purchase_status": purchase_status_by_label[label],
        })
        if label == "purchase-error-stale-balance":
            profile["purchase_fixture_semantics"] = (
                "ready_with_balance_update"
            )
        return profile
    profile.update({"kind": "dialog", "state": label})
    return profile


def resize_geometry_acceptance(
    *,
    label: str,
    declared_size: list[int] | tuple[int, int],
    actual_size: list[int] | tuple[int, int],
    minimum_size: list[int] | tuple[int, int],
    maximum_size: list[int] | tuple[int, int],
    screen_limited: bool,
    constraint_limited: bool,
    native_normalized: bool,
    normalization_reason: str,
) -> dict[str, Any]:
    """Classify requested-to-actual drift without hiding unsafe clamps.

    Breakpoint probes keep their declared width within one logical pixel so a
    native resize cannot cross or collapse the audited boundary.  Height may be
    reduced by the window manager, but it must remain inside the widget's
    declared constraints and may never grow unexpectedly beyond the request.
    """

    declared_width, declared_height = (int(value) for value in declared_size)
    actual_width, actual_height = (int(value) for value in actual_size)
    minimum_width, minimum_height = (int(value) for value in minimum_size)
    maximum_width, maximum_height = (int(value) for value in maximum_size)
    exact = [actual_width, actual_height] == [declared_width, declared_height]
    breakpoint_fixture = (
        "-content-" in str(label)
        or "-breakpoint-" in str(label)
    )
    reasons = {
        token.strip()
        for token in str(normalization_reason or "").split(",")
        if token.strip()
    }
    provenance_flags = {
        "screen_limited": bool(screen_limited),
        "constraint_limited": bool(constraint_limited),
        "native_normalized": bool(native_normalized),
    }
    provenance_tokens_match = (
        (not screen_limited or "extends-beyond-available-screen" in reasons)
        and (not constraint_limited or "widget-constraint" in reasons)
        and (not native_normalized or "native-frame-or-scale" in reasons)
    )
    provenance_explains_drift = bool(any(provenance_flags.values())) and bool(
        reasons
    ) and provenance_tokens_match
    breakpoint_width_within_one = (
        not breakpoint_fixture
        or abs(actual_width - declared_width) <= 1
    )
    safe_bounded_width = (
        max(1, minimum_width) <= actual_width <= max(1, maximum_width)
        and actual_width <= max(declared_width + 1, minimum_width)
    )
    safe_bounded_height = (
        max(1, minimum_height) <= actual_height <= max(1, maximum_height)
        and actual_height <= max(declared_height + 1, minimum_height)
    )
    accepted = exact or (
        provenance_explains_drift
        and breakpoint_width_within_one
        and safe_bounded_width
        and safe_bounded_height
    )
    return {
        "exact": exact,
        "drifted": not exact,
        "accepted": accepted,
        "breakpoint_fixture": breakpoint_fixture,
        "breakpoint_width_within_one": breakpoint_width_within_one,
        "safe_bounded_width": safe_bounded_width,
        "safe_bounded_height": safe_bounded_height,
        "provenance_explains_drift": provenance_explains_drift,
        "provenance_flags": provenance_flags,
        "normalization_reasons": sorted(reasons),
        "declared_client_size": [declared_width, declared_height],
        "actual_client_size": [actual_width, actual_height],
        "minimum_client_size": [minimum_width, minimum_height],
        "maximum_client_size": [maximum_width, maximum_height],
    }


def intentional_scroll_viewport_exemption(
    *,
    candidate_rect: list[int] | tuple[int, int, int, int],
    viewport_rect: list[int] | tuple[int, int, int, int],
    horizontal_scrollable: bool,
    vertical_scrollable: bool,
) -> bool:
    """Return whether a widget is wholly outside an intentional scroll viewport.

    An empty QWidget visible region is normally evidence of clipping or
    occlusion.  The sole safe exemption is content beyond a scroll viewport on
    axes that are actually reachable through a nonzero scrollbar range.
    """

    left, top, width, height = (int(value) for value in candidate_rect)
    view_left, view_top, view_width, view_height = (
        int(value) for value in viewport_rect
    )
    if width <= 0 or height <= 0 or view_width <= 0 or view_height <= 0:
        return False
    right = left + width
    bottom = top + height
    view_right = view_left + view_width
    view_bottom = view_top + view_height
    outside_horizontal = right <= view_left or left >= view_right
    outside_vertical = bottom <= view_top or top >= view_bottom
    if not outside_horizontal and not outside_vertical:
        return False
    return (
        (not outside_horizontal or bool(horizontal_scrollable))
        and (not outside_vertical or bool(vertical_scrollable))
    )


def canonicalize_development_stress_plants(
    plants: list[Any],
    species_order: list[str] | tuple[str, ...],
    generated_name: Callable[[str], str],
) -> list[Any]:
    """Return every development plant in deterministic source-catalog order."""

    order = tuple(str(species) for species in species_order)
    rank = {species: index for index, species in enumerate(order)}
    canonical = sorted(
        list(plants),
        key=lambda plant: (
            rank.get(str(getattr(plant, "species", "") or ""), len(rank)),
            str(getattr(plant, "species", "") or ""),
            str(getattr(plant, "plant_id", "") or ""),
        ),
    )
    for plant in canonical:
        species = str(getattr(plant, "species", "") or "")
        plant.name = str(generated_name(species))
        plant.name_customized = False
    return canonical


def restore_capture_plant_order(
    plants: list[Any],
    plant_id_order: list[str] | tuple[str, ...],
) -> list[Any]:
    """Restore exact runtime order after a state serialization round trip."""

    expected = tuple(str(plant_id) for plant_id in plant_id_order)
    by_id: dict[str, Any] = {}
    for plant in plants:
        plant_id = str(getattr(plant, "plant_id", "") or "")
        if not plant_id or plant_id in by_id:
            raise ValueError("Capture fixture plants require unique non-empty IDs")
        by_id[plant_id] = plant
    if len(expected) != len(set(expected)) or set(expected) != set(by_id):
        raise ValueError("Capture fixture plant IDs changed across restoration")
    return [by_id[plant_id] for plant_id in expected]


def start_capture(app: Any) -> None:
    """Launch the UI-face capture sequence for a running add-on instance."""
    _UiFaceCaptureRunner(app).start()


class _UiFaceCaptureRunner:
    def __init__(self, app: Any) -> None:
        self.app = app
        self._capture_started_at = datetime.now().isoformat(timespec="milliseconds")
        self._capture_started_monotonic = time.perf_counter()
        self._capture_requested_monotonic: dict[str, float] = {}
        self._performance_samples: dict[str, list[float]] = {
            "garden_open_ms": [],
        }
        self._development_stress_ready = False
        self._development_stress_checkpoint: Any | None = None
        self._active_scenario_snapshot: Any | None = None
        self._finished = False
        self._fatal_fixture_restore_failure = False
        self._active_fixture_source = "capture-runner-initialization"
        self._active_fixture_expected_label = ""
        self.capture_root = Path(
            os.environ.get(
                "ANKI_GARDEN_UI_CAPTURE_DIR",
                os.environ.get(
                    "ANKI_GARDEN_CAPTURE_DIR",
                    str(
                        Path(__file__).resolve().parent
                        / ".."
                        / ".."
                        / "build"
                        / "ui-face-captures"
                    ),
                ),
            )
        ).expanduser()
        self.session_dir = self.capture_root / datetime.now().strftime("%Y%m%d-%H%M%S")
        self.session_dir.mkdir(parents=True, exist_ok=True)
        self._screenshots: list[str] = []
        self._capture_records: list[dict[str, Any]] = []
        self._capture_annotations: dict[str, dict[str, Any]] = {}
        self._capture_phase_timings: dict[str, dict[str, Any]] = {}
        self._capture_calibration: dict[str, Any] = {
            "status": "not-run",
            "passed": False,
        }
        self._active_home_fixture_state = ""
        self._active_home_dom_audit: dict[str, Any] = {}
        self._active_reviewer_dom_audit: dict[str, Any] = {}
        self._first_run_sequence_evidence: dict[str, Any] = {}
        self._fertilizer_flow_source_plant_id = ""
        self._fertilizer_flow_source_plant_name = ""
        self._fertilizer_flow_source_snapshot: dict[str, Any] = {}
        self._thirty_day_reward_evidence: dict[str, dict[str, Any]] = {}
        self._text_layout_warnings: list[dict[str, Any]] = []
        self._capture_advisories: list[dict[str, Any]] = []
        self._failures: list[dict[str, str]] = []
        self._step_index = 0
        self._capture_index = 1
        self._reserved_capture_labels: set[str] = set()
        self._starter_seed_attempts = 0
        self._capture_display = "primary"
        self._capture_force_primary = False
        self._foreground_policy = str(
            os.environ.get("ANKI_GARDEN_CAPTURE_FOREGROUND_POLICY", "required-only")
        ).strip().lower()
        self._foreground_requests: list[dict[str, Any]] = []
        self._requested_scale_factor = os.environ.get("QT_SCALE_FACTOR", "system")
        self._active_geometry_request: dict[str, Any] | None = None
        self._phase = "starter"
        self._capture_profile = str(
            os.environ.get(
                "ANKI_GARDEN_CAPTURE_PROFILE",
                "representative",
            )
            or "representative"
        ).strip().lower()
        if self._capture_profile not in REGISTRY.profile_names:
            self._failures.append({
                "label": "capture-profile",
                "reason": f"Unsupported capture profile: {self._capture_profile}",
            })
            self._capture_profile = "representative"
        self._capture_face_groups = REGISTRY.profile_groups(self._capture_profile)
        self._capture_face_labels = REGISTRY.profile_labels(self._capture_profile)

        def bind_step(label: str) -> Callable[[], None]:
            surface = REGISTRY[label]
            method = getattr(self, surface.executor, None)
            if not callable(method):
                raise AttributeError(
                    f"Capture executor {surface.executor!r} is unavailable for {label!r}"
                )
            return partial(method, *surface.arguments)

        try:
            ordered_steps = tuple(
                (label, bind_step(label))
                for label in self._capture_face_labels
            )
        except (AttributeError, TypeError, ValueError) as exc:
            self._failures.append({
                "label": "capture-registry",
                "reason": f"Capture registry could not bind an executor: {exc}",
            })
            ordered_steps = ()
        self._starter_steps = [
            row for row in ordered_steps
            if REGISTRY[row[0]].checkpoint_cohort == "starter"
        ]
        self._release_steps = [
            row for row in ordered_steps
            if REGISTRY[row[0]].checkpoint_cohort != "starter"
        ]
        starter_count = len(self._starter_steps)
        self._capture_step_registry = dict(ordered_steps)
        if len(self._capture_step_registry) != len(self._capture_face_labels):
            self._failures.append({
                "label": "capture-registry",
                "reason": "Capture registry contains a duplicate or missing surface",
            })
        scenario_callables = {
            surface.stable_id: surface.executor
            for surface in REGISTRY.active_surfaces
        }
        if (
            set(scenario_callables) != set(EXHAUSTIVE_CAPTURE_FACE_LABELS)
            or any(label not in scenario_callables for label in self._capture_face_labels)
        ):
            self._failures.append({
                "label": "capture-scenario-registry",
                "reason": "SurfaceSpec executors do not exactly cover the active contract",
            })

        requested_payload = os.environ.get(
            "ANKI_GARDEN_CAPTURE_SURFACES_JSON",
            "",
        ).strip()
        requested_values: list[str] = []
        if requested_payload:
            try:
                raw_requested = json.loads(requested_payload)
                if not isinstance(raw_requested, list):
                    raise ValueError("surface selection must be a list")
                requested_values = [str(value).strip() for value in raw_requested]
            except (TypeError, ValueError, json.JSONDecodeError) as exc:
                self._failures.append({
                    "label": "capture-selection",
                    "reason": f"Capture surface selection was invalid: {type(exc).__name__}",
                })
        requested_set = set(
            requested_values
            if requested_payload
            else self._capture_face_labels
        )
        unknown_requested = requested_set - set(self._capture_face_labels)
        if unknown_requested:
            self._failures.append({
                "label": "capture-selection",
                "reason": (
                    "Unknown capture surfaces: "
                    + ", ".join(sorted(unknown_requested))
                ),
            })
        self._requested_face_labels = tuple(
            label for label in self._capture_face_labels if label in requested_set
        )
        self._capture_scope = (
            "full"
            if self._requested_face_labels == self._capture_face_labels
            else "patch"
        )

        # Resolve the source-owned setup closure for either canonical profile.
        # Prerequisites execute in contract order but never save a PNG unless
        # they were independently requested. This makes a one-face full audit
        # reach the same checkpoint as the complete registry-derived sequence.
        execution_labels = set(self._requested_face_labels)
        changed = True
        while changed:
            changed = False
            for label in tuple(execution_labels):
                for prerequisite in capture_scenario_prerequisites(label):
                    if (
                        prerequisite in self._capture_step_registry
                        and prerequisite not in execution_labels
                    ):
                        execution_labels.add(prerequisite)
                        changed = True
        self._setup_only_face_labels = tuple(
            label for label in self._capture_face_labels
            if label in execution_labels and label not in self._requested_face_labels
        )
        self._starter_steps = [
            row for row in self._starter_steps if row[0] in execution_labels
        ]
        self._release_steps = [
            row for row in self._release_steps if row[0] in execution_labels
        ]
        self._steps = self._starter_steps

        self._production_package_sha256 = str(
            os.environ.get("ANKI_GARDEN_PRODUCTION_PACKAGE_SHA256", "")
        ).strip()
        self._capture_environment_digest = str(
            os.environ.get("ANKI_GARDEN_CAPTURE_ENVIRONMENT_DIGEST", "")
        ).strip()
        self._render_inputs: dict[str, Any] = {}
        render_inputs_path = str(
            os.environ.get("ANKI_GARDEN_RENDER_INPUTS_PATH", "")
        ).strip()
        if render_inputs_path:
            try:
                loaded_inputs = json.loads(
                    Path(render_inputs_path).read_text(encoding="utf-8")
                )
                if not isinstance(loaded_inputs, dict):
                    raise ValueError("render-input catalog must be an object")
                self._render_inputs = loaded_inputs
            except (OSError, ValueError, json.JSONDecodeError) as exc:
                self._failures.append({
                    "label": "capture-provenance",
                    "reason": f"Render-input catalog was invalid: {type(exc).__name__}",
                })
        else:
            self._failures.append({
                "label": "capture-provenance",
                "reason": "Render-input catalog was not provided",
            })
        try:
            raw_invalidated = json.loads(
                os.environ.get("ANKI_GARDEN_INVALIDATED_SURFACES_JSON", "[]")
            )
            self._invalidated_face_labels = [
                str(value) for value in raw_invalidated
            ] if isinstance(raw_invalidated, list) else []
        except json.JSONDecodeError:
            self._invalidated_face_labels = []
        render_surfaces = dict(self._render_inputs.get("surfaces", {}) or {})
        self._capture_surface_registry = {
            label: {
                "capture_id": index,
                "label": label,
                "scenario_id": capture_scenario_id(label),
                "fixture_id": capture_fixture_id(label),
                "scenario_step": capture_scenario_step(label),
                "phase": "starter" if index <= starter_count else "release",
                "renderer_family": expected_capture_window_family(label),
                "readiness_policy": (
                    "web-composite" if label in _HOME_CAPTURE_LABELS else "native-layout"
                ),
                "render_input_digest": str(
                    dict(render_surfaces.get(label, {}) or {}).get("digest", "")
                ),
                "scenario_identity_digest": str(
                    dict(render_surfaces.get(label, {}) or {}).get(
                        "scenario_identity_digest",
                        "",
                    )
                ),
                "surface_contract_digest": str(
                    dict(render_surfaces.get(label, {}) or {}).get(
                        "surface_contract_digest",
                        "",
                    )
                ),
                "checkpoint": capture_scenario_checkpoint(label),
                "prerequisites": list(capture_scenario_prerequisites(label)),
                "internal_setups": list(capture_scenario_internal_setups(label)),
                "callable": scenario_callables.get(label, ""),
                "step": self._capture_step_registry.get(label),
            }
            for index, label in enumerate(self._capture_face_labels, start=1)
        }
        self._write_progress_manifest()

    @staticmethod
    def _atomic_json(path: Path, payload: dict[str, Any]) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary = path.with_name(f".{path.name}.tmp")
        temporary.write_text(
            json.dumps(payload, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )
        os.replace(temporary, path)

    def _run_level_evidence_payload(self) -> dict[str, Any]:
        run_level_digest = str(
            dict(getattr(self, "_render_inputs", {}) or {}).get(
                "run_level_digest",
                "",
            )
        )
        return {
            "clean_shutdown": {
                "required": True,
                "status": "pending",
                "passed": False,
                "capture_environment_digest": str(
                    getattr(self, "_capture_environment_digest", "")
                ),
                "run_level_digest": run_level_digest,
            },
            "dialog_memory_probe": {
                "required": False,
                "requested": False,
                "status": "not-run",
                "passed": False,
                "run_level_digest": run_level_digest,
                "result": {
                    "status": "not-run",
                    "cycles": 0,
                    "reason": "memory leak probing is not part of capture",
                },
            },
        }

    def _progress_manifest_payload(self) -> dict[str, Any]:
        expected = list(getattr(self, "_capture_face_labels", ()))
        requested = list(getattr(self, "_requested_face_labels", expected))
        records = list(getattr(self, "_capture_records", ()))
        captured = [str(record.get("label", "")) for record in records]
        groups = list(getattr(self, "_capture_face_groups", ()))
        profile = str(getattr(self, "_capture_profile", "representative"))
        return {
            "capture_contract_version": CAPTURE_CONTRACT_VERSION,
            "capture_contract_digest": capture_contract_digest(profile),
            "scenario_schema_version": CAPTURE_SCENARIO_SCHEMA_VERSION,
            "scenario_contract_digest": str(
                dict(getattr(self, "_render_inputs", {}) or {}).get(
                    "scenario_contract_digest",
                    "",
                )
            ),
            "evidence_schema_digest": str(
                dict(getattr(self, "_render_inputs", {}) or {}).get(
                    "evidence_schema_digest",
                    "",
                )
            ),
            "capture_profile": profile,
            "capture_scope": "patch",
            "capture_groups": [
                {"name": name, "labels": list(labels)}
                for name, labels in groups
            ],
            "expected_faces": expected,
            "expected_count": len(expected),
            "requested_faces": requested,
            "captured_faces": captured,
            "reused_faces": [],
            "invalidated_faces": list(
                getattr(self, "_invalidated_face_labels", ())
            ),
            "setup_only_steps": [
                {
                    "label": label,
                    "reason": "scenario-prerequisite",
                    "required_by": [
                        requested_label for requested_label in requested
                        if label in capture_scenario_prerequisites(requested_label)
                    ],
                }
                for label in getattr(self, "_setup_only_face_labels", ())
            ],
            "scenario_setup_closures": {
                label: {
                    "scenario_id": capture_scenario_id(label),
                    "fixture_id": capture_fixture_id(label),
                    "scenario_step": capture_scenario_step(label),
                    "capture_prerequisites": list(
                        capture_scenario_prerequisites(label)
                    ),
                    "internal_setups": list(
                        capture_scenario_internal_setups(label)
                    ),
                    "checkpoint": capture_scenario_checkpoint(label),
                }
                for label in requested
            },
            "screenshots": list(getattr(self, "_screenshots", ())),
            "captures": records,
            "failures": self._classified_failure_records(),
            "capture_advisories": self._classified_advisory_records(),
            "text_layout_warnings": list(
                getattr(self, "_text_layout_warnings", ())
            ),
            "requested_scale_factor": str(
                getattr(self, "_requested_scale_factor", "system")
            ),
            "capture_calibration": dict(
                getattr(self, "_capture_calibration", {}) or {}
            ),
            "capture_environment_digest": str(
                getattr(self, "_capture_environment_digest", "")
            ),
            "production_package_sha256": str(
                getattr(self, "_production_package_sha256", "")
            ),
            "render_inputs": dict(getattr(self, "_render_inputs", {}) or {}),
            "run_level_evidence": self._run_level_evidence_payload(),
            "progress_journal": {
                "directory": str(self.session_dir / "progress"),
                "record_count": len(records),
                "updated_at": datetime.now().isoformat(timespec="milliseconds"),
            },
            "fixture_validations_complete": False,
            "dialog_scroll_audits_complete": False,
            "scope_complete": False,
            "complete": False,
        }

    @staticmethod
    def _post_capture_lifecycle_failure(reason: str) -> bool:
        """Return whether a failure remains gross after valid pixels exist."""

        normalized = str(reason).casefold()
        return any(
            token in normalized
            for token in (
                "cleanup",
                "deferred delete",
                "checkpoint",
                "fixture state restoration",
                "could not be restored",
            )
        )

    def _partition_failure_records(
        self,
    ) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
        captured = {
            str(record.get("label", "")): bool(
                dict(record.get("capture_acceptance", {}) or {}).get(
                    "passed",
                    False,
                )
            )
            for record in getattr(self, "_capture_records", ())
        }
        records: list[dict[str, Any]] = []
        advisories: list[dict[str, Any]] = [
            dict(record)
            for record in getattr(self, "_capture_advisories", ())
            if isinstance(record, dict)
        ]
        checkpoint_failures: list[str] = []
        for raw in getattr(self, "_failures", ()):
            record = dict(raw)
            label = str(record.get("label", ""))
            reason = str(record.get("reason", ""))
            classification = classify_failure(
                REGISTRY,
                label=label,
                reason=reason,
                fatal_checkpoint_restore=bool(
                    self._fatal_fixture_restore_failure and label in REGISTRY
                ),
            )
            record["failure_classification"] = classification
            record.setdefault("blocked_by", "")
            if post_capture_surface_failure_is_advisory(
                CAPTURE_CONTRACT_VERSION,
                classification=classification,
                capture_passed=captured.get(label) is True,
                lifecycle_failure=self._post_capture_lifecycle_failure(reason),
                contract_gate=str(record.get("contract_gate", "") or ""),
            ):
                record["severity"] = "advisory"
                advisories.append(record)
                continue
            record["severity"] = "gross"
            records.append(record)
            if classification == "checkpoint-domain" and label in REGISTRY:
                checkpoint_failures.append(label)
        existing = {str(record.get("label", "")) for record in records}
        requested = set(getattr(self, "_requested_face_labels", ()))
        if CAPTURE_CONTRACT_VERSION >= 26:
            for capture_record in getattr(self, "_capture_records", ()):
                label = str(capture_record.get("label", ""))
                acceptance = capture_record.get("capture_acceptance")
                acceptance_passed = bool(
                    isinstance(acceptance, dict)
                    and acceptance.get("passed") is True
                )
                if (
                    label in requested
                    and label not in existing
                    and not acceptance_passed
                ):
                    records.append({
                        "label": label,
                        "reason": "v26 capture acceptance did not pass",
                        "failure_classification": "surface-local",
                        "blocked_by": "",
                        "severity": "gross",
                    })
                    existing.add(label)
        for blocker in checkpoint_failures:
            cohort = REGISTRY[blocker].checkpoint_cohort
            for surface in REGISTRY.active_surfaces:
                if (
                    surface.stable_id in requested
                    and surface.stable_id not in captured
                    and surface.stable_id not in existing
                    and surface.checkpoint_cohort == cohort
                ):
                    records.append({
                        "label": surface.stable_id,
                        "reason": f"Blocked by checkpoint failure {blocker}",
                        "failure_classification": "checkpoint-domain",
                        "blocked_by": blocker,
                        "severity": "gross",
                    })
                    existing.add(surface.stable_id)
        return records, advisories

    def _classified_failure_records(self) -> list[dict[str, Any]]:
        return self._partition_failure_records()[0]

    def _classified_advisory_records(self) -> list[dict[str, Any]]:
        return self._partition_failure_records()[1]

    def _write_progress_manifest(self) -> None:
        try:
            self._atomic_json(
                self.session_dir / "manifest.partial.json",
                self._progress_manifest_payload(),
            )
        except Exception:
            logger.error(
                "Anki Garden capture: could not persist the progress manifest",
                exc_info=True,
            )

    def _write_surface_progress(self, record: dict[str, Any]) -> None:
        try:
            capture_id = int(record.get("capture_id", 0) or 0)
            label = str(record.get("label", ""))
            width = max(2, len(str(len(self._capture_face_labels))))
            sidecar = self.session_dir / "progress" / (
                f"{capture_id:0{width}d}-{label}.json"
            )
            self._atomic_json(sidecar, {
                "capture_contract_version": CAPTURE_CONTRACT_VERSION,
                "capture_profile": self._capture_profile,
                "record": record,
            })
            self._write_progress_manifest()
        except Exception:
            logger.error(
                "Anki Garden capture: could not persist surface progress for %s",
                record.get("label", ""),
                exc_info=True,
            )

    def start(self) -> None:
        """Kick off capture after collection load and dashboard prerequisites."""
        self._wait_for_collection(self._prepare_capture_window, tries=120)

    def _prepare_capture_window(self) -> None:
        """Select one display only after geometry and DPR preflight."""

        try:
            screens = list(QGuiApplication.screens())
        except Exception:
            screens = []
        reports: list[dict[str, Any]] = []
        for index, screen in enumerate(screens):
            try:
                available = screen.availableGeometry()
                dpr = float(screen.devicePixelRatio())
                width = int(available.width())
                height = int(available.height())
                valid = bool(
                    width >= 1240
                    and height >= 840
                    and math.isfinite(dpr)
                    and dpr > 0
                )
                reports.append({
                    "index": index,
                    "name": str(getattr(screen, "name", lambda: "")()),
                    "available_geometry": [
                        int(available.x()),
                        int(available.y()),
                        width,
                        height,
                    ],
                    "device_pixel_ratio": dpr,
                    "valid": valid,
                })
            except Exception as exc:
                reports.append({
                    "index": index,
                    "name": "",
                    "available_geometry": [0, 0, 0, 0],
                    "device_pixel_ratio": 0.0,
                    "valid": False,
                    "error": type(exc).__name__,
                })
        primary_index = 0 if reports else -1
        selected_index = primary_index
        secondary_requested = (
            os.environ.get("ANKI_GARDEN_CAPTURE_SECOND_MONITOR", "1").lower()
            not in {"0", "false", "no"}
            and len(reports) >= 2
        )
        if secondary_requested and reports[1]["valid"]:
            primary_dpr = float(reports[0]["device_pixel_ratio"])
            secondary_dpr = float(reports[1]["device_pixel_ratio"])
            if not reports[0]["valid"]:
                selected_index = 1
                self._capture_force_primary = False
            elif abs(primary_dpr - secondary_dpr) <= 0.01:
                selected_index = 1
            else:
                self._capture_force_primary = True
        elif secondary_requested:
            self._capture_force_primary = True
        if selected_index >= 0 and not reports[selected_index]["valid"]:
            valid_indices = [
                int(report["index"]) for report in reports if report["valid"]
            ]
            if valid_indices:
                selected_index = valid_indices[0]
        self._capture_screen_index = selected_index
        self._capture_display_preflight = {
            "screens": reports,
            "secondary_requested": secondary_requested,
            "selected_index": selected_index,
            "passed": bool(
                selected_index >= 0 and reports[selected_index]["valid"]
            ),
        }
        if not self._capture_display_preflight["passed"]:
            self._failures.append({
                "label": "capture-display-preflight",
                "reason": "No display can contain the canonical 1240 by 840 client",
            })
        self._move_to_capture_display(mw)
        if (
            not self._capture_display_preflight["passed"]
            or not self._run_capture_calibration()
        ):
            self._write_progress_manifest()
            QTimer.singleShot(0, self._finish)
            return
        self._write_progress_manifest()
        QTimer.singleShot(80, self._prepare_starter_phase)

    def _run_capture_calibration(self) -> bool:
        """Validate the shared capture geometry before saving any evidence."""

        from ..ui.dashboard import ElidingLabel, set_button_size

        issues: list[str] = []
        measurements: dict[str, Any] = {}
        try:
            scale = float(self._requested_scale_factor)
        except (TypeError, ValueError):
            scale = math.nan
        if not math.isfinite(scale) or not math.isclose(scale, 1.0):
            issues.append("capture scale is not exactly 1.0")

        screens = list(QGuiApplication.screens())
        selected_index = int(getattr(self, "_capture_screen_index", -1))
        screen = (
            screens[selected_index]
            if 0 <= selected_index < len(screens)
            else QGuiApplication.primaryScreen()
        )
        if screen is None:
            issues.append("primary capture screen is unavailable")
            available_size = [0, 0]
        else:
            available = screen.availableGeometry()
            available_size = [int(available.width()), int(available.height())]
            if available_size[0] < 1240 or available_size[1] < 840:
                issues.append("capture screen cannot contain the canonical 1240×840 client")
        measurements["available_screen_size"] = available_size
        measurements["display_preflight"] = dict(
            getattr(self, "_capture_display_preflight", {}) or {}
        )
        measurements["screen_device_pixel_ratio"] = (
            float(screen.devicePixelRatio()) if screen is not None else 0.0
        )

        probe = QWidget()
        try:
            probe.setAttribute(Qt.WidgetAttribute.WA_DontShowOnScreen, True)
            layout = QVBoxLayout(probe)
            button_heights: dict[str, int] = {}
            for variant, expected_height in CAPTURE_BUTTON_HEIGHTS.items():
                button = QPushButton("Calibration", probe)
                set_button_size(button, variant)
                layout.addWidget(button)
                button_heights[variant] = int(button.height())
                if int(button.minimumHeight()) != int(expected_height):
                    issues.append(f"{variant} button minimum height drifted")
                if int(button.maximumHeight()) != int(expected_height):
                    issues.append(f"{variant} button maximum height drifted")
                point_size = float(button.font().pointSizeF())
                if point_size > 0 and point_size < 12.0:
                    issues.append(f"{variant} button font is below 12 px/pt")

            elided = ElidingLabel(
                "A deliberately long calibration label with full evidence",
                probe,
            )
            elided.setFixedWidth(48)
            layout.addWidget(elided)
            hidden_scroll = QScrollArea(probe)
            hidden_scroll.setVerticalScrollBarPolicy(
                Qt.ScrollBarPolicy.ScrollBarAlwaysOff
            )
            hidden_scroll.setHorizontalScrollBarPolicy(
                Qt.ScrollBarPolicy.ScrollBarAlwaysOff
            )
            hidden_scroll.setWidget(QWidget())
            layout.addWidget(hidden_scroll)
            probe.show()
            app = QApplication.instance()
            if app is not None:
                app.processEvents()
            elided.resize(48, max(20, int(elided.height())))
            elided._refresh_elision()
            if elided.property("textElided") is not True or not elided.toolTip():
                issues.append("tooltip-backed text elision calibration failed")
            if hidden_scroll.verticalScrollBar().isVisible():
                issues.append("hidden scrollbar became visible during calibration")
            measurements.update({
                "button_heights": button_heights,
                "elision_tooltip_present": bool(elided.toolTip()),
                "hidden_scrollbar_visible": bool(
                    hidden_scroll.verticalScrollBar().isVisible()
                ),
            })
        except Exception as exc:
            issues.append(f"calibration raised {type(exc).__name__}")
            logger.exception("Anki Garden capture: calibration failed")
        finally:
            self._close_widget(probe)
            probe.deleteLater()

        surfaces = self._render_inputs.get("surfaces")
        if not isinstance(surfaces, dict):
            issues.append("render-input surface catalog is unavailable")
        else:
            for label in self._requested_face_labels:
                row = surfaces.get(label)
                if (
                    not isinstance(row, dict)
                    or not isinstance(row.get("digest"), str)
                    or len(str(row.get("digest"))) != 64
                ):
                    issues.append(f"render-input digest is unavailable for {label}")
        if self._capture_environment_digest != self._render_inputs.get(
            "environment_digest"
        ):
            issues.append("capture environment digest does not match render inputs")

        self._capture_calibration = {
            "status": "passed" if not issues else "failed",
            "issues": list(dict.fromkeys(issues)),
            "measurements": measurements,
            "passed": not issues,
        }
        if issues:
            self._failures.append({
                "label": "capture-calibration",
                "reason": "; ".join(dict.fromkeys(issues)),
            })
        return not issues

    def _prepare_starter_phase(self, *, tries: int = 80) -> None:
        """Require the disposable profile's untouched first-run state."""
        state = getattr(self.app.storage, "state", None)
        if state is None:
            if tries <= 0:
                self._failures.append({
                    "label": "starter-state",
                    "reason": "Garden state was unavailable before first-run capture",
                })
                self._next_step()
                return
            QTimer.singleShot(
                120,
                lambda: self._prepare_starter_phase(tries=tries - 1),
            )
            return
        if bool(getattr(state, "starter_selection_complete", False)) or list(
            getattr(state, "plants", []) or []
        ):
            self._failures.append({
                "label": "starter-state",
                "reason": "Disposable profile was not in untouched first-run state",
            })
        self._next_step()

    def _move_to_capture_display(self, widget: Any | None) -> None:
        """Move capture windows fully onto the selected display."""
        if widget is None:
            return
        try:
            screens = list(QGuiApplication.screens())
        except Exception:
            screens = []
        if not screens:
            return
        selected_index = int(getattr(self, "_capture_screen_index", 0))
        effective_index = (
            0
            if self._capture_force_primary and screens
            else selected_index
        )
        use_secondary = bool(
            effective_index > 0
            and len(screens) >= 2
        )
        screen = (
            screens[effective_index]
            if 0 <= effective_index < len(screens)
            else QGuiApplication.primaryScreen()
        )
        screen = screen or screens[0]
        try:
            handle = widget.windowHandle()
            current_screen = None
            if handle is not None:
                current_screen_getter = getattr(handle, "screen", None)
                if callable(current_screen_getter):
                    current_screen = current_screen_getter()
            if current_screen is None:
                current_screen_getter = getattr(widget, "screen", None)
                if callable(current_screen_getter):
                    current_screen = current_screen_getter()
            already_on_target_screen = (
                current_screen is screen or current_screen == screen
            )
            if handle is not None and not already_on_target_screen:
                handle.setScreen(screen)
            geometry = screen.availableGeometry()
            frame = widget.frameGeometry()
            frame_width = max(int(frame.width()), int(widget.width()))
            frame_height = max(int(frame.height()), int(widget.height()))
            inset_x = max(0, min(24, int(geometry.width()) - frame_width))
            inset_y = max(0, min(24, int(geometry.height()) - frame_height))
            frame_fully_inside_target = (
                int(frame.x()) >= int(geometry.x())
                and int(frame.y()) >= int(geometry.y())
                and int(frame.x()) + frame_width
                <= int(geometry.x()) + int(geometry.width())
                and int(frame.y()) + frame_height
                <= int(geometry.y()) + int(geometry.height())
            )
            if not (
                already_on_target_screen and frame_fully_inside_target
            ):
                widget.move(geometry.x() + inset_x, geometry.y() + inset_y)
            self._capture_display = "secondary" if use_secondary else "primary"
        except Exception:
            logger.debug("Anki Garden capture: could not move to selected display", exc_info=True)

    def _prepare_capture_state(self) -> None:
        if self._ensure_capture_state():
            coordinator = getattr(self.app, "state_events", None)
            notify = getattr(coordinator, "notify", None)
            if callable(notify):
                notify("Capture starter fixture committed")
            reset = getattr(mw, "reset", None)
            if callable(reset):
                try:
                    reset()
                except Exception:
                    logger.debug("Anki Garden capture: seeded Home refresh failed", exc_info=True)
            self._phase = "release"
            self._steps = self._release_steps
            self._step_index = 0
            QTimer.singleShot(120, self._next_step)
            return
        if self._starter_seed_attempts >= 80:
            self._failures.append({
                "label": "release-fixture-seed",
                "reason": (
                    "Starter fixture did not reach the atomically completed, "
                    "actively nurtured release boundary"
                ),
            })
            self._finish()
            return
        self._starter_seed_attempts += 1
        QTimer.singleShot(250, self._prepare_capture_state)

    def _ensure_capture_state(self) -> bool:
        """Make capture deterministic at the atomic starter-completion boundary.

        The first-run capture sequence exercises the real Nursery selection,
        placement transaction, and exact Undo restoration.  Release surfaces
        then begin from the committed product result: one Seed-stage starter,
        active assignment, first-Nurture memory, setup version 1, and DONE.
        """
        from ..models.state import OnboardingStep

        state = getattr(self.app.storage, "state", None)
        if state is None:
            return False
        plants = list(getattr(state, "plants", []) or [])
        starter_id = str(
            getattr(state.onboarding, "starter_plant_id", "") or ""
        )
        starter = next(
            (
                plant for plant in plants
                if str(getattr(plant, "plant_id", "") or "") == starter_id
            ),
            None,
        )
        has_first_nurture = bool(
            starter is not None
            and any(
                str(getattr(memory, "memory_id", "") or "")
                == "nurture:first"
                or str(getattr(memory, "kind", "") or "")
                == "first_nurture"
                for memory in tuple(getattr(starter, "memories", ()) or ())
            )
        )
        if (
            bool(getattr(state, "starter_selection_complete", False))
            and len(plants) == 1
            and starter is not None
            and str(getattr(state, "active_plant_id", "") or "") == starter_id
            and str(getattr(starter, "growth_stage", "") or "") == "seed"
            and has_first_nurture
            and int(getattr(state, "garden_setup_version", 0) or 0) == 1
            and state.onboarding.step == OnboardingStep.DONE
        ):
            return True
        ready = getattr(self.app.engine, "release_ready_species", None)
        if ready is None:
            return False
        try:
            candidates = list(ready())
        except Exception:
            return False
        if not candidates:
            return False
        species = str(candidates[0]).lower()
        try:
            step = state.onboarding.step
            if step == OnboardingStep.INTRODUCTION:
                self.app.engine.enter_starter_nursery()
                return False
            if step == OnboardingStep.NURSERY:
                self.app.engine.select_starter_species(species)
                return False
            if step == OnboardingStep.CONFIRMATION:
                self.app.engine.confirm_starter_species()
                return False
            if step == OnboardingStep.PLACEMENT:
                ok, _message, plant = self.app.engine.place_starter(0)
                return bool(
                    ok
                    and plant is not None
                    and self._ensure_capture_state()
                )
        except Exception:
            logger.debug("Anki Garden capture: starter bootstrap waiting for scheduler", exc_info=True)
        return False

    def _next_step(self) -> None:
        scenario_snapshot = self._active_scenario_snapshot
        self._active_scenario_snapshot = None
        if scenario_snapshot is not None:
            try:
                self._restore_capture_fixture_state(scenario_snapshot)
            except Exception:
                self._finish()
                return
        if self._fatal_fixture_restore_failure:
            self._finish()
            return
        if self._step_index >= len(self._steps):
            if self._phase == "starter":
                if not self._starter_steps and not self._release_steps:
                    self._finish()
                    return
                self._phase = "seeding"
                self._close_top_level_dialogs()
                self._close_dashboard()
                QTimer.singleShot(350, self._prepare_capture_state)
                return
            self._finish()
            return
        expected_label, current = self._steps[self._step_index]
        self._step_index += 1
        self._active_fixture_source = (
            f"ordered-step-{self._step_index:03d}:"
            f"{getattr(current, '__name__', type(current).__name__)}"
        )
        self._active_fixture_expected_label = expected_label
        self._capture_requested_monotonic.setdefault(
            expected_label,
            time.perf_counter(),
        )
        trace = getattr(globals().get("logger"), "info", None)
        if callable(trace):
            trace(
                "Anki Garden capture step %d/%d: expected=%s source=%s capture_index=%d",
                self._step_index,
                len(self._steps),
                expected_label,
                self._active_fixture_source,
                self._capture_face_labels.index(expected_label) + 1,
            )
        development_setup = "development-stress" in (
            capture_scenario_internal_setups(expected_label)
        )
        if development_setup:
            try:
                self._active_scenario_snapshot = (
                    self._capture_fixture_state_snapshot(
                        f"{expected_label}:scenario-boundary",
                        exact_ledger_restore=True,
                    )
                )
                development_ready = self._ensure_development_stress_state()
            except Exception:
                development_ready = False
            if not development_ready:
                snapshot = self._active_scenario_snapshot
                self._active_scenario_snapshot = None
                if snapshot is not None:
                    try:
                        self._restore_capture_fixture_state(snapshot)
                    except Exception:
                        self._finish()
                        return
                self._failures.append({
                    "label": expected_label,
                    "reason": (
                        "Scenario development-stress checkpoint was unavailable"
                    ),
                })
                self._write_progress_manifest()
                self._next_after(160)
                return
        try:
            current()
        except Exception as exc:
            self._failures.append({
                "label": expected_label,
                "reason": (
                    f"Capture step {self._active_fixture_source!r} raised "
                    f"{type(exc).__name__}"
                ),
            })
            logger.exception("Anki Garden capture: step failed, moving on")
            self._next_after(300)

    def _next_after(self, delay_ms: int) -> None:
        QTimer.singleShot(max(80, int(delay_ms)), self._next_step)

    def _one_shot_async_callback(
        self,
        label: str,
        callback: Callable[..., Any],
        *,
        on_error: Callable[[], None] | None = None,
        advance_on_error: bool = True,
    ) -> Callable[..., Any]:
        """Guard a Qt callback so it runs once and exceptions fail closed.

        WebEngine, timers, and nested dialog loops may deliver a callback late
        or more than once.  A raised callback must never be mistaken for a
        predicate miss and retried against a later fixture.
        """

        if bool(getattr(callback, "_anki_garden_capture_one_shot", False)):
            return callback
        called = False

        def guarded(*args: Any, **kwargs: Any) -> Any:
            nonlocal called
            if called:
                return None
            called = True
            try:
                return callback(*args, **kwargs)
            except Exception as exc:
                self._failures.append({
                    "label": label,
                    "reason": (
                        "Capture readiness callback raised "
                        f"{type(exc).__name__}"
                    ),
                })
                logger.exception(
                    "Anki Garden capture: asynchronous callback failed for %s",
                    label,
                )
                if on_error is not None:
                    try:
                        on_error()
                    except Exception as cleanup_exc:
                        self._failures.append({
                            "label": label,
                            "reason": (
                                "Capture failure cleanup raised "
                                f"{type(cleanup_exc).__name__}"
                            ),
                        })
                        logger.exception(
                            "Anki Garden capture: callback cleanup failed for %s",
                            label,
                        )
                if advance_on_error:
                    self._next_after(120)
                return None

        setattr(guarded, "_anki_garden_capture_one_shot", True)
        setattr(guarded, "_anki_garden_capture_label", str(label))
        return guarded

    def _wait_for_collection(
        self,
        ready: Callable[[], None],
        *,
        tries: int = 40,
        failure_label: str = "collection-ready",
        on_error: Callable[[], None] | None = None,
    ) -> None:
        ready = self._one_shot_async_callback(
            failure_label,
            ready,
            on_error=on_error or self._finish,
            advance_on_error=False,
        )
        collection = getattr(mw, "col", None)
        if collection is not None and getattr(collection, "db", None) is not None:
            ready()
            return
        if tries <= 0:
            self._failures.append({
                "label": failure_label,
                "reason": "Anki collection did not become ready before capture",
            })
            if on_error is not None:
                on_error()
            else:
                self._finish()
            return
        QTimer.singleShot(
            120,
            lambda: self._wait_for_collection(
                ready,
                tries=tries - 1,
                failure_label=failure_label,
                on_error=on_error,
            ),
        )

    def _wait_for_dashboard(
        self,
        ready: Callable[[], None],
        *,
        tries: int = 80,
        failure_label: str = "dashboard-ready",
        on_error: Callable[[], None] | None = None,
    ) -> None:
        ready = self._one_shot_async_callback(
            failure_label,
            ready,
            on_error=on_error,
        )
        dashboard = getattr(self.app, "dashboard", None)
        visible = False
        if dashboard is not None:
            try:
                visible = bool(dashboard.isVisible())
            except Exception:
                visible = True
        if visible:
            ready()
            return
        if tries <= 0:
            self._failures.append({
                "label": failure_label,
                "reason": "Garden Dashboard did not become visible before capture",
            })
            if on_error is not None:
                on_error()
            self._next_after(120)
            return
        QTimer.singleShot(
            120,
            lambda: self._wait_for_dashboard(
                ready,
                tries=tries - 1,
                failure_label=failure_label,
                on_error=on_error,
            ),
        )

    def _wait_for(
        self,
        predicate: Callable[[], bool],
        on_ready: Callable[[], None],
        *,
        tries: int = 80,
        failure_label: str,
        failure_reason: str = "",
        started_monotonic: float | None = None,
        on_error: Callable[[], None] | None = None,
    ) -> None:
        on_ready = self._one_shot_async_callback(
            failure_label,
            on_ready,
            on_error=on_error,
        )
        if started_monotonic is None:
            started_monotonic = time.perf_counter()
        is_ready = False
        try:
            is_ready = bool(predicate())
        except Exception as exc:
            last_observation = self._capture_annotations.get(failure_label)
            if not isinstance(last_observation, dict):
                last_observation = {}
                self._capture_annotations[failure_label] = last_observation
            last_observation["wait_for_predicate_error"] = {
                "type": type(exc).__name__,
                "message": str(exc)[:300],
            }
        if is_ready:
            elapsed_ms = max(
                0.0,
                (time.perf_counter() - started_monotonic) * 1000.0,
            )
            self._performance_samples.setdefault(
                f"surface_ready:{failure_label}",
                [],
            ).append(round(elapsed_ms, 3))
            on_ready()
            return
        if tries <= 0:
            reason = failure_reason or "Timed out waiting for the requested UI surface"
            last_observation = self._capture_annotations.get(failure_label)
            if isinstance(last_observation, dict) and last_observation:
                reason = f"{reason}; last observation: {last_observation}"
            self._failures.append({
                "label": failure_label,
                "reason": reason,
            })
            if on_error is not None:
                on_error()
            self._next_after(120)
            return
        QTimer.singleShot(
            120,
            lambda: self._wait_for(
                predicate,
                on_ready,
                tries=tries - 1,
                failure_label=failure_label,
                failure_reason=failure_reason,
                started_monotonic=started_monotonic,
                on_error=on_error,
            ),
        )

    def _home_progress_fraction_matrix(self) -> dict[str, Any]:
        """Render the six bounded Home fractions through production projection."""

        from ..ui.home_widget import (
            HomeWidgetSnapshot,
            home_surface_view_model,
            render_home_widget,
        )

        controller = getattr(self.app, "_home_widget_controller", None)
        snapshot = getattr(controller, "snapshot", None)
        data = getattr(snapshot, "data", None)
        if data is None:
            return {
                "records": {},
                "issues": ["home-progress-source-data-unavailable"],
                "passed": False,
            }
        cases = {
            "zero": (0, 2_000, False),
            "near-zero": (1, 2_000, False),
            "partial": (750, 2_000, False),
            "checkpoint-carryover": (50, 2_000, False),
            "complete": (2_000, 2_000, True),
            "denominator-zero": (125, 0, False),
        }
        records: dict[str, dict[str, Any]] = {}
        for name, (current, maximum, complete) in cases.items():
            variant = replace(
                data,
                starter_selected=True,
                active_plant_name="Capture Bonsai",
                planted_starter_name="",
                active_growth_points=current,
                active_stage_points=current,
                active_stage_goal=maximum,
                active_fully_grown=complete,
                preview_snapshot=None,
            )
            projection = home_surface_view_model(variant)
            rendered = render_home_widget(
                HomeWidgetSnapshot(0, "success", variant)
            )
            expected_percent = capture_progress_fraction(
                current,
                maximum,
                complete=complete,
            )
            attributes_match = bool(
                f'data-progress-current="{current}"' in rendered
                and f'data-progress-maximum="{maximum}"' in rendered
                and f'data-progress-percent="{expected_percent:.2f}"' in rendered
            )
            records[name] = {
                "current": int(projection.progress_current),
                "maximum": int(projection.progress_maximum),
                "complete": bool(complete),
                "percent": float(projection.progress_percent),
                "painted_attributes_match": attributes_match,
            }
        issues = home_progress_fraction_issue_codes(records)
        return {
            "records": records,
            "issues": list(issues),
            "passed": not issues,
        }

    def _wait_for_home_surface(
        self,
        state: str,
        capture_label: str,
        on_ready: Callable[[], None],
        *,
        tries: int = 100,
        on_error: Callable[[], None] | None = None,
    ) -> None:
        on_ready = self._one_shot_async_callback(
            capture_label,
            on_ready,
            on_error=on_error,
        )
        if str(getattr(mw, "state", "")) != state:
            if tries <= 0:
                self._failures.append({
                    "label": capture_label,
                    "reason": f"Anki surface {state!r} did not become active",
                })
                if on_error is not None:
                    on_error()
                self._next_after(120)
                return
            QTimer.singleShot(
                120,
                self._one_shot_async_callback(
                    capture_label,
                    lambda: self._wait_for_home_surface(
                        state,
                        capture_label,
                        on_ready,
                        tries=tries - 1,
                        on_error=on_error,
                    ),
                    on_error=on_error,
                ),
            )
            return
        web = getattr(mw, "web", None)
        overview_root_script = ""
        if state == "overview" and tries in {100, 75, 50, 25}:
            # Anki keeps its external Congratulations document alive while
            # repeated Overview fixtures change underneath it.  That means
            # ``webview_did_inject_style_into_page`` is not guaranteed to fire
            # again even though the source-backed Garden HTML has advanced.
            # Prefix the DOM audit with the production replacement script so
            # both operations run in one current-frame WebEngine transaction.
            # A navigation can discard a separate asynchronous eval between
            # these operations during a complete full-profile run.
            build_overview_root_script = getattr(
                self.app,
                "_home_garden_root_replacement_script",
                None,
            )
            if callable(build_overview_root_script):
                try:
                    overview_root_script = str(
                        build_overview_root_script() or ""
                    )
                except Exception:
                    logger.debug(
                        "Anki Garden capture: Overview root refresh failed for %s",
                        capture_label,
                        exc_info=True,
                    )
        page_getter = getattr(web, "page", None)
        page = page_getter() if callable(page_getter) else None
        run_javascript = getattr(page, "runJavaScript", None)
        evaluate = getattr(web, "evalWithCallback", None)
        if not callable(run_javascript) and not callable(evaluate):
            self._failures.append({
                "label": capture_label,
                "reason": "Home fixture identity could not be verified without WebEngine",
            })
            if on_error is not None:
                on_error()
            self._next_after(120)
            return

        special_fixture_state = {
            "home-preview-loading": "preview-loading",
            "home-preview-error": "preview-error",
            "home-preview-stale": "preview-stale",
        }.get(capture_label, "")
        garden_state = getattr(self.app.storage, "state", None)
        starter_complete = bool(
            getattr(garden_state, "starter_selection_complete", False)
        )
        active_plant_id = str(
            getattr(garden_state, "active_plant_id", "") or ""
        )
        plants = list(getattr(garden_state, "plants", ()) or ())
        active_plant = next((
            plant for plant in plants
            if str(getattr(plant, "plant_id", "") or "") == active_plant_id
        ), None)
        active_slot_value = (
            getattr(active_plant, "slot_index", None)
            if active_plant is not None else None
        )
        expected_active_slot = (
            int(active_slot_value)
            if active_slot_value is not None else -1
        )
        if special_fixture_state:
            fixture_state = special_fixture_state
        elif not starter_complete:
            fixture_state = "starter-not-selected"
        elif active_plant_id:
            fixture_state = "nurtured-active"
        elif plants:
            fixture_state = "starter-planted-not-nurtured"
        else:
            fixture_state = "starter-complete-without-plant"
        self._active_home_fixture_state = fixture_state
        environment_visibility = getattr(
            garden_state,
            "environment_visibility",
            {},
        )
        garden_feature_visible = (
            bool(environment_visibility.get(
                "garden_feature",
                environment_visibility.get("weather", True),
            ))
            if isinstance(environment_visibility, dict)
            else True
        )
        expected_garden_feature_present = bool(
            garden_feature_visible
            and fixture_state not in {"preview-loading", "preview-error"}
        )
        expected_garden_feature_id = str(
            getattr(
                garden_state,
                "selected_garden_feature",
                "seedling_sign",
            )
            or "seedling_sign"
        )
        script = r"""
            (() => {
              const fixtureState = __FIXTURE_STATE__;
              const minimumRootHeight = fixtureState === 'starter-not-selected'
                ? 84 : 100;
              const roots = [...document.querySelectorAll('#ag-home-root')];
              const visibleRoots = roots.filter(candidate => {
                const bounds = candidate.getBoundingClientRect();
                const style = window.getComputedStyle(candidate);
                return bounds.width >= 100 && bounds.height >= minimumRootHeight
                  && style.display !== 'none' && style.visibility !== 'hidden';
              });
              const root = visibleRoots.length
                ? visibleRoots[visibleRoots.length - 1]
                : null;
              const visibleAddonRoot = candidate => {
                if (!candidate) return false;
                const bounds = candidate.getBoundingClientRect();
                const style = window.getComputedStyle(candidate);
                return bounds.width > 0 && bounds.height > 0
                  && style.display !== 'none'
                  && style.visibility !== 'hidden'
                  && Number.parseFloat(style.opacity || '1') > 0;
              };
              const measureHorizontalOverflow = candidate => {
                const clientWidth = candidate
                  ? Math.floor(candidate.clientWidth) : 0;
                const scrollWidth = candidate
                  ? Math.ceil(candidate.scrollWidth) : 0;
                const horizontalOverflow = Math.max(
                  0,
                  scrollWidth - clientWidth
                );
                return {
                  clientWidth,
                  scrollWidth,
                  horizontalOverflow,
                  passed: clientWidth > 0 && scrollWidth <= clientWidth,
                };
              };
              const documentRoot = document.documentElement;
              const documentRootOverflow = {
                identity: 'document.documentElement',
                source: 'document.documentElement',
                ...measureHorizontalOverflow(documentRoot),
              };
              const addonRootCandidates = [...document.querySelectorAll(
                '#ag-home-root, [data-anki-garden-root]'
              )];
              const rootKindCounts = new Map();
              const visibleAddonRootOverflows = [];
              addonRootCandidates.forEach((candidate, domIndex) => {
                const declaredKind = (
                  candidate.getAttribute('data-anki-garden-root') || ''
                ).trim();
                const rawKind = declaredKind
                  || (candidate.id === 'ag-home-root' ? 'home' : candidate.id)
                  || candidate.tagName.toLocaleLowerCase('en-US');
                const rootKind = rawKind
                  .toLocaleLowerCase('en-US')
                  .replace(/[^a-z0-9_-]+/g, '-')
                  .replace(/^-+|-+$/g, '') || 'root';
                const kindOrdinal = (rootKindCounts.get(rootKind) || 0) + 1;
                rootKindCounts.set(rootKind, kindOrdinal);
                if (!visibleAddonRoot(candidate)) return;
                visibleAddonRootOverflows.push({
                  identity: `anki-garden:${rootKind}:${kindOrdinal}`,
                  rootKind,
                  selector: candidate.id
                    ? `#${candidate.id}`
                    : `[data-anki-garden-root="${declaredKind}"]`,
                  domOrdinal: domIndex + 1,
                  kindOrdinal,
                  visible: true,
                  ...measureHorizontalOverflow(candidate),
                });
              });
              const visibleAddonRootCount = visibleAddonRootOverflows.length;
              const visibleAddonRootsOverflowPassed =
                visibleAddonRootOverflows.every(record => record.passed);
              const allRootOverflowPassed = documentRootOverflow.passed
                && visibleAddonRootsOverflowPassed;
              if (!root) {
                return {
                  ready: false,
                  reason: 'no-visible-root',
                  rootCount: roots.length,
                  visibleRootCount: visibleRoots.length,
                  documentRootOverflow,
                  addonRootCandidateCount: addonRootCandidates.length,
                  visibleAddonRootCount,
                  visibleAddonRootOverflows,
                  visibleAddonRootsOverflowPassed,
                  allRootOverflowPassed,
                };
              }
              const rect = root.getBoundingClientRect();
              const images = [...root.querySelectorAll('img')];
              const imagesComplete = images.every(img => img.complete);
              const failedImageCount = images.filter(
                img => img.complete && img.naturalWidth <= 0
              ).length;
              const homeAction = root.querySelector('[data-testid="home-open"]');
              const command = homeAction
                ? homeAction.dataset.ankiGardenCommand || ''
                : root.dataset.ankiGardenCommand || '';
              const growth = root.querySelector(
                '[data-testid="home-progress-copy"], [data-testid="home-growth"]'
              );
              const growthText = growth ? growth.textContent || '' : '';
              const growthTrack = root.querySelector(
                '[data-testid="home-growth-progress"]'
              );
              const growthCopyRect = growth
                ? growth.getBoundingClientRect() : null;
              const growthTrackRect = growthTrack
                ? growthTrack.getBoundingClientRect() : null;
              const progressCurrent = Number(root.dataset.progressCurrent || '0');
              const progressMaximum = Number(root.dataset.progressMaximum || '0');
              const progressPercent = Number(root.dataset.progressPercent || '0');
              const progressComplete = root.dataset.homeMode === 'active-complete';
              const calculatedProgressPercent = progressComplete
                ? 100
                : progressMaximum > 0
                  ? Math.min(100, Math.max(0, progressCurrent / progressMaximum * 100))
                  : 0;
              const paintedProgressCurrent = growthTrack
                ? Number(growthTrack.getAttribute('aria-valuenow') || '0') : null;
              const paintedProgressMaximum = growthTrack
                ? Number(growthTrack.getAttribute('aria-valuemax') || '0') : null;
              const paintedProgressPercent = growthTrack
                ? Number.parseFloat(
                    growthTrack.style.getPropertyValue('--ag-growth-percent') || '0'
                  ) : null;
              const progressFractionPassed = Number.isFinite(progressCurrent)
                && Number.isFinite(progressMaximum)
                && Number.isFinite(progressPercent)
                && Math.abs(progressPercent - calculatedProgressPercent) <= 0.011
                && (!growthTrack || (
                  paintedProgressCurrent === progressCurrent
                  && paintedProgressMaximum === Math.max(1, progressMaximum)
                  && Math.abs(paintedProgressPercent - progressPercent) <= 0.011
                ));
              const identity = root.querySelector('.ag-home__identity');
              const identityRect = identity
                ? identity.getBoundingClientRect() : null;
              const growthTrackCopyClearance = (
                growthTrackRect && growthCopyRect
              ) ? Math.floor(growthTrackRect.top - growthCopyRect.bottom) : null;
              const growthTrackBottomClearance = growthTrackRect
                ? Math.floor(rect.bottom - growthTrackRect.bottom) : null;
              const growthTrackContained = !growthTrackRect || (
                growthTrackRect.left >= rect.left
                && growthTrackRect.top >= rect.top
                && growthTrackRect.right <= rect.right
                && growthTrackRect.bottom <= rect.bottom
              );
              const growthTrackAlignedToIdentity = !growthTrackRect || !!(
                identityRect
                && Math.abs(growthTrackRect.left - identityRect.left) <= 1
                && growthTrackRect.right <= identityRect.right + 1
              );
              const growthTrackGeometryPassed = !growthTrackRect || !!(
                growthCopyRect
                && growthTrackContained
                && growthTrackAlignedToIdentity
                && growthTrackCopyClearance >= 4
                && growthTrackBottomClearance >= 5
                && Math.round(growthTrackRect.height) === 4
              );
              const activeSlot = Number(root.dataset.activeSlot || '-1');
              const sceneFrame = root.querySelector('.ag-home__scene-frame');
              const gardenFeature = root.querySelector(
                '[data-testid="home-garden-feature"]'
              );
              const gardenFeaturePad = root.querySelector(
                '[data-testid="home-garden-feature-pad"]'
              );
              const gardenFeatureRect = gardenFeature
                ? gardenFeature.getBoundingClientRect() : null;
              const gardenFeaturePadRect = gardenFeaturePad
                ? gardenFeaturePad.getBoundingClientRect() : null;
              const sceneFrameRect = sceneFrame
                ? sceneFrame.getBoundingClientRect() : null;
              const gardenFeaturePointerTransparent = !!gardenFeature
                && !!gardenFeaturePad
                && window.getComputedStyle(gardenFeature).pointerEvents === 'none'
                && window.getComputedStyle(gardenFeaturePad).pointerEvents === 'none';
              const containedBySceneFrame = candidate => !!(
                candidate && sceneFrameRect
                && candidate.left >= sceneFrameRect.left - 1
                && candidate.top >= sceneFrameRect.top - 1
                && candidate.right <= sceneFrameRect.right + 1
                && candidate.bottom <= sceneFrameRect.bottom + 1
              );
              const gardenFeatureClipped = !!gardenFeature
                && !!gardenFeaturePad
                && !!sceneFrame
                && window.getComputedStyle(sceneFrame).overflow === 'hidden'
                && containedBySceneFrame(gardenFeatureRect)
                && containedBySceneFrame(gardenFeaturePadRect);
              const literalSunPrimitive = root.querySelector(
                '[data-kind="literal-sun"], [data-feature="literal-sun"]'
              );
              const sunLayer = root.querySelector(
                '[data-testid="home-sun-layer"], .ag-home__sun-layer, .ag-home__sun'
              );
              const sceneryLayer = root.querySelector('[data-testid="home-scenery-layer"]');
              const previewStatus = root.querySelector(
                '[data-testid="home-preview-status"]'
              );
              const previewStatusPresent = !!previewStatus;
              const previewStatusRect = previewStatus
                ? previewStatus.getBoundingClientRect()
                : null;
              const homeActionRect = homeAction
                ? homeAction.getBoundingClientRect()
                : null;
              const previewStatusActionOverlap = !!(
                previewStatusRect && homeActionRect
                && previewStatusRect.left < homeActionRect.right
                && previewStatusRect.right > homeActionRect.left
                && previewStatusRect.top < homeActionRect.bottom
                && previewStatusRect.bottom > homeActionRect.top
              );
              const loadingPresent = !!root.querySelector(
                '[data-testid="home-loading"]'
              );
              const accessibilityCopy = [
                root.getAttribute('aria-label') || '',
                ...[...root.querySelectorAll('[aria-label]')].map(
                  candidate => candidate.getAttribute('aria-label') || ''
                ),
                ...[...root.querySelectorAll('.ag-home__sr-only')].map(
                  candidate => candidate.textContent || ''
                ),
              ].join(' ');
              const renderedCopy = `${root.innerText || ''} ${accessibilityCopy}`
                .replace(/\\s+/g, ' ')
                .trim();
              const normalizedCopy = renderedCopy.toLocaleLowerCase('en-US');
              const bannedTerms = [
                'today',
                'streak',
                'garden coins',
                'coins',
                'closest',
                'planted starter',
              ].filter(term => normalizedCopy.includes(term));
              const compactFieldsPresent = !!(
                root.querySelector('[data-testid="home-title"]')
                && root.querySelector('[data-testid="home-support"]')
                && homeAction
              );
              const expectedActiveSlot = __EXPECTED_ACTIVE_SLOT__;
              const title = root.querySelector('[data-testid="home-title"]');
              const support = root.querySelector('[data-testid="home-support"]');
              const titleText = (title ? title.textContent || '' : '').trim();
              const supportText = (support ? support.textContent || '' : '').trim();
              const homeActionText = (homeAction ? homeAction.textContent || '' : '').trim();
              const homeActionGeometryPassed = !homeAction
                || homeActionText !== 'Open garden'
                || (
                  Math.round(homeActionRect.width) >= 104
                  // The shared Home banner reserves a 128 px CTA column so
                  // longer localized action copy cannot collide with the
                  // title. Keep the source-backed audit aligned with that
                  // approved product geometry.
                  && Math.round(homeActionRect.width) <= 128
                  && Math.round(homeActionRect.height) === 36
                );
              const starterHomeGeometryPassed = fixtureState !== 'starter-not-selected'
                || !!(
                  title && support && homeAction && homeActionRect
                  && Math.round(rect.width) >= 500
                  && Math.round(rect.width) <= 540
                  && Math.round(rect.height) >= 84
                  && Math.round(rect.height) <= 140
                  && Math.abs(
                    (homeActionRect.top + homeActionRect.height / 2)
                    - (rect.top + rect.height / 2)
                  ) <= 2
                );
              const conciseInformationModelPassed = (
                fixtureState === 'preview-loading'
                  ? normalizedCopy.includes('loading garden')
                  : fixtureState === 'preview-error'
                    ? normalizedCopy.includes('garden preview unavailable')
                      && homeActionText === 'Open garden'
                    : fixtureState === 'starter-not-selected'
                      ? titleText === 'Choose your starter'
                        && supportText === 'Your first plant is free.'
                        && homeActionText === 'Choose starter'
                        && starterHomeGeometryPassed
                    : (/\b[\d,]+\s*\/\s*[\d,]+\s+Growth\b/i.test(growthText)
                        || growthText.includes('total Growth'))
                        && homeActionText === 'Open garden'
              );
              let fixtureMatches = false;
              if (fixtureState === 'starter-not-selected') {
                fixtureMatches = command.endsWith(':choose-starter')
                  && activeSlot < 0;
              } else if (fixtureState === 'starter-planted-not-nurtured') {
                fixtureMatches = command.endsWith(':open')
                  && activeSlot < 0;
              } else if (fixtureState === 'nurtured-active') {
                fixtureMatches = command.endsWith(':open')
                  && activeSlot === expectedActiveSlot;
              } else if (fixtureState === 'preview-loading') {
                fixtureMatches = root.dataset.state === 'loading'
                  && !!root.querySelector('[data-testid="home-loading"]');
              } else if (fixtureState === 'preview-error') {
                fixtureMatches = root.dataset.state === 'error'
                  && !!root.querySelector('[data-testid="home-error"]');
              } else if (fixtureState === 'preview-stale') {
                fixtureMatches = root.dataset.state === 'stale'
                  && command.endsWith(':open')
                  && !!previewStatus
                  && !!homeAction
                  && !homeAction.disabled
                  && !previewStatusActionOverlap;
              }
              const paintedState = fixtureState.startsWith('preview-')
                ? root.dataset.state === fixtureState.replace('preview-', '')
                : ['success', 'partial'].includes(root.dataset.state);
              const canonicalSettled = fixtureState.startsWith('preview-') || (
                root.dataset.state === 'success'
                && !previewStatusPresent
                && !loadingPresent
                && failedImageCount === 0
              );
              return {
                ready: paintedState && imagesComplete && canonicalSettled
                  && fixtureMatches && bannedTerms.length === 0
                  && homeActionGeometryPassed && conciseInformationModelPassed
                  && growthTrackGeometryPassed && progressFractionPassed
                  && allRootOverflowPassed,
                reason: !paintedState ? 'unpainted-state'
                  : !imagesComplete ? 'images-pending'
                  : !canonicalSettled ? 'canonical-preview-unsettled'
                  : !fixtureMatches ? 'fixture-mismatch'
                  : !growthTrackGeometryPassed ? 'growth-progress-clipped'
                  : !documentRootOverflow.passed
                    ? 'document-root-horizontal-overflow'
                  : !visibleAddonRootsOverflowPassed
                    ? 'addon-root-horizontal-overflow'
                  : 'ready',
                rootCount: roots.length,
                visibleRootCount: visibleRoots.length,
                state: root.dataset.state || '',
                command,
                activeSlot,
                gardenFeaturePresent: !!gardenFeature,
                gardenFeaturePadPresent: !!gardenFeaturePad,
                gardenFeatureSelected: gardenFeature
                  ? gardenFeature.dataset.gardenFeature || '' : '',
                gardenFeaturePointerTransparent,
                gardenFeatureClipped,
                expectedGardenFeaturePresent: __EXPECTED_GARDEN_FEATURE_PRESENT__,
                expectedGardenFeatureId: __EXPECTED_GARDEN_FEATURE_ID__,
                sunLayerPresent: !!sunLayer || !!literalSunPrimitive,
                sceneryLayerPresent: !!sceneryLayer,
                sceneOpacity: sceneFrame
                  ? Number.parseFloat(window.getComputedStyle(sceneFrame).opacity || '1')
                  : null,
                imagesComplete,
                failedImageCount,
                previewStatusPresent,
                previewStatusActionOverlap,
                previewStatusBounds: previewStatusRect ? {
                  left: Math.round(previewStatusRect.left - rect.left),
                  top: Math.round(previewStatusRect.top - rect.top),
                  right: Math.round(previewStatusRect.right - rect.left),
                  bottom: Math.round(previewStatusRect.bottom - rect.top),
                } : null,
                homeActionBounds: homeActionRect ? {
                  left: Math.round(homeActionRect.left - rect.left),
                  top: Math.round(homeActionRect.top - rect.top),
                  right: Math.round(homeActionRect.right - rect.left),
                  bottom: Math.round(homeActionRect.bottom - rect.top),
                } : null,
                homeActionEnabled: !!homeAction && !homeAction.disabled,
                homeActionText,
                homeActionWidth: homeActionRect
                  ? Math.round(homeActionRect.width) : null,
                homeActionHeight: homeActionRect
                  ? Math.round(homeActionRect.height) : null,
                homeActionGeometryPassed,
                starterHomeGeometryPassed,
                titleText,
                supportText,
                conciseInformationModelPassed,
                loadingPresent,
                renderedCopy,
                bannedTerms,
                compactFieldsPresent,
                growthText,
                growthTrackPresent: !!growthTrack,
                growthTrackBounds: growthTrackRect ? {
                  left: Math.round(growthTrackRect.left - rect.left),
                  top: Math.round(growthTrackRect.top - rect.top),
                  right: Math.round(growthTrackRect.right - rect.left),
                  bottom: Math.round(growthTrackRect.bottom - rect.top),
                  height: Math.round(growthTrackRect.height),
                } : null,
                growthCopyBounds: growthCopyRect ? {
                  left: Math.round(growthCopyRect.left - rect.left),
                  top: Math.round(growthCopyRect.top - rect.top),
                  right: Math.round(growthCopyRect.right - rect.left),
                  bottom: Math.round(growthCopyRect.bottom - rect.top),
                } : null,
                growthTrackCopyClearance,
                growthTrackBottomClearance,
                growthTrackContained,
                growthTrackAlignedToIdentity,
                growthTrackGeometryPassed,
                progressCurrent,
                progressMaximum,
                progressPercent,
                calculatedProgressPercent,
                paintedProgressCurrent,
                paintedProgressMaximum,
                paintedProgressPercent,
                progressComplete,
                progressFractionPassed,
                fixtureState,
                expectedActiveSlot,
                documentRootOverflow,
                addonRootCandidateCount: addonRootCandidates.length,
                visibleAddonRootCount,
                visibleAddonRootOverflows,
                visibleAddonRootsOverflowPassed,
                allRootOverflowPassed,
                width: Math.round(rect.width),
                height: Math.round(rect.height),
              };
            })()
        """.replace(
            "__FIXTURE_STATE__",
            repr(fixture_state),
        ).replace(
            "__EXPECTED_ACTIVE_SLOT__",
            str(expected_active_slot),
        ).replace(
            "__EXPECTED_GARDEN_FEATURE_PRESENT__",
            "true" if expected_garden_feature_present else "false",
        ).replace(
            "__EXPECTED_GARDEN_FEATURE_ID__",
            repr(expected_garden_feature_id),
        )
        if overview_root_script:
            script = f"{overview_root_script}\n{script}"

        settled = False

        def retry_or_fail() -> None:
            if tries in {100, 75, 50, 25, 0}:
                trace = getattr(globals().get("logger"), "info", None)
                if callable(trace):
                    trace(
                        "Anki Garden Home readiness: label=%s tries=%d observation=%r",
                        capture_label,
                        tries,
                        dict(getattr(self, "_active_home_dom_audit", {}) or {}),
                    )
            if tries <= 0:
                observed = dict(getattr(self, "_active_home_dom_audit", {}) or {})
                self._failures.append({
                    "label": capture_label,
                    "reason": (
                        "Home widget never reached the source-backed fixture state "
                        f"{fixture_state!r}; last DOM observation: {observed!r}"
                    ),
                })
                if on_error is not None:
                    on_error()
                self._next_after(120)
            else:
                observed = dict(getattr(self, "_active_home_dom_audit", {}) or {})
                stale_nurtured_slot = bool(
                    fixture_state == "nurtured-active"
                    and int(observed.get("activeSlot", -1))
                    != expected_active_slot
                )
                if tries in {75, 50, 25} or (tries == 100 and stale_nurtured_slot):
                    invalidate = getattr(self.app, "_invalidate_home_cache", None)
                    if callable(invalidate):
                        invalidate(f"capture readiness retry for {capture_label}")
                    reset = getattr(mw, "reset", None)
                    if callable(reset):
                        try:
                            reset()
                        except Exception:
                            logger.debug(
                                "Anki Garden capture: Home retry refresh failed",
                                exc_info=True,
                            )
                    surface_controller = getattr(mw, state, None)
                    refresh_surface = getattr(
                        surface_controller,
                        "refresh",
                        None,
                    )
                    if callable(refresh_surface):
                        try:
                            refresh_surface()
                        except Exception:
                            logger.debug(
                                "Anki Garden capture: %s controller refresh failed",
                                state,
                                exc_info=True,
                            )
                QTimer.singleShot(
                    120,
                    self._one_shot_async_callback(
                        capture_label,
                        lambda: self._wait_for_home_surface(
                            state,
                            capture_label,
                            on_ready,
                            tries=tries - 1,
                            on_error=on_error,
                        ),
                        on_error=on_error,
                    ),
                )

        def resolved(result: Any) -> None:
            nonlocal settled
            if settled:
                return
            settled = True
            observation = dict(result) if isinstance(result, dict) else {
                "ready": bool(result),
                "reason": "legacy-boolean-result",
            }
            observation.update({
                "capture_label": capture_label,
                "surface": state,
                "expected_fixture_state": fixture_state,
            })
            self._active_home_dom_audit = observation
            if bool(observation.get("ready", False)):
                QTimer.singleShot(32, on_ready)
            else:
                retry_or_fail()

        def callback_watchdog() -> None:
            """Retry if a page transition discards WebEngine's JS callback."""

            nonlocal settled
            if settled:
                return
            settled = True
            retry_or_fail()

        resolved_once = self._one_shot_async_callback(
            capture_label,
            resolved,
            on_error=on_error,
        )
        try:
            if callable(run_javascript):
                # Call the live QWebEnginePage directly. Anki's convenience
                # wrapper can retain a callback queue across repeated main-page
                # navigations; late in a full release run that queue may stop
                # delivering results even though the page remains painted.
                # The page API binds this audit to the current renderer frame.
                try:
                    run_javascript(script, 0, resolved_once)
                except TypeError:
                    run_javascript(script, resolved_once)
            else:
                evaluate(script, resolved_once)
            # A busy WebEngine compositor can legitimately take longer than
            # one frame budget to return runJavaScript results while native
            # capture windows are being moved and grabbed.  The old 750 ms
            # watchdog repeatedly invalidated callbacks that arrived shortly
            # afterward, so a healthy painted Home face could never settle.
            QTimer.singleShot(
                2500,
                self._one_shot_async_callback(
                    capture_label,
                    callback_watchdog,
                    on_error=on_error,
                ),
            )
        except Exception:
            settled = True
            retry_or_fail()

    def _wait_for_reviewer_surface(
        self,
        capture_label: str,
        on_ready: Callable[[], None],
        *,
        tries: int = 100,
        on_error: Callable[[], None] | None = None,
    ) -> None:
        """Require the disposable card in the live Reviewer WebEngine frame."""

        on_ready = self._one_shot_async_callback(capture_label, on_ready)
        reviewer = getattr(mw, "reviewer", None)
        web = getattr(reviewer, "web", None)
        page_getter = getattr(web, "page", None)
        page = page_getter() if callable(page_getter) else None
        run_javascript = getattr(page, "runJavaScript", None)
        evaluate = getattr(web, "evalWithCallback", None)

        def retry_or_fail() -> None:
            if tries <= 0:
                observed = dict(
                    getattr(self, "_active_reviewer_dom_audit", {}) or {}
                )
                self._failures.append({
                    "label": capture_label,
                    "reason": (
                        "Reviewer WebEngine never painted the disposable card; "
                        f"last DOM observation: {observed!r}"
                    ),
                })
                if on_error is not None:
                    on_error()
                self._next_after(120)
                return
            QTimer.singleShot(
                120,
                lambda: self._wait_for_reviewer_surface(
                    capture_label,
                    on_ready,
                    tries=tries - 1,
                    on_error=on_error,
                ),
            )

        if (
            str(getattr(mw, "state", "")) != "review"
            or web is None
            or not web.isVisible()
            or (
                not callable(run_javascript)
                and not callable(evaluate)
            )
        ):
            retry_or_fail()
            return

        script = r"""
            (() => {
              const visible = candidate => {
                if (!candidate) return false;
                const bounds = candidate.getBoundingClientRect();
                const style = window.getComputedStyle(candidate);
                return bounds.width > 0 && bounds.height > 0
                  && style.display !== 'none'
                  && style.visibility !== 'hidden'
                  && Number.parseFloat(style.opacity || '1') > 0;
              };
              const qa = document.querySelector('#qa');
              const bodyText = (document.body ? document.body.innerText || '' : '')
                .replace(/\s+/g, ' ')
                .trim();
              const homeRoots = [...document.querySelectorAll('#ag-home-root')];
              const deckMarkers = [...document.querySelectorAll(
                '#deck-tree, .deck-browser, .deckbrowser, .deck-browser-page, '
                + '[data-testid="deck-browser"]'
              )];
              const canonicalQuestionPresent = bodyText.includes(
                'What did this review uncover?'
              );
              const qaVisible = visible(qa);
              const visibleHomeRootCount = homeRoots.filter(visible).length;
              const visibleDeckBrowserMarkerCount = deckMarkers.filter(visible).length;
              const measureHorizontalOverflow = candidate => {
                const clientWidth = candidate
                  ? Math.floor(candidate.clientWidth) : 0;
                const scrollWidth = candidate
                  ? Math.ceil(candidate.scrollWidth) : 0;
                const horizontalOverflow = Math.max(
                  0,
                  scrollWidth - clientWidth
                );
                return {
                  clientWidth,
                  scrollWidth,
                  horizontalOverflow,
                  passed: clientWidth > 0 && scrollWidth <= clientWidth,
                };
              };
              const documentRoot = document.documentElement;
              const documentRootOverflow = {
                identity: 'document.documentElement',
                source: 'document.documentElement',
                ...measureHorizontalOverflow(documentRoot),
              };
              const addonRootCandidates = [...document.querySelectorAll(
                '#ag-home-root, [data-anki-garden-root]'
              )];
              const rootKindCounts = new Map();
              const visibleAddonRootOverflows = [];
              addonRootCandidates.forEach((candidate, domIndex) => {
                const declaredKind = (
                  candidate.getAttribute('data-anki-garden-root') || ''
                ).trim();
                const rawKind = declaredKind
                  || (candidate.id === 'ag-home-root' ? 'home' : candidate.id)
                  || candidate.tagName.toLocaleLowerCase('en-US');
                const rootKind = rawKind
                  .toLocaleLowerCase('en-US')
                  .replace(/[^a-z0-9_-]+/g, '-')
                  .replace(/^-+|-+$/g, '') || 'root';
                const kindOrdinal = (rootKindCounts.get(rootKind) || 0) + 1;
                rootKindCounts.set(rootKind, kindOrdinal);
                if (!visible(candidate)) return;
                visibleAddonRootOverflows.push({
                  identity: `anki-garden:${rootKind}:${kindOrdinal}`,
                  rootKind,
                  selector: candidate.id
                    ? `#${candidate.id}`
                    : `[data-anki-garden-root="${declaredKind}"]`,
                  domOrdinal: domIndex + 1,
                  kindOrdinal,
                  visible: true,
                  ...measureHorizontalOverflow(candidate),
                });
              });
              const visibleAddonRootCount = visibleAddonRootOverflows.length;
              const visibleAddonRootsOverflowPassed =
                visibleAddonRootOverflows.every(record => record.passed);
              const allRootOverflowPassed = documentRootOverflow.passed
                && visibleAddonRootsOverflowPassed;
              return {
                ready: !!qa && qaVisible && bodyText.length > 0
                  && canonicalQuestionPresent
                  && visibleHomeRootCount === 0
                  && visibleDeckBrowserMarkerCount === 0
                  && allRootOverflowPassed,
                qaPresent: !!qa,
                qaVisible,
                canonicalQuestionPresent,
                homeRootCount: homeRoots.length,
                visibleHomeRootCount,
                deckBrowserMarkerCount: deckMarkers.length,
                visibleDeckBrowserMarkerCount,
                documentRootOverflow,
                addonRootCandidateCount: addonRootCandidates.length,
                visibleAddonRootCount,
                visibleAddonRootOverflows,
                visibleAddonRootsOverflowPassed,
                allRootOverflowPassed,
                bodyText: bodyText.slice(0, 500),
              };
            })()
        """
        settled = False

        def resolved(result: Any) -> None:
            nonlocal settled
            if settled:
                return
            settled = True
            observation = dict(result) if isinstance(result, dict) else {
                "ready": False,
                "result_type": type(result).__name__,
            }
            observation.update({
                "capture_label": capture_label,
                "surface": "review",
            })
            self._active_reviewer_dom_audit = observation
            if bool(observation.get("ready", False)):
                QTimer.singleShot(32, on_ready)
            else:
                # Home and Reviewer share Anki's main WebEngine frame.  On
                # macOS the final Home render can occasionally land after
                # moveToState("review") has already invoked Reviewer.show(),
                # leaving the state and card correct while the old Home DOM
                # remains visible.  Only after that stale Home document is
                # positively observed, ask the real Reviewer to present again.
                # A bounded retry allows a late Home repaint to be superseded
                # without replacing Anki's native Reviewer document.
                stale_home_visible = bool(
                    observation.get("visibleHomeRootCount", 0)
                )
                repaint_attempts = int(
                    getattr(self, "_reviewer_repaint_after_home_attempts", 0)
                )
                if stale_home_visible and repaint_attempts < 4:
                    self._reviewer_repaint_after_home_attempts = repaint_attempts + 1
                    show_reviewer = getattr(reviewer, "show", None)
                    if callable(show_reviewer):
                        try:
                            show_reviewer()
                        except Exception:
                            logger.exception(
                                "Anki Garden capture: delayed Reviewer repaint failed"
                            )
                retry_or_fail()

        def callback_watchdog() -> None:
            nonlocal settled
            if settled:
                return
            settled = True
            retry_or_fail()

        resolved_once = self._one_shot_async_callback(capture_label, resolved)
        try:
            if callable(run_javascript):
                try:
                    run_javascript(script, 0, resolved_once)
                except TypeError:
                    run_javascript(script, resolved_once)
            else:
                evaluate(script, resolved_once)
            QTimer.singleShot(2500, callback_watchdog)
        except Exception:
            settled = True
            retry_or_fail()

    def _with_dashboard(
        self,
        on_ready: Callable[[], None],
        *,
        failure_label: str | None = None,
        on_error: Callable[[], None] | None = None,
    ) -> None:
        callback_label = str(
            failure_label
            or getattr(self, "_active_fixture_expected_label", "")
            or "dashboard-ready"
        )
        on_ready = self._one_shot_async_callback(
            callback_label,
            on_ready,
            on_error=on_error,
        )
        opened_at: float | None = None

        def prepare_dashboard() -> None:
            if opened_at is not None:
                elapsed_ms = max(0.0, (time.perf_counter() - opened_at) * 1000.0)
                self._performance_samples.setdefault("garden_open_ms", []).append(
                    round(elapsed_ms, 3)
                )
            dashboard = getattr(self.app, "dashboard", None)
            toast = getattr(dashboard, "toast_region", None)
            clear_toast = getattr(toast, "clear", None)
            if callable(clear_toast):
                clear_toast()
            self._move_to_capture_display(dashboard)
            on_ready()

        prepare_dashboard_once = self._one_shot_async_callback(
            callback_label,
            prepare_dashboard,
            on_error=on_error,
        )

        dashboard = getattr(self.app, "dashboard", None)
        try:
            if dashboard is not None and bool(dashboard.isVisible()):
                prepare_dashboard_once()
                return
        except Exception:
            pass
        opened_at = time.perf_counter()
        try:
            self.app.open_dashboard()
        except Exception as exc:
            self._failures.append({
                "label": callback_label,
                "reason": f"Garden Dashboard opener raised {type(exc).__name__}",
            })
            if on_error is not None:
                on_error()
            self._next_after(120)
            return
        self._wait_for_dashboard(
            prepare_dashboard_once,
            failure_label=callback_label,
            on_error=on_error,
        )

    def _record_nurtured_marker_audit(
        self,
        label: str,
        audit: dict[str, Any],
        issues: list[str],
    ) -> None:
        """Attach one fail-closed marker audit to the capture manifest."""

        passed = not issues
        audit["passed"] = passed
        if issues:
            audit["issues"] = list(dict.fromkeys(issues))
        annotation = self._capture_annotations.setdefault(label, {})
        annotation["nurtured_marker"] = audit
        annotation["passed"] = bool(annotation.get("passed", True)) and passed
        if issues:
            self._failures.append({
                "label": label,
                "reason": "Watering-can geometry audit failed: " + "; ".join(
                    dict.fromkeys(issues)
                ),
            })

    def _audit_home_nurtured_marker(self, label: str) -> None:
        """Validate the shared marker result embedded in Home HTML."""

        from ..ui.plant_display import (
            NURTURED_MARKER_MAX_GROUND_DELTA_RATIO,
            NURTURED_MARKER_MAX_PLANT_DISTANCE_RATIO,
        )

        issues: list[str] = []
        html_builder = getattr(self.app, "_home_garden_html_for_injection", None)
        html = html_builder() if callable(html_builder) else ""
        markers = re.findall(
            r'<img[^>]*data-testid="home-nurturing-marker"[^>]*>',
            str(html),
        )
        marker = markers[0] if markers else ""
        state = getattr(self.app.storage, "state", None)
        active_id = str(getattr(state, "active_plant_id", "") or "")
        active = next((
            plant for plant in list(getattr(state, "plants", ()) or ())
            if str(getattr(plant, "plant_id", "") or "") == active_id
        ), None)
        expected_slot = int(getattr(active, "slot_index", -1) or 0) if active is not None else -1
        preferred_side = "left" if expected_slot % 2 == 0 else "right"
        side_match = re.search(r'data-marker-side="([^"]+)"', marker)
        orientation_match = re.search(
            r'data-marker-orientation="([^"]+)"', marker
        )
        resolved_side = side_match.group(1) if side_match is not None else ""
        resolved_orientation = (
            orientation_match.group(1) if orientation_match is not None else ""
        )
        expected_orientation = (
            "spout-right" if resolved_side == "left" else "spout-left"
        )
        if active is None:
            issues.append("active nurtured plant was unavailable")
        if len(markers) != 1:
            issues.append(f"expected one rendered marker, found {len(markers)}")
        if f'data-marker-slot="{expected_slot}"' not in marker:
            issues.append(f"data-marker-slot did not equal {expected_slot}")
        if resolved_side not in {"left", "right"}:
            issues.append("data-marker-side was not left or right")
        if resolved_orientation != expected_orientation:
            issues.append("data-marker-orientation did not point inward")

        rect_match = re.search(r'data-marker-rect="([^"]+)"', marker)
        pulse_match = re.search(r'data-marker-pulse="([^"]+)"', marker)
        target_match = re.search(
            r'data-marker-target-ground="([^"]+)"', marker
        )
        planter_match = re.search(
            r'data-marker-planter-rect="([^"]+)"', marker
        )

        def parse_values(
            match: re.Match[str] | None,
            name: str,
            count: int,
        ) -> list[float]:
            if match is None:
                issues.append(f"{name} metadata was missing")
                return []
            try:
                values = [float(value) for value in match.group(1).split(",")]
            except (TypeError, ValueError):
                values = []
            if len(values) != count:
                issues.append(f"{name} metadata was invalid")
            return values

        rect = parse_values(rect_match, "marker rectangle", 4)
        pulse = parse_values(pulse_match, "pulse envelope", 4)
        target_ground = parse_values(target_match, "target ground", 2)
        planter = parse_values(planter_match, "planter rectangle", 4)
        if len(rect) == 4 and not (44.0 <= rect[2] <= 88.0 and rect[2] == rect[3]):
            issues.append("marker rectangle did not preserve its 44-88 pixel square")
        if len(pulse) == 4 and not (
            pulse[0] >= 0.0
            and pulse[1] >= 0.0
            and pulse[0] + pulse[2] <= 1000.0
            and pulse[1] + pulse[3] <= 420.0
        ):
            issues.append("pulse envelope extended outside the Home scene")
        plant_distance: float | None = None
        ground_delta: float | None = None
        if len(rect) == 4 and len(target_ground) == 2 and len(planter) == 4:
            marker_center_x = rect[0] + rect[2] / 2
            marker_ground_y = rect[1] + rect[3] * 0.916
            plant_distance = math.hypot(
                marker_center_x - target_ground[0],
                marker_ground_y - target_ground[1],
            )
            ground_delta = abs(marker_ground_y - target_ground[1])
            if plant_distance > planter[2] * NURTURED_MARKER_MAX_PLANT_DISTANCE_RATIO:
                issues.append("marker was too far from the nurtured plant")
            if ground_delta > rect[2] * NURTURED_MARKER_MAX_GROUND_DELTA_RATIO:
                issues.append("marker ground contact was detached from the plant")
            if resolved_side == "left" and marker_center_x >= target_ground[0]:
                issues.append("left marker crossed the nurtured plant center")
            if resolved_side == "right" and marker_center_x <= target_ground[0]:
                issues.append("right marker crossed the nurtured plant center")
        self._record_nurtured_marker_audit(
            label,
            {
                "renderer": "home-html",
                "expected_slot": expected_slot,
                "marker_count": len(markers),
                "preferred_side": preferred_side,
                "side": resolved_side,
                "orientation": resolved_orientation,
                "rect": rect,
                "pulse_bounds": pulse,
                "target_ground": target_ground,
                "planter_rect": planter,
                "plant_distance": plant_distance,
                "ground_contact_delta": ground_delta,
            },
            issues,
        )

    def _audit_qt_nurtured_marker(self, label: str, widget: QWidget) -> None:
        """Validate every visible native scene's marker and reserved envelope."""

        from ..ui.plant_display import (
            NURTURED_MARKER_MAX_GROUND_DELTA_RATIO,
            NURTURED_MARKER_MAX_PLANT_DISTANCE_RATIO,
            PlantPlacement,
            Rect,
            planter_draw_rect,
        )

        candidates = [widget, *widget.findChildren(QWidget)]
        scenes: list[Any] = []
        for candidate in candidates:
            geometry = getattr(candidate, "nurtured_marker_geometry", None)
            if not callable(geometry):
                continue
            try:
                if candidate is not widget and not candidate.isVisibleTo(widget):
                    continue
            except RuntimeError:
                continue
            scenes.append(candidate)
        issues: list[str] = []
        scene_audits: list[dict[str, Any]] = []
        if not scenes:
            issues.append("no visible native Garden scene was available")

        qt_app = QApplication.instance()
        for scene in scenes:
            scene.repaint()
            if qt_app is not None:
                qt_app.processEvents()
            # QWidget.repaint() may remain deferred for a child canvas on
            # macOS. A local grab forces the exact paint path synchronously so
            # the diagnostic below cannot describe the preceding capture.
            probe = scene.grab()
            if probe is None or probe.isNull():
                issues.append(f"{type(scene).__name__} marker probe was null")
                continue
            payload = getattr(scene, "scene", {})
            plants = [
                plant for plant in list(payload.get("plants", ()) or ())
                if isinstance(plant, dict)
            ] if isinstance(payload, dict) else []
            active = [plant for plant in plants if bool(plant.get("is_active"))]
            if len(active) != 1:
                issues.append(
                    f"{type(scene).__name__} contained {len(active)} active plants"
                )
            expected_slot = int(active[0].get("slot_index", -1)) if active else -1
            preferred_side = "left" if expected_slot % 2 == 0 else "right"
            diagnostic = scene.nurtured_marker_geometry()
            if not isinstance(diagnostic, dict):
                issues.append(f"{type(scene).__name__} did not resolve a marker")
                continue
            resolved_side = str(diagnostic.get("side", ""))
            expected_orientation = (
                "spout-right" if resolved_side == "left" else "spout-left"
            )
            expected_asset = (
                "nurtured_marker_spout_right"
                if expected_orientation == "spout-right"
                else "nurtured_marker"
            )
            if int(diagnostic.get("slot_index", -1)) != expected_slot:
                issues.append(f"{type(scene).__name__} marker targeted the wrong plot")
            if resolved_side not in {"left", "right"}:
                issues.append(f"{type(scene).__name__} marker did not use a side lane")
            if str(diagnostic.get("orientation", "")) != expected_orientation:
                issues.append(f"{type(scene).__name__} marker spout did not point inward")
            if str(diagnostic.get("asset_key", "")) != expected_asset:
                issues.append(f"{type(scene).__name__} marker used the wrong asset")
            if bool(diagnostic.get("used_fallback", True)):
                issues.append(f"{type(scene).__name__} required degraded placement")
            try:
                rect_values = [float(value) for value in diagnostic["rect"]]
                pulse_values = [float(value) for value in diagnostic["pulse_bounds"]]
                marker_rect = Rect(*rect_values)
                pulse_rect = Rect(*pulse_values)
            except (KeyError, TypeError, ValueError):
                issues.append(f"{type(scene).__name__} exposed invalid marker geometry")
                continue
            if not (44.0 <= marker_rect.width <= 88.0 and marker_rect.width == marker_rect.height):
                issues.append(f"{type(scene).__name__} marker size was outside 44-88 pixels")
            if not (
                pulse_rect.x >= 0.0
                and pulse_rect.y >= 0.0
                and pulse_rect.right <= float(scene.width())
                and pulse_rect.bottom <= float(scene.height())
            ):
                issues.append(f"{type(scene).__name__} pulse envelope left the canvas")

            layout_builder = getattr(scene, "_layout_plants", None)
            rows = (
                layout_builder(scene.width(), scene.height())
                if callable(layout_builder) else []
            )
            occupied_layouts = [
                row[1] for row in rows
                if isinstance(row, tuple)
                and len(row) >= 2
                and isinstance(row[1], PlantPlacement)
            ]
            family_builder = getattr(scene, "_planter_family_record", None)
            family = family_builder() if callable(family_builder) else {}
            target_layout = next(
                (
                    layout for layout in occupied_layouts
                    if layout.slot_index == expected_slot
                ),
                None,
            )
            plant_distance: float | None = None
            ground_delta: float | None = None
            if target_layout is None:
                issues.append(f"{type(scene).__name__} target layout was unavailable")
            else:
                diagnostic_planter = list(
                    diagnostic.get("planter_rect", ()) or ()
                )
                target_planter = planter_draw_rect(target_layout, family)
                planter_width = (
                    float(diagnostic_planter[2])
                    if len(diagnostic_planter) == 4
                    else float(target_planter.width)
                )
                marker_center_x = marker_rect.x + marker_rect.width / 2
                marker_ground_y = marker_rect.y + marker_rect.height * 0.916
                plant_distance = math.hypot(
                    marker_center_x - target_layout.ground_anchor[0],
                    marker_ground_y - target_layout.ground_anchor[1],
                )
                ground_delta = abs(
                    marker_ground_y - target_layout.ground_anchor[1]
                )
                if (
                    plant_distance
                    > max(1.0, planter_width)
                    * NURTURED_MARKER_MAX_PLANT_DISTANCE_RATIO
                ):
                    issues.append(
                        f"{type(scene).__name__} marker was too far from the nurtured plant"
                    )
                if (
                    ground_delta
                    > marker_rect.width * NURTURED_MARKER_MAX_GROUND_DELTA_RATIO
                ):
                    issues.append(
                        f"{type(scene).__name__} marker ground contact was detached"
                    )
                if resolved_side == "left" and marker_center_x >= target_layout.ground_anchor[0]:
                    issues.append(f"{type(scene).__name__} left marker crossed the plant center")
                if resolved_side == "right" and marker_center_x <= target_layout.ground_anchor[0]:
                    issues.append(f"{type(scene).__name__} right marker crossed the plant center")
            blockers = [layout.visible.expanded(4.0, 4.0) for layout in occupied_layouts]
            protected_reader = getattr(
                scene,
                "nurtured_marker_protected_regions",
                None,
            )
            protected_regions = (
                protected_reader()
                if callable(protected_reader)
                else tuple(
                    region for region in (
                        getattr(scene, "_card_connector_rect", None),
                        getattr(scene, "_status_rect", None),
                    )
                    if region is not None
                )
            )
            for qt_rect in protected_regions:
                if qt_rect is not None:
                    blockers.append(Rect(
                        qt_rect.x(),
                        qt_rect.y(),
                        qt_rect.width(),
                        qt_rect.height(),
                    ).expanded(4.0, 4.0))
            if any(pulse_rect.intersects(blocker) for blocker in blockers):
                issues.append(
                    f"{type(scene).__name__} pulse envelope overlapped protected geometry"
                )
            scene_audits.append({
                "widget": type(scene).__name__,
                "expected_slot": expected_slot,
                "preferred_side": preferred_side,
                "side": str(diagnostic.get("side", "")),
                "orientation": str(diagnostic.get("orientation", "")),
                "asset_key": str(diagnostic.get("asset_key", "")),
                "rect": rect_values,
                "pulse_bounds": pulse_values,
                "plant_distance": plant_distance,
                "ground_contact_delta": ground_delta,
                "used_fallback": bool(diagnostic.get("used_fallback", True)),
            })
        self._record_nurtured_marker_audit(
            label,
            {
                "renderer": "qt",
                "scene_count": len(scenes),
                "scenes": scene_audits,
            },
            issues,
        )

    def _audit_nurtured_marker_capture(self, label: str, widget: QWidget) -> None:
        if label not in NURTURED_MARKER_GEOMETRY_CAPTURE_LABELS:
            return
        if widget is mw:
            self._audit_home_nurtured_marker(label)
        else:
            self._audit_qt_nurtured_marker(label, widget)

    @staticmethod
    def _home_pixmap_metrics(
        pixmap: Any,
        *,
        expected_width: int,
        expected_height: int,
    ) -> dict[str, Any]:
        """Measure both generic image content and Garden-specific evidence."""

        image = pixmap.toImage()
        width = int(image.width())
        height = int(image.height())
        colors: dict[int, int] = {}
        saturated_samples = 0
        if width > 0 and height > 0:
            x_step = max(1, width // 31)
            y_step = max(1, height // 23)
            for y in range(y_step // 2, height, y_step):
                for x in range(x_step // 2, width, x_step):
                    color = image.pixelColor(x, y)
                    rgba = int(color.rgba())
                    colors[rgba] = colors.get(rgba, 0) + 1
                    if int(color.saturation()) >= 28:
                        saturated_samples += 1
        sample_count = sum(colors.values())
        dominant_ratio = (
            max(colors.values()) / sample_count
            if colors and sample_count else 1.0
        )
        saturated_ratio = (
            saturated_samples / sample_count if sample_count else 0.0
        )

        # Every release Home state has the same mint primary action and dark
        # Garden shell. Sampling both is a semantic identity gate: a colorful
        # desktop wallpaper, a transparent WebEngine layer, or the wrong native
        # window can no longer satisfy the capture contract merely by being
        # non-uniform.
        semantic_step = max(1, min(width, height) // 120)
        semantic_samples = 0
        brand_samples = 0
        dark_samples = 0
        for y in range(semantic_step // 2, height, semantic_step):
            for x in range(semantic_step // 2, width, semantic_step):
                color = image.pixelColor(x, y)
                rgb = (int(color.red()), int(color.green()), int(color.blue()))
                semantic_samples += 1
                if max(
                    abs(channel - expected)
                    for channel, expected in zip(rgb, HOME_CAPTURE_BRAND_RGB)
                ) <= 22:
                    brand_samples += 1
                if any(
                    max(
                        abs(channel - expected)
                        for channel, expected in zip(rgb, dark_rgb)
                    ) <= 22
                    for dark_rgb in HOME_CAPTURE_DARK_RGB
                ):
                    dark_samples += 1
        brand_ratio = (
            brand_samples / semantic_samples if semantic_samples else 0.0
        )
        dark_ratio = (
            dark_samples / semantic_samples if semantic_samples else 0.0
        )
        actual_aspect = width / height if width > 0 and height > 0 else 0.0
        expected_aspect = (
            max(1, int(expected_width)) / max(1, int(expected_height))
        )
        aspect_ratio_error = (
            abs(actual_aspect / expected_aspect - 1.0)
            if actual_aspect > 0 and expected_aspect > 0 else 1.0
        )
        semantic_passed = brand_ratio >= 0.001 and dark_ratio >= 0.003
        # A screen-filling Home keeps its content centered at the product's
        # authored width, so its saturated pixels occupy a smaller fraction of
        # the enlarged app-owned shell.  Once the exact Garden palette is
        # proven, retain the independent diversity, nondominance, and aspect
        # gates without requiring the compact-window density threshold too.
        semantic_density_fallback_used = bool(
            semantic_passed and saturated_ratio < 0.04
        )
        generic_passed = (
            len(colors) >= 8
            and dominant_ratio < 0.92
            and (saturated_ratio >= 0.04 or semantic_passed)
            and aspect_ratio_error <= 0.12
        )
        return {
            "sample_count": sample_count,
            "unique_sampled_colors": len(colors),
            "dominant_color_ratio": round(dominant_ratio, 4),
            "saturated_sample_ratio": round(saturated_ratio, 4),
            "semantic_sample_count": semantic_samples,
            "brand_sample_ratio": round(brand_ratio, 4),
            "dark_shell_sample_ratio": round(dark_ratio, 4),
            "actual_aspect_ratio": round(actual_aspect, 4),
            "expected_aspect_ratio": round(expected_aspect, 4),
            "aspect_ratio_error": round(aspect_ratio_error, 4),
            "semantic_density_fallback_used": semantic_density_fallback_used,
            "generic_content_passed": generic_passed,
            "semantic_identity_passed": semantic_passed,
            "passed": generic_passed and semantic_passed,
        }

    @staticmethod
    def _pixmap_contains_overlay(
        pixmap: Any,
        root: QWidget,
        overlay: QWidget,
    ) -> bool:
        """Confirm sampled overlay pixels survived the selected capture path."""

        try:
            if not overlay.isVisibleTo(root):
                return False
            overlay_pixmap = overlay.grab()
            if overlay_pixmap is None or overlay_pixmap.isNull():
                return False
            target_image = pixmap.toImage()
            overlay_image = overlay_pixmap.toImage()
            if target_image.isNull() or overlay_image.isNull():
                return False
            origin = overlay.mapTo(root, overlay.rect().topLeft())
            if (
                int(origin.x()) < 0
                or int(origin.y()) < 0
                or int(origin.x()) + int(overlay.width()) > int(root.width())
                or int(origin.y()) + int(overlay.height()) > int(root.height())
            ):
                return False
            scale_x = target_image.width() / max(1, int(root.width()))
            scale_y = target_image.height() / max(1, int(root.height()))
            matches = 0
            compared = 0
            for x_fraction in (0.08, 0.23, 0.41, 0.59, 0.77, 0.92):
                for y_fraction in (0.12, 0.31, 0.50, 0.69, 0.88):
                    source_x = min(
                        overlay_image.width() - 1,
                        max(0, round(x_fraction * (overlay_image.width() - 1))),
                    )
                    source_y = min(
                        overlay_image.height() - 1,
                        max(0, round(y_fraction * (overlay_image.height() - 1))),
                    )
                    source_color = overlay_image.pixelColor(source_x, source_y)
                    if source_color.alpha() < 192:
                        continue
                    target_x = round(
                        (int(origin.x()) + x_fraction * int(overlay.width()))
                        * scale_x
                    )
                    target_y = round(
                        (int(origin.y()) + y_fraction * int(overlay.height()))
                        * scale_y
                    )
                    if not (
                        0 <= target_x < target_image.width()
                        and 0 <= target_y < target_image.height()
                    ):
                        continue
                    target_color = target_image.pixelColor(target_x, target_y)
                    compared += 1
                    if max(
                        abs(source_color.red() - target_color.red()),
                        abs(source_color.green() - target_color.green()),
                        abs(source_color.blue() - target_color.blue()),
                    ) <= 48:
                        matches += 1
            if compared >= 8 and matches / compared >= 0.45:
                return True

            # Text, SVG strokes, and transparent icon buttons can have too few
            # opaque pixels at the coarse grid points above. Inspect their
            # actual painted pixels densely while keeping work bounded.
            dense_compared = 0
            dense_matches = 0
            dense_step = max(
                1,
                min(4, min(overlay_image.width(), overlay_image.height()) // 28),
            )
            for source_y in range(0, overlay_image.height(), dense_step):
                for source_x in range(0, overlay_image.width(), dense_step):
                    source_color = overlay_image.pixelColor(source_x, source_y)
                    if source_color.alpha() < 96:
                        continue
                    logical_x = (
                        source_x
                        * int(overlay.width())
                        / max(1, overlay_image.width())
                    )
                    logical_y = (
                        source_y
                        * int(overlay.height())
                        / max(1, overlay_image.height())
                    )
                    target_x = round(
                        (int(origin.x()) + logical_x) * scale_x
                    )
                    target_y = round(
                        (int(origin.y()) + logical_y) * scale_y
                    )
                    if not (
                        0 <= target_x < target_image.width()
                        and 0 <= target_y < target_image.height()
                    ):
                        continue
                    target_color = target_image.pixelColor(target_x, target_y)
                    dense_compared += 1
                    if max(
                        abs(source_color.red() - target_color.red()),
                        abs(source_color.green() - target_color.green()),
                        abs(source_color.blue() - target_color.blue()),
                    ) <= 64:
                        dense_matches += 1
            return bool(
                dense_compared >= 3
                and dense_matches / dense_compared >= 0.50
            )
        except (AttributeError, RuntimeError, TypeError, ValueError):
            return False

    @staticmethod
    def _pixmap_icon_region_has_detail(
        pixmap: Any,
        root: QWidget,
        button: QAbstractButton,
    ) -> bool:
        """Prove a compact icon left visible contrast in the final PNG."""

        try:
            target = pixmap.toImage()
            if target.isNull() or not button.isVisibleTo(root):
                return False
            origin = button.mapTo(root, button.rect().topLeft())
            icon_size = button.iconSize()
            logical_width = max(1, int(icon_size.width()))
            logical_height = max(1, int(icon_size.height()))
            logical_left = int(origin.x()) + max(
                0,
                (int(button.width()) - logical_width) // 2,
            )
            logical_top = int(origin.y()) + max(
                0,
                (int(button.height()) - logical_height) // 2,
            )
            scale_x = target.width() / max(1, int(root.width()))
            scale_y = target.height() / max(1, int(root.height()))
            left = max(0, round(logical_left * scale_x))
            top = max(0, round(logical_top * scale_y))
            right = min(
                target.width(),
                round((logical_left + logical_width) * scale_x),
            )
            bottom = min(
                target.height(),
                round((logical_top + logical_height) * scale_y),
            )
            if right - left < 3 or bottom - top < 3:
                return False
            luminance: list[int] = []
            quantized: set[tuple[int, int, int]] = set()
            for y in range(top, bottom):
                for x in range(left, right):
                    color = target.pixelColor(x, y)
                    if color.alpha() < 64:
                        continue
                    red, green, blue = color.red(), color.green(), color.blue()
                    luminance.append((red * 3 + green * 6 + blue) // 10)
                    quantized.add((red // 8, green // 8, blue // 8))
            return bool(
                len(luminance) >= 12
                and len(quantized) >= 3
                and max(luminance) - min(luminance) >= 16
            )
        except (AttributeError, RuntimeError, TypeError, ValueError):
            return False

    @staticmethod
    def _widget_bounds_evidence(
        widget: Any,
        container: Any,
    ) -> dict[str, Any]:
        """Return fail-closed logical bounds for one painted child."""

        if widget is None or container is None:
            return {
                "bounds": [],
                "container_size": [],
                "visible": False,
                "intersects": False,
                "contained": False,
            }
        try:
            origin = widget.mapTo(container, widget.rect().topLeft())
            bounds = [
                int(origin.x()),
                int(origin.y()),
                int(widget.width()),
                int(widget.height()),
            ]
            container_size = [int(container.width()), int(container.height())]
            left, top, width, height = bounds
            intersects = bool(
                width > 0
                and height > 0
                and left < container_size[0]
                and top < container_size[1]
                and left + width > 0
                and top + height > 0
            )
            contained = bool(
                intersects
                and left >= 0
                and top >= 0
                and left + width <= container_size[0]
                and top + height <= container_size[1]
            )
            return {
                "bounds": bounds,
                "container_size": container_size,
                "visible": bool(widget.isVisibleTo(container)),
                "intersects": intersects,
                "contained": contained,
            }
        except (AttributeError, RuntimeError, TypeError, ValueError):
            return {
                "bounds": [],
                "container_size": [],
                "visible": False,
                "intersects": False,
                "contained": False,
            }

    @staticmethod
    def _external_widget_bounds_evidence(
        widget: Any,
        container: Any,
    ) -> dict[str, Any]:
        """Return bounds for widgets outside the audited container tree."""

        if widget is None or container is None:
            return {
                "bounds": [],
                "container_size": [],
                "visible": False,
                "intersects": False,
                "contained": False,
            }
        try:
            origin = container.mapFromGlobal(
                widget.mapToGlobal(widget.rect().topLeft())
            )
            bounds = [
                int(origin.x()),
                int(origin.y()),
                int(widget.width()),
                int(widget.height()),
            ]
            container_size = [int(container.width()), int(container.height())]
            left, top, width, height = bounds
            intersects = bool(
                width > 0
                and height > 0
                and left < container_size[0]
                and top < container_size[1]
                and left + width > 0
                and top + height > 0
            )
            contained = bool(
                intersects
                and left >= 0
                and top >= 0
                and left + width <= container_size[0]
                and top + height <= container_size[1]
            )
            return {
                "bounds": bounds,
                "container_size": container_size,
                "visible": bool(widget.isVisible() and container.isVisible()),
                "intersects": intersects,
                "contained": contained,
            }
        except (AttributeError, RuntimeError, TypeError, ValueError):
            return {
                "bounds": [],
                "container_size": [],
                "visible": False,
                "intersects": False,
                "contained": False,
            }

    @staticmethod
    def _rectangle_clearance(
        first: list[int],
        second: list[int],
    ) -> int:
        """Return the minimum axis clearance, or zero for overlapping rects."""

        if len(first) != 4 or len(second) != 4:
            return 0
        first_left, first_top, first_width, first_height = first
        second_left, second_top, second_width, second_height = second
        first_right = first_left + first_width
        first_bottom = first_top + first_height
        second_right = second_left + second_width
        second_bottom = second_top + second_height
        horizontal_overlap = first_left < second_right and second_left < first_right
        vertical_overlap = first_top < second_bottom and second_top < first_bottom
        if horizontal_overlap and vertical_overlap:
            return 0
        horizontal_gap = max(
            0,
            second_left - first_right,
            first_left - second_right,
        )
        vertical_gap = max(
            0,
            second_top - first_bottom,
            first_top - second_bottom,
        )
        if horizontal_overlap:
            return vertical_gap
        if vertical_overlap:
            return horizontal_gap
        return min(horizontal_gap, vertical_gap)

    def _reviewer_overlay_geometry_audit(
        self,
        label: str,
        toast: Any,
    ) -> dict[str, Any]:
        """Prove Reviewer feedback is bounded and clear of answer controls."""

        reviewer = getattr(mw, "reviewer", None)
        expected_parent = getattr(reviewer, "web", None)
        parent = toast.parentWidget() if toast is not None else None
        evidence = self._widget_bounds_evidence(toast, parent)
        capture_evidence = self._external_widget_bounds_evidence(toast, mw)
        bounds = list(evidence.get("bounds", ()) or ())
        viewport_size = list(evidence.get("container_size", ()) or ())
        width = bounds[2] if len(bounds) == 4 else 0
        height = bounds[3] if len(bounds) == 4 else 0
        expected_width = 292
        width_exact = width == expected_width
        size_in_range = bool(
            width_exact
            and 48 <= height <= 78
        )

        # Reviewer answer buttons live inside WebEngine and are not QWidgets.
        # Reserve the complete lower control band in logical viewport pixels;
        # any discovered Qt-owned reviewer controls are added as stricter bounds.
        control_rects: list[dict[str, Any]] = []
        if len(viewport_size) == 2:
            reserved_height = min(128, max(88, viewport_size[1] // 5))
            control_rects.append({
                "name": "reviewer-answer-and-toolbar-reserved-band",
                "bounds": [
                    0,
                    max(0, viewport_size[1] - reserved_height),
                    viewport_size[0],
                    reserved_height,
                ],
                "source": "reviewer-viewport-contract",
            })
        if parent is not None:
            for control in mw.findChildren(QAbstractButton):
                try:
                    copy = " ".join((
                        _displayed_button_text(control),
                        str(control.accessibleName() or ""),
                        str(control.objectName() or ""),
                    )).casefold()
                    if not any(
                        marker in copy
                        for marker in (
                            "show answer", "again", "hard", "good", "easy",
                            "edit", "more",
                        )
                    ):
                        continue
                    control_evidence = self._external_widget_bounds_evidence(
                        control,
                        parent,
                    )
                    if not (
                        control_evidence.get("visible", False)
                        and control_evidence.get("intersects", False)
                    ):
                        continue
                    control_rects.append({
                        "name": copy.strip(),
                        "bounds": list(control_evidence["bounds"]),
                        "source": "qt-control",
                    })
                except (AttributeError, RuntimeError, TypeError, ValueError):
                    continue
        clearances = [
            self._rectangle_clearance(bounds, list(control["bounds"]))
            for control in control_rects
        ]
        minimum_clearance = min(clearances) if clearances else 0
        parent_is_reviewer_webview = bool(
            expected_parent is not None and parent is expected_parent
        )
        close_buttons = [
            candidate
            for candidate in toast.findChildren(QAbstractButton)
            if "close" in str(candidate.accessibleName() or "").casefold()
            and candidate.isVisibleTo(toast)
        ] if toast is not None else []
        close_evidence = (
            self._widget_bounds_evidence(close_buttons[0], toast)
            if len(close_buttons) == 1 else
            {"bounds": [], "contained": False}
        )
        close_contract = (
            self._close_pixmap_contract(
                close_buttons[0].icon().pixmap(
                    max(1, int(close_buttons[0].iconSize().width())),
                    max(1, int(close_buttons[0].iconSize().height())),
                )
            )
            if len(close_buttons) == 1 else
            {"passed": False}
        )
        close_passed = bool(
            len(close_buttons) == 1
            and close_evidence.get("contained", False)
            and int(close_buttons[0].width()) == 32
            and int(close_buttons[0].height()) == 32
            and close_contract.get("passed") is True
        )
        reviewer_state_is_review = str(getattr(mw, "state", "") or "") == "review"
        cleanup_handler = getattr(
            getattr(self.app, "reviewer_hooks", None),
            "on_state_change",
            None,
        )
        passed = bool(
            toast is not None
            and toast.isVisible()
            and reviewer_state_is_review
            and parent_is_reviewer_webview
            and callable(cleanup_handler)
            and evidence.get("contained", False)
            and size_in_range
            and control_rects
            and minimum_clearance >= 16
            and close_passed
        )
        return {
            "parent_is_reviewer_webview": parent_is_reviewer_webview,
            "parent_contract": "mw.reviewer.web-exact",
            "reviewer_state_is_review": reviewer_state_is_review,
            "non_review_cleanup_registered": callable(cleanup_handler),
            "overlay_bounds": bounds,
            "capture_bounds": list(
                capture_evidence.get("bounds", ()) or ()
            ),
            "viewport_size": viewport_size,
            "viewport_contained": bool(evidence.get("contained", False)),
            "width": width,
            "height": height,
            "expected_width": expected_width,
            "width_exact": width_exact,
            "size_in_range": size_in_range,
            "control_rects": control_rects,
            "minimum_control_clearance": minimum_clearance,
            "reserved_zone_passed": bool(
                control_rects and minimum_clearance >= 16
            ),
            "close_bounds": list(close_evidence.get("bounds", ()) or ()),
            "close_stroke_contract": close_contract,
            "close_passed": close_passed,
            "passed": passed,
        }

    @staticmethod
    def _icon_has_visible_pixels(button: Any) -> bool:
        try:
            icon = button.icon()
            icon_size = button.iconSize()
            if icon is None or icon.isNull():
                return False
            pixmap = icon.pixmap(
                max(1, int(icon_size.width())),
                max(1, int(icon_size.height())),
            )
            if pixmap.isNull():
                return False
            image = pixmap.toImage()
            visible = 0
            for y in range(int(image.height())):
                for x in range(int(image.width())):
                    if image.pixelColor(x, y).alpha() >= 64:
                        visible += 1
                        if visible >= 3:
                            return True
            return False
        except (AttributeError, RuntimeError, TypeError, ValueError):
            return False

    @staticmethod
    def _close_pixmap_contract(pixmap: Any) -> dict[str, Any]:
        """Prove that a rendered close mark has two centered diagonals."""

        result: dict[str, Any] = {
            "visible_pixels": 0,
            "quadrants": {"top_left": 0, "top_right": 0,
                          "bottom_left": 0, "bottom_right": 0},
            "both_diagonals": False,
            "centered": False,
            "passed": False,
        }
        try:
            if pixmap is None or pixmap.isNull():
                return result
            image = pixmap.toImage()
            width, height = int(image.width()), int(image.height())
            if width < 8 or height < 8:
                return result
            coordinates: list[tuple[int, int]] = []
            center_x = (width - 1) / 2.0
            center_y = (height - 1) / 2.0
            dead_x = max(0.5, width * 0.04)
            dead_y = max(0.5, height * 0.04)
            quadrants = result["quadrants"]
            for y in range(height):
                for x in range(width):
                    if image.pixelColor(x, y).alpha() < 64:
                        continue
                    coordinates.append((x, y))
                    if x < center_x - dead_x and y < center_y - dead_y:
                        quadrants["top_left"] += 1
                    elif x > center_x + dead_x and y < center_y - dead_y:
                        quadrants["top_right"] += 1
                    elif x < center_x - dead_x and y > center_y + dead_y:
                        quadrants["bottom_left"] += 1
                    elif x > center_x + dead_x and y > center_y + dead_y:
                        quadrants["bottom_right"] += 1
            result["visible_pixels"] = len(coordinates)
            if not coordinates:
                return result
            minimum_x = min(x for x, _y in coordinates)
            maximum_x = max(x for x, _y in coordinates)
            minimum_y = min(y for _x, y in coordinates)
            maximum_y = max(y for _x, y in coordinates)
            rendered_center_x = (minimum_x + maximum_x) / 2.0
            rendered_center_y = (minimum_y + maximum_y) / 2.0
            tolerance = max(1.0, max(width, height) * 0.08)
            centered = bool(
                abs(rendered_center_x - center_x) <= tolerance
                and abs(rendered_center_y - center_y) <= tolerance
            )
            both_diagonals = bool(
                quadrants["top_left"] >= 2
                and quadrants["bottom_right"] >= 2
                and quadrants["top_right"] >= 2
                and quadrants["bottom_left"] >= 2
            )
            span_passed = bool(
                maximum_x - minimum_x >= width * 0.42
                and maximum_y - minimum_y >= height * 0.42
            )
            result.update({
                "bounds": [minimum_x, minimum_y,
                           maximum_x - minimum_x + 1,
                           maximum_y - minimum_y + 1],
                "both_diagonals": both_diagonals,
                "centered": centered,
                "passed": bool(both_diagonals and centered and span_passed),
            })
            return result
        except (AttributeError, RuntimeError, TypeError, ValueError):
            return result

    @staticmethod
    def _switch_thumb_contract(button: Any) -> dict[str, Any]:
        """Verify the switch thumb is present at the state-defined end."""

        result = {
            "state": str(button.property("switchState") or ""),
            "thumb_contrast": 0,
            "passed": False,
        }
        try:
            icon = button.icon()
            icon_size = button.iconSize()
            if icon is None or icon.isNull():
                return result
            pixmap = icon.pixmap(
                max(1, int(icon_size.width())),
                max(1, int(icon_size.height())),
            )
            if pixmap.isNull():
                return result
            image = pixmap.toImage()
            width, height = int(image.width()), int(image.height())
            state = result["state"]
            expected_ratio = 27 / 38 if state == "on" else 11 / 38
            opposite_ratio = 11 / 38 if state == "on" else 27 / 38
            y = max(0, min(height - 1, round((height - 1) / 2)))
            expected_x = max(
                0,
                min(width - 1, round((width - 1) * expected_ratio)),
            )
            opposite_x = max(
                0,
                min(width - 1, round((width - 1) * opposite_ratio)),
            )
            expected = image.pixelColor(expected_x, y)
            opposite = image.pixelColor(opposite_x, y)
            contrast = max(
                abs(expected.red() - opposite.red()),
                abs(expected.green() - opposite.green()),
                abs(expected.blue() - opposite.blue()),
            )
            result["thumb_contrast"] = contrast
            result["icon_size"] = [width, height]
            result["passed"] = bool(
                state in {"on", "off"}
                and width >= 36
                and height >= 20
                and contrast >= 24
            )
            return result
        except (AttributeError, RuntimeError, TypeError, ValueError):
            return result

    def _native_layout_telemetry_audit(
        self,
        root: QWidget,
        label: str,
    ) -> tuple[dict[str, Any], list[dict[str, Any]]]:
        """Consume the shell-owned telemetry and bind it to release limits."""

        window_family = expected_capture_window_family(label)
        if window_family == "AnkiQt":
            return ({
                "applicable": False,
                "source": "",
                "issues": [],
                "passed": True,
            }, [])
        reader = getattr(root, "capture_layout_telemetry", None)
        if not callable(reader):
            return ({
                "applicable": False,
                "source": "",
                "issues": [],
                "passed": True,
            }, [])
        issue_codes: list[str] = []
        try:
            raw = dict(reader())
        except Exception as exc:
            issue = f"native-layout-telemetry-error:{type(exc).__name__}"
            return ({
                "applicable": True,
                "source": "DialogShell.capture_layout_telemetry",
                "issues": [issue],
                "passed": False,
            }, [{"kind": issue, "native_layout_telemetry": True}])

        client_width = max(1, int(root.contentsRect().width()))
        fill = raw.get("clientSurfaceFill")
        fill_number = (
            float(fill)
            if isinstance(fill, (int, float)) and not isinstance(fill, bool)
            else -1.0
        )
        client_gutter = (
            max(0, client_width - round(client_width * fill_number))
            if 0.0 <= fill_number <= 1.0 else -1
        )
        if not 0.0 <= fill_number <= 1.0:
            issue_codes.append("invalid-client-surface-fill")
        elif client_gutter > int(
            CAPTURE_LAYOUT_LIMITS["maximum_client_gutter_px"]
        ):
            issue_codes.append("client-surface-gutter")

        footer_gap = raw.get("contentToFooterGap")
        if footer_gap is not None and (
            type(footer_gap) is not int
            or footer_gap < 0
            or footer_gap > int(
                CAPTURE_LAYOUT_LIMITS["maximum_content_footer_gap_px"]
            )
        ):
            issue_codes.append("content-footer-gap")

        nursery_offset = raw.get("nurseryRootOffset")
        nursery_expected = expected_capture_window_family(label) == "NurseryDialog"
        if nursery_expected and (
            type(nursery_offset) is not int
            or nursery_offset < 0
            or nursery_offset > int(
                CAPTURE_LAYOUT_LIMITS["maximum_nursery_root_offset_px"]
            )
        ):
            issue_codes.append("nursery-root-offset")
        elif not nursery_expected and nursery_offset is not None and (
            type(nursery_offset) is not int or nursery_offset < 0
        ):
            issue_codes.append("invalid-nursery-root-offset")

        action_ratio = raw.get("maximumActionWidthRatio")
        action_ratio_number = (
            float(action_ratio)
            if isinstance(action_ratio, (int, float))
            and not isinstance(action_ratio, bool)
            else -1.0
        )
        if not 0.0 <= action_ratio_number <= 1.0:
            issue_codes.append("invalid-action-width-ratio")
        elif action_ratio_number > float(
            CAPTURE_LAYOUT_LIMITS["maximum_action_width_ratio"]
        ):
            issue_codes.append("stretched-action")

        minimum_text = raw.get("minimumRenderedTextSize")
        minimum_text_number = (
            float(minimum_text)
            if isinstance(minimum_text, (int, float))
            and not isinstance(minimum_text, bool)
            else -1.0
        )
        if minimum_text_number < float(
            CAPTURE_LAYOUT_LIMITS["minimum_rendered_text_px"]
        ):
            issue_codes.append("rendered-text-below-floor")
        if raw.get("elisionWithoutTooltipCount") != 0:
            issue_codes.append("elision-without-tooltip")

        scrollbars = raw.get("scrollbars")
        if not isinstance(scrollbars, list):
            scrollbars = []
            issue_codes.append("invalid-scrollbar-telemetry")
        window_mode = raw.get("windowMode")
        if window_mode not in {"canvas", "workspace", "content"}:
            issue_codes.append("invalid-window-mode")
            window_mode = ""
        content_fit_pending = raw.get("contentFitPending")
        if type(content_fit_pending) is not bool:
            issue_codes.append("invalid-content-fit-pending")
        elif content_fit_pending and window_mode != "canvas":
            issue_codes.append("content-fit-not-settled")
        safety_scroll_active = raw.get("safetyScrollActive")
        if type(safety_scroll_active) is not bool:
            issue_codes.append("invalid-safety-scroll-active")
            safety_scroll_active = False
        for bounds_name in ("clientBounds", "bodyBounds"):
            bounds = raw.get(bounds_name)
            if bounds_name == "bodyBounds" and window_mode == "canvas" and bounds is None:
                continue
            if (
                not isinstance(bounds, dict)
                or set(bounds) != {"x", "y", "width", "height"}
                or any(type(bounds.get(key)) is not int for key in bounds)
                or int(bounds.get("width", 0)) <= 0
                or int(bounds.get("height", 0)) <= 0
            ):
                issue_codes.append(f"invalid-{bounds_name}")
        footer_bounds = raw.get("footerBounds")
        if footer_bounds is not None and (
            not isinstance(footer_bounds, dict)
            or set(footer_bounds) != {"x", "y", "width", "height"}
            or any(type(footer_bounds.get(key)) is not int for key in footer_bounds)
            or int(footer_bounds.get("width", 0)) <= 0
            or int(footer_bounds.get("height", 0)) <= 0
        ):
            issue_codes.append("invalid-footerBounds")
        settled_size = raw.get("settledSize")
        if (
            not isinstance(settled_size, dict)
            or set(settled_size) != {"width", "height"}
            or type(settled_size.get("width")) is not int
            or type(settled_size.get("height")) is not int
            or settled_size.get("width") != int(root.width())
            or settled_size.get("height") != int(root.height())
        ):
            issue_codes.append("invalid-settled-size")
        overflow_owner_count = raw.get("overflowOwnerCount")
        if (
            type(overflow_owner_count) is not int
            or overflow_owner_count < 0
            or overflow_owner_count > int(
                CAPTURE_LAYOUT_LIMITS["maximum_overflow_owner_count"]
            )
        ):
            issue_codes.append("overflow-owner-count")
        elif window_mode == "canvas" and overflow_owner_count != 0:
            issue_codes.append("canvas-overflow-owner")
        elif window_mode == "workspace" and overflow_owner_count != 1:
            issue_codes.append("workspace-overflow-owner")
        elif window_mode == "content" and (
            (bool(safety_scroll_active) and overflow_owner_count != 1)
            or (not bool(safety_scroll_active) and overflow_owner_count != 0)
        ):
            issue_codes.append("content-overflow-owner")
        if window_mode != "content" and bool(safety_scroll_active):
            issue_codes.append("safety-scroll-outside-content-mode")
        if (
            window_mode == "content"
            and bool(safety_scroll_active)
            and not bool(getattr(root, "_content_screen_limited", False))
        ):
            issue_codes.append("safety-scroll-without-screen-limit")
        owner_rows = 0
        for row in scrollbars:
            if not isinstance(row, dict):
                issue_codes.append("invalid-scrollbar-record")
                continue
            minimum = row.get("minimum")
            maximum = row.get("maximum")
            value = row.get("value")
            visible = row.get("visible")
            owner = row.get("overflowOwner")
            if (
                type(minimum) is not int
                or type(maximum) is not int
                or type(value) is not int
                or type(visible) is not bool
                or type(owner) is not bool
                or maximum < minimum
                or not minimum <= value <= maximum
            ):
                issue_codes.append("invalid-scrollbar-record")
                continue
            owner_rows += int(owner)
            if owner and visible is not (maximum > minimum):
                issue_codes.append("scrollbar-range-visibility")
            if not owner and visible:
                issue_codes.append("non-owner-scrollbar-visible")
        if type(overflow_owner_count) is int and owner_rows != overflow_owner_count:
            issue_codes.append("overflow-owner-record-mismatch")

        buttons: list[dict[str, Any]] = []
        for button in root.findChildren(QPushButton):
            try:
                if (
                    button.window() is not root
                    or not button.isVisibleTo(root)
                    or bool(button.property("catalogCard"))
                    or bool(button.property("environmentTile"))
                ):
                    continue
                size_name = str(button.property("buttonSize") or "")
                # Navigation rows, filters, and other purpose-built controls
                # do not opt into the shared action-button tokens. Their own
                # geometry is audited by the visual contract; treating an
                # absent token as a failed token created warnings for valid UI.
                if not size_name:
                    continue
                expected_height = CAPTURE_BUTTON_HEIGHTS.get(size_name)
                height = int(button.height())
                text = _displayed_button_text(button).strip()
                measured_text_size = button.property("renderedTextSizePx")
                if (
                    isinstance(measured_text_size, (int, float))
                    and not isinstance(measured_text_size, bool)
                ):
                    text_size = round(float(measured_text_size), 2)
                else:
                    font = button.font()
                    pixel_size = int(font.pixelSize())
                    if pixel_size > 0:
                        text_size = float(pixel_size)
                    else:
                        point_size = float(font.pointSizeF())
                        screen = root.screen()
                        dpi = (
                            float(screen.logicalDotsPerInchY())
                            if screen is not None else 96.0
                        )
                        text_size = round(point_size * dpi / 72.0, 2)
                visual_control_size = button.property("visualControlSize")
                visual_size = (
                    int(visual_control_size)
                    if type(visual_control_size) is int else -1
                )
                expected_outer_height = (
                    int(expected_height)
                    if type(expected_height) is int else -1
                )
                maximum_outer_height = (
                    int(expected_height) + 4
                    if type(expected_height) is int else -1
                )
                outer_height_valid = bool(
                    expected_outer_height <= height <= maximum_outer_height
                )
                width = int(button.width())
                icon_geometry_valid = bool(
                    size_name != "icon"
                    or (
                        width == height
                        and expected_outer_height
                        <= width <= maximum_outer_height
                    )
                )
                passed = bool(
                    type(expected_height) is int
                    and visual_size == expected_height
                    and outer_height_valid
                    and 0 <= height - visual_size <= 4
                    and (
                        not text
                        or text_size >= float(
                            CAPTURE_LAYOUT_LIMITS["minimum_rendered_text_px"]
                        )
                    )
                    and icon_geometry_valid
                )
                buttons.append({
                    "text": text,
                    "buttonSize": size_name,
                    "height": height,
                    "width": width,
                    "expectedHeight": expected_height,
                    "expectedOuterHeight": expected_outer_height,
                    "maximumOuterHeight": maximum_outer_height,
                    "visualControlSize": visual_size,
                    "outerBorderAllowance": height - visual_size,
                    "renderedTextSize": text_size,
                    "passed": passed,
                })
                if not passed:
                    issue_codes.append("button-geometry-or-text-size")
            except (AttributeError, RuntimeError, TypeError, ValueError):
                issue_codes.append("button-telemetry-error")

        tabular_widgets: list[dict[str, Any]] = []
        for candidate in root.findChildren(QWidget):
            try:
                if candidate.window() is not root or not candidate.isVisibleTo(root):
                    continue
                text_getter = getattr(candidate, "text", None)
                text = str(text_getter()).strip() if callable(text_getter) else ""
                if not text or not any(character.isdigit() for character in text):
                    continue
                if bool(candidate.property("tabularNumerals")):
                    tabular_widgets.append({
                        "widget": type(candidate).__name__,
                        "objectName": str(candidate.objectName() or ""),
                        "text": text[:120],
                    })
            except (AttributeError, RuntimeError, TypeError, ValueError):
                continue
        if label in TABULAR_NUMERAL_CAPTURE_LABELS and not tabular_widgets:
            issue_codes.append("missing-tabular-numeral-evidence")

        unique_issues = list(dict.fromkeys(issue_codes))
        audit = {
            "applicable": True,
            "source": "DialogShell.capture_layout_telemetry",
            **raw,
            "clientWidth": client_width,
            "clientGutterPx": client_gutter,
            "buttonRecords": buttons,
            "tabularNumeralWidgets": tabular_widgets,
            "tabularNumeralWidgetCount": len(tabular_widgets),
            "tabularNumeralsRequired": label in TABULAR_NUMERAL_CAPTURE_LABELS,
            "limits": dict(CAPTURE_LAYOUT_LIMITS),
            "buttonHeights": dict(CAPTURE_BUTTON_HEIGHTS),
            "issues": unique_issues,
            "passed": not unique_issues,
        }
        warnings = [
            {"kind": issue, "native_layout_telemetry": True}
            for issue in unique_issues
        ]
        return audit, warnings

    def _visual_contract_audit(
        self,
        root: QWidget,
        label: str,
    ) -> tuple[dict[str, Any], list[dict[str, Any]]]:
        """Measure release geometry that warning lists alone cannot prove."""

        if root is mw:
            return ({
                "applicable": False,
                "controls": [],
                "visible_actions": [],
                "visible_action_count": 0,
                "dialog_size": [int(root.width()), int(root.height())],
                "visible_actions_contained": True,
                "visible_action_overlaps": [],
                "visible_actions_non_overlapping": True,
                "close_icons": [],
                "primary_action_count": 0,
                "visible_horizontal_scrollbars": [],
                "largest_unexplained_gap": 0,
                "screen_contained": True,
                "popover": {"applicable": False, "passed": True},
                "issues": [],
                "passed": True,
            }, [])

        issue_codes: list[str] = []
        controls: list[dict[str, Any]] = []
        close_icons: list[dict[str, Any]] = []
        primary_actions: list[str] = []
        primary_scope_widgets: list[QWidget] = []
        primary_action_groups: list[dict[str, Any]] = []
        footer_actions: list[dict[str, Any]] = []
        visible_action_records: list[dict[str, Any]] = []
        visible_action_widgets: list[QAbstractButton] = []
        pinned_footer = getattr(root, "_pinned_footer", None)
        clipping_records: list[dict[str, Any]] = []

        card_markers = (
            "catalogCard",
            "nurseryCatalogCard",
            "environmentTile",
            "fertilizerCard",
            "nurseryPlant",
            "spaceBed",
            "achievementCard",
            "sectionCard",
            "detailCard",
        )

        def nearest_clip_owner(widget: QWidget) -> tuple[QWidget, str]:
            ancestor = widget.parentWidget()
            while ancestor is not None and ancestor is not root:
                if isinstance(ancestor, QAbstractScrollArea):
                    name = str(
                        ancestor.accessibleName()
                        or ancestor.objectName()
                        or type(ancestor).__name__
                    )
                    return ancestor.viewport(), name
                ancestor = ancestor.parentWidget()
            return root, str(root.windowTitle() or type(root).__name__)

        def intentional_scroll_reveal(
            owner: QWidget,
            evidence: dict[str, Any],
        ) -> bool:
            bounds = list(evidence.get("bounds", ()) or ())
            owner_size = list(evidence.get("container_size", ()) or ())
            if owner is root or len(bounds) != 4 or len(owner_size) != 2:
                return False
            left, top, width, height = (int(value) for value in bounds)
            owner_width, owner_height = (int(value) for value in owner_size)
            horizontally_contained = bool(
                left >= 0 and left + width <= owner_width
            )
            vertically_clipped = bool(
                top < 0 or top + height > owner_height
            )
            return bool(horizontally_contained and vertically_clipped)

        # Audit every painted control and semantically marked card against its
        # real clipping viewport. A scroll viewport may intentionally reveal
        # part of the next row; surfaces that require complete first-fold rows
        # enforce that stronger rule in their dedicated semantic audit.
        for candidate in root.findChildren(QWidget):
            try:
                is_control = isinstance(
                    candidate,
                    (QAbstractButton, QLineEdit, QComboBox),
                )
                is_card = isinstance(candidate, QFrame) and any(
                    bool(candidate.property(marker))
                    for marker in card_markers
                )
                if (
                    (not is_control and not is_card)
                    or candidate.window() is not root
                    or not candidate.isVisibleTo(root)
                    or int(candidate.width()) <= 0
                    or int(candidate.height()) <= 0
                ):
                    continue
                owner, owner_name = nearest_clip_owner(candidate)
                evidence = self._widget_bounds_evidence(candidate, owner)
                if not bool(evidence.get("intersects", False)):
                    continue
                contained = bool(evidence.get("contained", False))
                scroll_reveal_allowed = intentional_scroll_reveal(
                    owner,
                    evidence,
                )
                ancestor = candidate.parentWidget()
                ancestor_clips: list[str] = []
                while ancestor is not None and ancestor is not owner and ancestor is not root:
                    if isinstance(ancestor, QFrame) and any(
                        bool(ancestor.property(marker))
                        for marker in card_markers
                    ):
                        ancestor_evidence = self._widget_bounds_evidence(
                            candidate,
                            ancestor,
                        )
                        if (
                            bool(ancestor_evidence.get("intersects", False))
                            and not bool(ancestor_evidence.get("contained", False))
                        ):
                            contained = False
                            ancestor_clips.append(
                                str(
                                    ancestor.objectName()
                                    or ancestor.property("semanticId")
                                    or type(ancestor).__name__
                                )
                            )
                    ancestor = ancestor.parentWidget()
                clipping_records.append({
                    "kind": "control" if is_control else "card",
                    "widget": type(candidate).__name__,
                    "object_name": str(candidate.objectName() or ""),
                    "text": (
                        _displayed_button_text(candidate)
                        if isinstance(candidate, QAbstractButton) else
                        str(candidate.text())
                        if isinstance(candidate, QLineEdit) else
                        str(candidate.currentText())
                        if isinstance(candidate, QComboBox) else
                        ""
                    )[:120],
                    "clip_owner": owner_name,
                    "bounds": list(evidence.get("bounds", ()) or ()),
                    "owner_size": list(
                        evidence.get("container_size", ()) or ()
                    ),
                    "ancestor_clips": ancestor_clips,
                    "contained": contained,
                    "scroll_reveal_allowed": scroll_reveal_allowed,
                })
                if not contained and not scroll_reveal_allowed:
                    issue_codes.append(
                        "partially-clipped-control"
                        if is_control else
                        "partially-clipped-card"
                    )
            except (AttributeError, RuntimeError, TypeError, ValueError):
                issue_codes.append("clipping-telemetry-error")

        def primary_scope(button: QAbstractButton) -> QWidget:
            current = button.parentWidget()
            while current is not None and current is not root:
                if any(
                    bool(current.property(marker))
                    for marker in (
                        "decisionGroup",
                        "actionFooter",
                        "dialogFooter",
                        "toastRegion",
                        "emptyState",
                        "nurseryCatalogCard",
                        "catalogCard",
                        "environmentTile",
                        "sectionCard",
                    )
                ):
                    return current
                current = current.parentWidget()
            return root

        def record_primary(button: QAbstractButton, action_name: str) -> None:
            scope = primary_scope(button)
            index = next(
                (
                    item_index
                    for item_index, candidate in enumerate(primary_scope_widgets)
                    if candidate is scope
                ),
                -1,
            )
            if index < 0:
                primary_scope_widgets.append(scope)
                marker = next(
                    (
                        name
                        for name in (
                            "decisionGroup",
                            "actionFooter",
                            "dialogFooter",
                            "toastRegion",
                            "emptyState",
                            "nurseryCatalogCard",
                            "catalogCard",
                            "environmentTile",
                            "sectionCard",
                        )
                        if bool(scope.property(name))
                    ),
                    "window",
                )
                primary_action_groups.append({
                    "scope": (
                        str(scope.objectName())
                        or f"{marker}-{len(primary_scope_widgets)}"
                    ),
                    "actions": [],
                })
                index = len(primary_action_groups) - 1
            primary_action_groups[index]["actions"].append(action_name)

        for button in root.findChildren(QAbstractButton):
            if button.window() is not root or not button.isVisibleTo(root):
                continue
            if (
                isinstance(button.parentWidget(), QLineEdit)
                and not str(button.property("gardenComponent") or "")
                and not button.property("iconButton")
            ):
                # Qt owns the embedded clear affordance and sizes it to the
                # line edit's contents rect. It is not an app icon control.
                continue
            painted = self._widget_bounds_evidence(button, root)
            if not painted.get("intersects", False):
                continue
            onboarding_shield = getattr(root, "onboarding_shield", None)
            onboarding_panel = getattr(root, "onboarding_panel", None)
            scene = getattr(root, "scene", None)
            if (
                isinstance(onboarding_shield, QWidget)
                and onboarding_shield.isVisibleTo(root)
                and isinstance(scene, QWidget)
                and scene.isAncestorOf(button)
                and not (
                    isinstance(onboarding_panel, QWidget)
                    and onboarding_panel.isAncestorOf(button)
                )
            ):
                # The modal onboarding shield paints above and intercepts the
                # scene. Hotspots behind it are not visible actions.
                continue
            owner, owner_name = nearest_clip_owner(button)
            owner_evidence = self._widget_bounds_evidence(button, owner)
            if not owner_evidence.get("intersects", False):
                # A child below a local scroll viewport can still map inside
                # the dialog root. It is not part of the visible action set.
                continue
            scroll_reveal_allowed = intentional_scroll_reveal(
                owner,
                owner_evidence,
            )
            visible_action_widgets.append(button)
            visible_action_records.append({
                "index": len(visible_action_records),
                "text": _displayed_button_text(button).strip(),
                "accessible_name": str(button.accessibleName() or ""),
                "object_name": str(button.objectName() or ""),
                "semantic_id": str(button.property("semanticId") or ""),
                "bounds": list(painted.get("bounds", ()) or ()),
                "clip_owner": owner_name,
                "owner_bounds": list(
                    owner_evidence.get("container_size", ()) or ()
                ),
                "visible": bool(painted.get("visible", False)),
                "contained_in_dialog": bool(
                    painted.get("contained", False)
                ),
                "contained_in_owner": bool(
                    owner_evidence.get("contained", False)
                ),
                "scroll_reveal_allowed": scroll_reveal_allowed,
                "pairwise_eligible": True,
            })
            text = _displayed_button_text(button).strip()
            component = str(button.property("gardenComponent") or "")
            composite_button = bool(
                button.property("catalogCard")
                or button.property("environmentTile")
            )
            switch_control = bool(
                str(button.property("gardenRole") or "") == "switch"
            )
            icon_only = bool(
                component == "icon-button"
                or button.property("iconButton")
                or (not text and not button.icon().isNull())
            ) and not composite_button and not switch_control
            visual_size = int(
                button.property("visualControlSize")
                or max(int(button.width()), int(button.height()))
            )
            icon_size = [
                int(button.iconSize().width()),
                int(button.iconSize().height()),
            ]
            standard_button = bool(
                component == "button"
                or str(button.property("variant") or "")
            )
            popover_action = bool(button.property("plantPopoverAction"))
            icon_width = (
                max(0, int(button.iconSize().width())) + 6
                if not button.icon().isNull()
                else 0
            )
            text_width = int(button.fontMetrics().horizontalAdvance(text))
            token_padding = button.property("horizontalPadding")
            horizontal_padding = (
                2 * int(token_padding)
                if type(token_padding) is int
                else 16
                if button.property("disclosureRow")
                else 28
            )
            available_text_width = max(
                0,
                int(button.contentsRect().width())
                - horizontal_padding
                - icon_width,
            )
            text_fit_clearance = max(
                0,
                int(button.property("textFitClearance") or 0),
            )
            text_fit_passed = bool(
                not text
                or text_width + text_fit_clearance <= available_text_width
            )
            footer_action = bool(
                pinned_footer is not None
                and (
                    button is pinned_footer
                    or pinned_footer.isAncestorOf(button)
                )
            )
            actual_height = int(button.height())
            actual_width = int(button.width())
            switch_contract = (
                self._switch_thumb_contract(button)
                if switch_control else
                {}
            )
            if switch_control:
                size_passed = bool(
                    actual_width >= 38
                    and actual_height >= 22
                    and int(button.iconSize().width()) == 38
                    and int(button.iconSize().height()) == 22
                    and switch_contract.get("passed") is True
                )
            elif popover_action:
                # The compact selected-plant popover owns an explicit 36 px
                # action grid independent of the shared button variant token.
                size_passed = bool(actual_height == 36 and actual_width > 0)
            elif icon_only:
                if bool(button.property("dashboardSettingsButton")):
                    # The Garden header deliberately promotes Settings to the
                    # same 40 px outer hit target as its adjacent navigation
                    # controls while retaining the shared 36 px icon token.
                    size_passed = bool(
                        actual_width == 40
                        and actual_height == 40
                        and 18 <= icon_size[0] <= 20
                        and 18 <= icon_size[1] <= 20
                    )
                elif bool(button.property("progressHeaderControl")):
                    # Garden Progress intentionally uses a denser pair of
                    # local 32 px Help/Close controls. This exception is
                    # explicit so it cannot reduce the global icon-button
                    # contract used by every other dialog.
                    size_passed = bool(
                        actual_width == 32
                        and actual_height == 32
                        and icon_size == [16, 16]
                    )
                else:
                    expected_icon_visual_size = 36
                    size_passed = bool(
                        visual_size == expected_icon_visual_size
                        and expected_icon_visual_size
                        <= actual_height
                        <= expected_icon_visual_size + 6
                        and actual_width == actual_height
                        and 14 <= icon_size[0] <= 18
                        and 14 <= icon_size[1] <= 18
                    )
            elif standard_button:
                # Qt's styled frame can add up to three physical border pixels
                # per side to the capture-visible widget rectangle.
                size_passed = bool(
                    visual_size in {32, 36, 40}
                    and visual_size <= actual_height <= visual_size + 6
                )
            else:
                size_passed = True
            controls.append({
                "text": text,
                "accessible_name": str(button.accessibleName() or ""),
                "bounds": list(painted.get("bounds", ()) or ()),
                "icon_only": icon_only,
                "switch_control": switch_control,
                "switch_contract": switch_contract,
                "popover_action": popover_action,
                "visual_size": visual_size,
                "actual_height": actual_height,
                "actual_width": actual_width,
                "icon_size": icon_size,
                "standard_button": standard_button,
                "size_passed": size_passed,
                "contained": bool(painted.get("contained", False)),
                "footer_action": footer_action,
                "text_width": text_width,
                "horizontal_padding": horizontal_padding,
                "text_fit_clearance": text_fit_clearance,
                "available_text_width": available_text_width,
                "text_fit_passed": text_fit_passed,
            })
            if not size_passed:
                issue_codes.append(
                    "switch-visibility"
                    if switch_control else
                    "icon-control-size"
                    if icon_only else
                    "standard-button-height"
                )
            if not text_fit_passed:
                issue_codes.append("action-label-overflow")
            if footer_action:
                footer_actions.append(controls[-1])
                if not painted.get("contained", False):
                    issue_codes.append("footer-action-outside-dialog")
            if str(button.property("variant") or "") == "primary":
                action_name = (
                    text or str(button.accessibleName() or type(button).__name__)
                )
                primary_actions.append(action_name)
                record_primary(button, action_name)
            accessible_name = str(button.accessibleName() or "").casefold()
            if icon_only and "close" in accessible_name:
                glyph_present = self._icon_has_visible_pixels(button)
                rendered_contract = self._close_pixmap_contract(
                    button.icon().pixmap(
                        max(1, int(button.iconSize().width())),
                        max(1, int(button.iconSize().height())),
                    )
                )
                dpr_contracts: list[dict[str, Any]] = []
                try:
                    from ..ui.icons import garden_icon_pixmap

                    for requested_dpr in (1.0, 2.0):
                        contract = self._close_pixmap_contract(
                            garden_icon_pixmap(
                                "close",
                                max(1, int(button.iconSize().width())),
                                device_pixel_ratio=requested_dpr,
                            )
                        )
                        contract["requested_dpr"] = requested_dpr
                        dpr_contracts.append(contract)
                except Exception:
                    dpr_contracts = []
                close_passed = bool(
                    size_passed
                    and glyph_present
                    and rendered_contract.get("passed") is True
                    and len(dpr_contracts) == 2
                    and all(
                        contract.get("passed") is True
                        for contract in dpr_contracts
                    )
                )
                close_icons.append({
                    "accessible_name": str(button.accessibleName() or ""),
                    "bounds": list(painted.get("bounds", ()) or ()),
                    "glyph_pixels_present": glyph_present,
                    "rendered_stroke_contract": rendered_contract,
                    "dpr_stroke_contracts": dpr_contracts,
                    "passed": close_passed,
                })
                if not close_passed:
                    issue_codes.append("close-icon-glyph-or-size")

        # A composite clickable card can legitimately contain a smaller
        # explicit action. Keep containment proof for both widgets, while
        # excluding only that ancestor/descendant pair from sibling-overlap
        # calculations. Every ordinary visible action remains eligible.
        nested_action_indexes: set[int] = set()
        for first_index, first_widget in enumerate(visible_action_widgets):
            for second_index in range(first_index + 1, len(visible_action_widgets)):
                second_widget = visible_action_widgets[second_index]
                if (
                    first_widget.isAncestorOf(second_widget)
                    or second_widget.isAncestorOf(first_widget)
                ):
                    nested_action_indexes.update((first_index, second_index))
        for index in nested_action_indexes:
            visible_action_records[index]["pairwise_eligible"] = False

        visible_action_overlaps: list[dict[str, Any]] = []
        for first_index, first in enumerate(visible_action_records):
            if not bool(first.get("pairwise_eligible", False)):
                continue
            first_bounds = list(first.get("bounds", ()) or ())
            if len(first_bounds) != 4:
                continue
            first_left, first_top, first_width, first_height = first_bounds
            for second in visible_action_records[first_index + 1:]:
                if not bool(second.get("pairwise_eligible", False)):
                    continue
                second_bounds = list(second.get("bounds", ()) or ())
                if len(second_bounds) != 4:
                    continue
                second_left, second_top, second_width, second_height = (
                    second_bounds
                )
                overlap_width = max(
                    0,
                    min(first_left + first_width, second_left + second_width)
                    - max(first_left, second_left),
                )
                overlap_height = max(
                    0,
                    min(first_top + first_height, second_top + second_height)
                    - max(first_top, second_top),
                )
                if overlap_width > 0 and overlap_height > 0:
                    visible_action_overlaps.append({
                        "actions": [
                            int(first.get("index", first_index)),
                            int(second.get("index", first_index + 1)),
                        ],
                        "width": overlap_width,
                        "height": overlap_height,
                    })
        visible_actions_contained = all(
            (
                bool(record.get("contained_in_dialog", False))
                or bool(record.get("scroll_reveal_allowed", False))
            )
            and (
                bool(record.get("contained_in_owner", False))
                or bool(record.get("scroll_reveal_allowed", False))
            )
            for record in visible_action_records
        )
        if not visible_actions_contained:
            issue_codes.append("visible-action-outside-container")
        if visible_action_overlaps:
            issue_codes.append("overlapping-visible-actions")

        requires_inline_close = bool(
            expected_capture_window_family(label) != "GardenDashboard"
        )
        if requires_inline_close and not close_icons:
            issue_codes.append("missing-inline-close-icon")

        for group in primary_action_groups:
            group["count"] = len(group["actions"])
            group["passed"] = group["count"] <= 1
        max_primary_actions_per_group = max(
            (int(group["count"]) for group in primary_action_groups),
            default=0,
        )
        if max_primary_actions_per_group > 1:
            issue_codes.append("multiple-filled-primary-actions")

        horizontal_scrollbars: list[str] = []
        horizontal_overflow_ranges: list[str] = []
        for scroll in root.findChildren(QAbstractScrollArea):
            try:
                bar = scroll.horizontalScrollBar()
                if (
                    scroll.window() is root
                    and scroll.isVisibleTo(root)
                    and bar is not None
                    and bar.maximum() > bar.minimum()
                ):
                    name = str(
                        scroll.accessibleName()
                        or scroll.objectName()
                        or type(scroll).__name__
                    )
                    horizontal_overflow_ranges.append(name)
                    if bar.isVisibleTo(root):
                        horizontal_scrollbars.append(name)
            except (AttributeError, RuntimeError):
                continue
        if horizontal_overflow_ranges:
            issue_codes.append("horizontal-container-overflow")
        if horizontal_scrollbars:
            issue_codes.append("visible-horizontal-scrollbar")

        def overlapping_area(
            first: list[int],
            second: list[int],
        ) -> int:
            if len(first) != 4 or len(second) != 4:
                return 0
            left = max(first[0], second[0])
            top = max(first[1], second[1])
            right = min(first[0] + first[2], second[0] + second[2])
            bottom = min(first[1] + first[3], second[1] + second[3])
            return max(0, right - left) * max(0, bottom - top)

        fixed_widgets: list[tuple[str, QWidget]] = []
        for name, candidate in (
            ("header", getattr(root, "header", None)),
            ("tabs", getattr(root, "tabs_region", None)),
            ("footer", getattr(root, "_pinned_footer", None)),
        ):
            if (
                isinstance(candidate, QWidget)
                and candidate.window() is root
                and candidate.isVisibleTo(root)
            ):
                fixed_widgets.append((name, candidate))
        for tabs_index, tabs in enumerate(root.findChildren(QTabWidget)):
            try:
                bar = tabs.tabBar()
                if (
                    bar.window() is root
                    and bar.isVisibleTo(root)
                    and int(bar.height()) > 0
                ):
                    fixed_widgets.append((f"tab-bar-{tabs_index}", bar))
            except (AttributeError, RuntimeError):
                continue
        fixed_records = [
            {
                "name": name,
                "bounds": list(
                    self._widget_bounds_evidence(widget, root).get(
                        "bounds", ()
                    ) or ()
                ),
            }
            for name, widget in fixed_widgets
        ]
        fixed_region_intersections: list[dict[str, Any]] = []
        body_widget = getattr(root, "body_region", None)
        body_bounds = list(
            self._widget_bounds_evidence(body_widget, root).get("bounds", ())
            or ()
        ) if isinstance(body_widget, QWidget) else []
        for record in fixed_records:
            # A QTabWidget's tab bar is a child of the body-owned widget and
            # therefore intentionally intersects the body's outer rectangle.
            # It remains part of the scrollbar-intrusion audit below, but it
            # is not a shell/body overlap defect.
            if str(record["name"]).startswith("tab-bar-"):
                continue
            area = overlapping_area(body_bounds, list(record["bounds"]))
            if area > 0:
                fixed_region_intersections.append({
                    "regions": ["body", str(record["name"])],
                    "area": area,
                })
        if fixed_region_intersections:
            issue_codes.append("fixed-region-intersection")

        scrollbar_records: list[dict[str, Any]] = []
        scrollbar_fixed_intersections: list[dict[str, Any]] = []
        for scroll_index, scroll in enumerate(root.findChildren(QAbstractScrollArea)):
            try:
                bar = scroll.verticalScrollBar()
                if (
                    scroll.window() is not root
                    or not scroll.isVisibleTo(root)
                    or bar is None
                    or not bar.isVisibleTo(root)
                    or bar.maximum() <= bar.minimum()
                ):
                    continue
                evidence = self._external_widget_bounds_evidence(bar, root)
                bounds = list(evidence.get("bounds", ()) or ())
                name = str(
                    scroll.accessibleName()
                    or scroll.objectName()
                    or f"scroll-{scroll_index}"
                )
                scrollbar_records.append({"name": name, "bounds": bounds})
                for fixed in fixed_records:
                    area = overlapping_area(bounds, list(fixed["bounds"]))
                    if area > 0:
                        scrollbar_fixed_intersections.append({
                            "scrollbar": name,
                            "fixed_region": str(fixed["name"]),
                            "area": area,
                        })
            except (AttributeError, RuntimeError, TypeError, ValueError):
                continue
        if scrollbar_fixed_intersections:
            issue_codes.append("scrollbar-fixed-region-intersection")

        overflow_menu_buttons: list[dict[str, Any]] = []
        for button in visible_action_widgets:
            accessible_name = str(button.accessibleName() or "")
            if "more action" not in accessible_name.casefold():
                continue
            parent_card = button.parentWidget()
            while parent_card is not None and parent_card is not root:
                if isinstance(parent_card, QFrame) and any(
                    bool(parent_card.property(marker))
                    for marker in card_markers
                ):
                    break
                parent_card = parent_card.parentWidget()
            evidence = self._widget_bounds_evidence(
                button,
                parent_card if isinstance(parent_card, QWidget) else root,
            )
            record = {
                "accessible_name": accessible_name,
                "bounds": list(evidence.get("bounds", ()) or ()),
                "contained": bool(evidence.get("contained", False)),
            }
            overflow_menu_buttons.append(record)
            if not record["contained"]:
                issue_codes.append("overflow-menu-button-clipped")

        switch_records = [
            {
                "accessible_name": str(record.get("accessible_name", "")),
                "bounds": list(record.get("bounds", ()) or ()),
                "contract": dict(record.get("switch_contract", {}) or {}),
                "visible": bool(record.get("contained", False)),
                "passed": bool(
                    record.get("contained", False)
                    and record.get("size_passed", False)
                ),
            }
            for record in controls
            if bool(record.get("switch_control", False))
        ]
        home_card_switch_visible = any(
            "anki home" in str(record["accessible_name"]).casefold()
            and bool(record["passed"])
            for record in switch_records
        )
        if (
            label == "settings-display-advanced-open"
            and not home_card_switch_visible
        ):
            issue_codes.append("settings-home-card-switch-hidden")

        direct_children: list[list[int]] = []
        for child in root.findChildren(QWidget):
            try:
                if child.parentWidget() is not root or not child.isVisibleTo(root):
                    continue
                evidence = self._widget_bounds_evidence(child, root)
                if evidence.get("intersects", False):
                    direct_children.append(list(evidence["bounds"]))
            except (AttributeError, RuntimeError, TypeError, ValueError):
                continue
        direct_children.sort(key=lambda bounds: (bounds[1], bounds[0]))
        vertical_gaps = [
            max(0, following[1] - (current[1] + current[3]))
            for current, following in zip(direct_children, direct_children[1:])
            if current[0] < following[0] + following[2]
            and following[0] < current[0] + current[2]
        ]
        largest_gap = max(vertical_gaps, default=0)
        if largest_gap > max(64, round(int(root.height()) * 0.20)):
            issue_codes.append("unexplained-large-vertical-gap")

        screen_contained = True
        try:
            screen = root.screen()
            available = screen.availableGeometry() if screen is not None else None
            frame = root.frameGeometry()
            screen_contained = bool(
                available is not None and available.contains(frame)
            )
        except (AttributeError, RuntimeError, TypeError):
            screen_contained = False
        if not screen_contained:
            issue_codes.append("window-outside-available-screen")

        popover: dict[str, Any] = {"applicable": False, "passed": True}
        if label.startswith("popover-plot-"):
            scene = getattr(root, "scene", None)
            card = getattr(root, "plant_card", None)
            evidence = self._widget_bounds_evidence(card, scene)
            mode_reader = getattr(root, "dialog_window_mode", None)
            mode = mode_reader() if callable(mode_reader) else mode_reader
            canvas_direct = str(getattr(mode, "value", mode) or "") == "canvas"
            popover = {
                "applicable": True,
                "bounds": list(evidence.get("bounds", ()) or ()),
                "scene_size": list(evidence.get("container_size", ()) or ()),
                "contained_in_scene": bool(evidence.get("contained", False)),
                "canvas_direct": canvas_direct,
                "passed": bool(
                    evidence.get("contained", False)
                    and canvas_direct
                ),
            }
            if not popover["passed"]:
                issue_codes.append("popover-outside-direct-canvas")

        plant_action_geometry: dict[str, Any] = {
            "applicable": False,
            "expected_actions": [],
            "records": [],
            "overlaps": [],
            "passed": True,
        }
        if label == "selected-plant-nurtured":
            card = getattr(root, "plant_card", None)
            expected_actions = [
                ("growth_charge", "Get Growth Charges"),
                ("fertilize", "Apply fertilizer"),
                ("move", "Move"),
                ("story", "Plant story"),
                ("nurture", "Stop nurturing"),
            ]
            action_records: list[dict[str, Any]] = []
            for attribute, expected_text in expected_actions:
                button = getattr(card, attribute, None)
                evidence = self._widget_bounds_evidence(button, card)
                action_records.append({
                    "attribute": attribute,
                    "expected_text": expected_text,
                    "text": (
                        _displayed_button_text(button).strip()
                        if isinstance(button, QAbstractButton) else
                        ""
                    ),
                    "bounds": list(evidence.get("bounds", ()) or ()),
                    "visible": bool(evidence.get("visible", False)),
                    "contained": bool(evidence.get("contained", False)),
                })
            overlaps: list[dict[str, Any]] = []
            for index, first in enumerate(action_records):
                first_bounds = first.get("bounds")
                if not isinstance(first_bounds, list) or len(first_bounds) != 4:
                    continue
                first_left, first_top, first_width, first_height = first_bounds
                for second in action_records[index + 1:]:
                    second_bounds = second.get("bounds")
                    if (
                        not isinstance(second_bounds, list)
                        or len(second_bounds) != 4
                    ):
                        continue
                    (
                        second_left,
                        second_top,
                        second_width,
                        second_height,
                    ) = second_bounds
                    overlap_width = max(
                        0,
                        min(first_left + first_width, second_left + second_width)
                        - max(first_left, second_left),
                    )
                    overlap_height = max(
                        0,
                        min(first_top + first_height, second_top + second_height)
                        - max(first_top, second_top),
                    )
                    if overlap_width > 0 and overlap_height > 0:
                        overlaps.append({
                            "actions": [
                                first["expected_text"],
                                second["expected_text"],
                            ],
                            "width": overlap_width,
                            "height": overlap_height,
                        })
            actions_passed = bool(
                all(
                    record.get("text") == record.get("expected_text")
                    and record.get("visible") is True
                    and record.get("contained") is True
                    for record in action_records
                )
                and not overlaps
            )
            plant_action_geometry = {
                "applicable": True,
                "expected_actions": [
                    expected_text for _attribute, expected_text in expected_actions
                ],
                "records": action_records,
                "overlaps": overlaps,
                "passed": actions_passed,
            }
            if not actions_passed:
                issue_codes.append("overlapping-plant-actions")

        plant_popover_geometry: dict[str, Any] = {
            "applicable": False,
            "passed": True,
        }
        if label == "selected-plant-nurtured":
            scene = getattr(root, "scene", None)
            card = getattr(root, "plant_card", None)
            side_dock = getattr(root, "plant_card_side_dock", None)
            bottom_dock = getattr(root, "plant_card_dock", None)
            card_parent = card.parentWidget() if isinstance(card, QWidget) else None
            presentation_mode = (
                "side"
                if card_parent is side_dock else
                "bottom-sheet"
                if card_parent is bottom_dock else
                "unknown"
            )
            dock = side_dock if presentation_mode == "side" else bottom_dock
            card_evidence = self._widget_bounds_evidence(card, dock)
            named_widgets = {
                "thumbnail": getattr(card, "artwork", None),
                "title": getattr(card, "heading", None),
                "stage": getattr(card, "identity", None),
                "status": getattr(card, "nurtured_badge", None),
                "close": getattr(card, "close_btn", None),
                "progress": getattr(
                    getattr(card, "stage_progress", None),
                    "bar",
                    None,
                ),
                "growth_charge": getattr(card, "growth_charge", None),
                "fertilize": getattr(card, "fertilize", None),
                "move": getattr(card, "move", None),
                "story": getattr(card, "story", None),
                "stop": getattr(card, "nurture", None),
            }
            records = {
                name: self._widget_bounds_evidence(widget, card)
                for name, widget in named_widgets.items()
            }

            def widget_bounds(name: str) -> list[int]:
                values = records.get(name, {}).get("bounds", [])
                return list(values) if isinstance(values, (list, tuple)) else []

            card_width = int(card.width()) if isinstance(card, QWidget) else 0
            card_height = int(card.height()) if isinstance(card, QWidget) else 0
            content_inset = 12
            card_contents = card.contentsRect()
            content_left = int(card_contents.x()) + content_inset
            content_right = (
                int(card_contents.x())
                + int(card_contents.width())
                - content_inset
            )
            content_width = max(0, content_right - content_left)
            thumbnail = widget_bounds("thumbnail")
            title = widget_bounds("title")
            stage = widget_bounds("stage")
            status = widget_bounds("status")
            close = widget_bounds("close")
            progress = widget_bounds("progress")
            growth_charge = widget_bounds("growth_charge")
            fertilize = widget_bounds("fertilize")
            move = widget_bounds("move")
            story = widget_bounds("story")
            stop = widget_bounds("stop")
            anatomy_passed = bool(
                (
                    card_width == 296
                    if presentation_mode == "side" else
                    288 <= card_width <= 720
                )
                and 300 <= card_height <= 420
                and all(
                    len(bounds) == 4
                    for bounds in (
                        thumbnail,
                        title,
                        stage,
                        status,
                        close,
                        progress,
                    )
                )
                and thumbnail[2:] == [44, 44]
                and 32 <= close[2] <= 36
                and 32 <= close[3] <= 36
                and title[0] >= thumbnail[0] + thumbnail[2] + 10
                and title[0] + title[2] <= close[0] - 4
                and stage[1] > title[1]
                and status[1] == stage[1]
                and status[0] >= stage[0] + stage[2] + 6
                and progress[0] == content_left
                and progress[2] == content_width
                and progress[3] == 8
            )
            actions_aligned = bool(
                all(
                    len(bounds) == 4
                    for bounds in (
                        growth_charge,
                        fertilize,
                        move,
                        story,
                        stop,
                    )
                )
                and growth_charge == [
                    content_left,
                    growth_charge[1],
                    content_width,
                    36,
                ]
                and fertilize[0] == content_left
                and fertilize[3] == 36
                and move[3] == 36
                and move[0] + move[2] == card_width - content_left
                and fertilize[0] + fertilize[2] + 8 == move[0]
                and fertilize[1] == move[1]
                and story == [content_left, story[1], content_width, 36]
                and stop == [content_left, stop[1], content_width, 36]
                and growth_charge[1] < fertilize[1] < story[1] < stop[1]
            )
            card_in_root = self._widget_bounds_evidence(card, root)
            scene_in_root = self._widget_bounds_evidence(scene, root)

            def separated(first: dict[str, Any], second: dict[str, Any]) -> bool:
                first_bounds = list(first.get("bounds", ()) or ())
                second_bounds = list(second.get("bounds", ()) or ())
                if len(first_bounds) != 4 or len(second_bounds) != 4:
                    return False
                first_left, first_top, first_width, first_height = first_bounds
                second_left, second_top, second_width, second_height = second_bounds
                return bool(
                    first_left + first_width <= second_left
                    or second_left + second_width <= first_left
                    or first_top + first_height <= second_top
                    or second_top + second_height <= first_top
                )

            external_to_scene = bool(
                isinstance(card, QWidget)
                and isinstance(scene, QWidget)
                and card.parentWidget() is not scene
                and separated(card_in_root, scene_in_root)
            )
            connector_hidden = bool(
                scene is not None
                and getattr(scene, "_card_connector_rect", None) is None
            )
            toast = getattr(root, "toast_region", None)
            toast_clear = bool(
                not isinstance(toast, QWidget)
                or not toast.isVisibleTo(root)
                or separated(
                    card_in_root,
                    self._widget_bounds_evidence(toast, root),
                )
            )
            inspector_passed = bool(
                presentation_mode in {"side", "bottom-sheet"}
                and card_evidence.get("visible") is True
                and card_evidence.get("contained") is True
                and external_to_scene
                and connector_hidden
                and toast_clear
            )
            popover_passed = anatomy_passed and actions_aligned and inspector_passed
