    def _capture_purchase_success_fixture(
        self,
        label: str,
        variant: str,
        tab_index: int,
    ) -> None:
        cleanup_holder: dict[str, Callable[[], None]] = {
            "callback": lambda: None,
        }

        def registered_cleanup() -> None:
            cleanup_holder["callback"]()

        def dashboard_ready() -> None:
            prepared = self._purchase_capture_snapshot(
                label,
                exact_ledger_restore=True,
            )
            if prepared is None:
                self._next_after(200)
                return
            snapshot, plant = prepared
            def cleanup() -> None:
                self._restore_purchase_capture(snapshot)

            # Register exact restoration before any purchase can commit.
            cleanup_holder["callback"] = cleanup
            from ..purchases import (
                PurchaseKind,
                PurchaseRequest,
                purchase_presentation,
            )
            from ..ui.dashboard import NurseryDialog

            state = self.app.storage.state
            collection_capacity_fixture: dict[str, Any] = {}
            if variant == "collection":
                from .fixtures import representative_collection_inventory_plan

                kind = PurchaseKind.SPECIES
                item_id = "sunflower"
                target_id = None
                state.plants = [item for item in state.plants if item.species != item_id]
                state.unlocked_species = [
                    item for item in state.unlocked_species if item != item_id
                ]
                # Start from the same truthful 29-entry lineage used by the
                # canonical Collection surface.  The real Sunflower purchase
                # below then owns the tenth species and the thirtieth entry.
                inventory_plan = representative_collection_inventory_plan()
                state.inventory["garden_features"] = list(
                    inventory_plan["garden_features"]
                )
                state.inventory["scenery"] = list(
                    inventory_plan["scenery"]
                )
                state.consumables.update(
                    dict(inventory_plan["consumables"])
                )
                occupied_slots = {
                    int(candidate.slot_index)
                    for candidate in state.plants
                    if candidate.slot_index is not None
                }
                missing_slots = [
                    slot
                    for slot in range(
                        max(0, min(6, int(state.unlocked_slots)))
                    )
                    if slot not in occupied_slots
                ]
                capacity_filler = next(
                    (
                        candidate
                        for candidate in state.plants
                        if candidate.slot_index is None
                    ),
                    None,
                )
                filled_capacity, capacity_message = (
                    self.app.engine.plant_from_collection(
                        capacity_filler.plant_id,
                        missing_slots[0],
                    )
                    if capacity_filler is not None and missing_slots else
                    (not missing_slots, "All beds were already occupied.")
                )
                collection_capacity_fixture = {
                    "missing_slots_before_fill": missing_slots,
                    "filler_plant_id": str(
                        getattr(capacity_filler, "plant_id", "") or ""
                    ),
                    "filled_capacity": bool(filled_capacity),
                    "message": str(capacity_message),
                    "occupied_slots_after_fill": sorted(
                        int(candidate.slot_index)
                        for candidate in state.plants
                        if candidate.slot_index is not None
                    ),
                }
                collection_capacity_fixture["passed"] = bool(
                    filled_capacity
                    and collection_capacity_fixture[
                        "occupied_slots_after_fill"
                    ] == list(range(6))
                )
            elif variant == "fertilizer":
                kind = PurchaseKind.FERTILIZER
                item_id = "basic"
                target_id = plant.plant_id
            else:
                kind = PurchaseKind.BED
                item_id = "next"
                target_id = None
                state.unlocked_slots = 2
                for candidate in state.plants:
                    if candidate.slot_index is not None and candidate.slot_index >= 2:
                        candidate.slot_index = None

            quote = self.app.engine.quote_purchase(
                kind,
                item_id,
                target_id=target_id,
            )
            outcome = self.app.engine.confirm_purchase(
                PurchaseRequest.from_quote(quote)
            )

            def collection_receipt_evidence(
                receipt_dialog: Any,
                *,
                expected_route: str,
            ) -> dict[str, Any]:
                """Measure Surface 32's exact painted collection receipt."""

                if variant != "collection":
                    return {}
                from ..presentation import project_collection

                toast = receipt_dialog.nursery_toast
                icon = toast.icon
                pixmap = icon.pixmap()
                pixmap_width = 0
                pixmap_height = 0
                pixmap_dpr = 1.0
                painted_width = 0
                painted_height = 0
                visible_alpha_pixels = 0
                if pixmap is not None and not pixmap.isNull():
                    image = pixmap.toImage()
                    pixmap_width = int(image.width())
                    pixmap_height = int(image.height())
                    pixmap_dpr = max(
                        1.0,
                        float(pixmap.devicePixelRatio()),
                    )
                    painted_width = round(pixmap_width / pixmap_dpr)
                    painted_height = round(pixmap_height / pixmap_dpr)
                    visible_alpha_pixels = sum(
                        1
                        for y in range(pixmap_height)
                        for x in range(pixmap_width)
                        if int(image.pixelColor(x, y).alpha()) >= 64
                    )
                icon_bounds = self._widget_bounds_evidence(icon, toast)
                projection = project_collection(self.app.storage.state)
                species_label = next(
                    (
                        label_widget
                        for label_widget in receipt_dialog.findChildren(QLabel)
                        if str(label_widget.text()) == projection.species_text
                        and label_widget.isVisibleTo(receipt_dialog)
                    ),
                    None,
                )
                collection_entries_label = next(
                    (
                        label_widget
                        for label_widget in receipt_dialog.findChildren(QLabel)
                        if str(label_widget.text())
                        == projection.collection_entries_text
                        and label_widget.isVisibleTo(receipt_dialog)
                    ),
                    None,
                )
                collection_viewport = receipt_dialog.scroll.viewport()
                species_bounds = self._widget_bounds_evidence(
                    species_label,
                    collection_viewport,
                )
                collection_entries_bounds = self._widget_bounds_evidence(
                    collection_entries_label,
                    collection_viewport,
                )
                action_text = _displayed_button_text(toast.action)
                message_text = str(toast.message.text())
                asset_id = str(
                    icon.property("receiptArtworkAssetId") or ""
                )
                source = str(
                    icon.property("receiptArtworkSource") or ""
                )
                species = str(
                    icon.property("receiptArtworkSpecies") or ""
                )
                stage = str(icon.property("receiptArtworkStage") or "")
                fallback = bool(icon.property("receiptArtworkFallback"))
                expected_source = (
                    "assets/v6_storybook_gouache/plants/sunflower/seed/"
                    "sunflower_seed_twilight_v6.webp"
                )
                painted = bool(
                    icon.isVisibleTo(receipt_dialog)
                    and icon_bounds.get("contained", False)
                    and 30 <= painted_width <= 34
                    and 30 <= painted_height <= 34
                    and icon.property("paintedArtworkLogicalSize")
                    == [32, 32]
                    and visible_alpha_pixels > 0
                )
                evidence = {
                    "message": message_text,
                    "route": str(
                        toast.property("receiptPrimaryRoute") or ""
                    ),
                    "action_text": action_text,
                    "action_visible": bool(
                        toast.action.isVisibleTo(receipt_dialog)
                    ),
                    "action_enabled": bool(toast.action.isEnabled()),
                    "receipt_item_id": str(
                        toast.property("receiptItemId") or ""
                    ),
                    "asset_id": asset_id,
                    "source": source,
                    "species": species,
                    "stage": stage,
                    "fallback": fallback,
                    "accessible_name": str(icon.accessibleName()),
                    "pixmap_size": [pixmap_width, pixmap_height],
                    "pixmap_device_pixel_ratio": pixmap_dpr,
                    "painted_size": [painted_width, painted_height],
                    "visible_alpha_pixels": visible_alpha_pixels,
                    "icon_bounds": icon_bounds,
                    "painted": painted,
                    "species_copy": projection.species_text,
                    "collection_entries_copy": (
                        projection.collection_entries_text
                    ),
                    "species_copy_bounds": species_bounds,
                    "collection_entries_copy_bounds": (
                        collection_entries_bounds
                    ),
                    "species_copy_visible": bool(
                        species_bounds.get("visible", False)
                        and species_bounds.get("contained", False)
                    ),
                    "collection_entries_copy_visible": bool(
                        collection_entries_bounds.get("visible", False)
                        and collection_entries_bounds.get("contained", False)
                    ),
                }
                evidence["passed"] = bool(
                    message_text == "Sunflower added to your collection."
                    and evidence["route"] == expected_route
                    and action_text == expected_route
                    and evidence["action_visible"]
                    and evidence["action_enabled"]
                    and evidence["receipt_item_id"] == "sunflower"
                    and asset_id == "plant_sunflower_seed_twilight_v6"
                    and source == expected_source
                    and species == "sunflower"
                    and stage == "seed"
                    and not fallback
                    and evidence["accessible_name"]
                    == "Sunflower Seed artwork"
                    and painted
                    and projection.species_text
                    == "10 of 10 species discovered"
                    and projection.collection_entries_text
                    == "30 of 39 collection entries discovered"
                    and evidence["species_copy_visible"]
                    and evidence["collection_entries_copy_visible"]
                )
                return evidence

            placement_branch: dict[str, Any] = {}
            if variant == "collection" and outcome.success:
                displaced = next(
                    (
                        candidate
                        for candidate in state.plants
                        if candidate.slot_index is not None
                        and str(candidate.plant_id)
                        != str(state.active_plant_id or "")
                        and str(candidate.plant_id)
                        != str(outcome.result_id or "")
                    ),
                    None,
                )
                displaced_slot = (
                    int(displaced.slot_index)
                    if displaced is not None
                    and displaced.slot_index is not None else
                    -1
                )
                freed, free_message = (
                    self.app.engine.move_to_collection(displaced.plant_id)
                    if displaced is not None else
                    (False, "No planted source was available.")
                )
                placement_dialog = NurseryDialog(
                    self.app.dashboard,
                    self.app.engine,
                    self.app.storage,
                )
                placement_dialog.catalog_tabs.setCurrentIndex(tab_index)
                placement_dialog.setWindowModality(Qt.WindowModality.NonModal)
                placement_dialog.setModal(False)
                self._move_to_capture_display(placement_dialog)
                placement_dialog._show_purchase_receipt(
                    outcome,
                    purchase_presentation(quote, ignore_status=True),
                )
                placement_dialog.show()
                for _settle_pass in range(3):
                    QApplication.processEvents()
                placement_receipt = collection_receipt_evidence(
                    placement_dialog,
                    expected_route="Place in garden",
                )
                placement_dialog.nursery_toast.action.click()
                QApplication.processEvents()
                purchased = self.app.engine.plant_story(
                    str(outcome.result_id or "")
                )
                placed_slot = (
                    int(purchased.slot_index)
                    if purchased is not None
                    and purchased.slot_index is not None else
                    -1
                )
                stored_again, store_message = (
                    self.app.engine.move_to_collection(purchased.plant_id)
                    if purchased is not None and purchased.planted else
                    (False, "Purchased plant was not placed.")
                )
                restored_bed, restore_message = (
                    self.app.engine.plant_from_collection(
                        displaced.plant_id,
                        displaced_slot,
                    )
                    if displaced is not None and displaced_slot >= 0 else
                    (False, "No displaced plant was available.")
                )
                placement_branch = {
                    "freed_bed": bool(freed),
                    "free_message": str(free_message),
                    "displaced_plant_id": str(
                        getattr(displaced, "plant_id", "") or ""
                    ),
                    "expected_slot": displaced_slot,
                    "placed_slot": placed_slot,
                    "stored_again": bool(stored_again),
                    "store_message": str(store_message),
                    "restored_bed": bool(restored_bed),
                    "restore_message": str(restore_message),
                    "receipt": placement_receipt,
                }
                placement_branch["passed"] = bool(
                    freed
                    and placement_receipt.get("passed", False)
                    and placed_slot == displaced_slot
                    and stored_again
                    and restored_bed
                )
                self._dispose_capture_widget(placement_dialog)
                QApplication.processEvents()

            dialog = NurseryDialog(
                self.app.dashboard,
                self.app.engine,
                self.app.storage,
            )
            dialog.catalog_tabs.setCurrentIndex(tab_index)
            if variant == "bed" and outcome.success:
                dialog._recently_unlocked_bed = int(outcome.result_id)
                dialog.refresh()
                dialog.catalog_tabs.setCurrentIndex(tab_index)
            if outcome.success:
                dialog._show_purchase_receipt(
                    outcome,
                    purchase_presentation(quote, ignore_status=True),
                )
            self._capture_annotations[label] = {
                "status": outcome.status.value,
                "disposition": outcome.disposition.value,
                "amount_spent": outcome.amount_spent,
                "new_balance": outcome.new_balance,
                "result_id": outcome.result_id,
                "collection_capacity_fixture": collection_capacity_fixture,
                "placement_branch": placement_branch,
                "passed": bool(
                    outcome.success
                    and (
                        variant != "collection"
                        or (
                            collection_capacity_fixture.get("passed", False)
                            and placement_branch.get("passed", False)
                        )
                    )
                ),
            }
            if not outcome.success:
                self._failures.append({
                    "label": label,
                    "reason": f"Success fixture failed with {outcome.status.value}",
                })
            dialog.setWindowModality(Qt.WindowModality.NonModal)
            dialog.setModal(False)
            self._move_to_capture_display(dialog)
            dialog.show()

            def audit_success_flow() -> None:
                QApplication.processEvents()
                host = dialog.nursery_feedback_host
                page = dialog.catalog_pages[tab_index]
                page_layout = dialog.catalog_page_layouts[tab_index]
                scroll = (
                    dialog.scroll,
                    dialog.supplements_scroll,
                    dialog.upgrades_scroll,
                    dialog.environment_scroll,
                )[tab_index]
                host_bounds = self._widget_bounds_evidence(host, dialog)
                scroll_bounds = self._widget_bounds_evidence(scroll, dialog)
                tab_bar_bounds = self._widget_bounds_evidence(
                    dialog.catalog_tabs.tabBar(),
                    dialog,
                )
                host_box = list(host_bounds.get("bounds", ()) or ())
                scroll_box = list(scroll_bounds.get("bounds", ()) or ())
                tab_box = list(tab_bar_bounds.get("bounds", ()) or ())
                normal_flow = bool(
                    host.parentWidget() is page
                    and page_layout.indexOf(host) == 0
                    and page_layout.indexOf(scroll) > page_layout.indexOf(host)
                    and not host.isHidden()
                    and not dialog.nursery_toast.isHidden()
                    and len(host_box) == 4
                    and len(scroll_box) == 4
                    and len(tab_box) == 4
                    and int(host_box[1])
                    >= int(tab_box[1]) + int(tab_box[3])
                    and int(host_box[1]) + int(host_box[3])
                    <= int(scroll_box[1])
                )
                annotation = self._capture_annotations[label]
                annotation["nursery_feedback_flow"] = {
                    "host_bounds": host_bounds,
                    "scroll_bounds": scroll_bounds,
                    "tab_bar_bounds": tab_bar_bounds,
                    "host_layout_index": page_layout.indexOf(host),
                    "scroll_layout_index": page_layout.indexOf(scroll),
                    "passed": normal_flow,
                }
                if variant == "collection":
                    annotation["no_bed_branch"] = (
                        collection_receipt_evidence(
                            dialog,
                            expected_route="Open garden",
                        )
                    )
                annotation["passed"] = bool(
                    annotation.get("passed", False)
                    and normal_flow
                    and (
                        variant != "collection"
                        or dict(
                            annotation.get("no_bed_branch", {}) or {}
                        ).get("passed", False)
                    )
                )

            def close_dialog() -> None:
                self._dispose_capture_widget(dialog)
                cleanup()

            self._capture_and_advance(
                label,
                dialog,
                capture_delay_ms=520,
                before_capture=audit_success_flow,
                close_callback=close_dialog,
                cleanup_predicate=lambda: self._capture_widget_disposed(dialog),
                close_ms=920,
                next_ms=1260,
            )

        self._with_dashboard(
            dashboard_ready,
            failure_label=label,
            on_error=registered_cleanup,
        )

    def _capture_purchase_success_collection(self) -> None:
        self._capture_purchase_success_fixture(
            "purchase-success-inventory-collection", "collection", 0
        )

    def _capture_purchase_success_fertilizer(self) -> None:
        self._capture_purchase_success_fixture(
            "purchase-success-fertilizer-applied", "fertilizer", 1
        )

    def _capture_purchase_success_bed(self) -> None:
        self._capture_purchase_success_fixture(
            "purchase-success-garden-bed-unlocked", "bed", 2
        )

    def _prepare_growth_charge_capture(
        self,
        label: str,
        *,
        inventory: int = 2,
        growth_points: int = 1_250,
        planted: bool = True,
        exact_ledger_restore: bool = False,
    ) -> tuple[dict[str, Any], list[Any], Any]:
        """Install one exact, reversible target for a Charge dialog fixture."""

        from ..environment import GROWTH_CHARGES
        from ..models.state import Plant, PlantMemory

        snapshot = self._capture_fixture_state_snapshot(
            label,
            exact_ledger_restore=exact_ledger_restore,
        )
        transition_snapshot = list(self.app.engine._pending_stage_transitions)
        state = self.app.storage.state
        today = str(state.daily_stats.day)
        plant = Plant(
            plant_id="capture_growth_charge_bonsai",
            species="bonsai",
            name="Bonsai Plant",
            slot_index=0 if planted else None,
            growth_points=max(0, int(growth_points)),
            planted_on=today,
            memories=[PlantMemory(
                memory_id="capture-growth-charge-planted",
                kind="planted",
                occurred_on=today,
            )],
        )
        state.plants = [plant]
        state.unlocked_species = list(dict.fromkeys([
            *state.unlocked_species,
            "bonsai",
        ]))
        state.unlocked_slots = max(1, int(state.unlocked_slots))
        state.active_plant_id = plant.plant_id if planted else None
        state.starter_selection_complete = True
        state.onboarding.starter_plant_id = plant.plant_id
        state.completed_growth_charge_requests.clear()
        for charge_id in GROWTH_CHARGES:
            state.consumables[charge_id] = 0
        state.consumables["growth_charge_small"] = max(0, int(inventory))
        state.selected_background = "default"
        stats = state.daily_stats
        stats.plant_charge_growth = {}
        stats.plant_direct_reward_growth = {}
        stats.reconcile_growth_totals()
        self._capture_annotations[label] = {
            "target_id": plant.plant_id,
            "initial_growth": plant.growth_points,
            "initial_inventory": max(0, int(inventory)),
            "passed": True,
        }
        return snapshot, transition_snapshot, plant

    def _restore_growth_charge_capture(
        self,
        snapshot: dict[str, Any],
        transition_snapshot: list[Any],
    ) -> None:
        self.app.engine._pending_stage_transitions = list(transition_snapshot)
        self._restore_capture_fixture_state(snapshot)

    def _exercise_growth_charge_transient_variants(
        self,
        label: str,
    ) -> dict[str, Any]:
        """Paint the no-transition preview and its reward-free success receipt."""

        from ..ui.dashboard import GrowthChargeConfirmationDialog

        snapshot, transition_snapshot, plant = self._prepare_growth_charge_capture(
            label,
            inventory=2,
            growth_points=600,
            planted=True,
            exact_ledger_restore=True,
        )
        dialog: Any | None = None
        records: dict[str, dict[str, Any]] = {}
        try:
            dialog = GrowthChargeConfirmationDialog(
                self.app.dashboard,
                self.app.engine,
                plant.plant_id,
                open_nursery=lambda: None,
            )
            dialog.setWindowModality(Qt.WindowModality.NonModal)
            dialog.setModal(False)
            self._move_to_capture_display(dialog)
            dialog.show()
            dialog.raise_()
            QApplication.processEvents()
            dialog.repaint()
            QApplication.processEvents()
            preview_probe = dialog.grab()
            records["ready-no-transition"] = {
                "transition_statement": str(
                    dialog.transition_statement.text()
                ).strip(),
                "before_label": str(dialog.before_stage_label.text()).strip(),
                "after_label": str(dialog.after_stage_label.text()).strip(),
                "impact_value": str(dialog.impact_value.text()).strip(),
                "growth_value": str(dialog.compact_growth_value.text()).strip(),
                "inventory_value": str(
                    dialog.compact_inventory_value.text()
                ).strip(),
                "stage_progress": str(
                    dialog.compact_stage_progress.text()
                ).strip(),
                "progress_label": str(
                    dialog.compact_progress_label.text()
                ).strip(),
                "current_growth": int(
                    dialog.compact_summary_card.property("currentGrowth") or -1
                ),
                "projected_growth": int(
                    dialog.compact_summary_card.property("projectedGrowth") or -1
                ),
                "inventory_before": int(
                    dialog.compact_summary_card.property("inventoryBefore") or -1
                ),
                "inventory_after": int(
                    dialog.compact_summary_card.property("inventoryAfter") or -1
                ),
                "progress_minimum": int(dialog.compact_progress_bar.minimum()),
                "progress_maximum": int(dialog.compact_progress_bar.maximum()),
                "progress_value": int(dialog.compact_progress_bar.value()),
                "stage_transition_visible": bool(
                    dialog.transition_statement.isVisibleTo(dialog)
                ),
                "reward_banner_visible": bool(
                    dialog.reward_banner.isVisibleTo(dialog)
                ),
                "painted": bool(
                    dialog.summary_panel.isVisibleTo(dialog)
                    and not preview_probe.isNull()
                ),
            }

            dialog._submitting = True
            dialog._commit()
            QApplication.processEvents()
            dialog.repaint()
            QApplication.processEvents()
            receipt_probe = dialog.grab()
            outcome = getattr(dialog, "outcome", None)
            target = self.app.engine.plant_story(plant.plant_id)
            records["success-no-stage-reward"] = {
                "transition_statement": str(
                    dialog.transition_statement.text()
                ).strip(),
                "before_label": str(dialog.before_stage_label.text()).strip(),
                "after_label": str(dialog.after_stage_label.text()).strip(),
                "impact_value": str(dialog.impact_value.text()).strip(),
                "growth_value": str(dialog.compact_growth_value.text()).strip(),
                "inventory_value": str(
                    dialog.compact_inventory_value.text()
                ).strip(),
                "stage_progress": str(
                    dialog.compact_stage_progress.text()
                ).strip(),
                "progress_label": str(
                    dialog.compact_progress_label.text()
                ).strip(),
                "completed_stage_count": int(
                    dialog.receipt.property("receiptCompletedStageCount") or 0
                ),
                "reward_total": int(
                    dialog.receipt.property("receiptRewardTotal") or 0
                ),
                "stage_transition_visible": bool(
                    dialog.transition_statement.isVisibleTo(dialog)
                ),
                "reward_banner_visible": bool(
                    dialog.reward_banner.isVisibleTo(dialog)
                ),
                "resulting_growth": int(
                    getattr(target, "growth_points", -1)
                ),
                "inventory_remaining": int(
                    getattr(outcome, "inventory_remaining", -1)
                ),
                "progress_minimum": int(dialog.receipt_progress.minimum()),
                "progress_maximum": int(dialog.receipt_progress.maximum()),
                "progress_value": int(dialog.receipt_progress.value()),
                "painted": bool(
                    dialog.receipt.isVisibleTo(dialog)
                    and not receipt_probe.isNull()
                ),
            }
        except Exception as exc:
            records["runtime-error"] = {"type": type(exc).__name__}
        finally:
            if dialog is not None:
                dialog._submitting = False
                self._dispose_capture_widget(dialog)
                QApplication.processEvents()
            self._restore_growth_charge_capture(
                snapshot,
                transition_snapshot,
            )
        issues = growth_charge_transient_variant_issue_codes(records)
        evidence = {
            "records": records,
            "issues": list(issues),
            "passed": not issues,
        }
        if issues:
            self._failures.append({
                "label": label,
                "reason": (
                    "Growth Charge transient painted variants failed: "
                    + ", ".join(issues)
                ),
            })
        return evidence

    def _growth_charge_capture_annotation(
        self,
        label: str,
        variant: str,
        dialog: Any,
        plant: Any,
    ) -> None:
        expected_status = str(
            expected_capture_state_profile(label).get("growth_charge_status", "")
        )
        actual_status = str(dialog.property("growthChargeState") or "")
        state = self.app.storage.state
        target = self.app.engine.plant_story(
            str(getattr(plant, "plant_id", "") or "")
        )
        inventory = max(
            0,
            int(state.consumables.get("growth_charge_small", 0) or 0),
        )
        ledger_count = len(state.completed_growth_charge_requests)
        alert_visible = not dialog.alert.isHidden()
        receipt_visible = bool(
            variant == "success" and dialog.summary_panel.isVisibleTo(dialog)
        )
        quote = getattr(dialog, "quote", None)
        outcome = getattr(dialog, "outcome", None)
        compact_result = str(dialog.compact_summary.text()).strip()
        compact_result_visible = bool(
            dialog.summary_panel.isVisibleTo(dialog)
        )
        preview_matches_quote = bool(
            quote is not None
            and dialog.summary_panel.isVisibleTo(dialog)
            and bool(dialog.compact_summary_card.property("previewReady"))
            and int(dialog.compact_summary_card.property("currentGrowth") or -1)
            == max(0, int(quote.current_growth))
            and int(dialog.compact_summary_card.property("projectedGrowth") or -1)
            == max(0, int(quote.projected_growth))
            and int(dialog.compact_summary_card.property("inventoryBefore") or -1)
            == max(0, int(quote.inventory_before))
            and int(dialog.compact_summary_card.property("inventoryAfter") or -1)
            == max(0, int(quote.inventory_after))
        )
        result_matches_quote = bool(
            preview_matches_quote
            or (
                variant == "success"
                and quote is not None
                and outcome is not None
                and bool(getattr(outcome, "success", False))
                and int(getattr(outcome, "previous_growth", -1))
                == max(0, int(quote.current_growth))
                and int(getattr(outcome, "resulting_growth", -1))
                == max(0, int(quote.projected_growth))
                and int(getattr(outcome, "growth_granted", -1))
                == max(0, int(quote.granted_growth))
                and int(getattr(outcome, "inventory_remaining", -1))
                == max(0, int(quote.inventory_after))
            )
        )
        plant_details_visible = bool(
            dialog.summary_panel.isVisibleTo(dialog)
            and dialog.transition_row.isVisibleTo(dialog)
            and dialog.before_stage_artwork.isVisibleTo(dialog)
            and not dialog.after_stage_artwork.isVisibleTo(dialog)
            and str(dialog.plant_name_label.text()).strip()
            and str(dialog.plant_species_label.text()).strip()
            and str(dialog.before_comparison_value.text()).strip()
            and str(dialog.after_comparison_value.text()).strip()
        )
        charge_details_visible = bool(
            dialog.summary_panel.isVisibleTo(dialog)
            and dialog.impact_row.isVisibleTo(dialog)
            and dialog.impact_artwork.isVisibleTo(dialog)
            and str(dialog.impact_name.text()).strip()
            and str(dialog.impact_value.text()).strip()
        )
        quantity_text = " ".join(filter(None, (
            str(dialog.charge_selector.currentText()).strip(),
            str(dialog.impact_name.text()).strip(),
            str(dialog.compact_inventory_value.text()).strip(),
        )))
        alert_copy = str(dialog.alert.text()).strip()
        receipt_copy = str(dialog.receipt_copy.text()).strip()
        conditions = [actual_status == expected_status]
        if variant == "ready":
            conditions.extend([
                bool(quote is not None and quote.ready),
                str(dialog.property("growthChargeDataSource") or "")
                == "engine-preview",
                dialog.use_action.isEnabled(),
                plant_details_visible,
                charge_details_visible,
                dialog.reward_banner.isVisibleTo(dialog),
                result_matches_quote,
                inventory == 2,
            ])
        elif variant == "empty":
            footer = getattr(dialog, "_pinned_footer", None)
            conditions.extend([
                dialog.empty_inventory.isVisible(),
                dialog.nursery_action.isVisible(),
                bool(
                    footer is not None
                    and footer.isAncestorOf(dialog.nursery_action)
                ),
                dialog.use_action.isHidden(),
                inventory == 0,
            ])
        elif variant == "loading":
            conditions.extend([
                dialog._submitting,
                dialog.dialog_in_flight,
                not dialog.use_action.isEnabled(),
                not dialog.cancel_action.isEnabled(),
                not dialog.charge_selector.isEnabled(),
                bool(dialog.use_action.property("busy")),
                plant_details_visible,
                charge_details_visible,
                result_matches_quote,
                inventory == 2,
            ])
        elif variant == "stale":
            conditions.extend([
                outcome is not None,
                str(
                    getattr(
                        getattr(outcome, "status", ""),
                        "value",
                        getattr(outcome, "status", ""),
                    )
                ) == "stale_inventory",
                bool(quote is not None and quote.ready),
                not dialog._submitting,
                dialog.use_action.isEnabled(),
                plant_details_visible,
                charge_details_visible,
                result_matches_quote,
                alert_visible,
                str(dialog.alert.property("growthChargeAlertStatus") or "")
                == "stale_inventory",
                inventory == 1,
                int(getattr(target, "growth_points", -1)) == 1_250,
                ledger_count == 0,
            ])
        elif variant == "invalid":
            target_state = str(
                getattr(
                    getattr(quote, "target_state", ""),
                    "value",
                    getattr(quote, "target_state", ""),
                )
            )
            conditions.extend([
                alert_visible,
                str(dialog.alert.property("semanticId") or "")
                == "growth-charge.alert",
                str(dialog.alert.property("growthChargeAlertStatus") or "")
                == expected_status,
                not plant_details_visible,
                not charge_details_visible,
                not compact_result_visible,
                target_state == "stored",
                dialog.use_action.isEnabled(),
                dialog.cancel_action.isVisible(),
                dialog.cancel_action.isEnabled(),
                dialog._primary_route == "choose_plant",
                not bool(getattr(target, "planted", False)),
                ledger_count == 0,
            ])
        elif variant == "persistence":
            conditions.extend([
                alert_visible,
                bool(dialog.alert.text().strip()),
                bool(quantity_text),
                dialog.use_action.isEnabled(),
                inventory == 2,
                int(getattr(target, "growth_points", -1)) == 1_250,
                ledger_count == 0,
            ])
        elif variant == "success":
            reward_total = sum(
                int(reward.garden_coins)
                for reward in getattr(outcome, "rewards", ())
            )
            conditions.extend([
                receipt_visible,
                bool(outcome is not None and outcome.success),
                tuple(getattr(outcome, "completed_stages", ())) == ("sprout",),
                reward_total == 2,
                str(dialog.summary_panel.property("semanticId") or "")
                == "growth-charge.summary",
                str(dialog.receipt.property("receiptPreviousStage") or "")
                == "seed",
                str(dialog.receipt.property("receiptResultingStage") or "")
                == "sprout",
                int(dialog.receipt.property("receiptRewardTotal") or 0)
                == reward_total,
                int(dialog.receipt.property("receiptGrowthGranted") or 0)
                == max(0, int(getattr(outcome, "growth_granted", 0))),
                int(dialog.receipt.property("receiptInventoryRemaining") or 0)
                == max(0, int(getattr(outcome, "inventory_remaining", 0))),
                str(dialog.property("growthChargeDataSource") or "")
                == "engine-confirmed",
                dialog.summary_panel is dialog.compact_summary_card,
                dialog.summary_panel is dialog.receipt,
                dialog.summary_panel is dialog.hero,
                bool(
                    getattr(
                        dialog,
                        "_capture_shared_markup_identity_stable",
                        False,
                    )
                ),
                bool(
                    getattr(
                        dialog,
                        "_capture_preview_layout_signature",
                        {},
                    )
                )
                and getattr(dialog, "_capture_preview_layout_signature", {})
                == getattr(dialog, "_capture_success_layout_signature", {})
                and getattr(dialog, "_capture_preview_position", [])
                == getattr(dialog, "_capture_success_position", []),
                bool(
                    getattr(
                        dialog,
                        "_capture_repeated_activation_safe",
                        False,
                    )
                ),
                inventory == 1,
                int(getattr(target, "growth_points", -1)) == 450,
                ledger_count == 1,
                dialog.use_action.isEnabled(),
                dialog.cancel_action.isVisible(),
                dialog.cancel_action.isEnabled(),
            ])
        rendered_values: dict[str, Any] = {
            "applicable": variant in {"ready", "success"},
            "variant": variant,
            "component_variant": str(
                dialog.property("growthChargeVariant") or ""
            ),
            "data_source": str(
                dialog.property("growthChargeDataSource") or ""
            ),
            "dialog_title": (
                str(dialog.dialog_title.text()).strip()
                if variant in {"ready", "success"} else ""
            ),
            "summary_semantic_id": str(
                dialog.summary_panel.property("semanticId") or ""
            ),
            "shared_component": bool(
                dialog.property("growthChargeSharedComponent")
            ),
            "shared_markup_tree": bool(
                dialog.summary_panel is dialog.compact_summary_card
                and dialog.summary_panel is dialog.receipt
                and dialog.summary_panel is dialog.hero
            ),
            "transition_statement": str(
                dialog.transition_statement.text()
            ).strip(),
            "plant_name": str(dialog.plant_name_label.text()).strip(),
            "plant_species": str(dialog.plant_species_label.text()).strip(),
            "before_label": str(dialog.before_stage_label.text()).strip(),
            "after_label": str(dialog.after_stage_label.text()).strip(),
            "before_heading": str(
                dialog.before_comparison_heading.text()
            ).strip(),
            "before_value": str(
                dialog.before_comparison_value.text()
            ).strip(),
            "after_heading": str(
                dialog.after_comparison_heading.text()
            ).strip(),
            "after_value": str(
                dialog.after_comparison_value.text()
            ).strip(),
            "impact_name": str(dialog.impact_name.text()).strip(),
            "impact_value": str(dialog.impact_value.text()).strip(),
            "growth_label": str(dialog.compact_growth_label.text()).strip(),
            "growth_value": str(dialog.compact_growth_value.text()).strip(),
            "inventory_label": str(
                dialog.compact_inventory_label.text()
            ).strip(),
            "inventory_value": str(
                dialog.compact_inventory_value.text()
            ).strip(),
            "inventory_row_visible": bool(
                dialog.compact_inventory_label.isVisibleTo(dialog)
                or dialog.compact_inventory_value.isVisibleTo(dialog)
            ),
            "progress_label": str(
                dialog.compact_progress_label.text()
            ).strip(),
            "stage_progress": str(
                dialog.compact_stage_progress.text()
            ).strip(),
            "progress_minimum": int(dialog.compact_progress_bar.minimum()),
            "progress_maximum": int(dialog.compact_progress_bar.maximum()),
            "progress_value": int(dialog.compact_progress_bar.value()),
            "reward_label": str(dialog.reward_label.text()).strip(),
            "reward_value": str(dialog.reward_value.text()).strip(),
            "reward_visible": bool(
                dialog.reward_banner.isVisibleTo(dialog)
            ),
            "charge_artwork_fallback": bool(
                dialog.impact_artwork.property("itemArtworkFallback")
            ),
            "coin_artwork_fallback": bool(
                dialog.reward_artwork.property("itemArtworkFallback")
            ),
            "before_artwork_fallback": bool(
                dialog.before_stage_artwork.property("plantArtworkFallback")
            ),
            "visible_plant_thumbnail_count": sum((
                bool(dialog.before_stage_artwork.isVisibleTo(dialog)),
                bool(dialog.after_stage_artwork.isVisibleTo(dialog)),
            )),
            "plant_thumbnail_role": str(
                dialog.before_stage_artwork.property("thumbnailRole") or ""
            ),
            "stage_event_kind": str(
                dialog.summary_panel.property("semanticEventKind") or ""
            ),
            "success_check_visible": bool(
                dialog.success_check.isVisibleTo(dialog)
            ),
            "primary_action": _displayed_button_text(
                dialog.use_action
            ).strip(),
            "secondary_action": _displayed_button_text(
                dialog.cancel_action
            ).strip(),
            "current_growth": int(
                dialog.summary_panel.property("currentGrowth") or -1
            ),
            "projected_growth": int(
                dialog.summary_panel.property("projectedGrowth") or -1
            ),
            "inventory_before": int(
                dialog.summary_panel.property("inventoryBefore") or -1
            ),
            "inventory_after": int(
                dialog.summary_panel.property("inventoryAfter") or -1
            ),
            "stage_carryover": int(dialog.compact_progress_bar.value()),
            "next_stage_goal": int(dialog.compact_progress_bar.maximum()),
            "comparison_labels": str(
                dialog.transition_row.property("comparisonLabels") or ""
            ),
            "before_art_role": str(
                dialog.before_stage_artwork.property("transitionRole") or ""
            ),
            "after_art_role": str(
                dialog.after_stage_artwork.property("transitionRole") or ""
            ),
            "transition_arrow_visible": bool(
                dialog.transition_arrow.isVisibleTo(dialog)
            ),
            "transition_arrow_role": bool(
                dialog.transition_arrow.property("transitionArrow")
            ),
            "passed": True,
        }
        common_rendered_ok = bool(
            rendered_values["summary_semantic_id"] == "growth-charge.summary"
            and rendered_values["shared_component"] is True
            and rendered_values["shared_markup_tree"] is True
            and rendered_values["plant_name"] == "Bonsai Plant"
            and rendered_values["plant_species"] == "Bonsai"
            and rendered_values["after_label"] == "After · Sprout"
            and rendered_values["before_heading"] == "Before"
            and rendered_values["before_value"] == "Seed\n350 Growth"
            and rendered_values["after_value"] == "Sprout\n450 Growth"
            and rendered_values["impact_name"] == "Small Growth Charge"
            and rendered_values["impact_value"] == "2 → 1 owned"
            and rendered_values["growth_label"] == "Growth"
            and rendered_values["growth_value"] == "350 → 450"
            and rendered_values["inventory_label"] == "Owned"
            and rendered_values["inventory_value"] == "2 → 1"
            and rendered_values["inventory_row_visible"] is False
            and rendered_values["stage_progress"] == "50 / 1,600 Growth"
            and rendered_values["progress_minimum"] == 0
            and rendered_values["progress_maximum"] == 1_600
            and rendered_values["progress_value"] == 50
            and rendered_values["reward_value"] == "+2 Garden Coins"
            and rendered_values["reward_visible"] is True
            and rendered_values["charge_artwork_fallback"] is False
            and rendered_values["coin_artwork_fallback"] is False
            and rendered_values["before_artwork_fallback"] is False
            and rendered_values["visible_plant_thumbnail_count"] == 1
            and rendered_values["plant_thumbnail_role"]
            == "growth-charge-plant"
            and rendered_values["stage_event_kind"] == "stage_change"
            and rendered_values["current_growth"] == 350
            and rendered_values["projected_growth"] == 450
            and rendered_values["inventory_before"] == 2
            and rendered_values["inventory_after"] == 1
            and rendered_values["comparison_labels"] == "before-after"
            and rendered_values["before_art_role"] == "before"
            and rendered_values["after_art_role"] == "after"
            and rendered_values["transition_arrow_visible"] is True
            and rendered_values["transition_arrow_role"] is True
        )
        if variant == "ready":
            rendered_values["passed"] = bool(
                dialog.summary_panel.isVisibleTo(dialog)
                and common_rendered_ok
                and rendered_values["dialog_title"]
                == "Use Small Growth Charge?"
                and rendered_values["component_variant"] == "confirmation"
                and rendered_values["data_source"] == "engine-preview"
                and rendered_values["transition_statement"]
                == "Stage change on use"
                and rendered_values["before_label"] == "Seed"
                and rendered_values["after_heading"] == "After use"
                and rendered_values["progress_label"]
                == "After use toward Young"
                and rendered_values["reward_label"]
                == "Stage reward on use"
                and rendered_values["success_check_visible"] is False
                and rendered_values["primary_action"] == "Use charge"
                and rendered_values["secondary_action"] == "Cancel"
            )
        elif variant == "success":
            preview_signature = dict(
                getattr(dialog, "_capture_preview_layout_signature", {}) or {}
            )
            success_signature = dict(
                getattr(dialog, "_capture_success_layout_signature", {}) or {}
            )
            rendered_values.update({
                "resulting_growth": int(getattr(target, "growth_points", -1)),
                "inventory_remaining": inventory,
                "stage_reward_total": sum(
                    int(reward.garden_coins)
                    for reward in getattr(outcome, "rewards", ())
                ) if outcome is not None else 0,
                "preview_layout_signature": preview_signature,
                "success_layout_signature": success_signature,
                "layout_stable": bool(
                    preview_signature
                    and preview_signature == success_signature
                    and list(
                        getattr(dialog, "_capture_preview_position", []) or []
                    ) == list(
                        getattr(dialog, "_capture_success_position", []) or []
                    )
                ),
                "repeated_activation_safe": bool(
                    getattr(
                        dialog,
                        "_capture_repeated_activation_safe",
                        False,
                    )
                ),
            })
            rendered_values["passed"] = bool(
                dialog.summary_panel.isVisibleTo(dialog)
                and common_rendered_ok
                and rendered_values["dialog_title"]
                == "Small Growth Charge applied"
                and rendered_values["component_variant"] == "success"
                and rendered_values["data_source"] == "engine-confirmed"
                and rendered_values["transition_statement"]
                == "Stage changed"
                and rendered_values["before_label"] == "Sprout"
                and rendered_values["after_heading"] == "Applied"
                and rendered_values["progress_label"]
                == "Result toward Young"
                and rendered_values["reward_label"]
                == "Stage reward earned"
                and rendered_values["success_check_visible"] is True
                and rendered_values["primary_action"] == "View plant"
                and rendered_values["secondary_action"] == "Close"
                and rendered_values["resulting_growth"] == 450
                and rendered_values["inventory_remaining"] == 1
                and rendered_values["stage_reward_total"] == 2
                and rendered_values["layout_stable"] is True
                and rendered_values["repeated_activation_safe"] is True
            )
        conditions.append(bool(rendered_values["passed"]))
        active_scrolls = tuple(dialog.active_vertical_scroll_regions())
        vertical = dialog.content_scroll.verticalScrollBar()
        normal_content_fit_no_scroll = bool(
            not active_scrolls
            and int(vertical.maximum()) == int(vertical.minimum())
            and not vertical.isVisible()
        )
        conditions.append(normal_content_fit_no_scroll)
        passed = all(conditions)
        failed_invariants: list[str] = []
        if actual_status != expected_status:
            failed_invariants.append(
                f"status:{actual_status!r}!={expected_status!r}"
            )
        if not result_matches_quote and variant in {
            "ready",
            "loading",
            "stale",
            "success",
        }:
            failed_invariants.append("engine-result-carryover")
        if not bool(rendered_values.get("passed", False)):
            failed_invariants.append("rendered-value-contract")
        if (
            variant == "success"
            and rendered_values.get("layout_stable") is not True
        ):
            failed_invariants.append("layout-stability")
        if (
            variant == "success"
            and rendered_values.get("repeated_activation_safe") is not True
        ):
            failed_invariants.append("repeated-activation-safety")
        if not normal_content_fit_no_scroll:
            failed_invariants.append("unexpected-vertical-overflow")
        if not passed and not failed_invariants:
            failed_invariants.append("variant-state-contract")
        self._capture_annotations[label].update({
            "variant": variant,
            "expected_status": expected_status,
            "actual_status": actual_status,
            "inventory": inventory,
            "target_growth": int(getattr(target, "growth_points", -1)),
            "request_ledger_count": ledger_count,
            "alert_visible": alert_visible,
            "receipt_visible": receipt_visible,
            "compact_result_visible": compact_result_visible,
            "result_matches_quote": result_matches_quote,
            "plant_details_visible": plant_details_visible,
            "charge_details_visible": charge_details_visible,
            "alert_copy": alert_copy,
            "receipt_copy": receipt_copy,
            "ready_with_stale_inventory_warning": bool(
                variant != "stale"
                or (
                    alert_visible
                    and str(
                        dialog.alert.property("growthChargeAlertStatus") or ""
                    ) == "stale_inventory"
                    and quote is not None
                    and bool(quote.ready)
                    and dialog.use_action.isEnabled()
                )
            ),
            "seed_to_sprout_receipt": bool(
                variant != "success"
                or (
                    receipt_visible
                    and str(
                        dialog.receipt.property("receiptPreviousStage") or ""
                    ) == "seed"
                    and str(
                        dialog.receipt.property("receiptResultingStage") or ""
                    ) == "sprout"
                )
            ),
            "growth_charge_rendered_values": rendered_values,
            "active_scroll_count": len(active_scrolls),
            "normal_content_fit_no_scroll": normal_content_fit_no_scroll,
            "failed_invariants": failed_invariants,
            "passed": passed,
        })
        if not passed:
            self._failures.append({
                "label": label,
                "reason": (
                    "Growth Charge fixture failed: "
                    + ", ".join(failed_invariants)
                ),
            })

    def _capture_growth_charge_dialog_fixture(
        self,
        label: str,
        variant: str,
    ) -> None:
        cleanup_holder: dict[str, Callable[[], None]] = {
            "callback": lambda: None,
        }

        def registered_cleanup() -> None:
            cleanup_holder["callback"]()

        def dashboard_ready() -> None:
            transient_variants = (
                self._exercise_growth_charge_transient_variants(label)
                if variant == "success" else
                {"records": {}, "issues": [], "passed": True}
            )
            inventory = 0 if variant == "empty" else 2
            # Ready and success are two views of one coherent transaction:
            # the same +100 charge crosses the 2.2 Seed -> Sprout threshold.
            growth_points = 350 if variant in {"ready", "success"} else 1_250
            planted = variant != "invalid"
            snapshot, transition_snapshot, plant = self._prepare_growth_charge_capture(
                label,
                inventory=inventory,
                growth_points=growth_points,
                planted=planted,
                exact_ledger_restore=variant == "success",
            )
            def cleanup() -> None:
                self._restore_growth_charge_capture(
                    snapshot,
                    transition_snapshot,
                )

            # Register cleanup before the dialog's synchronous commit path.
            cleanup_holder["callback"] = cleanup
            from ..ui.dashboard import GrowthChargeConfirmationDialog

            dialog = GrowthChargeConfirmationDialog(
                self.app.dashboard,
                self.app.engine,
                plant.plant_id,
                open_nursery=lambda: None,
            )
            if variant == "loading":
                dialog._commit = lambda: None
                dialog._activate_primary()
            elif variant == "stale":
                self.app.storage.state.consumables["growth_charge_small"] = 1
                dialog._submitting = True
                dialog._commit()
            elif variant == "persistence":
                original_save = self.app.storage.save

                def fail_save() -> None:
                    raise OSError("deterministic Growth Charge persistence failure")

                self.app.storage.save = fail_save
                try:
                    dialog._submitting = True
                    dialog._commit()
                finally:
                    self.app.storage.save = original_save

            dialog.setWindowModality(Qt.WindowModality.NonModal)
            dialog.setModal(False)
            self._move_to_capture_display(dialog)

            def close_dialog() -> None:
                dialog._submitting = False
                self._dispose_capture_widget(
                    dialog,
                    owner=self.app.dashboard,
                    owner_attribute="growth_charge_dialog",
                )
                cleanup()

            dialog.show()
            dialog.raise_()
            dialog.activateWindow()
            QApplication.processEvents()
            if variant == "success":
                dialog.fit_content_to_family(
                    breathing_room=8,
                    preserve_transition=False,
                )
                QApplication.processEvents()
                dialog._capture_preview_layout_signature = (
                    dialog.shared_layout_signature()
                )
                dialog._capture_preview_position = [
                    int(dialog.x()),
                    int(dialog.y()),
                ]
                summary_identity = id(dialog.summary_panel)
                dialog._activate_primary()
                # Simulate a repeated click before the queued commit runs.
                # The in-flight guard must consume exactly one charge.
                dialog._activate_primary()
                QApplication.processEvents()
                dialog.fit_content_to_family(
                    breathing_room=8,
                    preserve_transition=True,
                )
                QApplication.processEvents()
                dialog._capture_success_layout_signature = (
                    dialog.shared_layout_signature()
                )
                dialog._capture_success_position = [
                    int(dialog.x()),
                    int(dialog.y()),
                ]
                dialog._capture_shared_markup_identity_stable = bool(
                    summary_identity == id(dialog.summary_panel)
                )
                dialog._capture_repeated_activation_safe = bool(
                    int(
                        self.app.storage.state.consumables.get(
                            "growth_charge_small",
                            0,
                        )
                        or 0
                    ) == 1
                    and len(
                        self.app.storage.state.completed_growth_charge_requests
                    ) == 1
                )
            self._growth_charge_capture_annotation(label, variant, dialog, plant)
            if variant == "success":
                annotation = self._capture_annotations[label]
                annotation["transient_growth_charge_variants"] = (
                    transient_variants
                )
                annotation["passed"] = bool(
                    annotation.get("passed", False)
                    and transient_variants.get("passed", False)
                )
            self._capture_and_advance(
                label,
                dialog,
                capture_delay_ms=440,
                close_callback=close_dialog,
                cleanup_predicate=lambda: self._capture_widget_disposed(dialog),
                close_ms=840,
                next_ms=1180,
            )

        self._with_dashboard(
            dashboard_ready,
            failure_label=label,
            on_error=registered_cleanup,
        )

