    def _capture_collection_loadout_persistence_error(self) -> None:
        label = "collection-loadout-persistence-error"

        def ready() -> None:
            dashboard = self.app.dashboard
            prepared = self._purchase_capture_snapshot(label)
            if prepared is None:
                self._next_after(200)
                return
            snapshot, _plant = prepared
            state = self.app.storage.state
            if "wind_chime" not in state.inventory.setdefault(
                "garden_features", []
            ):
                state.inventory["garden_features"].append("wind_chime")
            state.selected_garden_feature = "seedling_sign"
            dialog = dashboard.collectible_detail_dialog
            dialog.prepare_to_show()
            dialog._select_option("garden_feature", "wind_chime")
            before = deepcopy(self.app.engine.state.loadout.to_dict())
            original_save = self.app.storage.save

            def fail_save() -> None:
                raise OSError("deterministic Collection loadout persistence failure")

            self.app.storage.save = fail_save
            try:
                dialog._apply_draft()
            finally:
                self.app.storage.save = original_save
            after = self.app.engine.state.loadout.to_dict()
            self._move_to_capture_display(dialog)
            dialog.show()
            dialog.raise_()
            dialog.activateWindow()
            QApplication.processEvents()
            error_copy = str(dialog.preview_feedback.message.text())
            error_visible = bool(
                dialog.preview_feedback.isVisible()
                and dialog.preview_panel.isAncestorOf(dialog.preview_feedback)
                and not dialog.preview_scene.isAncestorOf(dialog.preview_feedback)
                and "Could not apply changes" in error_copy
                and "unchanged" in error_copy
            )
            actions = {
                _displayed_button_text(dialog.cancel_preview),
                _displayed_button_text(dialog.apply_changes),
            }
            normal_width_actions = bool(
                dialog.property("footerMode") == "wide"
                and max(
                    dialog.cancel_preview.width(),
                    dialog.apply_changes.width(),
                )
                <= max(220, int(dialog.footer.width() * 0.35))
            )
            apply_origin = dialog.apply_changes.mapTo(
                dialog.footer,
                dialog.apply_changes.rect().topLeft(),
            )
            footer_margins = dialog.footer_layout.contentsMargins()
            actions_right_aligned = bool(
                apply_origin.x() + dialog.apply_changes.width()
                >= dialog.footer.width() - footer_margins.right() - 2
            )
            single_banner = bool(
                error_visible
                and dialog.unsaved.isHidden()
                and not str(dialog.unsaved.text()).strip()
            )
            self._capture_annotations[label] = {
                "passed": bool(
                    before == after
                    and error_visible
                    and actions == {"Try again", "Discard changes"}
                    and single_banner
                    and normal_width_actions
                    and actions_right_aligned
                ),
                "state_restored": before == after,
                "error_visible": error_visible,
                "error_copy": error_copy,
                "actions": sorted(actions),
                "single_banner": single_banner,
                "normal_width_actions": normal_width_actions,
                "actions_right_aligned": actions_right_aligned,
            }

            def bind_final_pixel_evidence() -> None:
                """Prove the settled rollback state is painted, not just owned."""

                QCoreApplication.sendPostedEvents(
                    None,
                    QEvent.Type.DeferredDelete,
                )
                app = QApplication.instance()
                if app is not None:
                    app.processEvents()
                dialog._refresh_preview()
                dialog._sync_option_page_geometry(
                    dialog.option_tabs.currentIndex()
                )
                dialog._sync_preview_scene_geometry()
                body = dialog.appearance_body
                active_scroll = dialog._catalog_scroll_by_page.get(
                    dialog.option_tabs.currentWidget()
                )
                for layout in (
                    dialog.main_grid,
                    dialog.library.layout(),
                    dialog.preview_panel.layout(),
                    body.layout() if body is not None else None,
                ):
                    if layout is None:
                        continue
                    layout.invalidate()
                    layout.activate()
                if body is not None:
                    body.setMinimumHeight(0)
                    body.updateGeometry()
                if active_scroll is not None:
                    active_scroll.verticalScrollBar().setValue(0)
                dialog.preview_scene.setProperty(
                    "captureEvidenceKey",
                    "loadout-preview-scene",
                )
                dialog.preview_feedback.setProperty(
                    "captureEvidenceKey",
                    "loadout-persistence-error",
                )
                dialog.preview_scene.update()
                dialog._position_preview_feedback()
                dialog.preview_feedback.raise_()
                if app is not None:
                    app.processEvents()
                dialog.preview_scene.repaint()
                if app is not None:
                    app.processEvents()

                scene_bounds = self._widget_bounds_evidence(
                    dialog.preview_scene,
                    dialog,
                )
                feedback_bounds = self._widget_bounds_evidence(
                    dialog.preview_feedback,
                    dialog,
                )
                scene_metrics = self._home_pixmap_metrics(
                    dialog.preview_scene.grab(),
                    expected_width=dialog.preview_scene.width(),
                    expected_height=dialog.preview_scene.height(),
                )
                scene_box = list(scene_bounds.get("bounds", ()) or ())
                feedback_box = list(feedback_bounds.get("bounds", ()) or ())
                feedback_outside_artwork = bool(
                    len(scene_box) == 4
                    and len(feedback_box) == 4
                    and int(feedback_box[1]) + int(feedback_box[3])
                    <= int(scene_box[1])
                )
                rendered_state = {
                    "scene_bounds": scene_bounds,
                    "scene_metrics": scene_metrics,
                    "feedback_bounds": feedback_bounds,
                    "feedback_text": str(dialog.preview_feedback.message.text()),
                    "feedback_outside_artwork": feedback_outside_artwork,
                    "scroll_maximum": int(
                        active_scroll.verticalScrollBar().maximum()
                        if active_scroll is not None else 0
                    ),
                    "passed": bool(
                        scene_bounds.get("visible", False)
                        and scene_bounds.get("contained", False)
                        and scene_metrics.get("generic_content_passed", False)
                        and feedback_bounds.get("visible", False)
                        and feedback_bounds.get("contained", False)
                        and feedback_outside_artwork
                        and "Could not save changes"
                        in str(dialog.preview_feedback.message.text())
                    ),
                }
                annotation = self._capture_annotations[label]
                annotation["rendered_state"] = rendered_state
                annotation["passed"] = bool(
                    annotation.get("passed", False)
                    and rendered_state["passed"]
                )

            def close_dialog() -> None:
                self._close_widget(dialog)
                self._restore_purchase_capture(snapshot)

            self._capture_and_advance(
                label,
                dialog,
                capture_delay_ms=460,
                before_capture=bind_final_pixel_evidence,
                close_callback=close_dialog,
                close_ms=800,
                next_ms=1120,
            )

        self._with_dashboard(ready, failure_label=label)

    def _capture_collection_origin_plant_placement(self) -> None:
        label = "collection-origin-plant-placement"

        def ready() -> None:
            dashboard = self.app.dashboard
            prepared = self._purchase_capture_snapshot(label)
            if prepared is None:
                self._next_after(200)
                return
            snapshot, plant = prepared
            cleanup_complete = False
            plant.slot_index = None
            dashboard.refresh_all()
            dashboard._begin_collection_placement(plant.plant_id)
            QApplication.processEvents()
            active = bool(
                dashboard._collection_placement_plant_id == plant.plant_id
                and dashboard.scene._interaction.placing
            )
            from ..ui.plant_display import (
                bed_badge_rect,
                move_badge_label,
                move_target_state,
            )

            scene = dashboard.scene
            viewport = dashboard
            scene_origin = scene.mapTo(viewport, scene.rect().topLeft())
            scene_viewport_bounds = [
                int(scene_origin.x()),
                int(scene_origin.y()),
                int(scene.width()),
                int(scene.height()),
            ]
            scene_fully_visible = bool(
                scene_origin.x() >= 0
                and scene_origin.y() >= 0
                and scene_origin.x() + scene.width() <= viewport.width()
                and scene_origin.y() + scene.height() <= viewport.height()
            )
            scene_plants = list(scene.scene.get("plants", ()))
            occupied_slots = {
                int(candidate.get("slot_index", -1))
                for candidate in scene_plants
            }
            occupant_names = {
                int(candidate.get("slot_index", -1)): str(
                    candidate.get("name")
                    or candidate.get("species")
                    or "plant"
                )
                for candidate in scene_plants
            }
            unlocked_slots = max(
                0,
                min(
                    6,
                    int(scene.scene.get("unlocked_slots", len(occupied_slots))),
                ),
            )
            valid_destinations = set(scene._destination_slots())
            origin_slot = scene._interaction.drag_origin_slot
            unplaced_placement = bool(
                origin_slot is None or int(origin_slot) < 0
            )
            destination_slot = scene._interaction.destination_slot
            hovered_slot = scene._hovered_move_slot
            plant_obstacles = [
                layout.visible.expanded(4.0, 3.0)
                for _candidate, layout in scene._layout_plants(
                    scene.width(),
                    scene.height(),
                )
            ]
            badge_font = QFont(scene.font())
            badge_font.setPointSizeF(11.0)
            badge_font.setBold(True)
            badge_metrics = QFontMetricsF(badge_font)
            placed_badges = []
            badge_audits: list[dict[str, Any]] = []

            for slot, row in scene._slot_placements.items():
                target_state = move_target_state(
                    slot,
                    origin_slot=origin_slot,
                    valid_destination_slots=valid_destinations,
                    unlocked_slots=unlocked_slots,
                )
                semantic_label, semantic_state = move_badge_label(
                    slot,
                    origin_slot=origin_slot,
                    destination_slot=(
                        slot
                        if slot == hovered_slot and target_state == "valid"
                        else destination_slot
                    ),
                    unlocked_slots=unlocked_slots,
                    occupied_slots=occupied_slots,
                    occupant_names=occupant_names,
                )
                current = target_state == "current"
                occupied_target = slot in occupied_slots and not current
                visual_label = (
                    "Current"
                    if current else
                    "Occupied"
                    if target_state == "unavailable" and occupied_target else
                    "Invalid"
                    if target_state == "unavailable" else
                    "Locked"
                    if target_state == "locked" else
                    "Place here"
                    if (
                        unplaced_placement
                        and semantic_state in {"active", "available"}
                    ) else
                    "Move here"
                    if semantic_state in {"active", "available"} else
                    semantic_label
                )
                badge = bed_badge_rect(
                    row,
                    visual_label,
                    scene.width(),
                    scene.height(),
                    [*plant_obstacles, *placed_badges],
                )
                text_width = float(badge_metrics.horizontalAdvance(visual_label))
                text_height = float(badge_metrics.height())
                contained = bool(
                    badge.x >= 4.0
                    and badge.y >= 4.0
                    and badge.right <= float(scene.width()) - 4.0
                    and badge.bottom <= float(scene.height()) - 4.0
                )
                clear_previous_badges = not any(
                    badge.intersects(previous) for previous in placed_badges
                )
                clear_plant_artwork = not any(
                    badge.intersects(obstacle) for obstacle in plant_obstacles
                )
                text_fits = bool(
                    text_width <= badge.width - 12.0
                    and text_height <= badge.height - 8.0
                )
                badge_audits.append({
                    "slot": int(slot),
                    "label": visual_label,
                    "semantic_state": semantic_state,
                    "rect": [
                        round(float(badge.x), 3),
                        round(float(badge.y), 3),
                        round(float(badge.width), 3),
                        round(float(badge.height), 3),
                    ],
                    "text_size": [
                        round(text_width, 3),
                        round(text_height, 3),
                    ],
                    "contained": contained,
                    "clear_previous_badges": clear_previous_badges,
                    "clear_plant_artwork": clear_plant_artwork,
                    "text_fits": text_fits,
                })
                placed_badges.append(badge)

            occupied_badge_widths = [
                float(audit["rect"][2])
                for audit in badge_audits
                if audit["label"] == "Occupied"
            ]
            occupied_badges_legible = bool(
                occupied_badge_widths
                and all(width >= 80.0 for width in occupied_badge_widths)
            )
            badge_text_fits = bool(
                badge_audits
                and all(audit["text_fits"] for audit in badge_audits)
            )
            badges_contained = bool(
                badge_audits
                and all(audit["contained"] for audit in badge_audits)
            )
            badges_pairwise_non_overlapping = bool(
                badge_audits
                and all(
                    audit["clear_previous_badges"] for audit in badge_audits
                )
            )
            badges_clear_plant_artwork = bool(
                badge_audits
                and all(audit["clear_plant_artwork"] for audit in badge_audits)
            )
            placement_badges = [
                audit
                for audit in badge_audits
                if audit["semantic_state"] in {"active", "available"}
            ]
            painted_move_labels = {
                int(slot): str(painted_label)
                for slot, painted_label in dict(
                    getattr(scene, "_painted_move_labels", {})
                ).items()
            }
            placement_labels_correct = bool(
                unplaced_placement
                and placement_badges
                and painted_move_labels
                and "Place here" in painted_move_labels.values()
                and "Move here" not in painted_move_labels.values()
            )
            self._capture_annotations[label] = {
                "passed": bool(
                    active
                    and occupied_badges_legible
                    and badge_text_fits
                    and badges_contained
                    and badges_pairwise_non_overlapping
                    and badges_clear_plant_artwork
                    and placement_labels_correct
                    and scene_fully_visible
                ),
                "plant_id": plant.plant_id,
                "placement_active": active,
                "badge_font_point_size": 11.0,
                "badge_font_bold": True,
                "badge_audits": badge_audits,
                "occupied_badge_widths": occupied_badge_widths,
                "occupied_badges_legible": occupied_badges_legible,
                "badge_text_fits": badge_text_fits,
                "badges_contained": badges_contained,
                "badges_pairwise_non_overlapping": (
                    badges_pairwise_non_overlapping
                ),
                "badges_clear_plant_artwork": badges_clear_plant_artwork,
                "painted_move_labels": painted_move_labels,
                "placement_labels_correct": placement_labels_correct,
                "scene_viewport_bounds": scene_viewport_bounds,
                "scene_fully_visible": scene_fully_visible,
            }

            def cleanup() -> None:
                nonlocal cleanup_complete
                if dashboard.scene._interaction.placing:
                    dashboard.scene.finish_move("Capture complete.")
                dashboard._collection_placement_plant_id = ""
                dashboard.rearrange_bar.hide()
                QApplication.processEvents()
                self._restore_purchase_capture(snapshot)
                cleanup_complete = True

            self._capture_and_advance(
                label,
                dashboard,
                capture_delay_ms=460,
                close_callback=cleanup,
                cleanup_predicate=lambda: cleanup_complete,
                close_ms=800,
                next_ms=1120,
            )

        self._with_dashboard(ready, failure_label=label)

    def _exercise_collection_loadout_state_matrix(
        self,
        dialog: Any,
    ) -> dict[str, Any]:
        """Paint a draft across all tabs, then restore the saved appearance."""

        def settle() -> None:
            dialog._sync_option_page_geometry(
                dialog.option_tabs.currentIndex()
            )
            dialog._sync_preview_scene_geometry()
            app = QApplication.instance()
            if app is not None:
                QCoreApplication.sendPostedEvents(
                    None,
                    QEvent.Type.LayoutRequest,
                )
                app.processEvents()
            dialog.repaint()
            if app is not None:
                app.processEvents()

        dialog.prepare_to_show()
        dialog.option_tabs.setCurrentIndex(0)
        settle()
        initial_apply_enabled = bool(dialog.apply_changes.isEnabled())
        candidate_ids = sorted(
            item_id
            for (kind, item_id), tile in dict(dialog._tiles).items()
            if kind == "scenery"
            and item_id != str(dialog._persisted_scenery)
            and tile.isEnabled()
        )
        selected_scenery_id = candidate_ids[0] if candidate_ids else ""
        dirty_apply_enabled = False
        selection_preserved = False
        selected_tile_checked = False
        dirty_state_painted = False
        if selected_scenery_id:
            dialog._select_option("scenery", selected_scenery_id)
            settle()
            dirty_apply_enabled = bool(dialog.apply_changes.isEnabled())
            dirty_pixmap = dialog.grab()
            dirty_state_painted = bool(
                dialog.isVisible()
                and dirty_pixmap is not None
                and not dirty_pixmap.isNull()
            )
            for tab_index in (1, 2, 0):
                dialog.option_tabs.setCurrentIndex(tab_index)
                settle()
            selection_preserved = bool(
                str(dialog._draft_scenery) == selected_scenery_id
            )
            selected_tile = dict(dialog._tiles).get(
                ("scenery", selected_scenery_id)
            )
            selected_tile_checked = bool(
                selected_tile is not None
                and selected_tile.isChecked()
                and str(
                    selected_tile.property("environmentSelectionState") or ""
                ) == "selected"
            )

        dialog.prepare_to_show()
        dialog.option_tabs.setCurrentIndex(0)
        settle()
        structured_values = {
            str(key): str(value.text()).strip()
            for key, value in dict(dialog.appearance_values).items()
        }
        summary_labels = [
            str(candidate.text()).strip()
            for candidate in dialog.appearance_summary.findChildren(QLabel)
            if bool(candidate.property("summaryLabel"))
        ]
        active_effect = dialog.appearance_effects.get("active_bonus")
        summary_layout = dialog.appearance_summary.layout()
        library_bounds = self._widget_bounds_evidence(dialog.library, dialog)
        preview_panel_bounds = self._widget_bounds_evidence(
            dialog.preview_panel,
            dialog,
        )
        library_box = list(library_bounds.get("bounds", ()) or ())
        preview_box = list(preview_panel_bounds.get("bounds", ()) or ())
        panels_share_bottom_boundary = bool(
            len(library_box) == 4
            and len(preview_box) == 4
            and abs(
                int(library_box[1]) + int(library_box[3])
                - int(preview_box[1]) - int(preview_box[3])
            ) <= 2
        )
        structured_values_visible = bool(
            set(structured_values) == {
                "scenery",
                "displayed_decoration",
                "active_bonus",
                "visual_effects",
            }
            and all(
                value.isVisibleTo(dialog)
                for value in dict(dialog.appearance_values).values()
            )
        )
        preview_size = [
            int(dialog.preview_scene.width()),
            int(dialog.preview_scene.height()),
        ]
        restored_pixmap = dialog.grab()
        restored_state_painted = bool(
            dialog.isVisible()
            and restored_pixmap is not None
            and not restored_pixmap.isNull()
        )
        evidence = {
            "structured_values": structured_values,
            "summary_labels": summary_labels,
            "active_bonus_effect": (
                str(active_effect.text()).strip()
                if active_effect is not None else ""
            ),
            "tab_labels": [
                str(dialog.option_tabs.tabText(index)).replace("&&", "&")
                for index in range(dialog.option_tabs.count())
            ],
            "header_overline": str(dialog.collection_overline.text()).strip(),
            "header_title": str(dialog.dialog_title.text()).strip(),
            "summary_values_left_aligned": all(
                bool(value.alignment() & Qt.AlignmentFlag.AlignLeft)
                for value in dialog.appearance_values.values()
            ),
            "summary_label_column_width": (
                int(summary_layout.columnMinimumWidth(1))
                if isinstance(summary_layout, QGridLayout) else -1
            ),
            "library_bounds": library_bounds,
            "preview_panel_bounds": preview_panel_bounds,
            "panels_share_bottom_boundary": panels_share_bottom_boundary,
            "structured_values_visible": structured_values_visible,
            "initial_apply_enabled": initial_apply_enabled,
            "dirty_apply_enabled": dirty_apply_enabled,
            "restored_apply_enabled": bool(
                dialog.apply_changes.isEnabled()
            ),
            "selected_scenery_id": selected_scenery_id,
            "selection_preserved_across_tabs": selection_preserved,
            "selected_tile_checked_after_tabs": selected_tile_checked,
            "preview_size": preview_size,
            "preview_aspect_ratio": (
                round(preview_size[0] / preview_size[1], 6)
                if preview_size[1] > 0 else
                0.0
            ),
            "dirty_state_painted": dirty_state_painted,
            "restored_state_painted": restored_state_painted,
            "restored_to_persisted_draft": bool(
                dialog._draft_key() == dialog._persisted_draft
            ),
        }
        issues = collection_loadout_state_matrix_issue_codes(evidence)
        evidence["issues"] = list(issues)
        evidence["passed"] = not issues
        if issues:
            self._failures.append({
                "label": "collection-loadout-detail",
                "reason": (
                    "Collection loadout state matrix failed: "
                    + ", ".join(issues)
                ),
            })
        return evidence

    def _capture_collection_loadout_detail(self) -> None:
        self._with_dashboard(self._capture_collection_loadout_detail_after)

    def _capture_collection_loadout_detail_after(self) -> None:
        label = "collection-loadout-detail"
        dashboard = getattr(self.app, "dashboard", None)
        opener = getattr(dashboard, "_open_loadout_detail", None)
        if dashboard is None or not callable(opener):
            self._failures.append({
                "label": label,
                "reason": "Collection loadout detail opener was unavailable",
            })
            self._next_after(250)
            return
        fixture: dict[str, Any] = {}
        cleanup: Callable[[], None] = lambda: None
        try:
            cleanup = self._prepare_appearance_capture_fixture(
                label,
                dashboard,
                fixture,
            )
            opener()
        except Exception as exc:
            cleanup()
            self._failures.append({
                "label": label,
                "reason": (
                    "Collection appearance fixture setup raised "
                    f"{type(exc).__name__}"
                ),
            })
            self._next_after(250)
            return
        dialog = getattr(dashboard, "collectible_detail_dialog", None)
        interaction_matrix: dict[str, Any] = {}

        def current_catalog_scroll() -> QScrollArea | None:
            return dialog._catalog_scroll_by_page.get(
                dialog.option_tabs.currentWidget()
            )

        def prepare_rendered_state() -> None:
            dialog.option_tabs.setCurrentIndex(0)
            dialog._refresh_preview()
            dialog._sync_option_page_geometry(dialog.option_tabs.currentIndex())
            dialog._sync_preview_scene_geometry()
            body = dialog.appearance_body
            active_scroll = current_catalog_scroll()
            for layout in (
                dialog.main_grid,
                dialog.library.layout(),
                dialog.preview_panel.layout(),
                body.layout() if body is not None else None,
            ):
                if layout is None:
                    continue
                layout.invalidate()
                layout.activate()
            if body is not None:
                body.setMinimumHeight(0)
                body.updateGeometry()
            if active_scroll is not None:
                active_scroll.verticalScrollBar().setValue(0)
            dialog.preview_scene.setProperty(
                "captureEvidenceKey",
                "loadout-preview-scene",
            )
            dialog.preview_scene.updateGeometry()
            dialog.preview_scene.update()
            app = QApplication.instance()
            if app is not None:
                app.processEvents()

        def rendered_state_ready() -> bool:
            nonlocal interaction_matrix
            prepare_rendered_state()
            if not interaction_matrix:
                interaction_matrix = (
                    self._exercise_collection_loadout_state_matrix(dialog)
                )
                prepare_rendered_state()
            active_scroll = current_catalog_scroll()
            dialog.preview_scene.repaint()
            app = QApplication.instance()
            if app is not None:
                app.processEvents()
            scene_bounds = self._widget_bounds_evidence(
                dialog.preview_scene,
                dialog,
            )
            viewport_bounds = self._widget_bounds_evidence(
                dialog.preview_scene,
                dialog.preview_panel,
            )
            scene_metrics = self._home_pixmap_metrics(
                dialog.preview_scene.grab(),
                expected_width=dialog.preview_scene.width(),
                expected_height=dialog.preview_scene.height(),
            )
            fit_pending = bool(
                getattr(dialog, "_content_fit_running", False)
                or dialog._content_fit_timer.isActive()
            )
            catalog_geometry: dict[str, Any] = {
                "scroll_name": "",
                "visible_scroll_names": [],
                "viewport_height": 0,
                "tile_count": 0,
                "visible_tile_count": 0,
                "visible_row_count": 0,
                "vertical_scroll_maximum": -1,
                "vertical_scroll_visible": True,
                "partial_tiles": [],
                "bottom_padding": 0,
                "preview_fixed": False,
                "passed": False,
            }
            if active_scroll is not None:
                viewport = active_scroll.viewport()
                host = active_scroll.widget()
                tiles = (
                    [
                        tile
                        for tile in host.findChildren(QAbstractButton)
                        if bool(tile.property("environmentTile"))
                        and tile.isVisibleTo(host)
                    ]
                    if host is not None else []
                )
                tile_records: list[dict[str, Any]] = []
                visible_row_tops: set[int] = set()
                partial_tiles: list[str] = []
                for tile in tiles:
                    evidence = self._widget_bounds_evidence(tile, viewport)
                    if not bool(evidence.get("intersects", False)):
                        continue
                    bounds = list(evidence.get("bounds", ()) or ())
                    contained = bool(evidence.get("contained", False))
                    tile_name = str(
                        tile.accessibleName()
                        or tile.text()
                        or tile.property("catalogItemId")
                        or "appearance tile"
                    )
                    tile_records.append({
                        "name": tile_name,
                        "bounds": bounds,
                        "contained": contained,
                    })
                    if contained and len(bounds) == 4:
                        visible_row_tops.add(int(bounds[1]))
                    if not contained:
                        partial_tiles.append(tile_name)
                bottom_padding = 0
                if host is not None and tiles:
                    last_bottom = max(
                        int(tile.mapTo(host, tile.rect().topLeft()).y())
                        + int(tile.height())
                        for tile in tiles
                    )
                    bottom_padding = max(0, int(host.height()) - last_bottom)
                visible_scroll_names = [
                    str(
                        scroll.accessibleName()
                        or scroll.objectName()
                        or type(scroll).__name__
                    )
                    for scroll in dialog._catalog_scrolls
                    if scroll.isVisibleTo(dialog)
                ]
                preview_ancestor = dialog.preview_scene.parentWidget()
                preview_inside_scroll = False
                while preview_ancestor is not None and preview_ancestor is not dialog:
                    if isinstance(preview_ancestor, QAbstractScrollArea):
                        preview_inside_scroll = True
                        break
                    preview_ancestor = preview_ancestor.parentWidget()
                preview_fixed = bool(
                    not preview_inside_scroll
                    and viewport_bounds.get("visible", False)
                    and viewport_bounds.get("contained", False)
                )
                catalog_geometry = {
                    "scroll_name": str(
                        active_scroll.accessibleName()
                        or active_scroll.objectName()
                        or type(active_scroll).__name__
                    ),
                    "visible_scroll_names": visible_scroll_names,
                    "viewport_height": int(viewport.height()),
                    "tile_count": len(tiles),
                    "visible_tile_count": len(tile_records),
                    "visible_row_count": len(visible_row_tops),
                    "vertical_scroll_maximum": int(
                        active_scroll.verticalScrollBar().maximum()
                    ),
                    "vertical_scroll_visible": bool(
                        active_scroll.verticalScrollBar().isVisible()
                    ),
                    "tile_records": tile_records,
                    "partial_tiles": partial_tiles,
                    "bottom_padding": bottom_padding,
                    "preview_fixed": preview_fixed,
                    "passed": bool(
                        str(active_scroll.accessibleName())
                        == "Scenery catalogue"
                        and visible_scroll_names == ["Scenery catalogue"]
                        and int(viewport.height()) >= 270
                        and len(tile_records) >= 4
                        and len(visible_row_tops) == 2
                        and not partial_tiles
                        and int(active_scroll.verticalScrollBar().maximum()) == 0
                        and not active_scroll.verticalScrollBar().isVisible()
                        and bottom_padding >= 12
                        and preview_fixed
                    ),
                }
            rendered_state = {
                "scene_bounds": scene_bounds,
                "viewport_bounds": viewport_bounds,
                "scene_metrics": scene_metrics,
                "content_fit_pending": fit_pending,
                "scroll_value": int(
                    active_scroll.verticalScrollBar().value()
                    if active_scroll is not None else 0
                ),
                "passed": bool(
                    dialog.option_tabs.currentIndex() == 0
                    and scene_bounds.get("visible", False)
                    and scene_bounds.get("contained", False)
                    and viewport_bounds.get("visible", False)
                    and viewport_bounds.get("contained", False)
                    and scene_metrics.get("generic_content_passed", False)
                    and not fit_pending
                    and catalog_geometry["passed"]
                ),
            }
            self._capture_annotations[label] = {
                "appearance_fixture": fixture,
                "rendered_state": rendered_state,
                "catalog_geometry": catalog_geometry,
                "collection_loadout_state_matrix": interaction_matrix,
                "passed": bool(
                    rendered_state["passed"]
                    and interaction_matrix.get("passed", False)
                ),
            }
            return bool(
                rendered_state["passed"]
                and interaction_matrix.get("passed", False)
            )

        def dialog_ready() -> None:
            def close_and_restore() -> None:
                self._close_widget(dialog)
                cleanup()

            self._wait_for(
                rendered_state_ready,
                lambda: self._capture_and_advance(
                    label,
                    dialog,
                    capture_delay_ms=420,
                    before_capture=prepare_rendered_state,
                    close_callback=close_and_restore,
                    close_ms=780,
                    next_ms=1200,
                ),
                tries=100,
                failure_label=label,
                failure_reason=(
                    "Collection loadout preview did not become visible and "
                    "painted in the first viewport"
                ),
                on_error=cleanup,
            )

        self._wait_for(
            lambda: bool(dialog is not None and dialog.isVisible()),
            dialog_ready,
            tries=80,
            failure_label=label,
            failure_reason="Collection loadout detail did not become ready",
            on_error=cleanup,
        )

    def _capture_collection_preview_active(self) -> None:
        self._capture_collection_preview("collection-preview-active", False)

    def _capture_collection_preview_restored(self) -> None:
        self._capture_collection_preview("collection-preview-restored", True)

    def _capture_collection_preview(self, label: str, enabled: bool) -> None:
        self._with_dashboard(
            lambda: self._capture_collection_preview_after(label, enabled)
        )

    def _capture_collection_preview_after(self, label: str, enabled: bool) -> None:
        dashboard = getattr(self.app, "dashboard", None)
        opener = getattr(dashboard, "_open_loadout_detail", None)
        if dashboard is None or not callable(opener):
            self._failures.append({
                "label": label,
                "reason": "Collection loadout detail opener was unavailable",
            })
            self._next_after(250)
            return
        opener()
        dialog = getattr(dashboard, "collectible_detail_dialog", None)

        def ready() -> None:
            dialog.option_tabs.setCurrentWidget(dialog.effects_page)
            persisted_draft = tuple(dialog._persisted_draft)
            persisted_weather_visible = bool(persisted_draft[2])
            persisted_scenery_visible = bool(persisted_draft[3])
            expected_weather_visible = bool(enabled)
            expected_scenery_visible = bool(enabled)
            committed_before = {
                "weather": str(self.app.storage.state.selected_weather),
                "scenery": str(self.app.storage.state.selected_background),
                "visibility": deepcopy(
                    self.app.storage.state.environment_visibility
                ),
                "loadout": deepcopy(self.app.storage.state.loadout.to_dict()),
            }
            dirty_preview_created = False
            reset_path_invoked = False

            if label == "collection-preview-restored":
                expected_weather_visible = persisted_weather_visible
                expected_scenery_visible = persisted_scenery_visible
                dialog.show_weather.setChecked(not persisted_weather_visible)
                dialog.show_scenery.setChecked(not persisted_scenery_visible)
                QApplication.processEvents()
                dirty_preview_created = bool(
                    dialog._draft_key() != persisted_draft
                    and dialog.dialog_dirty
                    and str(dialog.property("transactionPresentation") or "")
                    == "preview"
                )
                # Exercise the real Restore saved appearance control path, not
                # a direct toggle assignment that merely resembles its result.
                dialog._reset_preview()
                reset_path_invoked = True
                QApplication.processEvents()
            else:
                dialog.show_weather.setChecked(expected_weather_visible)
                dialog.show_scenery.setChecked(expected_scenery_visible)

            committed_after = {
                "weather": str(self.app.storage.state.selected_weather),
                "scenery": str(self.app.storage.state.selected_background),
                "visibility": deepcopy(
                    self.app.storage.state.environment_visibility
                ),
                "loadout": deepcopy(self.app.storage.state.loadout.to_dict()),
            }
            draft_restored = bool(
                dialog._draft_key() == persisted_draft
                and bool(dialog.show_weather.isChecked()) == persisted_weather_visible
                and bool(dialog.show_scenery.isChecked()) == persisted_scenery_visible
                and str(dialog.property("transactionPresentation") or "")
                == "committed-state"
            )
            committed_state_unchanged = committed_after == committed_before
            preview_feedback = getattr(dialog, "preview_feedback", None)
            if (
                label == "collection-preview-restored"
                and preview_feedback is not None
            ):
                preview_feedback.setProperty(
                    "captureEvidenceKey",
                    "restored-preview-banner",
                )
            preview_feedback_text = str(
                getattr(getattr(preview_feedback, "message", None), "text", lambda: "")()
                if preview_feedback is not None else ""
            ).strip()
            preview_feedback_bounds = self._widget_bounds_evidence(
                preview_feedback,
                dialog.preview_panel,
            )
            restored_preview_visual = {
                "text": preview_feedback_text,
                "semantic_state": str(
                    preview_feedback.property("previewState") or ""
                    if preview_feedback is not None else ""
                ),
                "visible": bool(
                    preview_feedback is not None
                    and preview_feedback.isVisible()
                ),
                "bounds": preview_feedback_bounds.get("bounds", []),
                "contained": bool(preview_feedback_bounds.get("contained", False)),
            }
            restored_preview_visual["passed"] = bool(
                label != "collection-preview-restored"
                or (
                    restored_preview_visual["semantic_state"] == "reset"
                    and restored_preview_visual["visible"]
                    and restored_preview_visual["contained"]
                )
            )
            transition_passed = bool(
                label != "collection-preview-restored"
                or (
                    dirty_preview_created
                    and reset_path_invoked
                    and draft_restored
                    and committed_state_unchanged
                    and restored_preview_visual["passed"]
                )
            )
            self._capture_annotations[label] = {
                "dirty_preview_created": dirty_preview_created,
                "reset_path_invoked": reset_path_invoked,
                "draft_restored": draft_restored,
                "committed_state_unchanged": committed_state_unchanged,
                "persisted_visibility": [
                    persisted_weather_visible,
                    persisted_scenery_visible,
                ],
                "restored_preview_visual": restored_preview_visual,
                "restored_preview_dirty_cleared": bool(
                    not dialog.dialog_dirty
                    and dialog.unsaved.isHidden()
                    and not str(dialog.unsaved.text()).strip()
                ),
                "passed": transition_passed,
            }

            def state_ready() -> bool:
                return bool(
                    dialog.isVisible()
                    and dialog.option_tabs.currentIndex()
                    == dialog.option_tabs.indexOf(dialog.effects_page)
                    and bool(dialog.show_weather.isChecked()) == expected_weather_visible
                    and bool(dialog.show_scenery.isChecked()) == expected_scenery_visible
                )

            self._wait_for(
                state_ready,
                lambda: self._capture_and_advance(
                    label,
                    dialog,
                    capture_delay_ms=420,
                    close_callback=lambda: self._close_widget(dialog),
                    close_ms=780,
                    next_ms=1200,
                ),
                tries=80,
                failure_label=label,
                failure_reason=f"Collection preview {label!r} did not become ready",
            )

        self._wait_for(
            lambda: bool(dialog is not None and dialog.isVisible()),
            ready,
            tries=80,
            failure_label=label,
            failure_reason="Collection loadout detail did not become ready",
        )

    def _capture_nursery_tab(
        self,
        index: int,
        label: str,
        *,
        fixture_setup: Callable[[Any], Callable[[], None]] | None = None,
        ready_audit: Callable[[Any], None] | None = None,
    ) -> None:
        self._with_dashboard(
            lambda: self._capture_nursery_tab_after(
                index,
                label,
                fixture_setup=fixture_setup,
                ready_audit=ready_audit,
            ),
            failure_label=label,
        )

    def _capture_nursery_tab_after(
        self,
        index: int,
        label: str,
        *,
        fixture_setup: Callable[[Any], Callable[[], None]] | None = None,
        ready_audit: Callable[[Any], None] | None = None,
    ) -> None:
        dashboard = getattr(self.app, "dashboard", None)
        open_nursery = getattr(dashboard, "_open_nursery", None)
        if dashboard is None or not callable(open_nursery):
            self._failures.append({
                "label": label,
                "reason": "Nursery opener was unavailable",
            })
            self._next_after(250)
            return
        cleanup: Callable[[], None] = lambda: None
        try:
            if fixture_setup is not None:
                cleanup = fixture_setup(dashboard)
        except Exception as exc:
            cleanup()
            self._failures.append({
                "label": label,
                "reason": (
                    "Nursery fixture setup raised "
                    f"{type(exc).__name__}"
                ),
            })
            self._close_dashboard()
            self._next_after(250)
            return

        def ready() -> None:
            dialog = getattr(dashboard, "nursery_dialog", None)

            if ready_audit is not None:
                ready_audit(dialog)

            QApplication.processEvents()
            active_scroll = (
                dialog.scroll,
                dialog.supplements_scroll,
                dialog.upgrades_scroll,
                dialog.environment_scroll,
            )[index]
            tab_buttons = [
                button
                for button in dialog.catalog_tabs.findChildren(QPushButton)
                if bool(button.property("nurserySegment"))
                and button.isVisibleTo(dialog)
            ]
            tab_buttons.sort(
                key=lambda button: int(button.property("tabIndex") or 0)
            )
            tab_widths = [int(button.width()) for button in tab_buttons]
            tab_bar_bounds = self._widget_bounds_evidence(
                dialog.catalog_tabs.tabBar(),
                dialog,
            )
            scroll_bounds = self._widget_bounds_evidence(
                active_scroll,
                dialog,
            )
            tab_box = list(tab_bar_bounds.get("bounds", ()) or ())
            scroll_box = list(scroll_bounds.get("bounds", ()) or ())
            status_chips = [
                chip
                for chip in dialog.findChildren(QLabel)
                if bool(chip.property("catalogStatusChip"))
                and chip.isVisibleTo(dialog)
            ]
            exact_tabs = [
                "Plants",
                "Fertilizers & boosts",
                "Garden beds",
                "Decorations & scenery",
            ]
            exact_titles = {
                0: "Plants",
                1: "Boost plant growth",
                2: "Garden beds",
                3: "Customize your garden",
            }
            noninteractive_statuses = all(
                chip.property("statusInteractive") is False
                and chip.focusPolicy() == Qt.FocusPolicy.NoFocus
                and chip.testAttribute(
                    Qt.WidgetAttribute.WA_TransparentForMouseEvents
                )
                for chip in status_chips
            )
            shell_contract = {
                "tab_labels": [
                    str(dialog.catalog_tabs.tabText(tab_index))
                    for tab_index in range(dialog.catalog_tabs.count())
                ],
                "tab_rows": int(
                    dialog.catalog_tabs.property("nurseryTabRows") or 0
                ),
                "tab_widths": tab_widths,
                "equal_width_tabs": bool(
                    len(tab_widths) == 4
                    and max(tab_widths, default=0)
                    - min(tab_widths, default=0) <= 1
                ),
                "active_tab_index": int(dialog.catalog_tabs.currentIndex()),
                "active_segment_count": sum(
                    1 for button in tab_buttons if button.isChecked()
                ),
                "page_title": str(dialog.heading.text()).strip(),
                "tab_bar_bounds": tab_bar_bounds,
                "scroll_bounds": scroll_bounds,
                "tab_bar_clear_of_scroll": bool(
                    len(tab_box) == 4
                    and len(scroll_box) == 4
                    and int(tab_box[1]) + int(tab_box[3])
                    <= int(scroll_box[1])
                ),
                "tab_bar_contained": bool(
                    tab_bar_bounds.get("visible", False)
                    and tab_bar_bounds.get("contained", False)
                ),
                "scroll_contained": bool(
                    scroll_bounds.get("visible", False)
                    and scroll_bounds.get("contained", False)
                ),
                "coin_width": int(dialog.coin_resource.width()),
                "coin_visible": bool(dialog.coin_resource.isVisibleTo(dialog)),
                "close_size": [
                    int(dialog.top_close.width()),
                    int(dialog.top_close.height()),
                ],
                "visible_status_chip_count": len(status_chips),
                "status_chips_noninteractive": noninteractive_statuses,
            }
            shell_contract["passed"] = bool(
                shell_contract["tab_labels"] == exact_tabs
                and shell_contract["tab_rows"] == 1
                and shell_contract["equal_width_tabs"]
                and shell_contract["active_tab_index"] == index
                and shell_contract["active_segment_count"] == 1
                and shell_contract["page_title"] == exact_titles[index]
                and shell_contract["tab_bar_clear_of_scroll"]
                and shell_contract["tab_bar_contained"]
                and shell_contract["scroll_contained"]
                and 88 <= shell_contract["coin_width"] <= 104
                and shell_contract["coin_visible"]
                and shell_contract["close_size"] == [32, 32]
                and shell_contract["status_chips_noninteractive"]
            )
            annotation = dict(self._capture_annotations.get(label, {}) or {})
            annotation["nursery_shell_contract"] = shell_contract
            annotation["passed"] = bool(
                annotation.get("passed", True)
                and shell_contract["passed"]
            )
            self._capture_annotations[label] = annotation
            if not shell_contract["passed"]:
                self._failures.append({
                    "label": label,
                    "reason": "Nursery shared shell contract did not pass",
                })

            def close_and_restore() -> None:
                self._close_widget(dialog)
                cleanup()

            self._capture_and_advance(
                label,
                dialog,
                capture_delay_ms=420,
                close_callback=close_and_restore,
                close_ms=780,
                next_ms=1200,
            )

        QTimer.singleShot(
            0,
            lambda: self._wait_for(
                lambda: bool(
                    getattr(dashboard, "nursery_dialog", None)
                    and dashboard.nursery_dialog.isVisible()
                    and dashboard.nursery_dialog.catalog_tabs.count() > index
                    and dashboard.nursery_dialog.catalog_tabs.currentIndex() == index
                ),
                ready,
                tries=80,
                failure_label=label,
                failure_reason=f"Nursery tab {index + 1} did not become ready",
                on_error=cleanup,
            ),
        )
        try:
            open_nursery(index)
        except Exception:
            cleanup()
            raise

    def _prepare_representative_nursery_fixture(
        self,
        label: str,
        dashboard: Any,
    ) -> Callable[[], None]:
        """Expose one useful partial-catalog state without weakening 30/39.

        The representative Collection capture owns the canonical broad state.
        Nursery needs a different single painting: one owned plant, affordable
        catalog context, the next bed, and unequipped environment choices. The
        mutation is fully reversible so later Settings and transaction facts
        continue to use the canonical development projection.
        """

        snapshot = self._capture_fixture_state_snapshot(
            label,
            exact_ledger_restore=True,
        )
        if self._capture_profile != "representative":
            return lambda: self._restore_capture_fixture_state(snapshot)
        try:
            from ..environment import GROWTH_CHARGES

            state = self.app.storage.state
            plants = list(getattr(state, "plants", ()) or ())
            if not plants:
                raise RuntimeError("representative Nursery requires one plant")
            representative = plants[0]
            representative.slot_index = 0
            state.plants = [representative]
            state.unlocked_species = [str(representative.species)]
            state.unlocked_slots = 2
            state.active_plant_id = str(representative.plant_id)
            state.currency_balance = 0

            inventory = dict(getattr(state, "inventory", {}) or {})
            for category, selected in (
                (
                    "garden_features",
                    str(getattr(state.loadout, "garden_feature_id", "") or ""),
                ),
                ("scenery", str(getattr(state.loadout, "scenery_id", "") or "")),
            ):
                inventory[category] = [selected] if selected else []
            state.inventory = inventory

            consumables = dict(getattr(state, "consumables", {}) or {})
            for item_id in (
                "fertilizer_basic",
                "booster_potion",
                *tuple(GROWTH_CHARGES),
            ):
                consumables[item_id] = 0
            state.consumables = consumables
            dashboard.refresh_all()
        except Exception:
            self._restore_capture_fixture_state(snapshot)
            raise
        return lambda: self._restore_capture_fixture_state(snapshot)

    def _prepare_nursery_plants_fixture(
        self,
        label: str,
        dashboard: Any,
        fixture: dict[str, Any],
    ) -> Callable[[], None]:
        """Install the exact complete-species, partial-registry Nursery state."""

        from ..presentation import project_collection
        from .fixtures import representative_collection_inventory_plan

        snapshot = self._capture_fixture_state_snapshot(
            label,
            exact_ledger_restore=True,
        )
        try:
            state = self.app.storage.state
            release_ready = list(self.app.engine.release_ready_species())
            state.unlocked_species = list(release_ready)
            inventory_plan = representative_collection_inventory_plan()
            state.inventory["garden_features"] = list(
                inventory_plan["garden_features"]
            )
            state.inventory["scenery"] = list(inventory_plan["scenery"])
            state.inventory.pop("backgrounds", None)
            state.consumables.update(dict(inventory_plan["consumables"]))

            projection = project_collection(state)
            fixture.update({
                "species_copy": (
                    f"All {projection.species_total} plant species discovered"
                ),
                "projection_species_copy": projection.species_text,
                "collection_entries_copy": projection.collection_entries_text,
                "species_discovered": projection.species_discovered,
                "species_total": projection.species_total,
                "collection_entries_discovered": (
                    projection.collection_entries_discovered
                ),
                "collection_entries_total": projection.collection_entries_total,
                "fixture_state_passed": bool(
                    projection.species_discovered == 10
                    and projection.species_total == 10
                    and projection.collection_entries_text
                    == "30 of 39 collection entries discovered"
                ),
                "reversible": True,
            })
            if not fixture["fixture_state_passed"]:
                raise RuntimeError(
                    "Nursery Plants fixture did not project canonical 10/10 "
                    "species and 30/39 collection counts"
                )
            dashboard.refresh_all()
        except Exception:
            self._restore_capture_fixture_state(snapshot)
            raise
        return lambda: self._restore_capture_fixture_state(snapshot)

    def _prepare_appearance_capture_fixture(
        self,
        label: str,
        dashboard: Any,
        fixture: dict[str, Any] | None = None,
    ) -> Callable[[], None]:
        """Install the same exact, reversible appearance state in both profiles."""

        snapshot = self._capture_fixture_state_snapshot(
            label,
            exact_ledger_restore=True,
        )
        restored = False

        def restore() -> None:
            nonlocal restored
            if restored:
                return
            restored = True
            self._restore_capture_fixture_state(snapshot)

        try:
            state = self.app.storage.state
            state.inventory["garden_features"] = [
                "seedling_sign",
                "watering_station",
            ]
            state.inventory["scenery"] = [
                "default",
                "spring",
                "summer",
                "autumn",
            ]
            state.inventory.pop("backgrounds", None)
            state.displayed_garden_feature = "seedling_sign"
            state.selected_garden_feature = "watering_station"
            state.selected_background = "default"
            state.loadout.visibility = {
                "garden_feature": True,
                "scenery": True,
            }
            schedule = state.daily_loadout
            anki_day = str(state.daily_stats.day)
            schedule.garden_feature_id = "watering_station"
            schedule.garden_bonus_anki_day_id = anki_day
            schedule.garden_bonus_locked_at_ms = 1
            schedule.pending_garden_feature_id = ""
            schedule.queued_for_day = ""
            schedule.queued_scenery_id = ""
            schedule.scheduler_day = anki_day
            schedule.locked_at_ms = 1
            schedule.scenery_id = "default"
            state.currency_balance = 100
            if fixture is not None:
                fixture.update({
                    "fixture_profiles": ["full", "representative"],
                    "reversible": True,
                    "displayed_decoration_id": "seedling_sign",
                    "active_bonus_id": "watering_station",
                    "purchasable_item_id": "wind_chime",
                    "locked_item_id": "firefly_lantern",
                })
            dashboard.refresh_all()
        except Exception:
            restore()
            raise
        return restore

    def _capture_nursery_plants(self) -> None:
        label = "nursery-plants"
        fixture: dict[str, Any] = {}

        def audit(dialog: Any) -> None:
            visible_labels = {
                str(candidate.text()).strip()
                for candidate in dialog.findChildren(QLabel)
                if candidate.isVisibleTo(dialog)
                and str(candidate.text()).strip()
            }
            fixture["species_copy_visible"] = bool(
                "All 10 plant species discovered" in visible_labels
            )
            fixture["collection_entries_copy_visible"] = bool(
                "30 of 39 collection entries discovered" in visible_labels
            )
            fixture["passed"] = bool(
                fixture.get("fixture_state_passed", False)
                and fixture["species_copy_visible"]
                and fixture["collection_entries_copy_visible"]
            )
            self._capture_annotations[label] = fixture

        self._capture_nursery_tab(
            0,
            label,
            fixture_setup=lambda dashboard: (
                self._prepare_nursery_plants_fixture(
                    label,
                    dashboard,
                    fixture,
                )
            ),
            ready_audit=audit,
        )

    def _capture_nursery_fertilizer_booster(self) -> None:
        label = "nursery-fertilizer-booster"
        fixture: dict[str, Any] = {}

        def setup(dashboard: Any) -> Callable[[], None]:
            from ..collectibles import collectible_registry
            from ..environment import GROWTH_CHARGES

            restore = self._prepare_representative_nursery_fixture(
                label,
                dashboard,
            )
            try:
                state = self.app.storage.state
                item = next(
                    definition
                    for definition in collectible_registry()
                    if definition.item_id == "growth_items:fertilizer_basic"
                )
                target = next(
                    (
                        plant
                        for plant in list(getattr(state, "plants", ()) or ())
                        if bool(getattr(plant, "planted", False))
                        and not bool(getattr(plant, "fully_grown", False))
                    ),
                    None,
                )
                if target is None:
                    raise RuntimeError(
                        "Basic Fertilizer capture requires an unfinished planted plant"
                    )
                target.fertilizer = None
                target.fertilizer_history = []
                target.fertilizer_card_batches = []
                target.fertilizer_card_queue = []
                state.active_plant_id = str(target.plant_id)
                for inventory_id in (
                    "fertilizer_premium",
                    *tuple(GROWTH_CHARGES),
                ):
                    state.consumables[inventory_id] = 0
                state.currency_balance = 500
                state.consumables["fertilizer_basic"] = 3
                state.consumables["fertilizer_quality"] = 2
                state.consumables["booster_potion"] = 2
                fixture.update({
                    "item_display_name": str(item.name),
                    "item_id": str(item.source_id),
                    "target_plant_id": str(target.plant_id),
                    "reversible": True,
                })
                dashboard.refresh_all()
            except Exception:
                restore()
                raise
            return restore

        def audit(dialog: Any) -> None:
            scroll = getattr(dialog, "supplements_scroll", None)
            app = QApplication.instance()
            records: dict[str, dict[str, Any]] = {}

            def settle(*, refresh: bool = False) -> None:
                if refresh:
                    dialog.refresh()
                    QCoreApplication.sendPostedEvents(
                        None,
                        QEvent.Type.DeferredDelete,
                    )
                dialog.catalog_tabs.setCurrentIndex(1)
                if app is not None:
                    app.processEvents()
                dialog.repaint()
                if app is not None:
                    app.processEvents()

            def item_card(item_id: str) -> Any | None:
                current_cards = [
                    candidate
                    for candidate in dialog.findChildren(QFrame)
                    if candidate.isVisibleTo(dialog)
                    and (
                        str(candidate.property("catalogItemId") or "")
                        == item_id
                        or (
                            item_id == "booster_potion"
                            and str(getattr(
                                getattr(candidate, "responsive", None),
                                "semantic_id",
                                "",
                            )) == "nursery.booster-potion"
                        )
                    )
                ]
                return current_cards[-1] if current_cards else None

            def card_action(card: Any | None) -> Any | None:
                return next(
                    (
                        button
                        for button in card.findChildren(QAbstractButton)
                        if button.isVisibleTo(card)
                    ),
                    None,
                ) if card is not None else None

            def card_texts(card: Any | None) -> list[str]:
                return [
                    str(candidate.text()).strip()
                    for candidate in card.findChildren(QLabel)
                    if candidate.isVisibleTo(card)
                    and str(candidate.text()).strip()
                ] if card is not None else []

            def painted_card(card: Any | None) -> bool:
                if card is None or scroll is None:
                    return False
                scroll.ensureWidgetVisible(card, 0, 18)
                settle()
                bounds = self._widget_bounds_evidence(
                    card,
                    scroll.viewport(),
                )
                probe = dialog.grab()
                return bool(
                    card.isVisibleTo(dialog)
                    and bounds.get("contained", False)
                    and not probe.isNull()
                )

            settle(refresh=True)
            sufficient_card = item_card("premium")
            sufficient_action = card_action(sufficient_card)
            sufficient_price = next(
                (
                    candidate
                    for candidate in sufficient_card.findChildren(QWidget)
                    if bool(candidate.property("nurseryPrice"))
                ),
                None,
            ) if sufficient_card is not None else None
            records["sufficient-balance"] = {
                "balance": int(self.app.storage.state.currency_balance),
                "balance_copy": str(dialog.coins.text()).strip(),
                "item_id": "premium",
                "price_copy": (
                    str(sufficient_price.accessibleName()).strip()
                    if sufficient_price is not None else
                    ""
                ),
                "action": (
                    _displayed_button_text(sufficient_action)
                    if sufficient_action is not None else
                    ""
                ),
                "action_disposition": (
                    str(sufficient_action.property(
                        "fertilizerActionDisposition"
                    ) or "")
                    if sufficient_action is not None else
                    ""
                ),
                "action_enabled": bool(
                    sufficient_action is not None
                    and sufficient_action.isEnabled()
                ),
                "painted": painted_card(sufficient_card),
            }

            stored_card = item_card("fertilizer_basic")
            stored_action = card_action(stored_card)
            stored_texts = card_texts(stored_card)
            stored_artwork = next(
                (
                    candidate
                    for candidate in stored_card.findChildren(QLabel)
                    if str(candidate.property("itemArtworkRef") or "")
                    == "fertilizer_basic"
                ),
                None,
            ) if stored_card is not None else None
            stored_pixmap = (
                stored_artwork.pixmap()
                if stored_artwork is not None else
                None
            )
            booster_card = item_card("booster_potion")
            booster_action = card_action(booster_card)
            booster_texts = card_texts(booster_card)
            records["stored-multiple"] = {
                "item_id": "fertilizer_basic",
                "item_name": (
                    "Basic Fertilizer"
                    if "Basic Fertilizer" in stored_texts else
                    ""
                ),
                "owned_copy": next(
                    (
                        text for text in stored_texts
                        if text == "Owned 3"
                    ),
                    "",
                ),
                "queued_copy": next(
                    (text for text in stored_texts if text == "Queued 0"),
                    "",
                ),
                "action": (
                    _displayed_button_text(stored_action)
                    if stored_action is not None else
                    ""
                ),
                "action_disposition": (
                    str(stored_action.property(
                        "fertilizerActionDisposition"
                    ) or "")
                    if stored_action is not None else
                    ""
                ),
                "meta_copy": next(
                    (
                        text for text in stored_texts
                        if "Growth per card" in text
                    ),
                    "",
                ),
                "artwork_ref": (
                    str(stored_artwork.property("itemArtworkRef") or "")
                    if stored_artwork is not None else
                    ""
                ),
                "artwork_source_matches": bool(
                    stored_artwork is not None
                    and str(stored_artwork.property("itemArtworkSource") or "")
                    .replace("\\", "/")
                    .endswith(
                        "assets/v6_storybook_gouache/ui/fertilizer_basic.webp"
                    )
                ),
                "artwork_fallback": bool(
                    stored_artwork.property("itemArtworkFallback")
                    if stored_artwork is not None else
                    True
                ),
                "booster_item_id": (
                    "booster_potion" if booster_card is not None else ""
                ),
                "booster_owned_copy": (
                    "Owned 2" if "Owned 2" in booster_texts else ""
                ),
                "booster_action": (
                    _displayed_button_text(booster_action)
                    if booster_action is not None else
                    ""
                ),
                "booster_painted": painted_card(booster_card),
                "painted": bool(
                    painted_card(stored_card)
                    and stored_artwork is not None
                    and stored_artwork.isVisibleTo(stored_card)
                    and stored_pixmap is not None
                    and not stored_pixmap.isNull()
                ),
            }

            target_id = str(fixture.get("target_plant_id", ""))
            basic_ok, basic_message = self.app.engine.use_fertilizer_item(
                target_id,
                tier="basic",
            )
            settle(refresh=True)
            target = self.app.engine.plant_story(target_id)
            active_batches = tuple(
                getattr(target, "fertilizer_card_batches", ()) or ()
            )
            active_card = item_card("fertilizer_basic")
            active_action = card_action(active_card)
            active_texts = card_texts(active_card)
            active_block = next(
                (
                    candidate
                    for candidate in dialog.findChildren(QFrame)
                    if bool(candidate.property("fertilizerStatusBlock"))
                    and bool(candidate.property("nurseryActiveBoost"))
                    and candidate.isVisibleTo(dialog)
                ),
                None,
            )
            active_summary = next(
                (
                    candidate
                    for candidate in active_block.findChildren(QLabel)
                    if bool(candidate.property("fertilizerStatusSummary"))
                ),
                None,
            ) if active_block is not None else None
            active_remaining = next(
                (
                    candidate
                    for candidate in active_block.findChildren(QLabel)
                    if bool(candidate.property("fertilizerRemainingCopy"))
                ),
                None,
            ) if active_block is not None else None
            active_title = next(
                (
                    candidate
                    for candidate in active_block.findChildren(QLabel)
                    if bool(candidate.property("nurseryPlantName"))
                ),
                None,
            ) if active_block is not None else None
            active_artwork = next(
                (
                    candidate
                    for candidate in active_block.findChildren(QLabel)
                    if str(candidate.property("itemArtworkRef") or "")
                    == "fertilizer_basic"
                ),
                None,
            ) if active_block is not None else None
            active_pixmap = (
                active_artwork.pixmap()
                if active_artwork is not None else
                None
            )
            active_painted = painted_card(active_block)
            if scroll is not None:
                scroll.verticalScrollBar().setValue(0)
            settle()
            section_labels = [
                candidate
                for candidate in dialog.supplements_catalog.findChildren(QLabel)
                if candidate.isVisibleTo(dialog)
                and bool(candidate.property("nurserySection"))
            ]
            active_heading = next(
                (
                    candidate
                    for candidate in section_labels
                    if str(candidate.text()).strip() == "Active boost"
                ),
                None,
            )
            inventory_heading = next(
                (
                    candidate
                    for candidate in section_labels
                    if str(candidate.text()).strip() == "Inventory"
                ),
                None,
            )
            shop_heading = next(
                (
                    candidate
                    for candidate in section_labels
                    if str(candidate.text()).strip() == "Shop"
                ),
                None,
            )
            shop_heading_bounds = self._widget_bounds_evidence(
                shop_heading,
                scroll.viewport() if scroll is not None else dialog,
            )
            records["active"] = {
                "engine_tier": str(
                    getattr(
                        active_batches[0] if active_batches else None,
                        "effect_id",
                        "",
                    )
                    or ""
                ).removeprefix("fertilizer_"),
                "item_id": "fertilizer_basic",
                "section_heading": (
                    str(active_heading.text()).strip()
                    if active_heading is not None else ""
                ),
                "item_name": (
                    str(active_title.text()).strip()
                    if active_title is not None else ""
                ),
                "inventory_heading": (
                    str(inventory_heading.text()).strip()
                    if inventory_heading is not None else ""
                ),
                "shop_heading": (
                    str(shop_heading.text()).strip()
                    if shop_heading is not None else ""
                ),
                "shop_heading_contained": bool(
                    shop_heading_bounds.get("visible", False)
                    and shop_heading_bounds.get("contained", False)
                ),
                "owned_copy": next(
                    (
                        text for text in active_texts
                        if text == "Owned 2"
                    ),
                    "",
                ),
                "queued_copy": next(
                    (text for text in active_texts if text == "Queued 0"),
                    "",
                ),
                "action": (
                    _displayed_button_text(active_action)
                    if active_action is not None else
                    ""
                ),
                "action_disposition": (
                    str(active_action.property(
                        "fertilizerActionDisposition"
                    ) or "")
                    if active_action is not None else
                    ""
                ),
                "status_phase": (
                    str(active_block.property("fertilizerPhase") or "")
                    if active_block is not None else
                    ""
                ),
                "status_copy": (
                    str(active_summary.text()).strip()
                    if active_summary is not None else
                    ""
                ),
                "remaining_copy": (
                    str(active_remaining.text()).strip()
                    if active_remaining is not None else
                    ""
                ),
                "artwork_ref": (
                    str(active_artwork.property("itemArtworkRef") or "")
                    if active_artwork is not None else
                    ""
                ),
                "artwork_source_matches": bool(
                    active_artwork is not None
                    and str(active_artwork.property("itemArtworkSource") or "")
                    .replace("\\", "/")
                    .endswith(
                        "assets/v6_storybook_gouache/ui/fertilizer_basic.webp"
                    )
                ),
                "artwork_fallback": bool(
                    active_artwork.property("itemArtworkFallback")
                    if active_artwork is not None else
                    True
                ),
                "artwork_painted": bool(
                    active_artwork is not None
                    and active_artwork.isVisibleTo(active_block)
                    and active_pixmap is not None
                    and not active_pixmap.isNull()
                ),
                "operation_succeeded": bool(basic_ok),
                "operation_message": str(basic_message),
                "painted": bool(
                    active_painted
                    and active_action is not None
                    and active_action.isVisibleTo(active_card)
                ),
            }

            quality_ok, quality_message = self.app.engine.use_fertilizer_item(
                target_id,
                tier="quality",
            )
            settle(refresh=True)
            target = self.app.engine.plant_story(target_id)
            queued_fertilizers = tuple(
                getattr(target, "fertilizer_card_queue", ()) or ()
            )
            queued_card = item_card("fertilizer_quality")
            queued_action = card_action(queued_card)
            queued_texts = card_texts(queued_card)
            final_basic_card = item_card("fertilizer_basic")
            final_basic_action = card_action(final_basic_card)
            final_basic_painted = painted_card(final_basic_card)
            final_quality_painted = painted_card(queued_card)
            records["queued"] = {
                "engine_tiers": [
                    str(getattr(period, "effect_id", "") or "")
                    .removeprefix("fertilizer_")
                    for period in queued_fertilizers
                ],
                "item_id": "fertilizer_quality",
                "owned_copy": next(
                    (
                        text for text in queued_texts
                        if text == "Owned 1"
                    ),
                    "",
                ),
                "queued_copy": next(
                    (text for text in queued_texts if text == "Queued 1"),
                    "",
                ),
                "action": (
                    _displayed_button_text(queued_action)
                    if queued_action is not None else
                    ""
                ),
                "action_disposition": (
                    str(queued_action.property(
                        "fertilizerActionDisposition"
                    ) or "")
                    if queued_action is not None else
                    ""
                ),
                "final_basic_action": (
                    _displayed_button_text(final_basic_action)
                    if final_basic_action is not None else
                    ""
                ),
                "final_basic_action_disposition": (
                    str(final_basic_action.property(
                        "fertilizerActionDisposition"
                    ) or "")
                    if final_basic_action is not None else
                    ""
                ),
                "final_basic_painted": bool(
                    final_basic_painted
                    and final_basic_action is not None
                    and final_basic_action.isVisibleTo(final_basic_card)
                ),
                "final_quality_action": (
                    _displayed_button_text(queued_action)
                    if queued_action is not None else
                    ""
                ),
                "final_quality_action_disposition": (
                    str(queued_action.property(
                        "fertilizerActionDisposition"
                    ) or "")
                    if queued_action is not None else
                    ""
                ),
                "final_quality_painted": bool(
                    final_quality_painted
                    and queued_action is not None
                    and queued_action.isVisibleTo(queued_card)
                ),
                "meta_copy": next(
                    (
                        text for text in queued_texts
                        if "Growth per card" in text
                    ),
                    "",
                ),
                "operation_succeeded": bool(quality_ok),
                "operation_message": str(quality_message),
                "painted": bool(
                    painted_card(queued_card)
                    and queued_action is not None
                    and queued_action.isVisibleTo(queued_card)
                ),
            }
            matrix_issues = nursery_supplement_state_matrix_issue_codes(records)
            state_matrix = {
                "records": records,
                "issues": list(matrix_issues),
                "passed": bool(
                    not matrix_issues
                    and records["active"].get("operation_succeeded", False)
                    and records["queued"].get("operation_succeeded", False)
                ),
            }
            if scroll is not None:
                scroll.verticalScrollBar().setValue(0)
            settle()
            item_id = str(fixture.get("item_id", ""))
            card = item_card(item_id)
            action = card_action(card)
            action_text = (
                _displayed_button_text(action) if action is not None else ""
            )
            state = self.app.storage.state
            owned_count = int(state.consumables.get(item_id, 0) or 0)
            first_fold_geometry: dict[str, Any] = {
                "visible_card_ids": [],
                "partial_card_ids": [],
                "partial_actions": [],
                "bottom_padding": 0,
                "premium_action_text": "",
                "premium_action_contained": False,
                "price_action_same_row": False,
                "passed": False,
            }
            if scroll is not None:
                viewport = scroll.viewport()
                host = scroll.widget()
                cards = (
                    [
                        candidate
                        for candidate in host.findChildren(QFrame)
                        if bool(candidate.property("nurseryCatalogCard"))
                        and candidate.isVisibleTo(host)
                    ]
                    if host is not None else []
                )
                visible_cards: list[dict[str, Any]] = []
                partial_card_ids: list[str] = []
                partial_actions: list[str] = []
                for candidate in cards:
                    candidate_id = str(
                        candidate.property("catalogItemId") or ""
                    )
                    card_bounds = self._widget_bounds_evidence(
                        candidate,
                        viewport,
                    )
                    if not bool(card_bounds.get("intersects", False)):
                        continue
                    card_contained = bool(card_bounds.get("contained", False))
                    visible_cards.append({
                        "item_id": candidate_id,
                        "bounds": list(card_bounds.get("bounds", ()) or ()),
                        "height": int(candidate.height()),
                        "contained": card_contained,
                    })
                    if not card_contained:
                        partial_card_ids.append(candidate_id)
                    for candidate_action in candidate.findChildren(
                        QAbstractButton
                    ):
                        if not candidate_action.isVisibleTo(candidate):
                            continue
                        action_bounds = self._widget_bounds_evidence(
                            candidate_action,
                            viewport,
                        )
                        if (
                            bool(action_bounds.get("intersects", False))
                            and not bool(action_bounds.get("contained", False))
                        ):
                            partial_actions.append(
                                _displayed_button_text(candidate_action)
                                or candidate_id
                            )
                premium_card = next(
                    (
                        candidate
                        for candidate in cards
                        if str(candidate.property("catalogItemId") or "")
                        == "premium"
                    ),
                    None,
                )
                premium_action = next(
                    iter(premium_card.findChildren(QAbstractButton)),
                    None,
                ) if premium_card is not None else None
                premium_action_bounds = self._widget_bounds_evidence(
                    premium_action,
                    premium_card,
                )
                price_action_same_row = False
                if premium_action is not None:
                    action_parent = premium_action.parentWidget()
                    price_widgets = [
                        price_widget
                        for price_widget in premium_card.findChildren(QWidget)
                        if bool(price_widget.property("nurseryPrice"))
                        and price_widget.parentWidget() is action_parent
                        and price_widget.isVisibleTo(premium_card)
                    ] if premium_card is not None else []
                    action_top = int(
                        premium_action.mapTo(
                            premium_card,
                            premium_action.rect().topLeft(),
                        ).y()
                    )
                    action_bottom = action_top + int(premium_action.height())
                    price_action_same_row = any(
                        (
                            lambda label_top, label_bottom: (
                                label_top < action_bottom
                                and action_top < label_bottom
                            )
                        )(
                            int(price_widget.mapTo(
                                premium_card,
                                price_widget.rect().topLeft(),
                            ).y()),
                            int(price_widget.mapTo(
                                premium_card,
                                price_widget.rect().topLeft(),
                            ).y()) + int(price_widget.height()),
                        )
                        for price_widget in price_widgets
                    )
                bottom_padding = 0
                if host is not None and cards:
                    bottom_padding = max(
                        0,
                        int(host.height())
                        - max(
                            int(candidate.mapTo(
                                host,
                                candidate.rect().topLeft(),
                            ).y()) + int(candidate.height())
                            for candidate in cards
                        ),
                    )
                visible_card_ids = [
                    str(row.get("item_id", "")) for row in visible_cards
                ]
                # The initial viewport must end on a complete row; products
                # below that fold remain inspectable in their own card. Do not
                # force Premium Fertilizer to peek into the viewport merely to
                # prove that its price and action share a row.
                expected_first_fold = {
                    "fertilizer_basic",
                    "fertilizer_quality",
                }
                first_fold_geometry = {
                    "scroll_name": str(
                        scroll.accessibleName()
                        or scroll.objectName()
                        or type(scroll).__name__
                    ),
                    "viewport_size": [
                        int(viewport.width()),
                        int(viewport.height()),
                    ],
                    "visible_cards": visible_cards,
                    "visible_card_ids": visible_card_ids,
                    "partial_card_ids": partial_card_ids,
                    "partial_actions": partial_actions,
                    "bottom_padding": bottom_padding,
                    "premium_action_text": (
                        _displayed_button_text(premium_action)
                        if premium_action is not None else ""
                    ),
                    "premium_action_contained": bool(
                        premium_action_bounds.get("visible", False)
                        and premium_action_bounds.get("contained", False)
                    ),
                    "price_action_same_row": price_action_same_row,
                    "passed": bool(
                        str(scroll.accessibleName())
                        == "Fertilizers and boosts catalog"
                        and expected_first_fold.issubset(visible_card_ids)
                        and not partial_card_ids
                        and not partial_actions
                        and all(
                            int(row.get("height", 0)) >= 88
                            for row in visible_cards
                        )
                        and bottom_padding >= 20
                        and premium_action_bounds.get("visible", False)
                        and premium_action_bounds.get("contained", False)
                        and price_action_same_row
                    ),
                }
            passed = bool(
                action is not None
                and action.isVisible()
                and action.isEnabled()
                and owned_count >= 1
                and str(getattr(state, "active_plant_id", "") or "")
                == fixture.get("target_plant_id")
                and state_matrix["passed"]
                and first_fold_geometry["passed"]
            )
            self._capture_annotations[label] = {
                **fixture,
                "action_text": action_text,
                "action_visible": bool(action is not None and action.isVisible()),
                "action_enabled": bool(action is not None and action.isEnabled()),
                "owned_count": owned_count,
                "supplement_state_matrix": state_matrix,
                "first_fold_geometry": first_fold_geometry,
                "passed": passed,
            }

        self._capture_nursery_tab(
            1,
            label,
            fixture_setup=setup,
            ready_audit=audit,
        )

    def _exercise_nursery_bed_incomplete_state(
        self,
        dialog: Any,
        label: str,
    ) -> None:
        """Audit the earned Bed 3 progression painted by Surface 23."""

        def settle() -> None:
            dialog.catalog_tabs.setCurrentIndex(2)
            dialog.upgrades_scroll.verticalScrollBar().setValue(0)
            app = QApplication.instance()
            if app is not None:
                QCoreApplication.sendPostedEvents(
                    None,
                    QEvent.Type.LayoutRequest,
                )
                app.processEvents()
            dialog.repaint()
            if app is not None:
                app.processEvents()

        settle()
        progression = next((
            candidate
            for candidate in dialog.upgrades_catalog.findChildren(QWidget)
            if candidate.property("gardenBedProgression") is True
            and candidate.isVisibleTo(dialog)
        ), None)
        details = next((
            candidate
            for candidate in dialog.upgrades_catalog.findChildren(QFrame)
            if candidate.property("selectedBedDetails") is True
            and candidate.isVisibleTo(dialog)
        ), None)
        labels = details.findChildren(QLabel) if details is not None else ()
        summary = next((
            candidate
            for candidate in dialog.upgrades_catalog.findChildren(QLabel)
            if candidate.isVisibleTo(dialog)
            and str(candidate.text()).strip() == "2 of 6 beds unlocked"
        ), None)
        title = next((
            candidate for candidate in labels
            if candidate.property("gardenBedTitle") is True
        ), None)
        capacity = next((
            candidate for candidate in labels
            if candidate.property("gardenBedCapacity") is True
        ), None)
        price = next((
            candidate for candidate in labels
            if candidate.property("gardenBedPrice") is True
        ), None)
        actions = tuple(
            candidate for candidate in (
                details.findChildren(QAbstractButton)
                if details is not None else ()
            )
            if candidate.isVisibleTo(dialog)
        )
        bed_tiles = sorted(
            (
                candidate
                for candidate in dialog.upgrades_catalog.findChildren(QFrame)
                if candidate.property("spaceBed") is True
                and candidate.isVisibleTo(dialog)
            ),
            key=lambda candidate: int(candidate.property("bedNumber") or 0),
        )
        bed_states = [
            {
                "bed_number": int(tile.property("bedNumber") or 0),
                "state": str(tile.property("spaceState") or ""),
                "chips": [
                    str(chip.text()).strip()
                    for chip in tile.findChildren(QLabel)
                    if bool(chip.property("catalogStatusChip"))
                    and chip.isVisibleTo(dialog)
                ],
            }
            for tile in bed_tiles
        ]
        viewport = dialog.upgrades_scroll.viewport()
        detail_bounds = self._widget_bounds_evidence(details, viewport)
        painted = dialog.upgrades_scroll.viewport().grab()
        evidence = {
            "unlocked_beds": int(
                progression.property("unlockedBedCount")
                if progression is not None else -1
            ),
            "summary": str(summary.text()).strip() if summary is not None else "",
            "bed_states": bed_states,
            "bed_number": int(
                details.property("bedNumber") if details is not None else -1
            ),
            "bed_title": str(title.text()).strip() if title is not None else "",
            "requirement": (
                str(details.property("bedRequirement") or "")
                if details is not None else ""
            ),
            "unlock_policy": str(
                details.property("bedUnlockPolicy")
                if details is not None else ""
            ),
            "resulting_capacity": int(
                details.property("resultingCapacity")
                if details is not None else -1
            ),
            "capacity_copy": (
                str(capacity.text()).strip() if capacity is not None else ""
            ),
            "price_present": bool(price is not None),
            "action_present": bool(actions),
            "painted": bool(painted is not None and not painted.isNull()),
            "contained": bool(detail_bounds.get("contained", False)),
            "detail_bounds": detail_bounds,
        }

        issues = nursery_bed_incomplete_state_issue_codes(evidence)
        evidence["issues"] = list(issues)
        evidence["passed"] = not issues
        annotation = dict(self._capture_annotations.get(label, {}) or {})
        annotation["nursery_bed_incomplete_state"] = evidence
        annotation["passed"] = bool(
            annotation.get("passed", True) and not issues
        )
        self._capture_annotations[label] = annotation
        if issues:
            self._failures.append({
                "label": label,
                "reason": (
                    "Nursery incomplete bed state failed: "
                    + ", ".join(issues)
                ),
            })

    def _capture_nursery_garden_spaces(self) -> None:
        label = "nursery-garden-spaces"

        def setup(dashboard: Any) -> Callable[[], None]:
            restore = self._prepare_representative_nursery_fixture(
                label,
                dashboard,
            )
            try:
                state = self.app.storage.state
                state.unlocked_slots = 2
                state.currency_balance = 0
                dashboard.refresh_all()
            except Exception:
                restore()
                raise
            return restore

        self._capture_nursery_tab(
            2,
            label,
            fixture_setup=setup,
            ready_audit=lambda dialog: (
                self._exercise_nursery_bed_incomplete_state(
                    dialog,
                    label,
                )
            ),
        )

    def _capture_nursery_garden_decorations_scenery(self) -> None:
        label = "nursery-garden-decorations-scenery"
        fixture: dict[str, Any] = {}

        def pixmap_signature(pixmap: Any) -> list[int]:
            image = pixmap.toImage()
            width = max(1, int(image.width()))
            height = max(1, int(image.height()))
            return [
                int(image.pixel(
                    min(width - 1, width * column // 7),
                    min(height - 1, height * row // 5),
                ))
                for row in range(1, 5)
                for column in range(1, 7)
            ]

        def audit(dialog: Any) -> None:
            QApplication.processEvents()
            product_cards = [
                candidate
                for candidate in dialog.environment_catalog.findChildren(QFrame)
                if bool(candidate.property("nurseryCatalogCard"))
                and bool(str(candidate.property("catalogItemId") or ""))
                and str(candidate.property("catalogRole") or "")
                != "active-bonus"
                and candidate.isVisibleTo(dialog)
            ]
            product_cards.sort(
                key=lambda candidate: (
                    int(candidate.mapTo(
                        dialog.environment_catalog,
                        candidate.rect().topLeft(),
                    ).y()),
                    int(candidate.mapTo(
                        dialog.environment_catalog,
                        candidate.rect().topLeft(),
                    ).x()),
                )
            )
            first_product_row: list[Any] = []
            if product_cards:
                first_top = int(product_cards[0].mapTo(
                    dialog.environment_catalog,
                    product_cards[0].rect().topLeft(),
                ).y())
                first_product_row = [
                    candidate
                    for candidate in product_cards
                    if abs(int(candidate.mapTo(
                        dialog.environment_catalog,
                        candidate.rect().topLeft(),
                    ).y()) - first_top) <= 2
                ]
                scroll_bar = dialog.environment_scroll.verticalScrollBar()
                scroll_bar.setValue(max(
                    int(scroll_bar.minimum()),
                    min(
                        int(scroll_bar.maximum()),
                        first_top - 30,
                    ),
                ))
                QApplication.processEvents()
            environment_viewport = dialog.environment_scroll.viewport()
            first_row_geometry = [
                self._widget_bounds_evidence(
                    candidate,
                    environment_viewport,
                )
                for candidate in first_product_row
            ]
            first_product_row_contained = bool(
                first_row_geometry
                and all(
                    record.get("contained", False)
                    for record in first_row_geometry
                )
            )
            preview_names: list[str] = []
            previews: dict[str, list[tuple[int, QLabel, list[int]]]] = {}
            missing_art_previews: list[str] = []
            for card in first_product_row[:2]:
                artwork = next(
                    (
                        candidate
                        for candidate in card.findChildren(QLabel)
                        if bool(candidate.property("nurseryArtwork"))
                        and candidate.isVisibleTo(dialog)
                    ),
                    None,
                )
                if artwork is None:
                    continue
                name = str(artwork.accessibleName() or "").strip()
                if not name:
                    continue
                preview_names.append(name)
                previews.setdefault(name, [])
                pixmap = artwork.pixmap()
                if (
                    pixmap is None
                    or pixmap.isNull()
                    or str(artwork.property("gardenRole") or "") == "missing-art"
                ):
                    missing_art_previews.append(name)
                    continue
                previews[name].append((
                    int(pixmap.width()) * int(pixmap.height()),
                    artwork,
                    pixmap_signature(pixmap),
                ))

            selected_signatures: dict[str, list[int]] = {}
            selected_sizes: dict[str, list[int]] = {}
            for name, matches in previews.items():
                if not matches:
                    continue
                _area, preview, signature = min(matches, key=lambda row: row[0])
                pixmap = preview.pixmap()
                selected_signatures[name] = signature
                selected_sizes[name] = [
                    int(pixmap.width()),
                    int(pixmap.height()),
                ]

            first_signature = (
                selected_signatures.get(preview_names[0])
                if len(preview_names) >= 1 else None
            )
            second_signature = (
                selected_signatures.get(preview_names[1])
                if len(preview_names) >= 2 else None
            )
            distinct = bool(
                first_signature
                and second_signature
                and first_signature != second_signature
            )
            all_cards = {
                str(candidate.property("catalogItemId") or ""): candidate
                for candidate in dialog.environment_catalog.findChildren(QFrame)
                if bool(candidate.property("nurseryCatalogCard"))
                and bool(str(candidate.property("catalogItemId") or ""))
            }
            scroll = dialog.environment_scroll
            viewport = scroll.viewport()

            def paint_widget(widget: Any) -> bool:
                if widget is None:
                    return False
                scroll.ensureWidgetVisible(widget, 0, 24)
                QApplication.processEvents()
                bounds = self._widget_bounds_evidence(widget, viewport)
                painted = dialog.grab()
                return bool(
                    painted is not None
                    and not painted.isNull()
                    and bounds.get("visible", False)
                    and bounds.get("contained", False)
                )

            def visible_copy(widget: Any) -> list[str]:
                if widget is None:
                    return []
                values = [
                    str(candidate.text()).strip()
                    for candidate in widget.findChildren(QLabel)
                    if str(candidate.text()).strip()
                ]
                values.extend(
                    _displayed_button_text(candidate).strip()
                    for candidate in widget.findChildren(QAbstractButton)
                    if _displayed_button_text(candidate).strip()
                )
                return values

            displayed_card = all_cards.get("seedling_sign")
            active_card = all_cards.get("watering_station")
            purchasable_card = all_cards.get("wind_chime")
            locked_card = all_cards.get("firefly_lantern")
            scenery_heading = next((
                candidate
                for candidate in dialog.environment_catalog.findChildren(QLabel)
                if str(candidate.property("semanticId") or "")
                == "nursery.scenery-heading"
            ), None)
            active_bonus_heading = next((
                candidate
                for candidate in dialog.environment_catalog.findChildren(QLabel)
                if str(candidate.property("semanticId") or "")
                == "nursery.active-bonus-heading"
            ), None)

            displayed_copy = visible_copy(displayed_card)
            displayed_bonus_controls = [
                candidate
                for candidate in (
                    displayed_card.findChildren(QAbstractButton)
                    if displayed_card is not None else ()
                )
                if candidate.isVisibleTo(displayed_card)
                and str(candidate.property("catalogActionState") or "")
                == "select-bonus"
            ]
            active_copy = visible_copy(active_card)
            purchasable_copy = visible_copy(purchasable_card)
            locked_copy = visible_copy(locked_card)
            locked_artwork = next((
                candidate
                for candidate in (
                    locked_card.findChildren(QLabel)
                    if locked_card is not None else ()
                )
                if bool(candidate.property("nurseryArtwork"))
            ), None)
            locked_pixmap = (
                locked_artwork.pixmap()
                if locked_artwork is not None else None
            )
            locked_buttons = [
                candidate
                for candidate in (
                    locked_card.findChildren(QAbstractButton)
                    if locked_card is not None else ()
                )
                if candidate.isVisibleTo(dialog)
                and bool(_displayed_button_text(candidate).strip())
            ]
            exact_fixture = {
                **fixture,
                "displayed_decoration": {
                    "item_id": "seedling_sign",
                    "ownership_state": str(
                        displayed_card.property("catalogOwnershipState") or ""
                    ) if displayed_card is not None else "",
                    "display_state": str(
                        displayed_card.property("catalogDisplayState") or ""
                    ) if displayed_card is not None else "",
                    "display_action": (
                        "Displayed" if "Displayed" in displayed_copy else ""
                    ),
                    "bonus_action": (
                        _displayed_button_text(displayed_bonus_controls[0])
                        if displayed_bonus_controls else ""
                    ),
                    "painted": paint_widget(displayed_card),
                },
                "active_bonus": {
                    "item_id": "watering_station",
                    "ownership_state": str(
                        active_card.property("catalogOwnershipState") or ""
                    ) if active_card is not None else "",
                    "bonus_state": str(
                        active_card.property("catalogBonusState") or ""
                    ) if active_card is not None else "",
                    "section_heading": (
                        str(active_bonus_heading.text()).strip()
                        if active_bonus_heading is not None else ""
                    ),
                    "effect_copy": next(
                        (
                            text for text in active_copy
                            if text == (
                                "Earn +1 bonus Growth every 5 cards during "
                                "your first 100 cards each day"
                            )
                        ),
                        "",
                    ),
                    "action": (
                        "Active today"
                        if "Active today" in active_copy else ""
                    ),
                    "painted": paint_widget(active_card),
                },
                "purchasable": {
                    "item_id": "wind_chime",
                    "ownership_state": str(
                        purchasable_card.property("catalogOwnershipState") or ""
                    ) if purchasable_card is not None else "",
                    "price": int(
                        purchasable_card.property("catalogPrice") or 0
                    ) if purchasable_card is not None else 0,
                    "action": "Buy" if "Buy" in purchasable_copy else "",
                    "action_enabled": bool(next((
                        candidate.isEnabled()
                        for candidate in purchasable_card.findChildren(QAbstractButton)
                        if _displayed_button_text(candidate).strip() == "Buy"
                    ), False)) if purchasable_card is not None else False,
                    "painted": paint_widget(purchasable_card),
                },
                "locked": {
                    "item_id": "firefly_lantern",
                    "ownership_state": str(
                        locked_card.property("catalogOwnershipState") or ""
                    ) if locked_card is not None else "",
                    "price": int(
                        locked_card.property("catalogPrice") or 0
                    ) if locked_card is not None else 0,
                    "acquisition_copy": (
                        "How to discover"
                        if "How to discover" in locked_copy else ""
                    ),
                    "interactive_action_present": bool(locked_buttons),
                    "artwork_id": str(
                        locked_artwork.property("catalogArtworkId") or ""
                    ) if locked_artwork is not None else "",
                    "artwork_locked": bool(
                        locked_artwork.property("catalogArtworkLocked")
                    ) if locked_artwork is not None else False,
                    "artwork_resolved": bool(
                        locked_artwork.property("catalogArtworkResolved")
                    ) if locked_artwork is not None else False,
                    "artwork_fallback": bool(
                        locked_artwork.property("catalogArtworkFallback")
                    ) if locked_artwork is not None else True,
                    "generic_placeholder": bool(
                        locked_artwork is None
                        or str(locked_artwork.text()).strip() == "?"
                        or locked_pixmap is None
                        or locked_pixmap.isNull()
                    ),
                    "painted": paint_widget(locked_card),
                },
                "scenery_heading": {
                    "text": str(scenery_heading.text()).strip()
                    if scenery_heading is not None else "",
                    "reachable": bool(scenery_heading is not None),
                    "painted": paint_widget(scenery_heading),
                },
            }
            fixture_issues = nursery_environment_fixture_issue_codes(
                exact_fixture
            )
            scroll.verticalScrollBar().setValue(0)
            QApplication.processEvents()
            passed = bool(
                len(preview_names) == 2
                and first_signature
                and second_signature
                and not missing_art_previews
                and distinct
                and len(first_product_row) == 3
                and first_product_row_contained
                and not fixture_issues
            )
            self._capture_annotations[label] = {
                "preview_names": preview_names,
                "garden_feature_previews_present": bool(
                    len(preview_names) == 2
                    and first_signature
                    and second_signature
                ),
                "missing_art_previews": missing_art_previews,
                "preview_match_counts": {
                    name: len(matches) for name, matches in previews.items()
                },
                "preview_sizes": selected_sizes,
                "preview_signatures_distinct": distinct,
                "first_product_row_count": len(first_product_row),
                "first_product_row_geometry": first_row_geometry,
                "first_product_row_contained": first_product_row_contained,
                "garden_decoration_scenery_fixture": exact_fixture,
                "garden_decoration_scenery_fixture_issues": list(
                    fixture_issues
                ),
                "passed": passed,
            }
            if not passed:
                self._failures.append({
                    "label": label,
                    "reason": (
                        "The first Garden Decoration product row did not expose "
                        "two distinct packaged previews in one complete row"
                    ),
                })

        self._capture_nursery_tab(
            3,
            label,
            fixture_setup=lambda dashboard: (
                self._prepare_appearance_capture_fixture(
                    label,
                    dashboard,
                    fixture,
                )
            ),
            ready_audit=audit,
        )

    def _capture_settings_display(self) -> None:
        self._with_dashboard(self._capture_settings_display_after)

    def _capture_settings_display_after(self) -> None:
        dashboard = getattr(self.app, "dashboard", None)
        if dashboard is None:
            self._next_after(250)
            return
        open_settings = getattr(dashboard, "_open_settings", None)
        if callable(open_settings):
            open_settings()
        self._wait_for(
            lambda: bool(
                self._find_settings_dialog() is not None
                and self._find_settings_dialog().isVisible()
            ),
            self._capture_settings_display_ready,
            tries=80,
            failure_label="settings-display",
            failure_reason="Settings Display tab did not become ready",
        )

    def _capture_settings_display_ready(self) -> None:
        settings_dialog = self._find_settings_dialog()
        if settings_dialog is None:
            self._close_dashboard()
            self._next_after(300)
            return
        self._set_settings_tab(settings_dialog, 0)
        self._capture_and_advance(
            "settings-display",
            settings_dialog,
            capture_delay_ms=450,
            close_callback=lambda: self._close_widget(settings_dialog),
            close_ms=900,
            next_ms=1400,
        )

    def _capture_settings_display_advanced(self) -> None:
        self._with_dashboard(
            self._capture_settings_display_advanced_after,
            failure_label="settings-display-advanced-open",
        )

    def _capture_settings_display_advanced_after(self) -> None:
        dashboard = getattr(self.app, "dashboard", None)
        if dashboard is None:
            self._next_after(250)
            return
        fixture: dict[str, Any] = {}
        cleanup = self._prepare_appearance_capture_fixture(
            "settings-display-advanced-open",
            dashboard,
            fixture,
        )
        self._settings_appearance_fixture = fixture
        self._settings_appearance_fixture_cleanup = cleanup
        open_settings = getattr(dashboard, "_open_settings", None)
        try:
            if callable(open_settings):
                open_settings()
        except Exception:
            cleanup()
            raise
        self._wait_for(
            lambda: bool(
                self._find_settings_dialog() is not None
                and self._find_settings_dialog().isVisible()
            ),
            self._capture_settings_display_advanced_ready,
            tries=80,
            failure_label="settings-display-advanced-open",
            failure_reason="Settings Display Advanced state did not become ready",
            on_error=cleanup,
        )

    def _exercise_settings_appearance_state_matrix(
        self,
        settings_dialog: Any,
    ) -> dict[str, Any]:
        """Paint exact shared Appearance projections without changing the draft."""

        from ..presentation import project_garden_appearance

        behavior = settings_dialog.behavior
        state = self.app.storage.state
        original_visibility = dict(state.loadout.visibility)
        draft_payload_before = deepcopy(behavior.build_theme_payload())
        garden_name_before = str(settings_dialog.garden_name_edit.text())
        draft_dirty_before = bool(settings_dialog._draft_is_dirty())
        records: dict[str, dict[str, Any]] = {}

        try:
            for state_name, enabled in (("off", False), ("on", True)):
                state.loadout.visibility = {
                    "garden_feature": enabled,
                    "scenery": enabled,
                }
                projection = project_garden_appearance(state)
                behavior._refresh_appearance_card()
                QApplication.processEvents()
                painted_rows = [
                    [caption, str(behavior.appearance_values[key].text())]
                    for key, caption in (
                        ("scenery", "Scenery"),
                        ("displayed_decoration", "Decoration"),
                        ("active_bonus", "Garden bonus"),
                        ("visual_effects", "Visual effects"),
                    )
                ]
                appearance_bounds = self._widget_bounds_evidence(
                    behavior.theme_card,
                    settings_dialog.behavior_scroll.viewport(),
                )
                painted = settings_dialog.grab()
                records[state_name] = {
                    "projection_rows": [
                        [caption, value]
                        for caption, value in projection.summary_rows
                    ],
                    "projection_bonus_effect": str(
                        projection.active_bonus_effect or ""
                    ).strip().rstrip("."),
                    "painted_rows": painted_rows,
                    "painted_bonus_effect": str(
                        behavior.bonus_description.text()
                    ).strip(),
                    "painted": bool(
                        painted is not None
                        and not painted.isNull()
                        and appearance_bounds.get("visible", False)
                        and appearance_bounds.get("contained", False)
                    ),
                }
        finally:
            # The capture itself intentionally ends on the canonical On state;
            # the fixture restore after close returns the pre-capture state.
            state.loadout.visibility = {
                "garden_feature": True,
                "scenery": True,
            }
            behavior._refresh_appearance_card()
            QApplication.processEvents()

        evidence = {
            "records": records,
            "final_state": "on",
            "draft_dirty_before": draft_dirty_before,
            "draft_dirty_after": bool(settings_dialog._draft_is_dirty()),
            "draft_payload_unchanged": bool(
                behavior.build_theme_payload() == draft_payload_before
            ),
            "garden_name_draft_unchanged": bool(
                str(settings_dialog.garden_name_edit.text())
                == garden_name_before
            ),
            "reversible": bool(
                getattr(self, "_settings_appearance_fixture", {}).get(
                    "reversible",
                    False,
                )
            ),
            "original_visibility": original_visibility,
        }
        evidence["issues"] = list(
            appearance_state_matrix_issue_codes(evidence)
        )
        evidence["passed"] = not evidence["issues"]
        return evidence

    def _settings_name_preview_absence_evidence(
        self,
        settings_dialog: Any,
    ) -> dict[str, Any]:
        """Prove Settings has one editable name field and no preview echo."""

        name_edit = settings_dialog.garden_name_edit
        draft_name = " ".join(str(name_edit.text()).split())
        normalized_draft = draft_name.casefold()
        labels = list(settings_dialog.findChildren(QLabel))
        preview_attribute = getattr(
            settings_dialog,
            "garden_name_preview",
            None,
        )
        preview_candidates: list[Any] = []
        if preview_attribute is not None:
            preview_candidates.append(preview_attribute)
        for candidate in labels:
            accessible_name = str(candidate.accessibleName() or "").strip()
            object_name = str(candidate.objectName() or "").strip()
            if (
                accessible_name.casefold() == "garden name preview"
                or object_name.casefold() in {
                    "gardennamepreview",
                    "garden_name_preview",
                }
                or candidate.property("gardenNamePreview") is True
            ):
                preview_candidates.append(candidate)
        preview_candidates = list({
            id(candidate): candidate
            for candidate in preview_candidates
        }.values())

        def visible(candidate: Any) -> bool:
            try:
                return bool(candidate.isVisibleTo(settings_dialog))
            except (AttributeError, RuntimeError, TypeError):
                return bool(getattr(candidate, "isVisible", lambda: False)())

        visible_candidates = [
            candidate
            for candidate in preview_candidates
            if visible(candidate)
        ]
        visible_copy = [
            " ".join(str(candidate.text()).split())
            for candidate in visible_candidates
            if callable(getattr(candidate, "text", None))
            and " ".join(str(candidate.text()).split())
        ]

        edit_origin = name_edit.mapTo(settings_dialog, QPoint(0, 0))
        edit_left = int(edit_origin.x())
        edit_right = edit_left + int(name_edit.width())
        edit_bottom = int(edit_origin.y()) + int(name_edit.height())
        draft_echoes: list[dict[str, Any]] = []
        if normalized_draft:
            for candidate in labels:
                if not visible(candidate):
                    continue
                candidate_copy = " ".join(str(candidate.text()).split())
                if candidate_copy.casefold() != normalized_draft:
                    continue
                origin = candidate.mapTo(settings_dialog, QPoint(0, 0))
                bounds = [
                    int(origin.x()),
                    int(origin.y()),
                    int(candidate.width()),
                    int(candidate.height()),
                ]
                horizontal_overlap = bool(
                    bounds[0] < edit_right
                    and bounds[0] + bounds[2] > edit_left
                )
                below_field_gap = bounds[1] - edit_bottom
                if horizontal_overlap and -2 <= below_field_gap <= 64:
                    draft_echoes.append({
                        "text": candidate_copy,
                        "bounds": bounds,
                    })

        evidence = {
            "attribute_present": hasattr(
                settings_dialog,
                "garden_name_preview",
            ),
            "candidate_count": len(preview_candidates),
            "visible_candidate_count": len(visible_candidates),
            "visible_copy": visible_copy,
            "draft_echo_count": len(draft_echoes),
            "draft_echoes": draft_echoes,
        }
        evidence["issues"] = list(
            settings_name_preview_absence_issue_codes(evidence)
        )
        evidence["passed"] = not evidence["issues"]
        return evidence

    def _capture_settings_display_advanced_ready(self) -> None:
        settings_dialog = self._find_settings_dialog()
        if settings_dialog is None:
            cleanup = getattr(
                self,
                "_settings_appearance_fixture_cleanup",
                None,
            )
            if callable(cleanup):
                cleanup()
            self._close_dashboard()
            self._next_after(300)
            return
        self._set_settings_tab(settings_dialog, 0)
        settings_dialog.behavior.advanced_toggle.setChecked(True)
        appearance_matrix = self._exercise_settings_appearance_state_matrix(
            settings_dialog
        )
        name_preview_absence = self._settings_name_preview_absence_evidence(
            settings_dialog
        )

        def display_geometry_ready() -> bool:
            app = QApplication.instance()
            if app is not None:
                QCoreApplication.sendPostedEvents(
                    None,
                    QEvent.Type.LayoutRequest,
                )
                app.processEvents()
            scroll = settings_dialog.behavior_scroll
            # The shared rows are compact enough to keep the expanded canonical
            # state content-fit. Pin the sole emergency scroll owner to the top
            # and reject any setting that would begin behind the fixed tabs.
            if scroll.verticalScrollBar().value() != 0:
                scroll.verticalScrollBar().setValue(0)
            viewport = scroll.viewport()
            behavior = settings_dialog.behavior
            settings_preview_removed = not hasattr(behavior, "preview_panel")
            appearance_bounds = self._widget_bounds_evidence(
                behavior.theme_card,
                viewport,
            )
            advanced_header_bounds = self._widget_bounds_evidence(
                settings_dialog.advanced_header,
                viewport,
            )
            advanced_panel_bounds = self._widget_bounds_evidence(
                behavior.advanced_panel,
                viewport,
            )
            home_setting_bounds = self._widget_bounds_evidence(
                behavior.home_preview_row,
                viewport,
            )
            home_switch_bounds = self._widget_bounds_evidence(
                behavior.show_home_widget,
                viewport,
            )
            appearance_origin = behavior.theme_card.mapTo(
                settings_dialog.behavior_page,
                behavior.theme_card.rect().topLeft(),
            )
            advanced_origin = settings_dialog.advanced_header.mapTo(
                settings_dialog.behavior_page,
                settings_dialog.advanced_header.rect().topLeft(),
            )
            appearance_to_advanced_gap = max(
                0,
                int(advanced_origin.y())
                - (
                    int(appearance_origin.y())
                    + int(behavior.theme_card.height())
                ),
            )
            outer_vertical_range = max(
                0,
                int(scroll.verticalScrollBar().maximum())
                - int(scroll.verticalScrollBar().minimum()),
            )
            outer_vertical_value = int(scroll.verticalScrollBar().value())
            outer_horizontal_range = max(
                0,
                int(scroll.horizontalScrollBar().maximum())
                - int(scroll.horizontalScrollBar().minimum()),
            )
            inner_scroll = behavior.controls_scroll
            inner_vertical_range = max(
                0,
                int(inner_scroll.verticalScrollBar().maximum())
                - int(inner_scroll.verticalScrollBar().minimum()),
            )
            geometry = {
                "outer_scroll_name": str(scroll.accessibleName()),
                "outer_vertical_range": outer_vertical_range,
                "outer_vertical_value": outer_vertical_value,
                "outer_horizontal_range": outer_horizontal_range,
                "inner_vertical_range": inner_vertical_range,
                "settings_preview_removed": settings_preview_removed,
                "appearance_bounds": appearance_bounds,
                "current_scenery": str(behavior.theme_title.text()).strip(),
                "appearance_to_advanced_gap": appearance_to_advanced_gap,
                "advanced_header_bounds": advanced_header_bounds,
                "advanced_panel_bounds": advanced_panel_bounds,
                "home_setting_bounds": home_setting_bounds,
                "home_switch_bounds": home_switch_bounds,
            }
            geometry_signature = (
                outer_vertical_range,
                outer_vertical_value,
                outer_horizontal_range,
                inner_vertical_range,
                settings_preview_removed,
                appearance_to_advanced_gap,
                bool(appearance_bounds.get("contained", False)),
                bool(advanced_header_bounds.get("visible", False)),
                bool(advanced_panel_bounds.get("contained", False)),
                bool(home_switch_bounds.get("contained", False)),
            )
            if geometry_signature != getattr(
                self,
                "_last_settings_display_geometry_signature",
                None,
            ):
                logger.info(
                    "Anki Garden capture Settings Display geometry: %s",
                    geometry,
                )
                self._last_settings_display_geometry_signature = (
                    geometry_signature
                )
            geometry["passed"] = bool(
                str(scroll.accessibleName()) == "Display settings"
                and outer_vertical_range <= 1
                and outer_vertical_value == 0
                and outer_horizontal_range <= 1
                and inner_vertical_range <= 1
                and settings_preview_removed
                and appearance_bounds.get("visible", False)
                and appearance_bounds.get("contained", False)
                and bool(str(behavior.theme_title.text()).strip())
                and 8 <= appearance_to_advanced_gap <= 12
                and advanced_header_bounds.get("visible", False)
                and advanced_header_bounds.get("contained", False)
                and advanced_panel_bounds.get("visible", False)
                and advanced_panel_bounds.get("contained", False)
                and home_setting_bounds.get("visible", False)
                and home_setting_bounds.get("contained", False)
                and home_switch_bounds.get("visible", False)
                and home_switch_bounds.get("contained", False)
            )
            self._capture_annotations["settings-display-advanced-open"] = {
                "display_geometry": geometry,
                "appearance_state_matrix": appearance_matrix,
                "garden_name_preview_absence": name_preview_absence,
                "passed": bool(
                    geometry["passed"]
                    and appearance_matrix.get("passed", False)
                    and name_preview_absence.get("passed", False)
                ),
            }
            return bool(
                geometry["passed"]
                and appearance_matrix.get("passed", False)
                and name_preview_absence.get("passed", False)
            )

        def close_and_restore() -> None:
            self._close_widget(settings_dialog)
            cleanup = getattr(
                self,
                "_settings_appearance_fixture_cleanup",
                None,
            )
            if callable(cleanup):
                cleanup()

        self._wait_for(
            lambda: bool(
                settings_dialog.isVisible()
                and settings_dialog.behavior.advanced_panel.isVisible()
                and settings_dialog.behavior.advanced_toggle.isChecked()
                and display_geometry_ready()
            ),
            lambda: self._capture_and_advance(
                "settings-display-advanced-open",
                settings_dialog,
                capture_delay_ms=500,
                close_callback=close_and_restore,
                close_ms=900,
                next_ms=1400,
            ),
            tries=80,
            failure_label="settings-display-advanced-open",
            failure_reason=(
                "Settings Display Advanced panel did not become visible and "
                "contained"
            ),
            on_error=close_and_restore,
        )

    def _capture_settings_troubleshooting(self) -> None:
        self._with_dashboard(self._capture_settings_troubleshooting_after)

    def _capture_settings_troubleshooting_after(self) -> None:
        dashboard = getattr(self.app, "dashboard", None)
        if dashboard is None:
            self._next_after(250)
            return
        open_settings = getattr(dashboard, "_open_settings", None)
        if callable(open_settings):
            open_settings()
        self._wait_for(
            lambda: bool(
                self._find_settings_dialog() is not None
                and self._find_settings_dialog().isVisible()
            ),
            self._capture_settings_troubleshooting_ready,
            tries=80,
            failure_label="diagnostics-clean",
            failure_reason="Settings Diagnostics tab did not become ready",
        )

    def _capture_settings_troubleshooting_ready(self) -> None:
        settings_dialog = self._find_settings_dialog()
        if settings_dialog is None:
            self._close_dashboard()
            self._next_after(300)
            return
        self._set_settings_tab(settings_dialog, 1)
        self._capture_and_advance(
            "diagnostics-clean",
            settings_dialog,
            capture_delay_ms=500,
            close_callback=lambda: self._close_widget(settings_dialog),
            close_ms=900,
            next_ms=1400,
        )

    def _capture_settings_warning(self) -> None:
        self._with_dashboard(self._capture_settings_warning_after)

    def _capture_settings_warning_after(self) -> None:
        from ..ui.dashboard import (
            _LOGGED_MISSING_ARTWORK,
            _record_missing_artwork,
        )

        _LOGGED_MISSING_ARTWORK.clear()
        for category, key in (
            ("plant", "capture_missing_plant"),
            ("scenery", "capture_missing_scenery"),
            ("garden_feature", "capture_missing_garden_feature"),
        ):
            _record_missing_artwork(
                category=category,
                item_key=key,
                source_path=f"capture fixture: {category} artwork unavailable",
            )
        dashboard = getattr(self.app, "dashboard", None)
        open_settings = getattr(dashboard, "_open_settings", None)
        if callable(open_settings):
            open_settings()
        self._wait_for(
            lambda: bool(
                self._find_settings_dialog() is not None
                and self._find_settings_dialog().isVisible()
            ),
            self._capture_settings_warning_ready,
            tries=80,
            failure_label="diagnostics-warning",
            failure_reason="Diagnostics warning state did not become ready",
        )

    def _capture_settings_warning_ready(self) -> None:
        settings_dialog = self._find_settings_dialog()
        if settings_dialog is None:
            self._next_after(300)
            return
        self._set_settings_tab(settings_dialog, 1)
        refresh = getattr(settings_dialog, "_refresh_debug_report", None)
        if callable(refresh):
            refresh()
        matrix = self._exercise_diagnostics_state_matrix(settings_dialog)
        annotation = self._capture_annotations.setdefault(
            "diagnostics-warning",
            {},
        )
        annotation["diagnostics_state_matrix"] = matrix
        annotation["passed"] = bool(
            annotation.get("passed", True)
            and matrix.get("passed", False)
        )
        self._capture_and_advance(
            "diagnostics-warning",
            settings_dialog,
            capture_delay_ms=500,
            close_callback=lambda: self._close_widget(settings_dialog),
            close_ms=900,
            next_ms=1400,
        )

    def _exercise_diagnostics_state_matrix(
        self,
        dialog: Any,
    ) -> dict[str, Any]:
        """Paint all Surface 26 states, ending on its transient copy toast."""

        from ..presentation import project_diagnostics

        variants: tuple[tuple[str, dict[str, Any]], ...] = (
            ("success", {}),
            ("warning", {"missing_artwork_count": 3}),
            ("failure", {"contract_failure_count": 1}),
            ("checking", {"checking": True}),
            (
                "copy-confirmation",
                {"missing_artwork_count": 3, "copy_confirmed": True},
            ),
        )
        records: dict[str, dict[str, Any]] = {}
        for name, inputs in variants:
            if name != "copy-confirmation":
                dialog.diagnostics_toast.clear()
            dialog._apply_diagnostics_projection(
                project_diagnostics(**inputs)
            )
            if name == "copy-confirmation":
                dialog._copy_debug_report()
            QApplication.processEvents()
            dialog.repaint()
            QApplication.processEvents()
            probe = dialog.grab()
            records[name] = {
                "diagnostic_state": str(
                    dialog.diagnostics_card.property("diagnosticState") or ""
                ),
                "result_state": str(
                    dialog.diagnostics_card.property(
                        "diagnosticResultState"
                    ) or ""
                ),
                "title": str(dialog.troubleshooting_status.text()).strip(),
                "summary": str(dialog.diagnostics_summary.text()).strip(),
                "check_enabled": bool(dialog.refresh_debug.isEnabled()),
                "check_label": str(dialog.refresh_debug.text()).strip(),
                "copy_enabled": bool(dialog.copy_debug.isEnabled()),
                "details_enabled": bool(
                    dialog.report_details_toggle.isEnabled()
                ),
                "copy_confirmation_visible": bool(
                    dialog.diagnostics_copy_confirmation.isVisibleTo(dialog)
                ),
                "copy_confirmation": str(
                    dialog.diagnostics_copy_confirmation.text()
                ).strip(),
                "toast_visible": bool(
                    dialog.diagnostics_toast.isVisibleTo(dialog)
                ),
                "toast_copy": str(
                    dialog.diagnostics_toast.message.text()
                ).strip(),
                "status_lane_visible": bool(
                    dialog.diagnostics_status_lane.isVisibleTo(dialog)
                ),
                "toast_overlaps_warning_card": bool(
                    dialog.diagnostics_toast.isVisibleTo(dialog)
                    and dialog.diagnostics_toast.geometry().translated(
                        dialog.diagnostics_toast.parentWidget().mapTo(
                            dialog,
                            QPoint(0, 0),
                        )
                    ).intersects(
                        dialog.diagnostics_card.geometry().translated(
                            dialog.diagnostics_card.parentWidget().mapTo(
                                dialog,
                                QPoint(0, 0),
                            )
                        )
                    )
                ),
                "checked_timestamp": str(
                    dialog.diagnostics_checked.text()
                ).strip(),
                "painted": bool(
                    dialog.diagnostics_card.isVisibleTo(dialog)
                    and not probe.isNull()
                ),
            }

        visible_scrolls = [
            scroll
            for scroll in dialog.findChildren(QScrollArea)
            if scroll.isVisibleTo(dialog)
        ]
        diagnostics_scroll = dialog.diagnostics_scroll
        chrome = (dialog.header, dialog.tabs, dialog.footer)
        topology = {
            "visible_central_scroll_owners": len(visible_scrolls),
            "diagnostics_scroll_is_owner": (
                len(visible_scrolls) == 1
                and visible_scrolls[0] is diagnostics_scroll
            ),
            "chrome_outside_scroll": all(
                not diagnostics_scroll.isAncestorOf(widget)
                for widget in chrome
            ),
        }
        evidence: dict[str, Any] = {
            "records": records,
            "topology": topology,
        }
        issues = diagnostics_state_matrix_issue_codes(evidence)
        evidence["issues"] = list(issues)
        evidence["passed"] = not issues
        if issues:
            self._failures.append({
                "label": "diagnostics-warning",
                "reason": (
                    "Diagnostics painted state matrix failed: "
                    + ", ".join(issues)
                ),
            })
        return evidence

    def _capture_dashboard_stress(
        self,
        label: str,
        mutate: Callable[[], None] | None = None,
        *,
        delay_ms: int = 480,
        reveal_plant_card: bool = False,
    ) -> None:
        def ready() -> None:
            snapshot = self._capture_fixture_state_snapshot(
                label,
                exact_ledger_restore=True,
            )
            try:
                if mutate is not None:
                    mutate()
                self._refresh_capture_dashboard()
                if reveal_plant_card:
                    self._reveal_capture_plant_card(label)
                toast = getattr(self.app.dashboard, "toast_region", None)
                clear_toast = getattr(toast, "clear", None)
                if callable(clear_toast):
                    clear_toast()
                self._capture_and_advance(
                    label,
                    self.app.dashboard,
                    capture_delay_ms=delay_ms,
                    close_callback=lambda: self._restore_capture_fixture_state(
                        snapshot
                    ),
                    cleanup_predicate=lambda: bool(
                        getattr(snapshot, "capture_restore_complete", False)
                    ),
                    next_ms=980,
                )
            except Exception:
                self._restore_capture_fixture_state(snapshot)
                raise

        self._with_dashboard(ready)

    def _reveal_capture_plant_card(self, label: str) -> None:
        """Prove the selected card is complete inside the direct canvas."""

        dashboard = getattr(self.app, "dashboard", None)
        card = getattr(dashboard, "plant_card", None)
        annotation = self._capture_annotations.setdefault(label, {})
        if dashboard is None or card is None or not card.isVisible():
            annotation.update({
                "plant_card_viewport_bounds": [],
                "plant_card_fully_visible": False,
                "passed": False,
            })
            self._failures.append({
                "label": label,
                "reason": "Selected plant details were unavailable for viewport reveal",
            })
            return
        QApplication.processEvents()
        viewport = dashboard
        origin = card.mapTo(viewport, card.rect().topLeft())
        bounds = [
            int(origin.x()),
            int(origin.y()),
            int(card.width()),
            int(card.height()),
        ]
        contained = bool(
            bounds[0] >= 0
            and bounds[1] >= 0
            and bounds[0] + bounds[2] <= int(viewport.width())
            and bounds[1] + bounds[3] <= int(viewport.height())
        )
        annotation.update({
            "plant_card_viewport_bounds": bounds,
            "plant_card_viewport_size": [
                int(viewport.width()),
                int(viewport.height()),
            ],
            "canvas_direct": True,
            "plant_card_fully_visible": contained,
            "passed": bool(annotation.get("passed", True)) and contained,
        })
        if not contained:
            self._failures.append({
                "label": label,
                "reason": "Selected plant details did not fit the Dashboard capture viewport",
            })

    def _capture_long_garden_name(self) -> None:
        self._capture_dashboard_stress(
            "long-garden-name",
            lambda: setattr(
                self.app.storage.state,
                "garden_name",
                "The Moonlit Conservatory at Willow Ridge"[:40],
            ),
        )

    def _capture_long_plant_name(self) -> None:
        def mutate() -> None:
            plant = self.app.engine.active_plant() or self.app.storage.state.plants[0]
            plant.name = "Bonsai of the Everlasting Twilight Grove"[:40]
            plant.name_customized = True

        self._capture_dashboard_stress("long-plant-name", mutate)

    def _capture_four_digit_coin_balance(self) -> None:
        self._capture_dashboard_stress(
            "four-digit-coin-balance",
            lambda: setattr(self.app.storage.state, "currency_balance", 9_999),
        )

    def _capture_growth_near_stage_completion(self) -> None:
        from ..models.state import GROWTH_THRESHOLDS

        def mutate() -> None:
            plant = self.app.engine.active_plant() or self.app.storage.state.plants[0]
            plant.growth_points = GROWTH_THRESHOLDS[-1] - 25
            self.app.storage.state.active_plant_id = plant.plant_id
            dashboard = self.app.dashboard
            dashboard.scene.keep_card_open(plant.plant_id)
            dashboard._on_scene_selection(plant.plant_id)

        self._capture_dashboard_stress(
            "growth-near-stage-completion",
            mutate,
            delay_ms=560,
        )

    def _ensure_development_stress_state(self) -> bool:
        checkpoint = getattr(self, "_development_stress_checkpoint", None)
        if (
            bool(getattr(self, "_development_stress_ready", False))
            and checkpoint is not None
        ):
            try:
                # Every development-stress face starts from the same exact
                # checkpoint. Earlier long-copy, near-threshold, purchase, or
                # placement mutations must never leak into a later surface.
                has_staged = getattr(
                    self.app.storage,
                    "reward_ledger_has_staged_writes",
                    None,
                )
                if not callable(has_staged) or has_staged():
                    raise RuntimeError(
                        "Canonical development restore requires a clean ledger"
                    )
                # The canonical fixture owns the bounded GardenState payload,
                # while the live ledger owns the current rollback generation.
                # Pair those at restore time: unrelated saves are allowed to
                # advance the generation without making this baseline stale.
                restore_snapshot = self.app.engine._state_snapshot()
                restore_snapshot.clear()
                restore_snapshot.update(deepcopy(checkpoint))
                self.app.engine._restore_state(restore_snapshot)
                restored_state = self.app.storage.state
                restored_state.plants = restore_capture_plant_order(
                    list(restored_state.plants),
                    tuple(
                        getattr(
                            self,
                            "_development_stress_plant_id_order",
                            (),
                        ) or ()
                    ),
                )
                self.app.storage.save()
            except Exception as exc:
                self._failures.append({
                    "label": "development-stress-state",
                    "reason": (
                        "Canonical development checkpoint could not be restored: "
                        f"{type(exc).__name__}"
                    ),
                })
                return False
            self._refresh_capture_dashboard()
            return True
        from ..models.state import (
            CURRENT_CATALOG_SPECIES_ORDER,
            GROWTH_THRESHOLDS,
            MAX_GARDEN_SLOTS,
            OnboardingStep,
        )

        # This is fixture preparation, not a learner action.  Keep the normal
        # development-control receipt intact everywhere else while preventing
        # setup copy from entering the persisted Garden feedback queue used by
        # later release-facing captures.
        ok, message = self.app.engine.development_populate(
            emit_feedback=False,
        )
        if not ok:
            self._failures.append({
                "label": "development-stress-state",
                "reason": str(message),
            })
            return False
        state = self.app.storage.state
        # A resumed disposable profile may still contain a receipt produced by
        # an older capture build.  Remove only development-fixture feedback;
        # product-action and reward events remain untouched.
        state.pending_feedback = [
            event
            for event in list(getattr(state, "pending_feedback", ()) or ())
            if str(getattr(event, "kind", "") or "") != "development"
            and not str(getattr(event, "event_id", "") or "").startswith(
                "development:"
            )
        ]
        catalog_order = tuple(str(species) for species in CURRENT_CATALOG_SPECIES_ORDER)
        release_ready_order = tuple(
            str(species) for species in self.app.engine.release_ready_species()
        )
        declared_order = tuple(DEVELOPMENT_STRESS_SPECIES_ORDER)
        if catalog_order != declared_order or release_ready_order != declared_order:
            self._failures.append({
                "label": "development-stress-state",
                "reason": (
                    "Development capture species order disagreed with the current "
                    "catalog or release-ready asset projection "
                    f"(catalog={catalog_order!r}, release_ready={release_ready_order!r})"
                ),
            })
            return False
        original_plants = list(state.plants)
        original_ids = sorted(
            str(getattr(plant, "plant_id", "") or "")
            for plant in original_plants
        )
        plants = canonicalize_development_stress_plants(
            original_plants,
            catalog_order,
            self.app.engine._generated_name,
        )
        canonical_species = tuple(
            str(getattr(plant, "species", "") or "") for plant in plants
        )
        canonical_ids = [
            str(getattr(plant, "plant_id", "") or "") for plant in plants
        ]
        if (
            len(plants) != len(declared_order)
            or canonical_species != declared_order
            or len(set(canonical_ids)) != len(declared_order)
            or sorted(canonical_ids) != original_ids
        ):
            self._failures.append({
                "label": "development-stress-state",
                "reason": (
                    "Development population did not preserve one canonical "
                    f"instance for all ten species ({canonical_species!r})"
                ),
            })
            return False
        state.plants = plants
        for index, plant in enumerate(plants):
            plant.slot_index = index if index < MAX_GARDEN_SLOTS else None
            plant.growth_points = GROWTH_THRESHOLDS[index % len(GROWTH_THRESHOLDS)]
        state.unlocked_species = list(declared_order)
        state.unlocked_slots = MAX_GARDEN_SLOTS
        state.currency_balance = 9_999
        state.currency_transactions.clear()
        state.active_plant_id = plants[0].plant_id
        state.starter_selection_complete = True
        state.garden_setup_version = 1
        state.onboarding.step = OnboardingStep.DONE
        state.onboarding.pending_species = None
        state.onboarding.starter_plant_id = plants[0].plant_id
        try:
            # development_populate() commits its shuffled seed. Persist the
            # canonical capture ordering and its matching bounded ledgers
            # before later fixtures take rollback checkpoints.
            self.app.storage.save()
        except Exception as exc:
            self._failures.append({
                "label": "development-stress-state",
                "reason": (
                    "Canonical development capture state could not be saved: "
                    f"{type(exc).__name__}"
                ),
            })
            return False
        self._development_stress_ready = True
        self._development_stress_plant_id_order = tuple(canonical_ids)
        self._development_stress_checkpoint = deepcopy(state.to_dict())
        self._refresh_capture_dashboard()
        return True

    def _capture_all_six_beds(self) -> None:
        def mutate() -> None:
            self._ensure_development_stress_state()
            self.app.dashboard.scene.dismiss_selection()

        self._capture_dashboard_stress("all-six-beds-occupied", mutate, delay_ms=620)

    def _capture_all_six_stages(self) -> None:
        self._capture_dashboard_stress(
            "plant-at-every-stage",
            self._ensure_development_stress_state,
            delay_ms=620,
        )

    def _capture_fully_grown_without_fertilize(self) -> None:
        def mutate() -> None:
            if not self._ensure_development_stress_state():
                return
            fully_grown = next(
                (
                    plant for plant in self.app.storage.state.plants
                    if bool(getattr(plant, "fully_grown", False))
                ),
                None,
            )
            dashboard = self.app.dashboard
            if fully_grown is None:
                self._failures.append({
                    "label": "fully-grown-plant-without-fertilize",
                    "reason": "No fully grown plant was available",
                })
                return
            dashboard.scene.keep_card_open(fully_grown.plant_id)
            dashboard._on_scene_selection(fully_grown.plant_id)
            fertilize_visible = bool(dashboard.plant_card.fertilize.isVisible())
            choose_visible = bool(dashboard.plant_card.choose_another.isVisible())
            passed = not fertilize_visible and choose_visible
            self._capture_annotations["fully-grown-plant-without-fertilize"] = {
                "fertilize_visible": fertilize_visible,
                "choose_another_visible": choose_visible,
                "passed": passed,
            }
            if not passed:
                self._failures.append({
                    "label": "fully-grown-plant-without-fertilize",
                    "reason": "Fully grown plant still exposed Fertilize or hid Choose another plant",
                })

        self._capture_dashboard_stress(
            "fully-grown-plant-without-fertilize",
            mutate,
            delay_ms=560,
            reveal_plant_card=True,
        )

    def _capture_popover_slot(self, slot: int) -> None:
        label = f"popover-plot-{slot + 1}"

        def mutate() -> None:
            if not self._ensure_development_stress_state():
                return
            plant = next(
                row for row in self.app.storage.state.plants
                if row.slot_index == slot
            )
            dashboard = self.app.dashboard
            dashboard.scene.keep_card_open(plant.plant_id)
            dashboard._on_scene_selection(plant.plant_id)
            # Opening an in-scene card must remain inside the direct painted
            # canvas. The card is clamped by the scene itself.
            QApplication.processEvents()
            if not bool(dashboard.plant_card.isVisible()):
                self._failures.append({
                    "label": label,
                    "reason": "Selected plant details were not visible for this plot",
                })

        self._capture_dashboard_stress(
            label,
            mutate,
            delay_ms=520,
            reveal_plant_card=False,
        )

    def _capture_move_mixed_destinations(self) -> None:
        def ready() -> None:
            if not self._ensure_development_stress_state():
                self._next_after(200)
                return
            plants = list(self.app.storage.state.plants)
            for plant in plants[:4]:
                plant.slot_index = plants.index(plant)
            for plant in plants[4:]:
                plant.slot_index = None
            active = plants[0]
            self.app.storage.state.active_plant_id = active.plant_id
            dashboard = self.app.dashboard
            dashboard.refresh_all()
            dashboard._begin_move(active.plant_id)
            QApplication.processEvents()
            cleanup_complete = False

            def cleanup() -> None:
                nonlocal cleanup_complete
                dashboard._cancel_move()
                QApplication.processEvents()
                cleanup_complete = True

            self._capture_and_advance(
                "move-occupied-empty-destinations",
                dashboard,
                capture_delay_ms=560,
                close_callback=cleanup,
                cleanup_predicate=lambda: cleanup_complete,
                close_ms=820,
                next_ms=1150,
            )

        self._with_dashboard(ready)

    def _prepare_expiring_fertilizer(self, label: str) -> str:
        from ..models.state import Fertilizer

        plants = list(self.app.storage.state.plants)
        expected_ids = [
            f"dev_{species}" for species in DEVELOPMENT_STRESS_SPECIES_ORDER
        ]
        actual_ids = [
            str(getattr(plant, "plant_id", "") or "") for plant in plants
        ]
        if actual_ids != expected_ids:
            self._failures.append({
                "label": label,
                "reason": (
                    "Expiring Fertilizer requires the current canonical "
                    "development fixture"
                ),
            })
            return ""
        plant = next(
            (
                candidate
                for candidate in plants
                if str(getattr(candidate, "species", "") or "").casefold()
                == "rose"
            ),
            plants[0],
        )
        plant.slot_index = 0
        self.app.storage.state.active_plant_id = plant.plant_id
        now = self.app.engine._now_seconds()
        plant.fertilizer = Fertilizer("basic", 1, now + 45, now)
        self._refresh_capture_dashboard()
        return plant.plant_id

    def _capture_fertilizer_expiring(self) -> None:
        label = "fertilizer-expiring-under-minute"
        cleanup_holder: dict[str, Callable[[], None]] = {
            "callback": lambda: None,
        }

        def registered_cleanup() -> None:
            cleanup_holder["callback"]()

        def ready() -> None:
            if not self._ensure_development_stress_state():
                self._next_after(200)
                return
            snapshot = self._capture_fixture_state_snapshot(label)

            def cleanup() -> None:
                self._restore_capture_fixture_state(snapshot)

            cleanup_holder["callback"] = cleanup
            plant_id = self._prepare_expiring_fertilizer(label)
            dashboard = self.app.dashboard
            if not plant_id:
                cleanup()
                self._next_after(200)
                return

            def dialog_ready() -> None:
                dialog = getattr(dashboard, "fertilizer_dialog", None)

                def close_dialog() -> None:
                    self._close_widget(dialog)
                    cleanup()

                self._capture_and_advance(
                    label,
                    dialog,
                    capture_delay_ms=420,
                    close_callback=close_dialog,
                    close_ms=760,
                    next_ms=1100,
                )

            QTimer.singleShot(
                0,
                lambda: self._wait_for(
                    lambda: bool(
                        getattr(dashboard, "fertilizer_dialog", None)
                        and dashboard.fertilizer_dialog.isVisible()
                    ),
                    dialog_ready,
                    failure_label=label,
                    failure_reason="Expiring Fertilizer dialog did not become ready",
                    on_error=cleanup,
                ),
            )
            dashboard._open_fertilizer_menu(plant_id)

        self._with_dashboard(
            ready,
            failure_label=label,
            on_error=registered_cleanup,
        )

    def _set_nurtured_capture_slot(self, slot: int, label: str) -> bool:
        """Commit a valid nurtured plant in one of the six disposable plots."""

        if not self._ensure_development_stress_state():
            return False
        from ..models.state import CURRENT_CATALOG_SPECIES_ORDER

        state = self.app.storage.state
        catalog_order = {
            species: index
            for index, species in enumerate(CURRENT_CATALOG_SPECIES_ORDER)
        }
        plants = sorted(
            list(state.plants),
            key=lambda item: (
                catalog_order.get(str(getattr(item, "species", "") or ""), 10_000),
                str(getattr(item, "plant_id", "") or ""),
            ),
        )
        # Earlier release faces deliberately exercise an occupied/empty move
        # matrix, long names, large balances, and stage extremes. Re-seat a
        # canonical, deterministic six-plant scene before every marker face so
        # watering position is the only variable under audit.
        state.garden_name = WATERING_CAPTURE_GARDEN_NAME
        state.currency_balance = WATERING_CAPTURE_CURRENCY_BALANCE
        for index, item in enumerate(plants):
            item.slot_index = index if index < 6 else None
            item.name = (
                f"{str(item.species).replace('_', ' ').title()} Plant"
            )[:40]
            item.name_customized = False
            if index < 6:
                item.growth_points = WATERING_CAPTURE_GROWTH_POINTS
                item.fertilizer = None
        plant = plants[slot] if 0 <= int(slot) < min(6, len(plants)) else None
        if plant is None:
            self._failures.append({
                "label": label,
                "reason": f"Plot {slot + 1} did not contain a plant",
            })
            return False
        ok, message = self.app.engine.set_active_plant(plant.plant_id)
        if not ok:
            self._failures.append({"label": label, "reason": str(message)})
            return False
        coordinator = getattr(self.app, "state_events", None)
        notify = getattr(coordinator, "notify", None)
        if callable(notify):
            notify(f"Capture watering can in plot {slot + 1}")
        self._refresh_capture_dashboard()
        return True

    def _capture_watering_can_garden_plot(self, slot: int) -> None:
        label = f"watering-can-garden-plot-{slot + 1}"

        def ready() -> None:
            if not self._set_nurtured_capture_slot(slot, label):
                self._next_after(200)
                return
            dashboard = self.app.dashboard
            dashboard.scene.dismiss_selection()
            dashboard.refresh_all()
            self._capture_and_advance(
                label,
                dashboard,
                capture_delay_ms=620,
                next_ms=1050,
            )

        self._with_dashboard(ready)

    def _capture_watering_can_home_plot(self, slot: int, surface: str) -> None:
        surface_slug = "deck-browser" if surface == "deckBrowser" else "overview"
        label = f"watering-can-{surface_slug}-plot-{slot + 1}"
        if surface not in {"deckBrowser", "overview"}:
            self._failures.append({
                "label": label,
                "reason": f"Unsupported Anki Home surface {surface}",
            })
            self._next_after(200)
            return
        if not self._set_nurtured_capture_slot(slot, label):
            self._next_after(200)
            return
        self._close_top_level_dialogs()
        self._close_dashboard()
        restore_fixture: Callable[[], None] | None = None
        opposite = "overview" if surface == "deckBrowser" else "deckBrowser"
        self._switch_surface(opposite)

        def enter_surface() -> None:
            invalidate = getattr(self.app, "_invalidate_home_cache", None)
            if callable(invalidate):
                invalidate(f"capture transition for {label}")
            self._switch_surface(surface)
            QTimer.singleShot(
                420,
                lambda: self._wait_for_home_surface(
                    surface,
                    label,
                    lambda: self._capture_and_advance(
                        label,
                        mw,
                        capture_delay_ms=650,
                        close_callback=restore_fixture,
                        close_ms=760 if restore_fixture is not None else 0,
                        next_ms=1200,
                    ),
                ),
            )

        def opposite_surface_settled() -> None:
            # ``mw.state`` changes before WebEngine finishes the corresponding
            # navigation. Let that real page load settle before requesting the
            # target state, otherwise repeated Home fixtures can strand the
            # renderer with every subsequent JavaScript callback discarded.
            QTimer.singleShot(420, enter_surface)

        # Consecutive Home fixtures alternate through the opposite Anki state
        # so WebEngine must construct a new source-backed root. A fixed delay
        # alone can race moveToState() under capture load, leaving the old
        # active-slot DOM in place even though the model has advanced. Wait for
        # the state transition, then give the matching WebEngine navigation one
        # bounded settle interval before returning to the requested surface.
        self._wait_for(
            lambda: str(getattr(mw, "state", "")) == opposite,
            opposite_surface_settled,
            tries=80,
            failure_label=label,
            failure_reason=(
                f"Anki Home did not reach the intermediate {opposite} state"
            ),
        )

    def _capture_collection_several(self) -> None:
        label = "collection-several-discovered"
        state = self.app.storage.state
        original_plants = list(state.plants)
        original_unlocked = list(state.unlocked_species)
        original_active = state.active_plant_id
        dashboard = getattr(self.app, "dashboard", None)
        original_filter = str(
            getattr(dashboard, "_collection_filter", "all") or "all"
        )
        restored = False

        def restore() -> None:
            nonlocal restored
            if restored:
                return
            restored = True
            state.plants = original_plants
            state.unlocked_species = original_unlocked
            state.active_plant_id = original_active
            if dashboard is not None:
                dashboard._collection_filter = original_filter
            self._refresh_capture_dashboard()

        if not self._ensure_development_stress_state():
            restore()
            self._next_after(200)
            return

        release_ready = list(self.app.engine.release_ready_species())
        plants_by_species = {
            str(plant.species): plant for plant in original_plants
        }
        discovered_species = [
            species for species in release_ready
            if species in plants_by_species
        ][:4]
        if len(discovered_species) != 4 or len(release_ready) <= 4:
            self._failures.append({
                "label": label,
                "reason": "Several-discovered fixture could not retain four of a larger catalog",
            })
            restore()
            self._next_after(200)
            return
        try:
            state.plants = [plants_by_species[species] for species in discovered_species]
            state.unlocked_species = list(discovered_species)
            state.active_plant_id = state.plants[0].plant_id
            summary = self.app.engine.catalog_summary()
            discovered_count = len(summary.get("owned_species", ()))
            total_count = len(summary.get("release_ready_species", ()))
            passed = discovered_count == 4 and total_count > discovered_count
            self._capture_annotations[label] = {
                "collected_species": list(discovered_species),
                "collected_count": discovered_count,
                "catalog_count": total_count,
                "passed": passed,
            }
            if not passed:
                self._failures.append({
                    "label": label,
                    "reason": (
                        "Several-discovered fixture did not project four discovered "
                        f"species in a larger catalog ({discovered_count}/{total_count})"
                    ),
                })

            self._refresh_capture_dashboard()
            self._capture_collection_filter(
                "all",
                label,
                restore_callback=restore,
            )
        except Exception:
            restore()
            raise

    def _capture_collection_no_matches(self) -> None:
        if not self._ensure_development_stress_state():
            self._next_after(200)
            return
        from ..collectibles import collection_entry_views

        label = "collection-no-filter-matches"
        snapshot = self._capture_fixture_state_snapshot(label)
        state = self.app.storage.state

        def restore() -> None:
            self._restore_capture_fixture_state(snapshot)

        try:
            locked = [
                view for view in collection_entry_views(state) if not view.owned
            ]
            unsupported = [
                view.definition.item_id
                for view in locked
                if view.definition.category != "growth_items"
            ]
            if unsupported:
                self._failures.append({
                    "label": label,
                    "reason": (
                        "No-matches fixture found non-growth collectibles that "
                        "the development stress state did not own: "
                        + ", ".join(unsupported)
                    ),
                })
                restore()
                self._next_after(200)
                return
            for view in locked:
                item_id = str(view.definition.source_id)
                state.consumables[item_id] = max(
                    1,
                    int(state.consumables.get(item_id, 0) or 0),
                )
            remaining = [
                view.definition.item_id
                for view in collection_entry_views(state)
                if not view.owned
            ]
            if remaining:
                self._failures.append({
                    "label": label,
                    "reason": (
                        "No-matches fixture could not derive complete ownership "
                        "from the Collection registry: " + ", ".join(remaining)
                    ),
                })
                restore()
                self._next_after(200)
                return
            self._refresh_capture_dashboard()
            self._capture_collection_filter(
                "not_collected",
                label,
                restore_callback=restore,
            )
        except Exception:
            restore()
            raise

    def _capture_achievement_completed(self) -> None:
        from ..achievements import (
            ACHIEVEMENT_DEFINITIONS,
            AchievementProgressMetric,
        )

        if not self._ensure_development_stress_state():
            self._next_after(200)
            return
        completed_ids = tuple(
            definition.achievement_id
            for definition in ACHIEVEMENT_DEFINITIONS
        )
        def metric_target(metric: AchievementProgressMetric) -> int:
            return max(
                (
                    max(
                        int(definition.progress_target),
                        int(definition.minimum_answers),
                    )
                    for definition in ACHIEVEMENT_DEFINITIONS
                    if definition.progress_metric is metric
                ),
                default=0,
            )

        streak_days = metric_target(AchievementProgressMetric.STREAK_DAYS)
        daily_answers = metric_target(AchievementProgressMetric.DAILY_ANSWERS)
        lifetime_answers = metric_target(
            AchievementProgressMetric.LIFETIME_ANSWERS
        )
        non_again_run = metric_target(
            AchievementProgressMetric.CONSECUTIVE_NON_AGAIN
        )
        snapshot, projections = self._prepare_canonical_achievement_capture_fixture(
            streak_days=streak_days,
            daily_answers=daily_answers,
            lifetime_answers=lifetime_answers,
            non_again_run=non_again_run,
            completed_ids=completed_ids,
        )
        self._capture_annotations["achievement-completed"] = {
            "projection_ids": [item.achievement_id for item in projections],
            "completed_projection_ids": [
                item.achievement_id for item in projections if item.completed
            ],
            "reward_summaries": {
                item.achievement_id: item.reward_summary
                for item in projections
            },
            "canonical_projection_count": len(projections),
            "streak_days": streak_days,
            "daily_answers": daily_answers,
            "lifetime_answers": lifetime_answers,
            "non_again_run": non_again_run,
            "passed": bool(
                len(projections) == len(ACHIEVEMENT_DEFINITIONS)
                and all(item.completed for item in projections)
                and all(bool(item.reward_summary) for item in projections)
            ),
        }
        dashboard = getattr(self.app, "dashboard", None)
        previous_filter = str(
            getattr(dashboard, "_achievement_filter", "all") or "all"
        )
        if dashboard is not None:
            dashboard._achievement_filter = "completed"

        def restore() -> None:
            if dashboard is not None:
                dashboard._achievement_filter = previous_filter
            self._restore_reward_capture_fixture(snapshot)

        self._refresh_capture_dashboard()
        self._capture_progress_page(
            "achievements",
            "achievement-completed",
            restore_callback=restore,
        )

    def _capture_clear_recall_projection(self) -> None:
        from ..achievements import ACHIEVEMENTS_BY_ID
        from ..reward_presentation import achievement_presentation

        if not self._ensure_development_stress_state():
            self._next_after(200)
            return
        definition = ACHIEVEMENTS_BY_ID["retention_90"]
        daily_answers = max(1, int(definition.minimum_answers) * 3 // 5)
        again_answers = max(1, daily_answers // 6)
        snapshot, projections = self._prepare_canonical_achievement_capture_fixture(
            daily_answers=daily_answers,
            again_answers=again_answers,
            non_again_run=max(
                1,
                int(ACHIEVEMENTS_BY_ID["retention_100"].progress_target) // 3,
            ),
        )
        projection = achievement_presentation(
            "retention_90",
            self.app.storage.state,
        )
        if projection is None:
            self._failures.append({
                "label": "clear-recall-canonical-projection",
                "reason": "Clear Recall canonical projection was unavailable",
            })
            self._restore_reward_capture_fixture(snapshot)
            self._next_after(200)
            return
        unlocked_ids = [
            item.achievement_id for item in projections if item.unlocked
        ]
        passed = bool(
            len(projection.condition_lines) >= 1
            and projection.current == daily_answers
            and projection.progress_target == definition.progress_target
            and projection.reward_coins == definition.reward.coins
            and projection.reward_small_growth_charges
            == definition.reward.small_growth_charges
            and projection.reward_standard_growth_charges
            == definition.reward.standard_growth_charges
            and not projection.completed
            and not unlocked_ids
        )
        if not passed:
            self._failures.append({
                "label": "clear-recall-canonical-projection",
                "reason": "Clear Recall did not match its canonical projection",
            })
        self._capture_annotations["clear-recall-canonical-projection"] = {
            "achievement_id": projection.achievement_id,
            "condition_lines": list(projection.condition_lines),
            "value_text": projection.value_text,
            "reward_summary": projection.reward_summary,
            "current": projection.current,
            "target": projection.progress_target,
            "daily_answers": daily_answers,
            "again_answers": again_answers,
            "unlocked_achievement_ids": unlocked_ids,
            "canonical_projection": True,
            "passed": passed,
        }
        dashboard = getattr(self.app, "dashboard", None)
        previous_filter = str(
            getattr(dashboard, "_achievement_filter", "all") or "all"
        )
        if dashboard is not None:
            dashboard._achievement_filter = "in_progress"

        def restore() -> None:
            if dashboard is not None:
                dashboard._achievement_filter = previous_filter
            self._restore_reward_capture_fixture(snapshot)

        self._refresh_capture_dashboard()
        self._capture_progress_page(
            "achievements",
            "clear-recall-canonical-projection",
            restore_callback=restore,
        )

    def _set_streak_capture_state(
        self,
        *,
        days: int,
        reviewed: int,
        last_active_offset: int,
        completed_ids: tuple[str, ...] = (),
    ) -> tuple[dict[str, Any], tuple[Any, ...]]:
        snapshot, projections = self._prepare_canonical_achievement_capture_fixture(
            streak_days=days,
            daily_answers=reviewed,
            completed_ids=completed_ids,
        )
        state = self.app.storage.state
        try:
            current_day = date.fromisoformat(str(state.daily_stats.day)[:10])
        except (TypeError, ValueError):
            current_day = date.today()
            state.daily_stats.day = current_day.isoformat()
        state.last_active_day = (current_day + timedelta(days=last_active_offset)).isoformat()
        if reviewed > 0:
            self._append_canonical_streak_reward_receipts(streak_days=days)
        self._refresh_capture_dashboard()
        return snapshot, projections

    def _capture_streak_at_risk(self) -> None:
        from ..achievements import ACHIEVEMENTS_BY_ID

        definition = ACHIEVEMENTS_BY_ID["streak_7"]
        streak_days = int(definition.progress_target)
        snapshot, _projections = self._set_streak_capture_state(
            days=streak_days,
            reviewed=0,
            last_active_offset=-1,
            completed_ids=(definition.achievement_id,),
        )
        self._capture_annotations["streak-at-risk"] = {
            "achievement_id": definition.achievement_id,
            "streak_days": streak_days,
            "daily_answers": 0,
            "passed": bool(
                self.app.storage.state.streak_days == streak_days
                and self.app.storage.state.daily_stats.reviewed == 0
            ),
        }
        self._capture_metric(
            "streak",
            "streak-at-risk",
            restore_callback=lambda: self._restore_reward_capture_fixture(snapshot),
        )

    def _capture_streak_missed_day(self) -> None:
        from ..achievements import ACHIEVEMENTS_BY_ID
        from ..ui.state_contracts import StreakPresentationState, streak_presentation

        previous_days = max(
            1,
            int(ACHIEVEMENTS_BY_ID["streak_7"].progress_target) // 2,
        )
        snapshot, _projections = self._set_streak_capture_state(
            days=previous_days,
            reviewed=0,
            last_active_offset=-2,
        )
        state = self.app.storage.state
        presentation = streak_presentation(
            state.streak_days,
            state.last_active_day,
            state.daily_stats.reviewed,
            today=date.fromisoformat(str(state.daily_stats.day)[:10]),
        )
        if not (
            presentation.state == StreakPresentationState.ENDED
            and presentation.current_days == 0
            and presentation.previous_days == previous_days
        ):
            self._failures.append({
                "label": "streak-missed-day",
                "reason": "Missed-day fixture did not project an ended 0-day streak with its previous context",
            })
        from ..reward_presentation import recurring_reward_presentations

        weekly_reward = next(
            rule
            for rule in recurring_reward_presentations(
                state,
                self.app.engine,
                current_streak_days=presentation.current_days,
            )
            if rule.rule_id == "weekly_streak"
        )
        self._capture_annotations["streak-missed-day"] = {
            "previous_streak_days": previous_days,
            "daily_answers": 0,
            "presentation_state": presentation.state.value,
            "projected_streak_days": presentation.current_days,
            "weekly_reward_status": weekly_reward.status,
            "passed": bool(
                presentation.state == StreakPresentationState.ENDED
                and presentation.current_days == 0
                and presentation.previous_days == previous_days
            ),
        }
        self._capture_metric(
            "streak",
            "streak-missed-day",
            restore_callback=lambda: self._restore_reward_capture_fixture(snapshot),
        )

    def _capture_streak_achievement_states(self) -> None:
        from ..achievements import ACHIEVEMENTS_BY_ID
        from ..models.state import STREAK_BONUS_TIERS
        from ..reward_presentation import recurring_reward_presentations

        label = "streak-achievement-earned-next"
        completed_definition = ACHIEVEMENTS_BY_ID["streak_7"]
        next_definition = ACHIEVEMENTS_BY_ID["streak_30"]
        current_days = min(
            int(next_definition.progress_target) - 1,
            int(completed_definition.progress_target) * 2,
        )
        daily_answers = max(1, current_days - 2)
        snapshot, projections = self._set_streak_capture_state(
            days=current_days,
            reviewed=daily_answers,
            last_active_offset=0,
            completed_ids=("streak_7",),
        )
        completed = next(
            item for item in projections if item.achievement_id == "streak_7"
        )
        next_achievement = next(
            item for item in projections if item.achievement_id == "streak_30"
        )
        next_bonus_day = next(
            day for day, _percent in STREAK_BONUS_TIERS if day > current_days
        )
        next_bonus_percent = next(
            percent
            for day, percent in STREAK_BONUS_TIERS
            if day == next_bonus_day
        )
        reward_rules = {
            rule.rule_id: rule
            for rule in recurring_reward_presentations(
                self.app.storage.state,
                self.app.engine,
            )
        }
        self._capture_annotations[label] = {
            "current_streak_days": current_days,
            "daily_answers": daily_answers,
            "completed_achievement_id": completed.achievement_id,
            "completed_achievement_name": completed.name,
            "completed_achievement_reward": completed.reward_summary,
            "next_achievement_id": next_achievement.achievement_id,
            "next_achievement_name": next_achievement.name,
            "next_achievement_value": next_achievement.value_text,
            "next_growth_bonus_days": next_bonus_day,
            "next_growth_bonus_percent": next_bonus_percent,
            "days_until_next_growth_bonus": next_bonus_day - current_days,
            "daily_reward_earned": reward_rules["daily_activity"].awarded_today,
            "weekly_reward_earned": reward_rules["weekly_streak"].awarded_today,
            "canonical_projection": True,
            "passed": bool(
                completed.completed
                and completed.reward_coins
                == completed_definition.reward.coins
                and completed.reward_small_growth_charges
                == completed_definition.reward.small_growth_charges
                and completed.reward_standard_growth_charges
                == completed_definition.reward.standard_growth_charges
                and not next_achievement.completed
                and next_achievement.current == current_days
                and next_achievement.progress_target
                == next_definition.progress_target
                and reward_rules["daily_activity"].awarded_today
                and reward_rules["weekly_streak"].awarded_today
            ),
        }

        restored = False

        def restore_once() -> None:
            nonlocal restored
            if restored:
                return
            restored = True
            self._restore_reward_capture_fixture(snapshot)

        self._with_dashboard(
            lambda: self._capture_metric(
                "streak",
                label,
                restore_callback=restore_once,
            ),
            failure_label=label,
            on_error=restore_once,
        )

    def _capture_nursery_owned_item(self) -> None:
        label = "nursery-item-owned"
        fixture: dict[str, str] = {}

        def setup(_dashboard: Any) -> Callable[[], None]:
            if not self._ensure_development_stress_state():
                raise RuntimeError("development stress state was unavailable")
            snapshot = self._capture_fixture_state_snapshot(label)
            state = self.app.storage.state
            state.plants = list(state.plants[:6])
            state.unlocked_species = [
                str(plant.species) for plant in state.plants
            ]
            state.active_plant_id = state.plants[0].plant_id
            state.onboarding.starter_plant_id = state.active_plant_id
            # The active plant lives in the dedicated "Currently growing"
            # strip. Target another owned plant so this fixture visibly proves
            # the reusable owned catalog-card state.
            owned_catalog_plant = state.plants[1]
            fixture["plant_id"] = str(owned_catalog_plant.plant_id)
            fixture["plant_name"] = str(owned_catalog_plant.name)
            self._refresh_capture_dashboard()
            return lambda: self._restore_capture_fixture_state(snapshot)

        def reveal_owned_item(dialog: Any) -> None:
            target_id = fixture.get("plant_id", "")
            target_name = fixture.get("plant_name", "")
            cards = dialog.scroll.findChildren(QFrame)
            card = next(
                (
                    candidate for candidate in cards
                    if str(candidate.property("catalogItemId") or "") == target_id
                ),
                None,
            )
            if card is not None:
                card.setProperty("captureEvidenceKey", "owned-item-card")
                dialog.scroll.ensureWidgetVisible(card, 0, 24)
            QApplication.processEvents()
            labels = card.findChildren(QLabel) if card is not None else []
            buttons = (
                card.findChildren(QAbstractButton) if card is not None else []
            )
            title_label = next(
                (
                    item for item in labels
                    if bool(item.property("nurseryPlantName"))
                    and str(item.text()).strip().startswith(f"{target_name} ·")
                ),
                None,
            )
            action = next(
                (
                    button for button in buttons
                    if _displayed_button_text(button)
                    in {"Move to storage", "Place in garden"}
                ),
                None,
            )
            viewport = dialog.scroll.viewport()
            card_bounds = self._widget_bounds_evidence(card, viewport)
            title_bounds = self._widget_bounds_evidence(title_label, viewport)
            action_bounds = self._widget_bounds_evidence(action, viewport)
            visual = {
                "item_id": target_id,
                "item_name": target_name,
                "action": (
                    _displayed_button_text(action) if action is not None else ""
                ),
                "card": card_bounds,
                "title": title_bounds,
                "action_bounds": action_bounds,
            }
            visual["passed"] = bool(
                target_id
                and target_name
                and str(getattr(title_label, "text", lambda: "")()).startswith(
                    f"{target_name} ·"
                )
                and visual["action"]
                in {"Move to storage", "Place in garden"}
                and all(
                    bool(evidence.get("contained", False))
                    for evidence in (
                        card_bounds,
                        title_bounds,
                        action_bounds,
                    )
                )
            )
            self._capture_annotations[label] = {
                "owned_item_visual": visual,
                "passed": bool(visual["passed"]),
            }

        self._capture_nursery_tab(
            0,
            label,
            fixture_setup=setup,
            ready_audit=reveal_owned_item,
        )

    def _capture_custom_nursery(
        self,
        index: int,
        label: str,
        on_ready: Callable[[Any], None],
        *,
        on_error: Callable[[], None] | None = None,
    ) -> None:
        def dashboard_ready() -> None:
            dashboard = self.app.dashboard

            def dialog_ready() -> None:
                dialog = dashboard.nursery_dialog
                on_ready(dialog)

            QTimer.singleShot(
                0,
                lambda: self._wait_for(
                    lambda: bool(
                        getattr(dashboard, "nursery_dialog", None)
                        and dashboard.nursery_dialog.isVisible()
                        and dashboard.nursery_dialog.catalog_tabs.currentIndex() == index
                    ),
                    dialog_ready,
                    failure_label=label,
                    failure_reason=f"Nursery stress state {label!r} did not become ready",
                    on_error=on_error,
                ),
            )
            dashboard._open_nursery(index)

        self._with_dashboard(
            dashboard_ready,
            failure_label=label,
            on_error=on_error,
        )

    def _capture_nursery_locked_item(self) -> None:
        label = "nursery-item-locked"
        snapshot = self._capture_fixture_state_snapshot(label)

        def cleanup() -> None:
            self._restore_capture_fixture_state(snapshot)

        self.app.storage.state.currency_balance = 0
        for key in list(self.app.storage.state.consumables):
            self.app.storage.state.consumables[key] = 0

        def ready(dialog: Any) -> None:
            growth_heading = next(
                (
                    candidate
                    for candidate in dialog.supplements_catalog.findChildren(QLabel)
                    if str(candidate.property("semanticId") or "")
                    == "nursery.growth-charges"
                ),
                None,
            )
            target_card = next(
                (
                    card
                    for card in dialog.supplements_catalog.findChildren(QFrame)
                    if str(card.property("responsiveRegion") or "").startswith(
                        "nursery."
                    )
                    and bool(card.property("unaffordable"))
                    and str(card.property("catalogItemId") or "").startswith(
                        "growth_charge_"
                    )
                ),
                None,
            )
            if target_card is not None:
                dialog.supplements_scroll.ensureWidgetVisible(
                    target_card,
                    0,
                    24,
                )

            def align_and_audit() -> bool:
                dialog.supplements_layout.activate()
                QCoreApplication.sendPostedEvents(
                    None,
                    QEvent.Type.LayoutRequest,
                )
                QApplication.processEvents()
                viewport = dialog.supplements_scroll.viewport()
                card_bounds = self._widget_bounds_evidence(target_card, viewport)
                heading_bounds = self._widget_bounds_evidence(
                    growth_heading,
                    viewport,
                )
                action = (
                    next(
                        iter(target_card.findChildren(QAbstractButton)),
                        None,
                    )
                    if target_card is not None else None
                )
                action_bounds = self._widget_bounds_evidence(action, viewport)
                geometry = {
                    "interaction": "ensureWidgetVisible",
                    "target_item_id": str(
                        target_card.property("catalogItemId") or ""
                    ) if target_card is not None else "",
                    "target_semantic_id": str(
                        target_card.property("responsiveRegion") or ""
                    ) if target_card is not None else "",
                    "heading": heading_bounds,
                    "card": card_bounds,
                    "action": action_bounds,
                    "action_disabled": bool(
                        action is not None and not action.isEnabled()
                    ),
                    "unaffordable": bool(
                        target_card is not None
                        and target_card.property("unaffordable")
                    ),
                }
                geometry["passed"] = bool(
                    geometry["target_item_id"]
                    and geometry["target_semantic_id"]
                    and card_bounds.get("visible", False)
                    and card_bounds.get("contained", False)
                    and action_bounds.get("visible", False)
                    and action_bounds.get("contained", False)
                    and geometry["action_disabled"]
                    and geometry["unaffordable"]
                )
                self._capture_annotations[label] = {
                    "locked_catalog_geometry": geometry,
                    "passed": bool(geometry["passed"]),
                }
                return bool(geometry["passed"])

            def close_dialog() -> None:
                self._close_widget(dialog)
                cleanup()

            self._wait_for(
                align_and_audit,
                lambda: self._capture_and_advance(
                    label,
                    dialog,
                    capture_delay_ms=520,
                    before_capture=align_and_audit,
                    close_callback=close_dialog,
                    close_ms=850,
                    next_ms=1200,
                ),
                tries=80,
                failure_label=label,
                failure_reason=(
                    "Locked Nursery item did not settle through normal scrolling"
                ),
                on_error=close_dialog,
            )

        try:
            self._capture_custom_nursery(
                1,
                label,
                ready,
                on_error=cleanup,
            )
        except Exception:
            cleanup()
            raise

    def _capture_nursery_purchase_success(self) -> None:
        from ..environment import GARDEN_FEATURE_CATALOG, SCENERY_CATALOG
        from ..purchases import PurchaseKind, PurchaseRequest, purchase_presentation

        label = "nursery-purchase-success"
        snapshot = self._capture_fixture_state_snapshot(
            label,
            exact_ledger_restore=True,
        )

        def cleanup() -> None:
            self._restore_capture_fixture_state(snapshot)

        state = self.app.storage.state
        state.currency_balance = 100_000
        state.currency_transactions.clear()
        state.completed_purchase_requests.clear()
        item = next(
            entry
            for entry in [
                *GARDEN_FEATURE_CATALOG.values(),
                *SCENERY_CATALOG.values(),
            ]
            if entry.acquisition == "purchase"
        )
        inventory_key = (
            "garden_features" if item.kind == "garden_feature" else "scenery"
        )
        state.inventory[inventory_key] = [
            key for key in state.inventory.get(inventory_key, [])
            if key != item.item_id
        ]
        if item.kind == "scenery":
            if state.selected_background == item.item_id:
                state.selected_background = "default"
        elif state.selected_garden_feature == item.item_id:
            state.selected_garden_feature = "seedling_sign"

        def ready(dialog: Any) -> None:
            purchase_kind = PurchaseKind(item.kind)
            quote = self.app.engine.quote_purchase(purchase_kind, item.item_id)
            outcome = self.app.engine.confirm_purchase(
                PurchaseRequest.from_quote(quote)
            )
            dialog.refresh()
            dialog.catalog_tabs.setCurrentIndex(3)
            if outcome.success:
                dialog._show_purchase_receipt(
                    outcome,
                    purchase_presentation(quote, ignore_status=True),
                )
            if not self.app.engine.owns_environment(item.kind, item.item_id):
                self._failures.append({
                    "label": label,
                    "reason": f"Purchase fixture did not own {item.name} after the transaction",
                })

            def close_dialog() -> None:
                self._close_widget(dialog)
                cleanup()

            self._capture_and_advance(
                label,
                dialog,
                capture_delay_ms=520,
                close_callback=close_dialog,
                close_ms=900,
                next_ms=1250,
            )

        try:
            self._capture_custom_nursery(
                3,
                label,
                ready,
                on_error=cleanup,
            )
        except Exception:
            cleanup()
            raise

    def _capture_nursery_final_row(self) -> None:
        label = "nursery-final-row-above-footer"
        if not self._ensure_development_stress_state():
            self._next_after(200)
            return

        def ready(dialog: Any) -> None:
            scrollbar = dialog.scroll.verticalScrollBar()
            scrollbar.setValue(scrollbar.maximum())

            def capture_ready() -> None:
                # Catalog rows can finish their deferred geometry after the
                # dialog first becomes visible, which can increase the range
                # after the initial scroll. Re-anchor to the settled edge
                # immediately before the reachability audit.
                scrollbar.setValue(scrollbar.maximum())
                QApplication.processEvents()
                scrollbar.setValue(scrollbar.maximum())
                self._audit_nursery_action_above_footer(
                    dialog,
                    dialog.scroll,
                    label,
                    row="last",
                )
                self._capture_and_advance(
                    label,
                    dialog,
                    capture_delay_ms=420,
                    close_callback=lambda: self._close_widget(dialog),
                    close_ms=780,
                    next_ms=1200,
                )

            QTimer.singleShot(140, capture_ready)

        self._capture_custom_nursery(0, label, ready)

    def _capture_missing_artwork_fallback(self) -> None:
        from ..environment import (
            GARDEN_FEATURE_CATALOG,
            GROWTH_CHARGES,
            SCENERY_CATALOG,
        )
        from ..purchases import PurchaseKind
        from ..ui.dashboard import (
            _LOGGED_MISSING_ARTWORK,
            _asset_preview_label,
            _item_preview_label,
        )

        label = "missing-artwork-graphical-fallback"
        weather_item = GARDEN_FEATURE_CATALOG.get("seedling_sign")
        scenery_item = SCENERY_CATALOG.get("spring")
        growth_charge = GROWTH_CHARGES.get("growth_charge_small")
        if weather_item is None or scenery_item is None or growth_charge is None:
            self._failures.append({
                "label": label,
                "reason": "The complete missing-artwork catalog matrix was unavailable",
            })
            self._next_after(200)
            return

        def ready(dialog: Any) -> None:
            engine = self.app.engine
            resolver_names = (
                "resolve_garden_feature_preview_asset",
                "resolve_scenery_preview_asset",
                "resolve_plant_asset",
                "resolve_plant_image",
                "resolve_item_asset",
            )
            original_resolvers = {
                name: getattr(engine, name, None) for name in resolver_names
            }
            if not all(callable(original_resolvers[name]) for name in resolver_names):
                self._failures.append({
                    "label": label,
                    "reason": "One or more artwork resolvers were unavailable",
                })
                self._close_widget(dialog)
                self._next_after(200)
                return

            restored = False

            class MissingCaptureAsset:
                def __init__(self, path: str) -> None:
                    self.path = path
                    self.placement: dict[str, Any] = {}

            missing_paths = {
                "plant": "/capture-missing/plant-bonsai-seed.webp",
                "fertilizer": "/capture-missing/fertilizer-basic.webp",
                "growth-charge": "/capture-missing/growth-charge-small.webp",
                "weather": "/capture-missing/garden-decoration-wind-chime.webp",
                "scenery": "/capture-missing/scenery-spring.webp",
            }

            def restore_resolver() -> None:
                nonlocal restored
                if restored:
                    return
                restored = True
                for name, resolver in original_resolvers.items():
                    setattr(engine, name, resolver)

            try:
                original_scenery_resolver = original_resolvers[
                    "resolve_scenery_preview_asset"
                ]
                setattr(
                    engine,
                    "resolve_garden_feature_preview_asset",
                    lambda _item_id: MissingCaptureAsset(missing_paths["weather"]),
                )

                def scenery_resolver(item_id: str) -> Any:
                    if str(item_id) == scenery_item.item_id:
                        return MissingCaptureAsset(missing_paths["scenery"])
                    return original_scenery_resolver(item_id)

                setattr(engine, "resolve_scenery_preview_asset", scenery_resolver)
                setattr(
                    engine,
                    "resolve_plant_asset",
                    lambda _species, _stage: MissingCaptureAsset(
                        missing_paths["plant"]
                    ),
                )
                setattr(
                    engine,
                    "resolve_plant_image",
                    lambda _species, _stage: missing_paths["plant"],
                )

                def item_resolver(item_key: str) -> MissingCaptureAsset:
                    path_key = (
                        "fertilizer"
                        if "fertilizer" in str(item_key)
                        else "growth-charge"
                    )
                    return MissingCaptureAsset(missing_paths[path_key])

                setattr(engine, "resolve_item_asset", item_resolver)

                # Exercise every fallback renderer without injecting a
                # cross-category diagnostics strip into the product UI.
                previews = {
                    "plant": _asset_preview_label(
                        engine,
                        "bonsai",
                        "seed",
                        size=84,
                    ),
                    "fertilizer": _item_preview_label(
                        engine,
                        "rich_compost",
                        "Rich Compost preview",
                        size=76,
                        placeholder_kind=PurchaseKind.FERTILIZER,
                    ),
                    "growth-charge": _item_preview_label(
                        engine,
                        growth_charge.charge_id,
                        f"{growth_charge.name} preview",
                        size=76,
                        placeholder_kind=PurchaseKind.GROWTH_CHARGE,
                    ),
                    "weather": dialog._environment_artwork(
                        weather_item,
                        width=124,
                        height=72,
                    ),
                    "scenery": dialog._environment_artwork(
                        scenery_item,
                        width=124,
                        height=72,
                    ),
                }
                expected_aspects = {
                    "plant": 1.0,
                    "fertilizer": 1.0,
                    "growth-charge": 1.0,
                    "weather": 114 / 62,
                    "scenery": 114 / 62,
                }
                original_weather_resolver = original_resolvers[
                    "resolve_garden_feature_preview_asset"
                ]
                original_scenery_resolver = original_resolvers[
                    "resolve_scenery_preview_asset"
                ]
                setattr(
                    engine,
                    "resolve_garden_feature_preview_asset",
                    lambda item_id: (
                        MissingCaptureAsset(missing_paths["weather"])
                        if str(item_id) == weather_item.item_id
                        else original_weather_resolver(item_id)
                    ),
                )
                setattr(
                    engine,
                    "resolve_scenery_preview_asset",
                    original_scenery_resolver,
                )
                dialog.refresh()
                dialog.catalog_tabs.setCurrentIndex(3)
                dialog.environment_scroll.verticalScrollBar().setValue(0)
                QApplication.processEvents()

                normal_card = getattr(dialog, "environment_feature_card", None)
                visible_preview = getattr(dialog, "environment_feature_art", None)
                if visible_preview is not None:
                    visible_preview.setProperty(
                        "captureEvidenceKey",
                        "missing-art-weather",
                    )
                if normal_card is not None:
                    dialog.environment_scroll.ensureWidgetVisible(
                        normal_card,
                        0,
                        24,
                    )
                    QApplication.processEvents()

                expected_fingerprints = {
                    (
                        "plant",
                        "bonsai:seed",
                        missing_paths["plant"],
                    ),
                    (
                        "fertilizer",
                        "rich_compost",
                        missing_paths["fertilizer"],
                    ),
                    (
                        "growth_charge",
                        growth_charge.charge_id,
                        missing_paths["growth-charge"],
                    ),
                    (
                        "garden_feature",
                        weather_item.item_id,
                        missing_paths["weather"],
                    ),
                    (
                        "scenery",
                        scenery_item.item_id,
                        missing_paths["scenery"],
                    ),
                }
                matrix_entries: list[dict[str, Any]] = []
                for artwork_type in MISSING_ARTWORK_CAPTURE_TYPES:
                    preview = previews[artwork_type]
                    pixmap = preview.pixmap()
                    pixmap_width = int(pixmap.width()) if pixmap is not None else 0
                    pixmap_height = int(pixmap.height()) if pixmap is not None else 0
                    actual_aspect = (
                        pixmap_width / pixmap_height if pixmap_height > 0 else 0.0
                    )
                    expected_aspect = expected_aspects[artwork_type]
                    entry = {
                        "type": artwork_type,
                        "source_path": missing_paths[artwork_type],
                        "accessible_name": str(preview.accessibleName() or ""),
                        "accessible_description": str(
                            preview.accessibleDescription() or ""
                        ),
                        "semantic_role": str(
                            preview.property("gardenRole") or ""
                        ),
                        "pixmap_size": [pixmap_width, pixmap_height],
                        "graphic_present": bool(
                            pixmap is not None and not pixmap.isNull()
                        ),
                        "expected_aspect_ratio": round(expected_aspect, 4),
                        "actual_aspect_ratio": round(actual_aspect, 4),
                        "aspect_ratio_preserved": bool(
                            actual_aspect > 0
                            and abs(actual_aspect / expected_aspect - 1.0) <= 0.03
                        ),
                        "diagnostic_path_logged": any(
                            fingerprint[2] == missing_paths[artwork_type]
                            for fingerprint in _LOGGED_MISSING_ARTWORK
                        ),
                    }
                    entry["passed"] = bool(
                        entry["semantic_role"] == "missing-art"
                        and entry["graphic_present"]
                        and entry["aspect_ratio_preserved"]
                        and str(entry["accessible_name"]).strip()
                        and str(entry["accessible_description"]).startswith(
                            "Artwork unavailable"
                        )
                        and entry["diagnostic_path_logged"]
                    )
                    matrix_entries.append(entry)
                logged_fingerprints = sorted(
                    [
                        list(fingerprint)
                        for fingerprint in expected_fingerprints
                        if fingerprint in _LOGGED_MISSING_ARTWORK
                    ]
                )

                def prepare_capture() -> None:
                    current_card = getattr(
                        dialog,
                        "environment_feature_card",
                        None,
                    )
                    current_preview = getattr(
                        dialog,
                        "environment_feature_art",
                        None,
                    )
                    if current_preview is not None:
                        current_preview.setProperty(
                            "captureEvidenceKey",
                            "missing-art-weather",
                        )
                    if current_card is not None:
                        dialog.environment_scroll.ensureWidgetVisible(
                            current_card,
                            0,
                            24,
                        )
                        QApplication.processEvents()
                    viewport = dialog.environment_scroll.viewport()
                    visible_card_evidence = self._widget_bounds_evidence(
                        current_card,
                        viewport,
                    )
                    visible_preview_evidence = self._widget_bounds_evidence(
                        current_preview,
                        viewport,
                    )
                    visible_missing_previews = [
                        child
                        for child in dialog.environment_catalog.findChildren(QLabel)
                        if str(child.property("gardenRole") or "") == "missing-art"
                        and bool(
                            self._widget_bounds_evidence(child, viewport).get(
                                "visible",
                                False,
                            )
                        )
                        and bool(
                            self._widget_bounds_evidence(child, viewport).get(
                                "contained",
                                False,
                            )
                        )
                    ]
                    matrix_passed = bool(
                        [entry["type"] for entry in matrix_entries]
                        == list(MISSING_ARTWORK_CAPTURE_TYPES)
                        and expected_fingerprints.issubset(_LOGGED_MISSING_ARTWORK)
                        and all(entry["passed"] for entry in matrix_entries)
                        and visible_card_evidence.get("visible", False)
                        and visible_card_evidence.get("contained", False)
                        and visible_preview_evidence.get("visible", False)
                        and visible_preview_evidence.get("contained", False)
                        and len(visible_missing_previews) == 1
                        and self.app.storage.state.selected_weather
                        == weather_item.item_id
                    )
                    self._capture_annotations[label] = {
                        "resolvers_forced_missing": list(resolver_names),
                        "missing_artwork_matrix": {
                            "types": list(MISSING_ARTWORK_CAPTURE_TYPES),
                            "entries": matrix_entries,
                            "missing_source_paths": dict(missing_paths),
                            "diagnostic_log_fingerprints": logged_fingerprints,
                            "visible_card": visible_card_evidence,
                            "visible_preview": visible_preview_evidence,
                            "visible_missing_preview_count": len(
                                visible_missing_previews
                            ),
                            "selected_weather": str(
                                self.app.storage.state.selected_weather
                            ),
                            "target_weather": weather_item.item_id,
                            "equipped_weather_target": bool(
                                self.app.storage.state.selected_weather
                                == weather_item.item_id
                            ),
                            "passed": matrix_passed,
                        },
                        "passed": matrix_passed,
                    }
                    if not matrix_passed:
                        self._failures.append({
                            "label": label,
                            "reason": (
                                "The normal Nursery card or offscreen fallback contract "
                                "was incomplete"
                            ),
                        })
            except Exception:
                restore_resolver()
                self._failures.append({
                    "label": label,
                    "reason": "Missing-artwork fallback fixture could not be prepared",
                })
                self._close_widget(dialog)
                self._next_after(200)
                return

            def close_capture() -> None:
                restore_resolver()
                self._close_widget(dialog)

            self._capture_and_advance(
                label,
                dialog,
                capture_delay_ms=520,
                before_capture=prepare_capture,
                close_callback=close_capture,
                close_ms=850,
                next_ms=1200,
            )

        self._capture_custom_nursery(3, label, ready)

    def _capture_custom_settings(
        self,
        label: str,
        tab: int,
        prepare: Callable[[Any], None],
        *,
        restore_callback: Callable[[], None] | None = None,
    ) -> None:
        dialog_for_cleanup: Any | None = None
        cleanup_complete = False

        def cleanup_once() -> None:
            nonlocal cleanup_complete
            if cleanup_complete:
                return
            cleanup_complete = True
            dialog = dialog_for_cleanup
            if dialog is None:
                try:
                    dialog = self._find_settings_dialog()
                except Exception as exc:
                    self._failures.append({
                        "label": label,
                        "reason": (
                            "Settings fixture cleanup could not inspect the dialog: "
                            f"{type(exc).__name__}"
                        ),
                    })
            if dialog is not None:
                try:
                    self._close_settings_capture(dialog)
                except Exception as exc:
                    self._failures.append({
                        "label": label,
                        "reason": (
                            "Settings fixture cleanup could not close the dialog: "
                            f"{type(exc).__name__}"
                        ),
                    })
            if restore_callback is not None:
                try:
                    restore_callback()
                except Exception as exc:
                    self._failures.append({
                        "label": label,
                        "reason": (
                            "Settings fixture state restoration failed: "
                            f"{type(exc).__name__}"
                        ),
                    })

        def dashboard_ready() -> None:
            dashboard = self.app.dashboard
            dashboard._open_settings()

            def settings_ready() -> None:
                nonlocal dialog_for_cleanup
                dialog = self._find_settings_dialog()
                dialog_for_cleanup = dialog
                self._set_settings_tab(dialog, tab)
                prepare(dialog)
                self._capture_and_advance(
                    label,
                    dialog,
                    capture_delay_ms=480,
                    close_callback=cleanup_once,
                    close_ms=700,
                    next_ms=1250,
                )

            self._wait_for(
                lambda: bool(
                    self._find_settings_dialog() is not None
                    and self._find_settings_dialog().isVisible()
                ),
                settings_ready,
                failure_label=label,
                failure_reason=f"Settings stress state {label!r} did not become ready",
                on_error=cleanup_once,
            )

        self._with_dashboard(
            dashboard_ready,
            failure_label=label,
            on_error=cleanup_once,
        )

    @staticmethod
    def _close_settings_capture(dialog: Any) -> None:
        """Restore the saved draft so stress captures never open a discard prompt."""
        try:
            dialog.behavior.apply_persistent_payload(dialog._persisted_payload)
            dialog.garden_name_edit.setText(dialog._persisted_name)
            dialog.done(int(QDialog.DialogCode.Rejected))
        except Exception:
            dialog.close()

    def _capture_settings_unsaved(self) -> None:
        self._capture_custom_settings(
            "settings-unsaved-changes",
            0,
            lambda dialog: dialog.garden_name_edit.setText("Unsaved Moonlit Garden"),
        )

    def _prepare_reviewer_capture_card(self) -> bool:
        """Create one disposable Basic note so reward captures use real Reviewer UI."""

        if bool(getattr(self, "_reviewer_capture_card_ready", False)):
            return True
        collection = getattr(mw, "col", None)
        if collection is None:
            return False
        try:
            decks = collection.decks
            # ``id_for_name()`` is lookup-only in current Anki releases.  The
            # legacy-named ``id()`` API remains the supported create-or-reuse
            # path across the full 25.07-26.08 release target.
            deck_id = decks.id("Anki Garden Capture")
            if deck_id is None:
                return False
            models = collection.models
            note_type = models.by_name("Basic") or models.current()
            if note_type is None:
                return False
            note = collection.new_note(note_type)
            field_names = list(note.keys())
            if not field_names:
                return False
            note[field_names[0]] = "What did this review uncover?"
            if len(field_names) > 1:
                note[field_names[1]] = "A Standard Find."
            add_note = getattr(collection, "add_note", None)
            if callable(add_note):
                add_note(note, int(deck_id))
            else:
                note_type = note.note_type()
                note_type["did"] = int(deck_id)
                collection.addNote(note)
            select_deck = getattr(decks, "select", None)
            if callable(select_deck):
                select_deck(int(deck_id))
            self._reviewer_capture_card_ready = True
            return True
        except Exception:
            logger.exception("Anki Garden capture: could not prepare Reviewer card")
            return False

    def _prepare_canonical_reviewer_feedback_fixture(
        self,
        *,
        find_reward_ids: tuple[str, ...],
        environment_item_ids: tuple[str, ...] = (),
        include_daily_activity: bool = False,
        achievement_ids: tuple[str, ...] = (),
        stack_individual: bool = False,
    ) -> tuple[dict[str, Any], Any, dict[str, Any]]:
        """Project a real Reviewer event from committed, registry-owned facts."""

        from ..achievements import ACHIEVEMENTS_BY_ID
        from ..garden_finds import (
            ENVIRONMENT_POOL_ID,
            ENVIRONMENT_POOL_VERSION,
            SPECIAL_ENVIRONMENT_POOL,
            STANDARD_FIND_REGISTRY,
            STANDARD_POOL_ID,
            STANDARD_POOL_VERSION,
        )
        from ..models.state import (
            CurrencyTransaction,
            GardenFindOutcome,
            RewardReceipt,
        )
        from ..reward_presentation import (
            recent_garden_finds,
            recent_reward_summaries,
        )

        # Showing Reviewer feedback consumes and persists queued presentation
        # state, which advances the ledger generation. Use the capture-owned
        # exact database boundary rather than a rollback-only checkpoint.
        snapshot = self._capture_fixture_state_snapshot(
            "reviewer-feedback",
            exact_ledger_restore=True,
        )
        try:
            handler = getattr(self.app, "reviewer_hooks", None)
            if handler is None:
                raise RuntimeError("Reviewer reward handler was unavailable")
            state = self.app.storage.state
            active = self.app.engine.active_plant() or next(
                (
                    plant for plant in state.plants
                    if bool(getattr(plant, "planted", False))
                    and not bool(getattr(plant, "fully_grown", False))
                ),
                None,
            )
            if active is None:
                raise RuntimeError(
                    "canonical Reviewer reward capture requires an unfinished plant"
                )

            reward_by_id = {
                reward.reward_id: reward for reward in STANDARD_FIND_REGISTRY
            }
            environment_by_id = {
                item.item_id: item for item in SPECIAL_ENVIRONMENT_POOL
            }
            unknown_find_ids = set(find_reward_ids) - set(reward_by_id)
            if unknown_find_ids:
                raise ValueError(
                    "unknown canonical Reviewer Find IDs: "
                    + ", ".join(sorted(unknown_find_ids))
                )
            unknown_environment_ids = (
                set(environment_item_ids) - set(environment_by_id)
            )
            if unknown_environment_ids:
                raise ValueError(
                    "unknown canonical Reviewer environment Find IDs: "
                    + ", ".join(sorted(unknown_environment_ids))
                )
            unknown_achievement_ids = set(achievement_ids) - set(
                ACHIEVEMENTS_BY_ID
            )
            if unknown_achievement_ids:
                raise ValueError(
                    "unknown canonical Reviewer achievement IDs: "
                    + ", ".join(sorted(unknown_achievement_ids))
                )

            day_value = "2026-08-21"
            state.daily_stats.day = day_value
            state.daily_stats.reviewed = 176
            completion = state.daily_completion
            completion.scheduler_day = day_value
            completion.status = "complete"
            completion.starting_required_cards = 176
            completion.starting_required_cards_completed = 176
            completion.remaining_required_reviews = 0
            completion.remaining_learning_steps = 0
            completion.future_learning_steps_before_cutoff = 0
            completion.next_learning_due_at_ms = 0
            completion.cards_completed_today = 176
            completion.reward_claimed = True
            state.recent_reward_receipts = []
            state.garden_find_outcomes = {}
            state.garden_find_daily_counts = {day_value: len(find_reward_ids)}
            state.garden_find_reward_daily_counts = {day_value: {}}
            state.currency_transactions = []
            state.pending_feedback = []
            state.applied_reward_event_keys = []
            state.processed_answer_keys = []
            self.app.engine._ensure_achievements()

            sync_correlation = f"sync:capture-reviewer:{day_value}"
            all_receipt_groups: list[tuple[RewardReceipt, ...]] = []
            for index, reward_id in enumerate(find_reward_ids, start=1):
                reward = reward_by_id[reward_id]
                answer_key = f"capture-reviewer-{index}"
                correlation_id = sync_correlation
                occurred_at = f"{day_value}T09:{index:02d}:00+00:00"
                find_event_key = (
                    f"garden_find:{answer_key}:{STANDARD_POOL_ID}"
                )
                item_id = reward.inventory_item_id or ""
                outcome = GardenFindOutcome(
                    answer_key=answer_key,
                    scheduler_day=day_value,
                    status="hit",
                    pool_id=STANDARD_POOL_ID,
                    pool_version=STANDARD_POOL_VERSION,
                    occurred_at=occurred_at,
                    reward_id=reward.reward_id,
                    reward_type=reward.reward_kind,
                    amount=reward.amount,
                    item_id=item_id,
                    display_name=reward.display_name,
                    description=reward.description,
                    tier=reward.tier,
                    artwork_ref=reward.artwork_ref,
                    localization_key=reward.localization_key,
                )
                state.garden_find_outcomes[outcome.outcome_key] = outcome
                receipts: list[RewardReceipt] = []
                if include_daily_activity and index == 1:
                    receipts.append(RewardReceipt(
                        event_key=f"daily_activity:{day_value}",
                        reward_type="coins",
                        source="daily_activity",
                        source_id=day_value,
                        scheduler_day=day_value,
                        correlation_id=correlation_id,
                        occurred_at=occurred_at,
                        amount=int(self.app.engine.DAILY_ACTIVITY_COINS),
                        title="Daily activity reward",
                    ))
                receipts.append(RewardReceipt(
                    event_key=find_event_key,
                    reward_type=reward.reward_kind,
                    source="garden_find",
                    source_id=reward.reward_id,
                    scheduler_day=day_value,
                    correlation_id=correlation_id,
                    occurred_at=occurred_at,
                    amount=reward.amount,
                    item_id=item_id,
                    plant_id=(
                        active.plant_id if reward.reward_kind == "growth" else ""
                    ),
                    title=reward.display_name,
                    description=reward.description,
                ))

                if index == len(find_reward_ids):
                    for achievement_id in achievement_ids:
                        definition = ACHIEVEMENTS_BY_ID[achievement_id]
                        event_key = f"achievement:{achievement_id}"
                        if definition.reward.coins:
                            receipts.append(RewardReceipt(
                                event_key=event_key,
                                reward_type="coins",
                                source="achievement",
                                source_id=achievement_id,
                                scheduler_day=day_value,
                                correlation_id=correlation_id,
                                occurred_at=occurred_at,
                                amount=definition.reward.coins,
                                title=definition.name,
                                description=definition.description,
                            ))
                        for charge_id, amount in (
                            (
                                "growth_charge_small",
                                definition.reward.small_growth_charges,
                            ),
                            (
                                "growth_charge_standard",
                                definition.reward.standard_growth_charges,
                            ),
                        ):
                            if amount:
                                receipts.append(RewardReceipt(
                                    event_key=event_key,
                                    reward_type="inventory_item",
                                    source="achievement",
                                    source_id=achievement_id,
                                    scheduler_day=day_value,
                                    correlation_id=correlation_id,
                                    occurred_at=occurred_at,
                                    amount=amount,
                                    item_id=charge_id,
                                    title=definition.name,
                                    description=definition.description,
                                ))
                        achievement = state.achievements[achievement_id]
                        achievement.unlocked = True
                        achievement.progress = 1.0
                        achievement.unlocked_at = occurred_at
                        achievement.rewarded_at = occurred_at
                        achievement.reward_event_key = event_key
                        achievement.historical_backfill = False

                for receipt_index, receipt in enumerate(receipts, start=1):
                    state.recent_reward_receipts.append(receipt)
                    if receipt.event_key not in state.applied_reward_event_keys:
                        state.applied_reward_event_keys.append(receipt.event_key)
                    if receipt.reward_type == "coins":
                        state.currency_balance += receipt.amount
                        state.currency_transactions.append(CurrencyTransaction(
                            transaction_id=(
                                f"capture-reviewer-tx-{index}-{receipt_index}"
                            ),
                            event_key=receipt.event_key,
                            reason=receipt.title,
                            delta=receipt.amount,
                            balance=state.currency_balance,
                            occurred_at=receipt.occurred_at,
                            transaction_type="credit",
                            source=receipt.source,
                            source_id=receipt.source_id,
                            scheduler_day=receipt.scheduler_day,
                            correlation_id=receipt.correlation_id,
                        ))
                    elif receipt.reward_type == "growth":
                        active.growth_points += receipt.amount
                        direct_growth = (
                            state.daily_stats.plant_direct_reward_growth
                        )
                        direct_growth[active.plant_id] = (
                            int(direct_growth.get(active.plant_id, 0) or 0)
                            + receipt.amount
                        )
                    elif receipt.reward_type == "inventory_item" and receipt.item_id:
                        state.consumables[receipt.item_id] = (
                            int(state.consumables.get(receipt.item_id, 0) or 0)
                            + receipt.amount
                        )
                state.processed_answer_keys.append(answer_key)
                state.garden_find_reward_daily_counts[day_value][reward_id] = (
                    int(state.garden_find_reward_daily_counts[day_value].get(
                        reward_id,
                        0,
                    ) or 0)
                    + 1
                )
                receipt_group = tuple(receipts)
                all_receipt_groups.append(receipt_group)

            for offset, item_id in enumerate(environment_item_ids, start=1):
                item = environment_by_id[item_id]
                answer_key = f"capture-reviewer-environment-{offset}"
                correlation_id = sync_correlation
                minute = len(find_reward_ids) + offset
                occurred_at = f"{day_value}T09:{minute:02d}:30+00:00"
                find_event_key = (
                    f"garden_find:{answer_key}:{ENVIRONMENT_POOL_ID}"
                )
                outcome = GardenFindOutcome(
                    answer_key=answer_key,
                    scheduler_day=day_value,
                    status="hit",
                    pool_id=ENVIRONMENT_POOL_ID,
                    pool_version=ENVIRONMENT_POOL_VERSION,
                    occurred_at=occurred_at,
                    reward_id=item.item_id,
                    reward_type="environment_item",
                    amount=1,
                    item_id=item.item_id,
                    display_name=item.display_name,
                    description=(
                        "Added to garden decorations"
                        if item.environment_kind == "garden_feature"
                        else "Added to Scenery"
                    ),
                    tier=item.tier,
                    artwork_ref=item.item_id,
                    localization_key=f"garden_find.environment.{item.item_id}",
                )
                state.garden_find_outcomes[outcome.outcome_key] = outcome
                receipt = RewardReceipt(
                    event_key=find_event_key,
                    reward_type="environment_item",
                    source="garden_find_environment",
                    source_id=item.item_id,
                    scheduler_day=day_value,
                    correlation_id=correlation_id,
                    occurred_at=occurred_at,
                    amount=1,
                    item_id=item.item_id,
                    title=item.display_name,
                    description=outcome.description,
                )
                state.recent_reward_receipts.append(receipt)
                if receipt.event_key not in state.applied_reward_event_keys:
                    state.applied_reward_event_keys.append(receipt.event_key)
                ownership_category = (
                    "garden_features"
                    if item.environment_kind == "garden_feature"
                    else "scenery"
                )
                owned_items = state.inventory.setdefault(ownership_category, [])
                if item.item_id not in owned_items:
                    owned_items.append(item.item_id)
                state.processed_answer_keys.append(answer_key)
                all_receipt_groups.append((receipt,))

            all_receipts = tuple(
                receipt
                for group in all_receipt_groups
                for receipt in group
            )
            if not self.app.engine._queue_reward_feedback(
                sync_correlation,
                all_receipts,
                achievement_ids=achievement_ids,
                plant_id=active.plant_id,
                title="Garden rewards added",
            ):
                raise RuntimeError(
                    "canonical Reviewer sync reward feedback was not queued"
                )
            state.pending_feedback[-1].occurred_at = (
                all_receipts[-1].occurred_at if all_receipts else f"{day_value}T09:00:00+00:00"
            )

            presentations = recent_garden_finds(state, limit=8)
            feedback = handler._consolidated_reward_feedback(
                list(state.pending_feedback)
            )
            if feedback is None:
                raise RuntimeError(
                    "canonical Reviewer reward feedback could not be projected"
                )
            expected_title = "Standard Find"
            receipt_correlations = {
                receipt.correlation_id for receipt in all_receipts
            }
            all_groups_share_correlation = bool(
                all_receipt_groups
                and all(all_receipt_groups)
                and receipt_correlations == {sync_correlation}
            )
            matching_summaries = tuple(
                summary
                for summary in recent_reward_summaries(state)
                if summary.correlation_id == sync_correlation
            )
            if len(matching_summaries) != 1:
                raise RuntimeError(
                    "canonical Reviewer fixture did not produce one typed summary"
                )
            expected_coins = sum(
                max(0, int(receipt.amount))
                for receipt in all_receipts
                if receipt.reward_type == "coins"
            )
            expected_growth = sum(
                max(0, int(receipt.amount))
                for receipt in all_receipts
                if receipt.reward_type == "growth"
            )
            expected_environments = sum(
                max(0, int(receipt.amount))
                for receipt in all_receipts
                if receipt.reward_type == "environment_item"
            )
            expected_parts = []
            if expected_coins:
                expected_parts.append(
                    f"+{expected_coins:,} Garden Coins"
                )
            if expected_growth:
                expected_parts.append(f"+{expected_growth:,} Growth")
            if expected_parts:
                expected_message = " · ".join(expected_parts)
            elif len(presentations) == 1:
                expected_message = str(presentations[0].description)
            else:
                expected_message = "Garden rewards added"
            annotation = {
                "canonical_find_ids": [
                    presentation.reward_id for presentation in presentations
                ],
                "canonical_find_pools": [
                    presentation.pool_id for presentation in presentations
                ],
                "canonical_feedback_title": feedback.title,
                "canonical_feedback_detail": feedback.reward_detail,
                "canonical_feedback_message": feedback.message,
                "expected_feedback_message": expected_message,
                "expected_feedback_amount": 0,
                "stacked_find_count": len(presentations),
                "sync_correlation": sync_correlation,
                "all_receipt_groups_share_correlation": (
                    all_groups_share_correlation
                ),
                "canonical_projection_passed": bool(
                    feedback.title == expected_title
                    and feedback.reward_detail == ""
                    and feedback.message == expected_message
                    and feedback.amount == 0
                    and all_groups_share_correlation
                    and len(presentations)
                    == len(find_reward_ids) + len(environment_item_ids)
                ),
            }
            if stack_individual:
                visible_presentations = list(presentations[:6])
                common_index = next(
                    (
                        index
                        for index, presentation in enumerate(
                            visible_presentations
                        )
                        if str(presentation.tier).casefold() == "common"
                    ),
                    None,
                )
                if common_index is not None:
                    # The contract's regular visible toast demonstrates the
                    # Common tier; overflow still summarizes the other five.
                    visible_presentations.append(
                        visible_presentations.pop(common_index)
                    )
                stack_events = [
                    replace(
                        feedback,
                        event_id=f"{feedback.event_id}:find:{index}",
                        event_ids=(f"{feedback.event_id}:find:{index}",),
                        title="Standard Find",
                        message=str(presentation.description),
                        asset_category=(
                            "environment"
                            if str(presentation.pool_id) == ENVIRONMENT_POOL_ID
                            else "ui"
                        ),
                        asset_key=str(presentation.artwork_ref or ""),
                        tier=str(presentation.tier).replace("_", " ").title(),
                        find_count=1,
                    )
                    for index, presentation in enumerate(
                        visible_presentations,
                        start=1,
                    )
                ]
                # The regular toast must prove that effects from one Garden
                # Find are grouped instead of spawning duplicate cards. Use
                # the canonical Common Growth and coin rewards as the two
                # typed lines while the other five notifications remain in
                # the overflow summary.
                grouped_presentations = [
                    presentation
                    for reward_id in (
                        "find_morning_dew",
                        "find_coin_pouch",
                    )
                    for presentation in visible_presentations
                    if str(presentation.reward_id) == reward_id
                ]
                grouped_copy = "\n".join(
                    str(presentation.description)
                    for presentation in grouped_presentations
                    if str(presentation.description).strip()
                )
                if stack_events and len(grouped_presentations) == 2:
                    stack_events[-1] = replace(
                        stack_events[-1],
                        message=grouped_copy,
                    )
                annotation["stack_event_count"] = len(stack_events)
                annotation["expected_visible_toasts"] = 2
                annotation["expected_overflow_copy"] = "+5 more rewards"
                annotation["grouped_find_reward_copy"] = grouped_copy
                annotation["expected_newest_title"] = str(
                    stack_events[-1].title if stack_events else ""
                )
                annotation["expected_newest_message"] = str(
                    stack_events[-1].message if stack_events else ""
                )
                return snapshot, tuple(stack_events), annotation
            return snapshot, feedback, annotation
        except Exception:
            self._restore_reward_capture_fixture(snapshot)
            raise

    def _maximize_reviewer_capture_window(self) -> None:
        """Maximize Reviewer evidence and remember the disposable window state."""

        if getattr(self, "_reviewer_capture_window_state", None) is not None:
            return
        normal_geometry = mw.normalGeometry()
        self._reviewer_capture_window_state = {
            "fullscreen": bool(mw.isFullScreen()),
            "maximized": bool(mw.isMaximized()),
            "normal_bounds": (
                int(normal_geometry.x()),
                int(normal_geometry.y()),
                int(normal_geometry.width()),
                int(normal_geometry.height()),
            ),
        }
        self._move_to_capture_display(mw)
        mw.showMaximized()

    def _restore_reviewer_capture_window(self) -> None:
        state = getattr(self, "_reviewer_capture_window_state", None)
        self._reviewer_capture_window_state = None
        if not isinstance(state, dict):
            return
        if bool(state.get("fullscreen", False)):
            mw.showFullScreen()
            return
        if bool(state.get("maximized", False)):
            mw.showMaximized()
            return
        mw.showNormal()
        bounds = tuple(state.get("normal_bounds", ()) or ())
        if len(bounds) == 4 and int(bounds[2]) > 0 and int(bounds[3]) > 0:
            mw.setGeometry(*(int(value) for value in bounds))

    def _with_capture_reviewer(
        self,
        label: str,
        ready: Callable[[], None],
        *,
        on_error: Callable[[], None] | None = None,
    ) -> None:
        # GardenDashboard is a native child panel on macOS. Leaving it visible
        # can cover the main Reviewer even after Anki enters review state, so a
        # foreground screen-region grab records a cropped Garden instead of
        # the card and reward notice. Close it before the transition and make
        # hidden Dashboard state part of Reviewer readiness.
        self._close_top_level_dialogs()
        self._close_dashboard()

        def failure_cleanup() -> None:
            if on_error is not None:
                on_error()
            self._leave_capture_reviewer()

        if not self._prepare_reviewer_capture_card():
            self._failures.append({
                "label": label,
                "reason": "A disposable Reviewer card could not be prepared",
            })
            self._next_after(180)
            return
        logger.info(
            "Anki Garden capture Reviewer entry: label=%s stage=card-prepared",
            label,
        )
        self._maximize_reviewer_capture_window()
        logger.info(
            "Anki Garden capture Reviewer entry: label=%s stage=maximized",
            label,
        )
        self._reviewer_repaint_after_home_attempts = 0

        def reviewer_window_ready() -> bool:
            window_evidence = self._home_fullscreen_window_evidence()
            annotation = self._capture_annotations.setdefault(label, {})
            annotation["reviewer_window_mode"] = window_evidence
            annotation["reviewer_window_screen_filling"] = bool(
                window_evidence.get("passed", False)
            )
            return bool(
                str(getattr(mw, "state", "")) == "review"
                and getattr(getattr(mw, "reviewer", None), "web", None)
                is not None
                and mw.reviewer.web.isVisible()
                and getattr(mw.reviewer, "card", None) is not None
                and (
                    getattr(self.app, "dashboard", None) is None
                    or not self.app.dashboard.isVisible()
                )
                and window_evidence.get("passed", False)
            )

        def reviewer_dom_ready() -> None:
            handler = getattr(self.app, "reviewer_hooks", None)
            ensure_hud = getattr(handler, "_ensure_reviewer_hud", None)
            if callable(ensure_hud):
                ensure_hud(force_collapsed=False, force_dock="right")
            app = QApplication.instance()
            if app is not None:
                app.processEvents()
            self._wait_for_reviewer_surface(
                label,
                ready,
                on_error=failure_cleanup,
            )

        def enter_reviewer() -> None:
            logger.info(
                "Anki Garden capture Reviewer entry: label=%s stage=transitioning",
                label,
            )
            try:
                mw.moveToState("review")
            except Exception as exc:
                failure_cleanup()
                self._failures.append({
                    "label": label,
                    "reason": (
                        "Reviewer state could not open: "
                        f"{type(exc).__name__}"
                    ),
                })
                self._next_after(180)
                return
            logger.info(
                "Anki Garden capture Reviewer entry: label=%s stage=transitioned",
                label,
            )
            self._wait_for(
                reviewer_window_ready,
                reviewer_dom_ready,
                tries=100,
                failure_label=label,
                failure_reason=(
                    "The real Anki Reviewer did not reach "
                    "screen-filling maximized geometry"
                ),
                on_error=failure_cleanup,
            )

        settle_samples = {"count": 0}

        def reviewer_entry_settled() -> bool:
            app = QApplication.instance()
            visible_garden_shell = False
            if app is not None:
                try:
                    from ..ui.dashboard import DialogShell

                    visible_garden_shell = any(
                        widget is not mw
                        and isinstance(widget, DialogShell)
                        and widget.isVisible()
                        for widget in app.allWidgets()
                    )
                except (AttributeError, RuntimeError, TypeError):
                    visible_garden_shell = True
            dashboard = getattr(self.app, "dashboard", None)
            try:
                dashboard_hidden = bool(
                    dashboard is None or not dashboard.isVisible()
                )
            except RuntimeError:
                dashboard_hidden = True
            home_web = getattr(mw, "web", None)
            try:
                settled = bool(
                    str(getattr(mw, "state", "")) == "deckBrowser"
                    and home_web is not None
                    and home_web.isVisible()
                    and dashboard_hidden
                    and not visible_garden_shell
                )
            except RuntimeError:
                settled = False
            settle_samples["count"] = (
                settle_samples["count"] + 1 if settled else 0
            )
            return settle_samples["count"] >= 2

        # WebEngine and deferred native-widget deletion can outlive the first
        # hidden-state event. Enter Reviewer only after two stable Home
        # samples on later event turns; synchronous transitions here have
        # intermittently terminated the disposable macOS process.
        QTimer.singleShot(
            280,
            lambda: self._wait_for(
                reviewer_entry_settled,
                enter_reviewer,
                tries=40,
                failure_label=label,
                failure_reason=(
                    "The deck browser did not settle before Reviewer entry"
                ),
                on_error=failure_cleanup,
            ),
        )

    def _leave_capture_reviewer(self) -> None:
        """Return the shared main WebEngine to a stable non-Reviewer page."""

        try:
            if str(getattr(mw, "state", "")) == "review":
                mw.moveToState("deckBrowser")
        except Exception:
            logger.exception(
                "Anki Garden capture: Reviewer cleanup transition failed"
            )
        finally:
            self._restore_reviewer_capture_window()

    def _capture_reviewer_find_feedback(
        self,
        label: str,
        prepare_feedback: Callable[
            [],
            tuple[dict[str, Any], Any, dict[str, Any]],
        ],
        *,
        reduced_motion: bool = False,
    ) -> None:
        cleanup_holder: dict[str, Callable[[], None]] = {
            "callback": lambda: None,
        }
        reviewer_cleanup: dict[str, float] = {"left_at": 0.0}

        def registered_cleanup() -> None:
            cleanup_holder["callback"]()
            self._leave_capture_reviewer()

        def ready() -> None:
            handler = getattr(self.app, "reviewer_hooks", None)
            if handler is None:
                self._failures.append({
                    "label": label,
                    "reason": "Reviewer reward handler was unavailable",
                })
                registered_cleanup()
                self._next_after(180)
                return
            try:
                snapshot, event, fixture_annotation = prepare_feedback()
            except Exception as exc:
                logger.exception(
                    "Anki Garden capture: canonical Reviewer fixture failed"
                )
                self._failures.append({
                    "label": label,
                    "reason": (
                        "Canonical Reviewer reward fixture failed: "
                        f"{type(exc).__name__}"
                    ),
                })
                registered_cleanup()
                self._next_after(180)
                return
            ensure_hud = getattr(handler, "_ensure_reviewer_hud", None)
            if callable(ensure_hud):
                ensure_hud(force_collapsed=False, force_dock="right")
            app = QApplication.instance()
            if app is not None:
                app.processEvents()
            cleaned_up = False
            config_value: Callable[..., Any] | None = None
            config_update: Callable[..., Any] | None = None
            baseline_reduced_motion = False

            def cleanup() -> None:
                nonlocal cleaned_up
                if cleaned_up:
                    return
                cleaned_up = True
                current = getattr(handler, "_reward_toast", None)
                state_cleanup = getattr(handler, "on_state_change", None)
                if callable(state_cleanup):
                    state_cleanup("capture-cleanup")
                elif current is not None:
                    try:
                        current.hide()
                    except RuntimeError:
                        pass
                    finally:
                        handler._reward_toast = None
                if reduced_motion and callable(config_update):
                    try:
                        config_update({"reduced_motion": baseline_reduced_motion})
                    except Exception:
                        logger.exception(
                            "Anki Garden capture: reduced-motion fixture restoration failed"
                        )
                self._leave_capture_reviewer()
                reviewer_cleanup["left_at"] = time.perf_counter()
                # Exact ledger restoration may take a few hundred
                # milliseconds. Start the required post-Reviewer WebEngine
                # settle interval as soon as the transition completes, then
                # restore the disposable fixture while that interval elapses.
                self._restore_reward_capture_fixture(snapshot)

            # Install cleanup immediately after the fixture mutates state. The
            # outer readiness guard can now restore it for every later failure.
            cleanup_holder["callback"] = cleanup

            try:
                config = getattr(self.app, "config", None)
                config_value = getattr(config, "value", None)
                config_update = getattr(config, "update", None)
                baseline_reduced_motion = (
                    bool(config_value("reduced_motion", False))
                    if callable(config_value) else False
                )
                if reduced_motion and callable(config_update):
                    config_update({"reduced_motion": True})
                app = QApplication.instance()
                focus_target = getattr(
                    getattr(mw, "reviewer", None),
                    "web",
                    None,
                )
                if focus_target is not None:
                    focus_target.setFocus(Qt.FocusReason.TabFocusReason)
                if app is not None:
                    app.processEvents()
                focus_before = QApplication.focusWidget()
                event_sequence = (
                    tuple(event)
                    if isinstance(event, (tuple, list)) else
                    (event,)
                )
                rendered = bool(
                    event_sequence
                    and all(
                        handler._show_reward_toast(item)
                        for item in event_sequence
                    )
                )
                if app is not None:
                    app.processEvents()
                focus_after = QApplication.focusWidget()
                toast = getattr(handler, "_reward_toast", None)
                visible_toasts = [
                    candidate
                    for candidate in tuple(
                        getattr(handler, "_reward_toasts", ()) or ()
                    )
                    if candidate.isVisible()
                ]
            except Exception:
                cleanup()
                raise
            overlay_geometries = [
                self._reviewer_overlay_geometry_audit(label, candidate)
                for candidate in visible_toasts
            ]
            overlay_geometry = (
                overlay_geometries[-1]
                if overlay_geometries else
                self._reviewer_overlay_geometry_audit(label, toast)
            )
            summary_toasts = [
                candidate
                for candidate in visible_toasts
                if bool(candidate.property("rewardSummary"))
            ]
            summary_copy = (
                str(summary_toasts[0]._garden_detail_label.text())
                if len(summary_toasts) == 1 else
                ""
            )
            regular_toasts = [
                candidate
                for candidate in visible_toasts
                if not bool(candidate.property("rewardSummary"))
            ]
            newest_expected_title = str(
                getattr(event_sequence[-1], "title", "")
                if event_sequence else
                ""
            )
            newest_expected_message = str(
                getattr(event_sequence[-1], "message", "")
                if event_sequence else
                ""
            )
            newest_visible_title = (
                str(regular_toasts[0]._garden_title_label.text())
                if len(regular_toasts) == 1 else
                ""
            )
            newest_visible_message = (
                str(regular_toasts[0]._garden_message_label.text())
                if len(regular_toasts) == 1 else
                ""
            )
            newest_event_visible = bool(
                len(regular_toasts) == 1
                and newest_visible_title == newest_expected_title
                and newest_visible_message == newest_expected_message
            )
            ordered_overlay_bounds = sorted(
                (
                    list(row.get("overlay_bounds", ()) or ())
                    for row in overlay_geometries
                    if len(list(row.get("overlay_bounds", ()) or ())) == 4
                ),
                key=lambda bounds: (bounds[1], bounds[0]),
            )
            stack_gaps = [
                following[1] - (current[1] + current[3])
                for current, following in zip(
                    ordered_overlay_bounds,
                    ordered_overlay_bounds[1:],
                )
            ]
            stack_non_overlapping = bool(
                all(gap >= 8 for gap in stack_gaps)
            )
            stacked_requested = len(event_sequence) > 1
            stack_evidence = {
                "requested_event_count": len(event_sequence),
                "visible_toast_count": len(visible_toasts),
                "summary_toast_count": len(summary_toasts),
                "regular_toast_count": len(regular_toasts),
                "summary_copy": summary_copy,
                "newest_expected_title": newest_expected_title,
                "newest_expected_message": newest_expected_message,
                "newest_visible_title": newest_visible_title,
                "newest_visible_message": newest_visible_message,
                "newest_event_visible": newest_event_visible,
                "overlay_bounds": ordered_overlay_bounds,
                "stack_gaps": stack_gaps,
                "stack_non_overlapping": stack_non_overlapping,
                "reviewer_reserved_zones_passed": all(
                    row.get("reserved_zone_passed", False)
                    for row in overlay_geometries
                ),
                "passed": bool(
                    not stacked_requested
                    or (
                        len(event_sequence) == 6
                        and len(visible_toasts) == 2
                        and len(summary_toasts) == 1
                        and len(regular_toasts) == 1
                        and summary_copy == "+5 more rewards"
                        and newest_event_visible
                        and stack_non_overlapping
                        and all(
                            row.get("passed", False)
                            for row in overlay_geometries
                        )
                    )
                ),
            }
            reviewer_dom_identity = dict(
                getattr(self, "_active_reviewer_dom_audit", {}) or {}
            )
            hud = getattr(handler, "_reviewer_hud", None)
            reviewer_hud_geometry = self._reviewer_hud_geometry_audit(
                label,
                hud,
            )
            reviewer_window_mode = self._home_fullscreen_window_evidence()
            passed = bool(
                rendered
                and toast is not None
                and toast.isVisible()
                and focus_after is focus_before
                and focus_after is not toast
                and overlay_geometry.get("passed", False)
                and stack_evidence["passed"]
                and fixture_annotation.get(
                    "canonical_projection_passed",
                    False,
                )
                and reviewer_dom_identity.get("ready", False)
                and reviewer_hud_geometry.get("passed", False)
                and reviewer_window_mode.get("passed", False)
            )
            self._capture_annotations[label] = {
                **fixture_annotation,
                "reviewer_dom_identity": reviewer_dom_identity,
                "focus_preserved": focus_after is focus_before,
                "focus_owner": (
                    type(focus_after).__name__ if focus_after is not None else ""
                ),
                "reduced_motion_config_enabled": bool(
                    reduced_motion
                    and callable(config_value)
                    and config_value("reduced_motion", False)
                ),
                "toast_visible": bool(toast is not None and toast.isVisible()),
                "reviewer_overlay_geometry": overlay_geometry,
                "reviewer_overlay_geometries": overlay_geometries,
                "reviewer_hud_geometry": reviewer_hud_geometry,
                "reviewer_hud_visible": bool(
                    hud is not None and hud.isVisible()
                ),
                "reviewer_window_mode": reviewer_window_mode,
                "reviewer_window_screen_filling": bool(
                    reviewer_window_mode.get("passed", False)
                ),
                "reviewer_stack": stack_evidence,
                "passed": passed,
            }
            if not passed:
                self._failures.append({
                    "label": label,
                    "reason": "Reviewer Find notification did not match its focus-safe projection",
                })

            try:
                self._capture_and_advance(
                    label,
                    mw,
                    capture_delay_ms=520,
                    close_callback=cleanup,
                    cleanup_predicate=lambda: (
                        getattr(handler, "_reward_toast", None) is None
                        and str(getattr(mw, "state", "")) == "deckBrowser"
                        # State changes synchronously, while the shared
                        # WebEngine page and the native overlay tear down on
                        # later event turns.  Keep the disposable Anki process
                        # alive long enough for those deferred deletions before
                        # the runner advances to its shutdown gate; exiting on
                        # the first deckBrowser tick can crash Qt with SIGSEGV.
                        and reviewer_cleanup["left_at"] > 0.0
                        and time.perf_counter() - reviewer_cleanup["left_at"]
                        >= 1.2
                    ),
                    cleanup_timeout_ms=2600,
                    close_ms=760,
                    next_ms=1120,
                )
            except Exception:
                cleanup()
                raise

        self._with_capture_reviewer(
            label,
            ready,
            on_error=registered_cleanup,
        )

    def _capture_reviewer_hud_expanded(self) -> None:
        """Capture one clean, maximized Reviewer with the expanded HUD."""

        from ..models.state import CardEffectBatch

        label = "reviewer-hud-expanded"
        snapshot, plant_id = self._prepare_growth_capture_fixture(populated=True)
        state = self.app.storage.state
        plant = next(
            candidate for candidate in state.plants
            if str(getattr(candidate, "plant_id", "")) == plant_id
        )
        plant.name = "Juniper of the Moonlit Library Garden"
        plant.name_customized = True
        plant.fertilizer = None
        plant.fertilizer_history = []
        plant.fertilizer_card_batches = [CardEffectBatch(
            "fertilizer_quality",
            200,
            200,
            164,
            activated_at="2026-08-28T12:00:00+00:00",
            source_event_key="capture-hud-fertilizer",
        )]
        plant.fertilizer_card_queue = []
        plant.booster_card_batches = [CardEffectBatch(
            "booster_potion",
            500,
            100,
            38,
            source_event_key="capture-hud-booster",
        )]
        state.stored_growth_units = 1_250
        day_value = str(state.daily_stats.day)
        completion = state.daily_completion
        completion.scheduler_day = day_value
        completion.status = "in_progress"
        completion.starting_required_cards = 194
        completion.starting_required_cards_completed = 176
        completion.remaining_new_cards = 0
        completion.remaining_required_reviews = 18
        completion.remaining_learning_steps = 0
        completion.future_learning_steps_before_cutoff = 0
        completion.next_learning_due_at_ms = 0
        completion.cards_completed_today = 176
        completion.reward_claimed = False
        state.daily_stats.reviewed = 176
        state.garden_find_daily_counts = {day_value: 2}
        state.garden_find_drought_count = 52
        state.currency_balance = 248
        state.streak_days = 14
        state.selected_weather = "gentle_rain"
        state.selected_background = "spring"
        schedule = state.daily_loadout
        schedule.scheduler_day = day_value
        schedule.locked_at_ms = max(1, int(self.app.storage.current_time_ms()))
        schedule.weather_id = "gentle_rain"
        schedule.scenery_id = "spring"
        schedule.queued_weather_id = ""
        schedule.queued_scenery_id = ""

        restored = False
        reviewer_left_at = 0.0

        def cleanup() -> None:
            nonlocal restored, reviewer_left_at
            if restored:
                return
            restored = True
            handler = getattr(self.app, "reviewer_hooks", None)
            state_cleanup = getattr(handler, "on_state_change", None)
            if callable(state_cleanup):
                state_cleanup("capture-cleanup")
            self._leave_capture_reviewer()
            reviewer_left_at = time.perf_counter()
            self._restore_growth_capture_fixture(snapshot)

        def ready() -> None:
            handler = getattr(self.app, "reviewer_hooks", None)
            ensure_hud = getattr(handler, "_ensure_reviewer_hud", None)
            if not callable(ensure_hud):
                self._failures.append({
                    "label": label,
                    "reason": "Reviewer HUD handler was unavailable",
                })
                cleanup()
                self._next_after(180)
                return
            ensure_hud(force_collapsed=False, force_dock="right")
            app = QApplication.instance()
            if app is not None:
                app.processEvents()

            def matrix_ready(
                viewport_matrix: dict[str, Any],
                content_matrix: dict[str, Any],
                resilience_matrix: dict[str, Any],
            ) -> None:
                def hud_ready() -> bool:
                    hud = getattr(handler, "_reviewer_hud", None)
                    audit = self._reviewer_hud_geometry_audit(label, hud)
                    self._capture_annotations[label] = {
                        "reviewer_hud_visible": bool(
                            hud is not None and hud.isVisible()
                        ),
                        "reviewer_hud_geometry": audit,
                        "reviewer_hud_viewport_matrix": viewport_matrix,
                        "reviewer_hud_content_matrix": content_matrix,
                        "reviewer_hud_resilience_matrix": resilience_matrix,
                        "reviewer_dom_identity": dict(
                            getattr(self, "_active_reviewer_dom_audit", {}) or {}
                        ),
                        "reviewer_window_mode": dict(
                            audit.get("window_mode", {}) or {}
                        ),
                        "reviewer_window_screen_filling": bool(
                            dict(audit.get("window_mode", {}) or {}).get(
                                "passed",
                                False,
                            )
                        ),
                        "passed": bool(
                            audit.get("passed", False)
                            and viewport_matrix.get("passed", False)
                            and content_matrix.get("passed", False)
                            and resilience_matrix.get("passed", False)
                        ),
                    }
                    return bool(self._capture_annotations[label]["passed"])

                def capture_ready() -> None:
                    self._capture_and_advance(
                        label,
                        mw,
                        capture_delay_ms=520,
                        close_callback=cleanup,
                        cleanup_predicate=lambda: bool(
                            restored
                            and str(getattr(mw, "state", "")) == "deckBrowser"
                            and reviewer_left_at > 0.0
                            and time.perf_counter() - reviewer_left_at >= 1.2
                        ),
                        cleanup_timeout_ms=2600,
                        close_ms=760,
                        next_ms=1120,
                    )

                self._wait_for(
                    hud_ready,
                    capture_ready,
                    tries=100,
                    failure_label=label,
                    failure_reason=(
                        "Expanded Reviewer HUD did not reach bounded geometry"
                    ),
                    on_error=cleanup,
                )

            self._exercise_reviewer_hud_acceptance_matrix(
                label,
                handler,
                matrix_ready,
                cleanup,
            )

        self._with_capture_reviewer(label, ready, on_error=cleanup)

    def _capture_session_summary_after_review(self) -> None:
        """Capture the canonical post-review summary over a maximized Home."""

        from ..models.state import RewardReceipt
        from ..ui.session_summary import (
            BoosterSnapshot,
            CoinAward,
            EffectRow,
            EffectsSnapshot,
            EnvironmentDiscovery,
            FertilizerSnapshot,
            PlantGrowthTotal,
            PlantMilestone,
            ReviewContinuationTarget,
            SessionDaySummary,
            SessionProjectGrowthAllocation,
            SessionSummaryPayload,
            StandardFind,
            StoredGrowthTotal,
            TodayCardsSnapshot,
        )

        label = "session-summary-after-review"
        self._close_top_level_dialogs()
        self._close_dashboard()
        handler = getattr(self.app, "reviewer_hooks", None)
        if handler is None:
            self._failures.append({
                "label": label,
                "reason": "Session Summary handler was unavailable",
            })
            self._next_after(180)
            return

        plant = self.app.engine.active_plant()
        plant_id = str(getattr(plant, "plant_id", "") or "capture-summary-plant")
        plant_name = str(getattr(plant, "name", "") or "Juniper")
        species_name = str(getattr(plant, "species", "") or "Bonsai").replace(
            "_",
            " ",
        ).title()
        art_asset = ""
        full_bloom_art_asset = ""
        if plant is not None:
            try:
                asset = self.app.engine.resolve_plant_asset(
                    str(getattr(plant, "species", "") or ""),
                    str(getattr(plant, "growth_stage", "seed") or "seed"),
                )
                art_asset = str(getattr(asset, "path", "") or "")
            except Exception:
                art_asset = ""
        try:
            full_bloom_asset = self.app.engine.resolve_plant_asset(
                "wisteria",
                "rare",
            )
            full_bloom_art_asset = str(
                getattr(full_bloom_asset, "path", "") or ""
            )
        except Exception:
            full_bloom_art_asset = art_asset

        # Deliberately keep the local session delta distinct from the
        # scheduler's all-day total. This catches a presentation that simply
        # repeats Today’s Cards in the Session Summary.
        capture_session_cards_completed = 24
        capture_today_cards_completed = 126
